INSERT INTO `ai_message` (`id`, `conversation_id`, `user_id`, `request_id`, `seq`, `message_key`, `role`, `kind`, `content`, `run_status`, `error_code`, `history_summary`, `create_time`, `update_time`, `deleted`) VALUES (2124210686190968833,2124210189346299906,1900000000000000001,'a0ed6dff-4850-4982-bb06-c5267e5d76f1',18,'a0ed6dff-4850-4982-bb06-c5267e5d76f1:step:call_096dd577918647228fc65967','assistant','ASSISTANT_STEP','\"该仓也没有待出库销售订单。我再核实是否存在“已下单但尚有数量未到货”的采购明细，这是晚到批次最可能的落点。\"',NULL,NULL,NULL,'2026-11-22 02:37:48','2026-11-22 02:37:48',0);
