INSERT INTO `ai_message` (`id`, `conversation_id`, `user_id`, `request_id`, `seq`, `message_key`, `role`, `kind`, `content`, `run_status`, `error_code`, `history_summary`, `create_time`, `update_time`, `deleted`) VALUES (2124423462834425858,2124423434279604226,1900000000000000001,'355859dd-a8a8-49bd-adb0-2146699b89eb',4,'355859dd-a8a8-49bd-adb0-2146699b89eb:step:call_cc47782b012643f59b89fefe','assistant','ASSISTANT_STEP','\"技能要求先确认基线、成本和活动情景。我先查该商品的主档、当前库存与近半年实际出库（销量与成交价），再就系统缺失的成本与活动条件向你确认。\"',NULL,NULL,NULL,'2026-11-22 16:43:18','2026-11-22 16:43:18',0);
