INSERT INTO `ai_message` (`id`, `conversation_id`, `user_id`, `request_id`, `seq`, `message_key`, `role`, `kind`, `content`, `run_status`, `error_code`, `history_summary`, `create_time`, `update_time`, `deleted`) VALUES (2124424096178524162,2124424075508994050,1900000000000000001,'e5a06ace-040b-4b9e-aae9-3910cd13908d',5,'e5a06ace-040b-4b9e-aae9-3910cd13908d:tool:call_158ed24a46114baf8f06d81f','assistant','TOOL_CALL','{\"callId\":\"call_158ed24a46114baf8f06d81f\",\"name\":\"read_skill\",\"label\":\"处理当前步骤\",\"status\":\"done\",\"durationMs\":\"0\"}',NULL,NULL,NULL,'2026-11-22 16:45:49','2026-11-22 16:45:49',0);
INSERT INTO `ai_message` (`id`, `conversation_id`, `user_id`, `request_id`, `seq`, `message_key`, `role`, `kind`, `content`, `run_status`, `error_code`, `history_summary`, `create_time`, `update_time`, `deleted`) VALUES (2124424142974373889,2124424075508994050,1900000000000000001,'e5a06ace-040b-4b9e-aae9-3910cd13908d',6,'e5a06ace-040b-4b9e-aae9-3910cd13908d:step:call_55747fa6c5d14269a500e6bc','assistant','ASSISTANT_STEP','\"我先调用历史经验，同时把「成都缺口、源仓可释放量」这一核心计算交办给分析专家。\"',NULL,NULL,NULL,'2026-11-22 16:46:00','2026-11-22 16:46:00',0);
