INSERT INTO `ai_message` (`id`, `conversation_id`, `user_id`, `request_id`, `seq`, `message_key`, `role`, `kind`, `content`, `run_status`, `error_code`, `history_summary`, `create_time`, `update_time`, `deleted`) VALUES (2124762215155318785,2124761984778977281,1900000000000000001,'026275db-dfa3-4539-abec-3b9cba45fa14',9,'026275db-dfa3-4539-abec-3b9cba45fa14:step:call_283400f8c8104b6a9f007969','assistant','ASSISTANT_STEP','\"已确认仓库 ID 为 `8400000000004000001`（WH000001），产品为「沁泉 碳酸饮料便携装 500ml×12瓶×2装」，单位“罐”，数量精度 0（整数），安全库存 88.00 罐。接下来查看库存分布和候选供应商。\"',NULL,NULL,NULL,'2026-11-23 15:09:22','2026-11-23 15:09:22',0);
