INSERT INTO `ai_agent_trace` (`id`, `user_id`, `conversation_id`, `task_id`, `agent_type`, `event_type`, `content`, `create_time`) VALUES (2143,1900000000000000001,2124418644136972290,'d7717c98-a316-4e34-af02-4f7752f7359d','ANALYSIS','TOOL_CALL','{\"name\": \"executePython\", \"text\": \"{\\\"code\\\": \\\"import json, pandas as pd, numpy as np\\\\nfiles = {\\\\\\\"8400000000004000001\\\\\\\":\\\\\\\"ds_92ea43a53e304696a82cf1d5a0115433\\\\\\\",\\\\\\\"8400000000004000002\\\\\\\":\\\\\\\"ds_6be2a8af3147499da930fe35db3af2b5\\\\\\\",\\\\\\\"8400000000004000003\\\\\\\":\\\\\\\"ds_eba7e817ea47485c939c3e456972e2eb\\\\\\\",\\\\\\\"8400000000004000004\\\\\\\":\\\\\\\"ds_b132809bf3114a80ae22a7deb192ec09\\\\\\\",\\\\\\\"8400000000004000005\\\\\\\":\\\\\\\"ds_757f918cd11c498584e099345185423a\\\\\\\"}\\\\ndef load(p,col):\\\\n    rows=[json.loads(l) for l in open(p) if l.strip()]\\\\n    return pd.DataFrame(rows,columns=col)\\\\ncols=[\\\\\\\"warehouse_id\\\\\\\",\\\\\\\"warehouse_name\\\\\\\",\\\\\\\"product_id\\\\\\\",\\\\\\\"product_code\\\\\\\",\\\\\\\"product_name\\\\\\\",\\\\\\\"unit_name\\\\\\\",\\\\\\\"quantity_precision\\\\\\\",\\\\\\\"stock_qty\\\\\\\",\\\\\\\"locked_qty\\\\\\\",\\\\\\\"safety_stock_qty\\\\\\\"]\\\\ndf=pd.concat([load(f\\\\\\\"/tmp/erp-analysis/input/{v}.jsonl\\\\\\\",cols) for v in files.values()],ignore_index=True)\\\\nfor c in [\\\\\\\"stock_qty\\\\\\\",\\\\\\\"locked_qty\\\\\\\",\\\\\\\"safety_stock_qty\\\\\\\",\\\\\\\"quantity_precision\\\\\\\"]: df[c]=pd.to_numeric(df[c])\\\\ndf[\\\\\\\"warehouse_id\\\\\\\"]=df.warehouse_id.astype(str); df[\\\\\\\"product_id\\\\\\\"]=df.product_id.astype(str)\\\\nprod=load(\\\\\\\"/tmp/erp-analysis/input/ds_c7cc4f42fd99473ab8d6a3baddc1e303.jsonl\\\\\\\",[\\\\\\\"product_id\\\\\\\",\\\\\\\"product_code\\\\\\\",\\\\\\\"product_name\\\\\\\",\\\\\\\"unit_name\\\\\\\",\\\\\\\"quantity_precision\\\\\\\",\\\\\\\"safety_stock_qty\\\\\\\"])\\\\nprod[\\\\\\\"product_id\\\\\\\"]=prod.product_id.astype(str)\\\\nfor c in [\\\\\\\"quantity_precision\\\\\\\",\\\\\\\"safety_stock_qty\\\\\\\"]: prod[c]=pd.to_numeric(prod[c])\\\\nprint(\\\\\\\"active products:\\\\\\\",len(prod),\\\\\\\"distinct products in stock:\\\\\\\",df.product_id.nunique())\\\\nwhs=[\\\\\\\"8400000000004000001\\\\\\\",\\\\\\\"8400000000004000002\\\\\\\",\\\\\\\"8400000000004000003\\\\\\\",\\\\\\\"8400000000004000004\\\\\\\",\\\\\\\"8400000000004000005\\\\\\\"]\\\\nnpresent={w:df[df.warehouse_id==w].product_id.nunique() for w in whs}\\\\nprint(\\\\\\\"products present per wh:\\\\\\\",npresent)\\\\nmissing=set(prod.product_id)-set(df.product_id)\\\\nprint(\\\\\\\"active products with NO stock record in any of 5 wh:\\\\\\\",len(missing))\\\\n# products in stock but not active (already filtered by SQL, expect 0)\\\\nprint(\\\\\\\"stock products not in active prod:\\\\\\\",len(set(df.product_id)-set(prod.product_id)))\\\\n# business metrics\\\\ndf[\\\\\\\"stock\\\\\\\"]=df.stock_qty/100; df[\\\\\\\"locked\\\\\\\"]=df.locked_qty/100; df[\\\\\\\"avail\\\\\\\"]=df.stock-df.locked; df[\\\\\\\"safety\\\\\\\"]=df.safety_stock_qty/100\\\\ndf[\\\\\\\"prec\\\\\\\"]=df.quantity_precision\\\\ndef rnd(x,p): return float(np.round(x,p))\\\\nlow=df[df.avail<df.safety].copy()\\\\nlow[\\\\\\\"gap_raw\\\\\\\"]=(low.safety-low.avail)\\\\nlow[\\\\\\\"gap\\\\\\\"]=[rnd(g,p) for g,p in zip(low.gap_raw,low.prec)]\\\\nlow[\\\\\\\"gap_plus1\\\\\\\"]=[rnd(g,p) for g,p in zip(low.gap_raw,low.prec)]\\\\n# round-trip check: gap rounded then availability+gap == safety\\\\nprint(\\\\\\\"rounding mismatch (safety != avail+gap):\\\\\\\",(np.abs((low.avail+low.gap)-low.safety)>1e-9).sum())\\\\nlow[\\\\\\\"fill\\\\\\\"]=[rnd(a/s,6) for a,s in zip(low.avail,low.safety)]\\\\nlow[\\\\\\\"zero\\\\\\\"]=[\\\\\\\"是\\\\\\\" if a<=0 else \\\\\\\"否\\\\\\\" for a in low.avail]\\\\n\\\\n# score: priority = larger gap & lower fill. use rank-based composite\\\\nlow[\\\\\\\"r_gap\\\\\\\"]=low.gap.rank(ascending=False,method=\\\\\\\"min\\\\\\\")\\\\nlow[\\\\\\\"r_fill\\\\\\\"]=low.fill.rank(ascending=True,method=\\\\\\\"min\\\\\\\")\\\\nlow[\\\\\\\"score\\\\\\\"]=(low.r_gap+low.r_fill)/2\\\\nlow=low.sort_values([\\\\\\\"zero\\\\\\\",\\\\\\\"gap\\\\\\\",\\\\\\\"fill\\\\\\\"],ascending=[False,False,True])\\\\nlow[\\\\\\\"rank\\\\\\\"]=range(1,len(low)+1)\\\\n\\\\nout=pd.DataFrame({\\\\n \\\\\\\"紧急排名\\\\\\\":low[\\\\\\\"rank\\\\\\\"],\\\\n \\\\\\\"仓库名称\\\\\\\":low.warehouse_name,\\\\\\\"产品编码\\\\\\\":low.product_code,\\\\\\\"产品名称\\\\\\\":low.product_name,\\\\\\\"单位\\\\\\\":low.unit_name,\\\\n \\\\\\\"当前库存数量\\\\\\\":low.stock,\\\\\\\"锁定数量\\\\\\\":low.locked,\\\\\\\"可用库存\\\\\\\":low.avail,\\\\\\\"安全库存\\\\\\\":low.safety,\\\\n \\\\\\\"补货量\\\\\\\":low.gap,\\\\\\\"库存满足率\\\\\\\":low.fill,\\\\\\\"是否零库存\\\\\\\":low.zero})\\\\nout[\\\\\\\"库存满足率\\\\\\\"]=out[\\\\\\\"库存满足率\\\\\\\"].map(lambda v:f\\\\\\\"{v:.4f}\\\\\\\")\\\\nprint(\\\\\\\"\\\\\\\\n== summary ==\\\\\\\")\\\\nprint(\\\\\\\"low combos\\\\\\\",len(low),\\\\\\\"products\\\\\\\",low.product_id.nunique(),\\\\\\\"whs\\\\\\\",low.warehouse_name.nunique())\\\\nprint(\\\\\\\"zero/neg combos\\\\\\\",(low.avail<=0).sum(),\\\\\\\"neg\\\\\\\",(low.avail<0).sum())\\\\nprint(\\\\\\\"fully locked (stock>0 & avail==0):\\\\\\\",((low.stock>0)&(low.avail==0)).sum(),\\\\\\\" stock==0:\\\\\\\",(low.stock==0).sum())\\\\nprint(\\\\\\\"by wh:\\\\\\\",low.groupby(\\\\\\\"warehouse_name\\\\\\\").agg(组合数=(\\\\\\\"gap\\\\\\\",\\\\\\\"size\\\\\\\"),补货量=(\\\\\\\"gap\\\\\\\",\\\\\\\"sum\\\\\\\"),零库存=(\\\\\\\"zero\\\\\\\",lambda s:(s==\\\\\\\"是\\\\\\\").sum())).round(2).to_dict(\\\\\\\"index\\\\\\\"))\\\\nprint(\\\\\\\"total gap by unit:\\\\\\\",low.assign(g=low.gap.round(2)).groupby(\\\\\\\"unit_name\\\\\\\")[\\\\\\\"g\\\\\\\"].sum().sort_values(ascending=False).to_dict())\\\\nprint(\\\\\\\"gap sum overall:\\\\\\\",round(low.gap.sum(),2))\\\\nprint(\\\\\\\"\\\\\\\\n-- top10 gap --\\\\\\\")\\\\nprint(out.head(10).to_string(index=False))\\\\nprint(\\\\\\\"\\\\\\\\n-- top10 lowest fill --\\\\\\\")\\\\nt=low.sort_values([\\\\\\\"fill\\\\\\\",\\\\\\\"gap\\\\\\\"],ascending=[True,False]).head(10)\\\\nprint(pd.DataFrame({\\\\\\\"仓库名称\\\\\\\":t.warehouse_name,\\\\\\\"产品编码\\\\\\\":t.product_code,\\\\\\\"产品名称\\\\\\\":t.product_name,\\\\\\\"单位\\\\\\\":t.unit_name,\\\\\\\"可用库存\\\\\\\":t.avail,\\\\\\\"安全库存\\\\\\\":t.safety,\\\\\\\"补货量\\\\\\\":t.gap,\\\\\\\"库存满足率\\\\\\\":t.fill.map(lambda v:f\\\\\\\"{v:.4f}\\\\\\\"),\\\\\\\"是否零库存\\\\\\\":t.zero}).to_string(index=False))\\\\nprint(\\\\\\\"\\\\\\\\n-- cross-warehouse structure --\\\\\\\")\\\\nprod_low=low.groupby(\\\\\\\"product_id\\\\\\\").size()\\\\nprint(\\\\\\\"products low in n whs:\\\\\\\",prod_low.value_counts().sort_index().to_dict())\\\\n# product coverage per warehouse: how many whs each product has records in\\\\ncov=df.groupby(\\\\\\\"product_id\\\\\\\").warehouse_id.nunique()\\\\nstruct=low.groupby(\\\\\\\"product_id\\\\\\\").agg(whs=(\\\\\\\"warehouse_name\\\\\\\",lambda s:\\\\\\\"、\\\\\\\".join(sorted(s))),gap=(\\\\\\\"gap\\\\\\\",\\\\\\\"sum\\\\\\\"))\\\\nstruct=struct.join(cov.rename(\\\\\\\"stock_wh\\\\\\\"))\\\\nstruct[\\\\\\\"_\\\\\\\"]=struct.index.map(prod.set_index(\\\\\\\"product_id\\\\\\\").product_code)\\\\nstruct[\\\\\\\"__\\\\\\\"]=struct.index.map(prod.set_index(\\\\\\\"product_id\\\\\\\").product_name)\\\\nstruct[\\\\\\\"___\\\\\\\"]=struct.index.map(prod.set_index(\\\\\\\"product_id\\\\\\\").unit_name)\\\\nstruct[\\\\\\\"____\\\\\\\"]=struct.index.map(prod.set_index(\\\\\\\"product_id\\\\\\\").safety_stock_qty)/100\\\\nprint(\\\\\\\"\\\\\\\\nproducts low in ALL warehouses where they have stock (structural):\\\\\\\")\\\\nfull=struct[struct.whs.str.count(\\\\\\\"、\\\\\\\")+1==struct.stock_wh-0]\\\\nprint(len(full))\\\\nprint(full[[\\\\\\\"_\\\\\\\",\\\\\\\"__\\\\\\\",\\\\\\\"stock_wh\\\\\\\",\\\\\\\"whs\\\\\\\",\\\\\\\"gap\\\\\\\",\\\\\\\"____\\\\\\\"]].to_string())\\\\nprint(\\\\\\\"\\\\\\\\nproducts low in >=2 whs:\\\\\\\",(struct.whs.str.count(\'、\')+1>=2).sum())\\\\nout.to_csv(\\\\\\\"/tmp/erp-analysis/output/low_safety_stock_detail.csv\\\\\\\",index=False)\\\\nlow.to_pickle(\\\\\\\"/tmp/erp-analysis/output/low.pkl\\\\\\\")\\\\nprod.to_pickle(\\\\\\\"/tmp/erp-analysis/output/prod.pkl\\\\\\\"); df.to_pickle(\\\\\\\"/tmp/erp-analysis/output/df.pkl\\\\\\\")\\\\nprint(\\\\\\\"\\\\\\\\nfile saved\\\\\\\")\\\", \\\"datasetIds\\\": [\\\"ds_92ea43a53e304696a82cf1d5a0115433\\\", \\\"ds_6be2a8af3147499da930fe35db3af2b5\\\", \\\"ds_eba7e817ea47485c939c3e456972e2eb\\\", \\\"ds_b132809bf3114a80ae22a7deb192ec09\\\", \\\"ds_757f918cd11c498584e099345185423a\\\", \\\"ds_c7cc4f42fd99473ab8d6a3baddc1e303\\\"], \\\"saveResult\\\": false}\", \"callId\": \"call_6c49f7b4409c4d858ce1e4c2\"}','2026-11-22 16:27:12.880186');
