INSERT INTO `ai_agent_trace` (`id`, `user_id`, `conversation_id`, `task_id`, `agent_type`, `event_type`, `content`, `create_time`) VALUES (2149,1900000000000000001,2124418644136972290,'d7717c98-a316-4e34-af02-4f7752f7359d','ANALYSIS','TOOL_CALL','{\"name\": \"executePython\", \"text\": \"{\\\"code\\\": \\\"import pandas as pd, numpy as np\\\\npd.set_option(\\\\\\\"display.width\\\\\\\",250); pd.set_option(\\\\\\\"display.max_colwidth\\\\\\\",28)\\\\nlow=pd.read_pickle(\\\\\\\"/tmp/erp-analysis/output/low.pkl\\\\\\\"); df=pd.read_pickle(\\\\\\\"/tmp/erp-analysis/output/df.pkl\\\\\\\"); prod=pd.read_pickle(\\\\\\\"/tmp/erp-analysis/output/prod.pkl\\\\\\\")\\\\nfor d in (low,df): d[\\\\\\\"product_id\\\\\\\"]=d.product_id.astype(str)\\\\n# --- integer cross-check of gap ---\\\\nlow[\\\\\\\"gap_int_check\\\\\\\"]=(low.safety_stock_qty-(low.stock_qty-low.locked_qty))/100\\\\nprint(\\\\\\\"max diff gap vs int recompute:\\\\\\\",np.abs(low.gap-low.gap_int_check).max())\\\\nprint(\\\\\\\"avail check max diff:\\\\\\\",np.abs(low.avail-(low.stock_qty-low.locked_qty)/100).max())\\\\n# --- structural classification ---\\\\ncnt=low.groupby(\\\\\\\"product_id\\\\\\\").size()\\\\nprint(\\\\\\\"products low in >=2 warehouses:\\\\\\\",(cnt>=2).sum())\\\\ncov=df.groupby(\\\\\\\"product_id\\\\\\\").warehouse_id.nunique()\\\\nl=low.set_index(\\\\\\\"product_id\\\\\\\").join(cov.rename(\\\\\\\"stock_wh\\\\\\\"))\\\\nl[\\\\\\\"struct\\\\\\\"]=np.where(l.stock_wh==1,\\\\\\\"仅1仓有货且低于安全线(结构性)\\\\\\\",\\\\\\\"多仓经营但仅此仓低于安全线(单仓问题)\\\\\\\")\\\\nprint(l.struct.value_counts().to_dict())\\\\nprint(\\\\\\\"stock_wh distribution for low products:\\\\\\\",l.stock_wh.value_counts().to_dict())\\\\nprint(\\\\\\\"products present in 4 or 5 whs:\\\\\\\",(cov>=4).sum())\\\\nprint(\\\\\\\"all-warehouse-low products (stocked in>=4 whs and low in all):\\\\\\\",int(((cnt>=1)&(cov>=4)&(cnt>=cov)).sum()))\\\\n# --- totals ---\\\\nprint(\\\\\\\"\\\\\\\\nlow combos\\\\\\\",len(low),\\\\\\\"gap total\\\\\\\",round(low.gap.sum(),2),\\\\\\\"full-stock-out\\\\\\\",int((low.avail<=0).sum()))\\\\nprint(\\\\\\\"partial (0<fill<1):\\\\\\\",int((low.fill>0).sum()),\\\\\\\"gap sum partial:\\\\\\\",round(low.loc[low.fill>0,\'gap\'].sum(),2))\\\\n# --- partial-stock worst fill (discriminative list) ---\\\\np=low[low.fill>0].sort_values([\\\\\\\"fill\\\\\\\",\\\\\\\"gap\\\\\\\"],ascending=[True,False]).head(10)\\\\nprint(\\\\\\\"\\\\\\\\n== 满足率最低(仅部分有货) top10 ==\\\\\\\")\\\\nprint(pd.DataFrame({\\\\\\\"仓库\\\\\\\":p.warehouse_name,\\\\\\\"产品编码\\\\\\\":p.product_code,\\\\\\\"产品名称\\\\\\\":p.product_name,\\\\\\\"单位\\\\\\\":p.unit_name,\\\\\\\"可用库存\\\\\\\":p.avail,\\\\\\\"安全库存\\\\\\\":p.safety,\\\\\\\"补货量\\\\\\\":p.gap,\\\\\\\"满足率\\\\\\\":p[\\\\\\\"fill\\\\\\\"].round(4)}).to_string(index=False))\\\\n# --- 47th-113 free: rank by gap among partial ---\\\\nprint(\\\\\\\"\\\\\\\\nlowest fill values overall distinct count:\\\\\\\",low[\\\\\\\"fill\\\\\\\"].nunique(),\\\\\\\"zero-fill count:\\\\\\\",int((low.fill==0).sum()))\\\\n# --- final detail file ---\\\\nwh_order=[\\\\\\\"上海浦东中心仓\\\\\\\",\\\\\\\"广州白云分拨仓\\\\\\\",\\\\\\\"北京顺义北仓\\\\\\\",\\\\\\\"成都双流西仓\\\\\\\",\\\\\\\"武汉江夏南仓\\\\\\\"]\\\\nout=pd.DataFrame({\\\\\\\"紧急排名\\\\\\\":low[\\\\\\\"rank\\\\\\\"],\\\\\\\"仓库名称\\\\\\\":low.warehouse_name,\\\\\\\"产品编码\\\\\\\":low.product_code,\\\\\\\"产品名称\\\\\\\":low.product_name,\\\\\\\"单位\\\\\\\":low.unit_name,\\\\n \\\\\\\"当前库存数量\\\\\\\":low.stock,\\\\\\\"锁定数量\\\\\\\":low.locked,\\\\\\\"可用库存\\\\\\\":low.avail,\\\\\\\"安全库存\\\\\\\":low.safety,\\\\\\\"补货量\\\\\\\":low.gap,\\\\n \\\\\\\"库存满足率\\\\\\\":low[\\\\\\\"fill\\\\\\\"].round(4),\\\\\\\"是否零库存\\\\\\\":low.zero,\\\\\\\"结构类型\\\\\\\":l.struct.values})\\\\nout.to_csv(\\\\\\\"/tmp/erp-analysis/output/low_stock_detail_ranked.csv\\\\\\\",index=False,encoding=\\\\\\\"utf-8-sig\\\\\\\")\\\\n# warehouse summary\\\\nws=low.groupby(\\\\\\\"warehouse_name\\\\\\\").agg(低于安全线组合数=(\\\\\\\"gap\\\\\\\",\\\\\\\"size\\\\\\\"),补货量合计=(\\\\\\\"gap\\\\\\\",\\\\\\\"sum\\\\\\\"),零可用库存组合数=(\\\\\\\"zero\\\\\\\",lambda s:(s==\\\\\\\"是\\\\\\\").sum()),满足率均值=(\\\\\\\"fill\\\\\\\",\\\\\\\"mean\\\\\\\")).reindex(wh_order).round({\\\\\\\"补货量合计\\\\\\\":2,\\\\\\\"满足率均值\\\\\\\":4})\\\\nws[\\\\\\\"补货量分单位\\\\\\\"]=[low[low.warehouse_name==w].groupby(\\\\\\\"unit_name\\\\\\\").gap.sum().round(2).to_dict() for w in wh_order]\\\\nws.to_csv(\\\\\\\"/tmp/erp-analysis/output/low_stock_warehouse_summary.csv\\\\\\\",encoding=\\\\\\\"utf-8-sig\\\\\\\")\\\\nprint(\\\\\\\"\\\\\\\\n== 各仓汇总 ==\\\\\\\")\\\\nprint(ws.drop(columns=[\\\\\\\"补货量分单位\\\\\\\"]).to_string())\\\\nprint(ws[\\\\\\\"补货量分单位\\\\\\\"].to_string())\\\\nprint(\\\\\\\"\\\\\\\\n== 单位合计 ==\\\\\\\")\\\\nprint(low.assign(g=low.gap.round(2)).groupby(\\\\\\\"unit_name\\\\\\\").agg(组合数=(\\\\\\\"gap\\\\\\\",\\\\\\\"size\\\\\\\"),补货量=(\\\\\\\"g\\\\\\\",\\\\\\\"sum\\\\\\\")).sort_values(\\\\\\\"补货量\\\\\\\",ascending=False).to_string())\\\\nprint(\\\\\\\"\\\\\\\\n排名分布:\\\\\\\",low.groupby(\\\\\\\"warehouse_name\\\\\\\")[\\\\\\\"rank\\\\\\\"].apply(lambda s:f\\\\\\\"{s.min()}-{s.max()}\\\\\\\").to_dict())\\\\nprint(\\\\\\\"前20:\\\\\\\\n\\\\\\\",out.head(20).to_string(index=False))\\\", \\\"datasetIds\\\": [\\\"ds_92ea43a53e304696a82cf1d5a0115433\\\", \\\"ds_6be2a8af3147499da930fe35db3af2b5\\\", \\\"ds_eba7e817ea47485c939c3e456972e2eb\\\", \\\"ds_b132809bf3114a80ae22a7deb192ec09\\\", \\\"ds_757f918cd11c498584e099345185423a\\\", \\\"ds_c7cc4f42fd99473ab8d6a3baddc1e303\\\"], \\\"saveResult\\\": false}\", \"callId\": \"call_8082eebf5fc14e8b88d3a6af\"}','2026-11-22 16:27:35.909311');
