INSERT INTO `ai_agent_trace` (`id`, `user_id`, `conversation_id`, `task_id`, `agent_type`, `event_type`, `content`, `create_time`) VALUES (2426,1900000000000000001,2123852411582849025,'50d6f831-f227-4379-86d3-91bdea08629e','ANALYSIS','TOOL_CALL','{\"name\": \"executePython\", \"text\": \"{\\\"code\\\": \\\"import pandas as pd, json, numpy as np, os\\\\nbase=\'/tmp/erp-analysis/input/\'\\\\nspecs={\\\\n \'bill\':(\'ds_38b263873f7d4950af19f9fa51ae70cb.jsonl\',[\'id\',\'bill_no\',\'bill_type\',\'confirmed_at\',\'create_time\',\'warehouse_name\']),\\\\n \'item\':(\'ds_b34c5faa94384341b467b95d5123f6c3.jsonl\',[\'bill_id\',\'product_id\',\'product_code\',\'product_name\',\'unit_name\',\'quantity_precision\',\'qualified_qty\',\'change_qty\',\'before_qty\',\'after_qty\',\'create_time\']),\\\\n \'stock\':(\'ds_d8e997d0d4d3479e8f5485da1fb9c12a.jsonl\',[\'warehouse_id\',\'warehouse_code\',\'warehouse_name\',\'product_id\',\'product_code\',\'product_name\',\'unit_name\',\'stock_qty\',\'locked_qty\']),\\\\n \'wh\':(\'ds_f53106e7e5fe4d95bead57288fae11c6.jsonl\',[\'id\',\'warehouse_code\',\'warehouse_name\',\'status\',\'deleted\']),\\\\n \'prod\':(\'ds_abab696fbb634a3080c06d8d64918b42.jsonl\',[\'product_id\',\'product_code\',\'product_name\',\'category_id\',\'unit_name\',\'quantity_precision\',\'reference_purchase_price\',\'safety_stock_qty\',\'status\']),\\\\n \'cat\':(\'ds_6c12192f8c6745caac8b5baaea9d5b30.jsonl\',[\'category_id\',\'parent_id\',\'category_name\',\'status\',\'deleted\']),\\\\n}\\\\nd={k:pd.DataFrame([json.loads(l) for l in open(base+f) if l.strip()],columns=cols) for k,(f,cols) in specs.items()}\\\\nbill,item,stock,wh,prod,cat=[d[k] for k in [\'bill\',\'item\',\'stock\',\'wh\',\'prod\',\'cat\']]\\\\nfor c in [\'qualified_qty\',\'change_qty\',\'before_qty\',\'after_qty\']: item[c]=pd.to_numeric(item[c])\\\\nprod[\'safety_stock_qty\']=pd.to_numeric(prod[\'safety_stock_qty\'])\\\\nbill[\'confirmed_at\']=pd.to_datetime(bill[\'confirmed_at\'])\\\\n\\\\n# ---------- 1) monthly in/out ----------\\\\nm=item.merge(bill[[\'id\',\'bill_no\',\'bill_type\',\'confirmed_at\']],left_on=\'bill_id\',right_on=\'id\',how=\'left\',suffixes=(\'\',\'_b\'))\\\\nm[\'qty\']=m[\'change_qty\']/100.0\\\\nm[\'month\']=m[\'confirmed_at\'].dt.strftime(\'%Y-%m\')\\\\nmonths=[\'2026-06\',\'2026-07\',\'2026-08\',\'2026-09\',\'2026-10\',\'2026-11\']\\\\ninb=m[m[\'qty\']>0].groupby(\'month\')[\'qty\'].agg([\'sum\',\'count\'])\\\\nout=m[m[\'qty\']<0].groupby(\'month\')[\'qty\'].agg([\'sum\',\'count\'])\\\\nrows=[]\\\\nfor mo in months:\\\\n    i=inb.loc[mo] if mo in inb.index else None\\\\n    o=out.loc[mo] if mo in out.index else None\\\\n    rows.append({\'月份\':mo,\\\\n      \'入库数量\':round(i[\'sum\'],2) if i is not None else 0.0,\\\\n      \'入库凭证笔数\':int(i[\'count\']) if i is not None else 0,\\\\n      \'出库数量\':round(abs(o[\'sum\']),2) if o is not None else 0.0,\\\\n      \'出库凭证笔数\':int(o[\'count\']) if o is not None else 0,\\\\n      \'净变动\':round((i[\'sum\'] if i is not None else 0)+(o[\'sum\'] if o is not None else 0),2)})\\\\nline=pd.DataFrame(rows)\\\\nprint(line.to_string(index=False))\\\\nprint(\'max confirmed_at:\', bill[\'confirmed_at\'].max(), \' min:\', bill[\'confirmed_at\'].min())\\\\nprint(\'total in/out:\', round(m[m.qty>0][\'qty\'].sum(),2), round(abs(m[m.qty<0][\'qty\'].sum()),2))\\\\nprint(\'类型分布(明细级):\', m.groupby(\'bill_type\')[\'qty\'].agg([\'count\',\'sum\']).to_string())\\\\n# ledger continuity check: for each product/warehouse, chain of before/after? check sum change per product equals latest after? skip heavy; check before_qty==0 for first rows sample\\\\nprint(\'change_qty==qualified_qty 比例:\', (m[\'change_qty\']==m[\'qualified_qty\']).mean())\\\\n\\\\n# ---------- 2) warehouse available stock ----------\\\\nstock[\'avail\']=stock[\'stock_qty\']-stock[\'locked_qty\']\\\\nw=wh[(wh[\'status\']==1)&(wh[\'deleted\']==0)]\\\\nvalid_wh=set(w[\'id\'])\\\\ns_in=stock[stock[\'warehouse_id\'].isin(valid_wh)].copy()\\\\nprint(\'stock rows excluded by warehouse filter:\', len(stock)-len(s_in))\\\\n# product filter\\\\nvalid_prod=set(prod.loc[(prod[\'status\']==1),\'product_id\'])  # prod master already deleted=0\\\\ns_in[\'prod_ok\']=s_in[\'product_id\'].isin(valid_prod)\\\\nprint(\'stock rows with product not in valid master:\', (~s_in[\'prod_ok\']).sum())\\\\ns_f=s_in[s_in[\'prod_ok\']].copy()\\\\nbar=(s_f.groupby([\'warehouse_id\',\'warehouse_code\',\'warehouse_name\'])\\\\n       .agg(账面库存=(\'stock_qty\',\'sum\'),锁定库存=(\'locked_qty\',\'sum\'),可用库存=(\'avail\',\'sum\'),\\\\n            商品条数=(\'product_id\',\'nunique\'),记录数=(\'product_id\',\'size\'))\\\\n       .reset_index().sort_values(\'warehouse_code\'))\\\\nbar[\'账面库存\']=bar[\'账面库存\'].round(2); bar[\'锁定库存\']=bar[\'锁定库存\'].round(2); bar[\'可用库存\']=bar[\'可用库存\'].round(2)\\\\nprint(bar.to_string(index=False))\\\\nprint(\'bar totals:\', bar[[\'账面库存\',\'锁定库存\',\'可用库存\']].sum().to_dict())\\\\n\\\\n# ---------- 3) warehouse x category ----------\\\\ncmap=cat.set_index(\'category_id\')[\'category_name\'].to_dict()\\\\np=prod.set_index(\'product_id\')\\\\ns_f[\'category_id\']=s_f[\'product_id\'].map(p[\'category_id\'])\\\\ns_f[\'分类名称\']=s_f[\'category_id\'].map(cmap).fillna(\'未分类\')\\\\nstack=s_f.pivot_table(index=[\'warehouse_code\',\'warehouse_name\'],columns=\'分类名称\',values=\'stock_qty\',aggfunc=\'sum\',fill_value=0).round(2)\\\\nprint(stack.shape, \'categories:\', len(stack.columns))\\\\nprint(\'未分类数量:\', round(s_f.loc[s_f[\'分类名称\']==\'未分类\',\'stock_qty\'].sum(),2), \'记录数:\', (s_f[\'分类名称\']==\'未分类\').sum())\\\\nprint(\'pivot total:\', round(stack.values.sum(),2))\\\\nprint(\'仓库合计对齐:\', np.allclose(stack.sum(axis=1).values, bar.set_index([\'warehouse_code\',\'warehouse_name\']).loc[stack.index,\'账面库存\'].values))\\\\n\\\\n# ---------- amount ----------\\\\ns_f[\'price\']=s_f[\'product_id\'].map(p[\'reference_purchase_price\'])\\\\ns_f[\'金额\']=s_f[\'stock_qty\']*s_f[\'price\']\\\\nprint(\'库存金额参考值(元):\', round(s_f[\'金额\'].sum(),2), \' 单价缺失行:\', s_f[\'price\'].isna().sum())\\\\namt_by_wh=s_f.groupby([\'warehouse_code\',\'warehouse_name\'])[\'金额\'].sum().round(2)\\\\nprint(amt_by_wh.to_string())\\\\nprint(\'单位种类:\', sorted(s_f[\'unit_name\'].unique()), \'商品条数:\', s_f[\'product_id\'].nunique())\\\\nos.makedirs(\'/tmp/erp-analysis/output\',exist_ok=True)\\\\nline.to_csv(\'/tmp/erp-analysis/output/chart1_monthly_inout.csv\',index=False,encoding=\'utf-8-sig\')\\\\nbar.to_csv(\'/tmp/erp-analysis/output/chart2_warehouse_stock.csv\',index=False,encoding=\'utf-8-sig\')\\\\nstack.to_csv(\'/tmp/erp-analysis/output/chart3_warehouse_category_stock.csv\',encoding=\'utf-8-sig\')\\\\nlong=s_f.groupby([\'warehouse_code\',\'warehouse_name\',\'分类名称\']).agg(库存数量=(\'stock_qty\',\'sum\'),商品条数=(\'product_id\',\'nunique\'),库存金额=(\'金额\',\'sum\')).reset_index()\\\\nlong[[\'库存数量\',\'库存金额\']]=long[[\'库存数量\',\'库存金额\']].round(2)\\\\nlong.to_csv(\'/tmp/erp-analysis/output/chart3_long.csv\',index=False,encoding=\'utf-8-sig\')\\\\nprint(len(long),\'long rows\')\\\", \\\"datasetIds\\\": [\\\"ds_38b263873f7d4950af19f9fa51ae70cb\\\", \\\"ds_b34c5faa94384341b467b95d5123f6c3\\\", \\\"ds_d8e997d0d4d3479e8f5485da1fb9c12a\\\", \\\"ds_f53106e7e5fe4d95bead57288fae11c6\\\", \\\"ds_abab696fbb634a3080c06d8d64918b42\\\", \\\"ds_6c12192f8c6745caac8b5baaea9d5b30\\\"], \\\"saveResult\\\": true, \\\"outputTextName\\\": \\\"三张图表数据计算与校验\\\"}\", \"callId\": \"call_6accd7b79ca34cf7ba381681\"}','2026-11-21 02:56:52.258374');
