INSERT INTO `ai_agent_trace` (`id`, `user_id`, `conversation_id`, `task_id`, `agent_type`, `event_type`, `content`, `create_time`) VALUES (2430,1900000000000000001,2123852411582849025,'50d6f831-f227-4379-86d3-91bdea08629e','ANALYSIS','TOOL_CALL','{\"name\": \"executePython\", \"text\": \"{\\\"code\\\": \\\"import pandas as pd, json, numpy as np\\\\nbase=\'/tmp/erp-analysis/input/\'\\\\nspecs={\\\\n \'bill\':(\'ds_38b263873f7d4950af19f9fa51ae70cb.jsonl\',[\'id\',\'bill_no\',\'bill_type\',\'confirmed_at\',\'create_time\',\'warehouse_name\']),\\\\n \'item\':(\'ds_b34c5faa94384341b467b95d5123f6c3.jsonl\',[\'bill_id\',\'product_id\',\'product_code\',\'product_name\',\'unit_name\',\'quantity_precision\',\'qualified_qty\',\'change_qty\',\'before_qty\',\'after_qty\',\'create_time\']),\\\\n \'stock\':(\'ds_d8e997d0d4d3479e8f5485da1fb9c12a.jsonl\',[\'warehouse_id\',\'warehouse_code\',\'warehouse_name\',\'product_id\',\'product_code\',\'product_name\',\'unit_name\',\'stock_qty\',\'locked_qty\']),\\\\n \'prod\':(\'ds_abab696fbb634a3080c06d8d64918b42.jsonl\',[\'product_id\',\'product_code\',\'product_name\',\'category_id\',\'unit_name\',\'quantity_precision\',\'reference_purchase_price\',\'safety_stock_qty\',\'status\']),\\\\n \'cat\':(\'ds_6c12192f8c6745caac8b5baaea9d5b30.jsonl\',[\'category_id\',\'parent_id\',\'category_name\',\'status\',\'deleted\'])}\\\\nd={k:pd.DataFrame([json.loads(l) for l in open(base+f) if l.strip()],columns=cols) for k,(f,cols) in specs.items()}\\\\nbill,item,stock,prod,cat=d[\'bill\'],d[\'item\'],d[\'stock\'],d[\'prod\'],d[\'cat\']\\\\nfor c in [\'qualified_qty\',\'change_qty\',\'before_qty\',\'after_qty\']: item[c]=pd.to_numeric(item[c])\\\\nbill[\'confirmed_at\']=pd.to_datetime(bill[\'confirmed_at\'])\\\\n\\\\nm=item.merge(bill[[\'id\',\'bill_type\',\'confirmed_at\']],left_on=\'bill_id\',right_on=\'id\',how=\'left\',suffixes=(\'\',\'_b\'))\\\\n# 期初核对\\\\nfirst=m.sort_values(\'confirmed_at\').groupby(\'product_id\').first()\\\\nopening=first[\'before_qty\'].sum()/100\\\\nnet=m[\'change_qty\'].sum()/100\\\\nprint(\'期初(首笔before_qty合计):\',opening,\' 净变动:\',net,\' 推算期末:\',opening+net,\' 当前库存合计:\',stock[\'stock_qty\'].sum())\\\\nprint(\'推算与当前差:\', round(opening+net-stock[\'stock_qty\'].sum(),2))\\\\n# 每商品推算期末 vs 库存\\\\npos=(first[\'after_qty\']/100)\\\\nfor pid,after in pos.items():\\\\n    pass\\\\nlast=m.sort_values(\'confirmed_at\').groupby(\'product_id\').last()[\'after_qty\']/100\\\\ncmp=pd.DataFrame({\'last_after\':last})\\\\ncmp[\'stock\']=cmp.index.map(stock.set_index(\'product_id\')[\'stock_qty\'])\\\\ncmp[\'diff\']=(cmp[\'stock\']-cmp[\'last_after\']).round(2)\\\\nprint(\'商品数:\',len(cmp),\' 与当前库存不一致的商品数:\',(cmp[\'diff\'].abs()>0.005).sum())\\\\nprint(cmp[\'diff\'].describe().to_dict())\\\\nprint(cmp[cmp[\'diff\'].abs()>0.005].head(10).to_string())\\\", \\\"datasetIds\\\": [\\\"ds_38b263873f7d4950af19f9fa51ae70cb\\\", \\\"ds_b34c5faa94384341b467b95d5123f6c3\\\", \\\"ds_d8e997d0d4d3479e8f5485da1fb9c12a\\\", \\\"ds_abab696fbb634a3080c06d8d64918b42\\\", \\\"ds_6c12192f8c6745caac8b5baaea9d5b30\\\"], \\\"saveResult\\\": false}\", \"callId\": \"call_4d8b0874031e48d9bbe602de\"}','2026-11-21 02:57:09.324638');
INSERT INTO `ai_agent_trace` (`id`, `user_id`, `conversation_id`, `task_id`, `agent_type`, `event_type`, `content`, `create_time`) VALUES (2431,1900000000000000001,2123852411582849025,'50d6f831-f227-4379-86d3-91bdea08629e','ANALYSIS','TOOL_RESULT','{\"name\": \"executePython\", \"text\": \"{\\\"status\\\":\\\"SUCCESS\\\",\\\"textOutput\\\":{\\\"content\\\":\\\"期初(首笔before_qty合计): 1575.0  净变动: 55684.0  推算期末: 57259.0  当前库存合计: 124417.0\\\\n推算与当前差: -67158.0\\\\n商品数: 717  与当前库存不一致的商品数: 0\\\\n{\'count\': 717.0, \'mean\': 0.0, \'std\': 0.0, \'min\': 0.0, \'25%\': 0.0, \'50%\': 0.0, \'75%\': 0.0, \'max\': 0.0}\\\\nEmpty DataFrame\\\\nColumns: [last_after, stock, diff]\\\\nIndex: []\\\\n\\\",\\\"bytes\\\":360,\\\"truncated\\\":false,\\\"saved\\\":false},\\\"files\\\":[],\\\"message\\\":\\\"本次执行完成。\\\"}\", \"callId\": \"call_4d8b0874031e48d9bbe602de\"}','2026-11-21 02:57:10.020132');
INSERT INTO `ai_agent_trace` (`id`, `user_id`, `conversation_id`, `task_id`, `agent_type`, `event_type`, `content`, `create_time`) VALUES (2432,1900000000000000001,2123852411582849025,'50d6f831-f227-4379-86d3-91bdea08629e','ANALYSIS','TOOL_CALL','{\"name\": \"executePython\", \"text\": \"{\\\"code\\\": \\\"import pandas as pd, json, numpy as np, os\\\\nbase=\'/tmp/erp-analysis/input/\'\\\\nspecs={\\\\n \'bill\':(\'ds_38b263873f7d4950af19f9fa51ae70cb.jsonl\',[\'id\',\'bill_no\',\'bill_type\',\'confirmed_at\',\'create_time\',\'warehouse_name\']),\\\\n \'item\':(\'ds_b34c5faa94384341b467b95d5123f6c3.jsonl\',[\'bill_id\',\'product_id\',\'product_code\',\'product_name\',\'unit_name\',\'quantity_precision\',\'qualified_qty\',\'change_qty\',\'before_qty\',\'after_qty\',\'create_time\']),\\\\n \'stock\':(\'ds_d8e997d0d4d3479e8f5485da1fb9c12a.jsonl\',[\'warehouse_id\',\'warehouse_code\',\'warehouse_name\',\'product_id\',\'product_code\',\'product_name\',\'unit_name\',\'stock_qty\',\'locked_qty\']),\\\\n \'wh\':(\'ds_f53106e7e5fe4d95bead57288fae11c6.jsonl\',[\'id\',\'warehouse_code\',\'warehouse_name\',\'status\',\'deleted\']),\\\\n \'prod\':(\'ds_abab696fbb634a3080c06d8d64918b42.jsonl\',[\'product_id\',\'product_code\',\'product_name\',\'category_id\',\'unit_name\',\'quantity_precision\',\'reference_purchase_price\',\'safety_stock_qty\',\'status\']),\\\\n \'cat\':(\'ds_6c12192f8c6745caac8b5baaea9d5b30.jsonl\',[\'category_id\',\'parent_id\',\'category_name\',\'status\',\'deleted\'])}\\\\nd={k:pd.DataFrame([json.loads(l) for l in open(base+f) if l.strip()],columns=cols) for k,(f,cols) in specs.items()}\\\\nbill,item,stock,wh,prod,cat=d[\'bill\'],d[\'item\'],d[\'stock\'],d[\'wh\'],d[\'prod\'],d[\'cat\']\\\\nfor c in [\'qualified_qty\',\'change_qty\',\'before_qty\',\'after_qty\']: item[c]=pd.to_numeric(item[c])\\\\nbill[\'confirmed_at\']=pd.to_datetime(bill[\'confirmed_at\'])\\\\nos.makedirs(\'/tmp/erp-analysis/output\',exist_ok=True)\\\\n\\\\n# chart1\\\\nm=item.merge(bill[[\'id\',\'bill_type\',\'confirmed_at\']],left_on=\'bill_id\',right_on=\'id\',how=\'left\',suffixes=(\'\',\'_b\'))\\\\nm[\'qty\']=m[\'change_qty\']/100; m[\'month\']=m[\'confirmed_at\'].dt.strftime(\'%Y-%m\')\\\\nmonths=[\'2026-06\',\'2026-07\',\'2026-08\',\'2026-09\',\'2026-10\',\'2026-11\']\\\\ninb=m[m.qty>0].groupby(\'month\')[\'qty\'].sum(); out=m[m.qty<0].groupby(\'month\')[\'qty\'].agg(lambda s:-s.sum())\\\\nrows=[]\\\\nfor mo in months:\\\\n    rows.append({\'月份\':mo,\'入库数量\':round(inb.get(mo,0.0),2),\'出库数量\':round(out.get(mo,0.0),2),\\\\n                 \'净变动\':round(inb.get(mo,0.0)-out.get(mo,0.0),2),\\\\n                 \'入库凭证数\':int(((m.month==mo)&(m.qty>0)).sum()),\'出库凭证数\':int(((m.month==mo)&(m.qty<0)).sum()),\\\\n                 \'备注\':\'不完整月份(数据截至2026-11-21,末笔流水2026-11-08)\' if mo==\'2026-11\' else \'\'})\\\\nline=pd.DataFrame(rows); line.to_csv(\'/tmp/erp-analysis/output/chart1_monthly_inout.csv\',index=False,encoding=\'utf-8-sig\')\\\\nprint(line.to_string(index=False))\\\\n\\\\n# chart2/3 with filters documented\\\\nw=wh[(wh.status==1)&(wh.deleted==0)][[\'id\',\'warehouse_code\',\'warehouse_name\']]\\\\nvalid_p=prod[prod.status==1][\'product_id\']\\\\nexcl_wh=stock[~stock.warehouse_id.isin(w.id)]\\\\nexcl_prod=stock[stock.warehouse_id.isin(w.id)&(~stock.product_id.isin(valid_p))]\\\\ns=stock[stock.warehouse_id.isin(w.id)&(stock.product_id.isin(valid_p))].copy()\\\\ns[\'avail\']=s.stock_qty-s.locked_qty\\\\nbar=s.groupby([\'warehouse_code\',\'warehouse_name\']).agg(账面库存=(\'stock_qty\',\'sum\'),锁定库存=(\'locked_qty\',\'sum\'),可用库存=(\'avail\',\'sum\'),商品条数=(\'product_id\',\'nunique\')).reset_index().sort_values(\'warehouse_code\')\\\\nbar[[\'账面库存\',\'锁定库存\',\'可用库存\']]=bar[[\'账面库存\',\'锁定库存\',\'可用库存\']].round(2)\\\\nbar.to_csv(\'/tmp/erp-analysis/output/chart2_warehouse_stock.csv\',index=False,encoding=\'utf-8-sig\')\\\\nprint(bar.to_string(index=False)); print(\'合计:\',bar[[\'账面库存\',\'锁定库存\',\'可用库存\']].sum().round(2).to_dict())\\\\n\\\\ncmap=cat.set_index(\'category_id\')[\'category_name\'].to_dict()\\\\ns[\'category_id\']=s.product_id.map(prod.set_index(\'product_id\')[\'category_id\'])\\\\ns[\'分类名称\']=s.category_id.map(cmap).fillna(\'未分类\')\\\\ns[\'金额\']=s.stock_qty*s.product_id.map(prod.set_index(\'product_id\')[\'reference_purchase_price\'])\\\\npiv=s.pivot_table(index=[\'warehouse_code\',\'warehouse_name\'],columns=\'分类名称\',values=\'stock_qty\',aggfunc=\'sum\',fill_value=0).round(2)\\\\npiv.to_csv(\'/tmp/erp-analysis/output/chart3_warehouse_category_stock.csv\',encoding=\'utf-8-sig\')\\\\nlong=s.groupby([\'warehouse_code\',\'warehouse_name\',\'分类名称\']).agg(库存数量=(\'stock_qty\',\'sum\'),商品条数=(\'product_id\',\'nunique\'),库存金额=(\'金额\',\'sum\')).reset_index()\\\\nlong[[\'库存数量\',\'库存金额\']]=long[[\'库存数量\',\'库存金额\']].round(2)\\\\nlong.to_csv(\'/tmp/erp-analysis/output/chart3_long.csv\',index=False,encoding=\'utf-8-sig\')\\\\nprint(\'分类数:\',piv.shape[1],\'组合行数:\',len(long),\'未分类记录:\',int((s.分类名称==\'未分类\').sum()))\\\\ncattot=s.groupby(\'分类名称\').agg(库存数量=(\'stock_qty\',\'sum\'),商品条数=(\'product_id\',\'nunique\'),库存金额=(\'金额\',\'sum\')).round(2).sort_values(\'库存数量\',ascending=False)\\\\ncattot.to_csv(\'/tmp/erp-analysis/output/category_totals.csv\',encoding=\'utf-8-sig\')\\\\nprint(cattot.head(10).to_string())\\\\nprint(\'分类合计:\',round(cattot[\'库存数量\'].sum(),2),\' 金额:\',round(cattot[\'库存金额\'].sum(),2))\\\\nprint(\'校验 分类合计=仓库合计:\', np.isclose(cattot[\'库存数量\'].sum(), bar[\'账面库存\'].sum()))\\\\nprint(\'排除：禁用/删除仓库行数\',len(excl_wh),\'；禁用/删除商品行数\',len(excl_prod))\\\\nprint(\'单位清单:\',s.unit_name.unique().tolist(),\' 商品条数:\',s.product_id.nunique(),\' 库存记录数:\',len(s))\\\\nprint(\'金额(元):\',round(s[\'金额\'].sum(),2))\\\\n# duplicate category name split check\\\\ndup_ids=[k for k,v in cat[\'category_name\'].value_counts().items() if v>1]\\\\nfor n in dup_ids:\\\\n    ids=cat[cat.category_name==n][\'category_id\'].tolist()\\\\n    print(n, ids, [round(s[s.category_id==i].stock_qty.sum(),2) for i in ids])\\\\n\\\\n# 数据完整性交叉核对\\\\nprint(\'流水商品数:\',m.product_id.nunique(),\'条数:\',len(m),\'凭证数:\',bill.id.nunique())\\\\nprint(\'末笔流水时间:\',bill.confirmed_at.max())\\\", \\\"datasetIds\\\": [\\\"ds_38b263873f7d4950af19f9fa51ae70cb\\\", \\\"ds_b34c5faa94384341b467b95d5123f6c3\\\", \\\"ds_d8e997d0d4d3479e8f5485da1fb9c12a\\\", \\\"ds_f53106e7e5fe4d95bead57288fae11c6\\\", \\\"ds_abab696fbb634a3080c06d8d64918b42\\\", \\\"ds_6c12192f8c6745caac8b5baaea9d5b30\\\"], \\\"saveResult\\\": true, \\\"outputTextName\\\": \\\"最终图表数据与校验\\\"}\", \"callId\": \"call_1118e35fbe6d4da4bdfdc10f\"}','2026-11-21 02:57:20.244514');
