INSERT INTO `ai_agent_trace` (`id`, `user_id`, `conversation_id`, `task_id`, `agent_type`, `event_type`, `content`, `create_time`) VALUES (2436,1900000000000000001,2123852411582849025,'50d6f831-f227-4379-86d3-91bdea08629e','ANALYSIS','TOOL_CALL','{\"name\": \"executePython\", \"text\": \"{\\\"code\\\": \\\"import pandas as pd, json, numpy as np, os\\\\nbase=\'/tmp/erp-analysis/input/\'\\\\nd={}\\\\nfor k,(f,cols) in {\'stock\':(\'ds_d8e997d0d4d3479e8f5485da1fb9c12a.jsonl\',[\'warehouse_id\',\'warehouse_code\',\'warehouse_name\',\'product_id\',\'product_code\',\'product_name\',\'unit_name\',\'stock_qty\',\'locked_qty\']),\\\\n \'wh\':(\'ds_f53106e7e5fe4d95bead57288fae11c6.jsonl\',[\'id\',\'warehouse_code\',\'warehouse_name\',\'status\',\'deleted\']),\\\\n \'prod\':(\'ds_abab696fbb634a3080c06d8d64918b42.jsonl\',[\'product_id\',\'product_code\',\'product_name\',\'category_id\',\'unit_name\',\'quantity_precision\',\'reference_purchase_price\',\'safety_stock_qty\',\'status\']),\\\\n \'cat\':(\'ds_6c12192f8c6745caac8b5baaea9d5b30.jsonl\',[\'category_id\',\'parent_id\',\'category_name\',\'status\',\'deleted\'])}.items():\\\\n    d[k]=pd.DataFrame([json.loads(l) for l in open(base+f) if l.strip()],columns=cols)\\\\nstock,wh,prod,cat=d[\'stock\'],d[\'wh\'],d[\'prod\'],d[\'cat\']\\\\ns=stock[stock.warehouse_id.isin(wh[(wh.status==1)&(wh.deleted==0)].id)].copy()\\\\ns=s[s.product_id.isin(prod[prod.status==1].product_id)]\\\\npm=prod.set_index(\'product_id\')\\\\ns[\'分类名称\']=s.product_id.map(pm[\'category_id\']).map(cat.set_index(\'category_id\')[\'category_name\']).fillna(\'未分类\')\\\\npiv=s.pivot_table(index=[\'warehouse_code\',\'warehouse_name\'],columns=\'分类名称\',values=\'stock_qty\',aggfunc=\'sum\',fill_value=0).round(2)\\\\npiv.to_csv(\'/tmp/erp-analysis/output/chart3_warehouse_by_category_wide.csv\',encoding=\'utf-8-sig\')\\\\nlong=s.groupby([\'warehouse_code\',\'warehouse_name\',\'分类名称\'])[\'stock_qty\'].sum().reset_index().rename(columns={\'stock_qty\':\'库存数量\'}).round(2)\\\\nlong.to_csv(\'/tmp/erp-analysis/output/chart3_warehouse_by_category_long.csv\',index=False,encoding=\'utf-8-sig\')\\\\nprint(\'宽表 shape:\', piv.shape, \'合计:\', round(piv.values.sum(),2))\\\\nprint(piv.iloc[:, :8].to_string())\\\\nprint(\'列示例:\', list(piv.columns)[:5], \'...\')\\\\nprint(\'长表行数:\', len(long), \'合计:\', round(long[\'库存数量\'].sum(),2))\\\\nprint(long.head(8).to_string(index=False))\\\", \\\"datasetIds\\\": [\\\"ds_d8e997d0d4d3479e8f5485da1fb9c12a\\\", \\\"ds_f53106e7e5fe4d95bead57288fae11c6\\\", \\\"ds_abab696fbb634a3080c06d8d64918b42\\\", \\\"ds_6c12192f8c6745caac8b5baaea9d5b30\\\"], \\\"saveResult\\\": false}\", \"callId\": \"call_5fe8427e7c4f46d9a61c12ff\"}','2026-11-21 02:57:30.767725');
