INSERT INTO `ai_agent_trace` (`id`, `user_id`, `conversation_id`, `task_id`, `agent_type`, `event_type`, `content`, `create_time`) VALUES (2476,1900000000000000001,2123852411582849025,'sqlrun_1156a160cd6146329c92375d9b687a16','SQL_GENERATE','MODEL_OUTPUT','{\"sql\": \"SELECT warehouse_code AS `仓库编码`, warehouse_name AS `仓库名称`, SUM(stock_qty) / 100.0 AS `账面库存合计`, SUM(locked_qty) / 100.0 AS `锁定库存合计`, (SUM(stock_qty) - SUM(locked_qty)) / 100.0 AS `可用库存合计` FROM warehouse_stock GROUP BY warehouse_code, warehouse_name\", \"decision\": \"QUERY\", \"needFullData\": true}','2026-11-21 02:59:15.229841');
