INSERT INTO `ai_agent_trace` (`id`, `user_id`, `conversation_id`, `task_id`, `agent_type`, `event_type`, `content`, `create_time`) VALUES (3028,1900000000000000001,2124210189346299906,'sqlrun_bface6168eb94038b40916c279a77d99','SQL_GENERATE','MODEL_OUTPUT','{\"sql\": \"SELECT inbound_type AS `入库类型`, status AS `状态`, COUNT(*) AS `单数`, MIN(expected_arrival_date) AS `最早预计到货日期`, MAX(expected_arrival_date) AS `最晚预计到货日期` FROM inbound_bill WHERE deleted = 0 AND inbound_type IN (\'PURCHASE_IN\', \'SALES_RETURN\', \'ADJUST_IN\') AND status IN (\'DRAFT\', \'PENDING_CONFIRM\', \'CONFIRMED\', \'CANCELLED\') GROUP BY inbound_type, status\", \"decision\": \"QUERY\", \"needFullData\": true}','2026-11-22 02:36:23.263105');
