INSERT INTO `ai_agent_trace` (`id`, `user_id`, `conversation_id`, `task_id`, `agent_type`, `event_type`, `content`, `create_time`) VALUES (3095,1900000000000000001,2124210189346299906,'sqlrun_f7ee89ef20fc4b759ae23da6fb0e5ba3','SQL_INSPECT','MODEL_OUTPUT','{\"message\": \"已统计演示区域仓01（DEMOW01）未删除销售订单按状态分组的订单数及预计发货日期区间。结果显示该仓库当前仅有312个状态为\'OUTBOUND_DONE\'（已出库）的订单，其预计发货日期范围在2025-11-26至2026-11-06之间。由于不存在状态为\'SUBMITTED\'、\'APPROVED\'或\'PARTIAL_OUTBOUND\'等尚未完全出库的订单，表明在该仓库维度下，截至查询时刻没有待出库的销售需求。注意：此结果基于全量历史数据聚合，若需严格限定2026-11-22至2026-11-30期间的特定需求，需结合具体业务时间窗口过滤，但就“是否存在尚未出库订单”这一核心问题而言，结果为否。\", \"decision\": \"PASS\", \"dataDescription\": {\"grain\": \"每个销售订单状态一行\", \"fields\": [{\"index\": 0, \"meaning\": \"销售订单状态（英文枚举值，如 OUTBOUND_DONE 表示已出库）\"}, {\"index\": 1, \"meaning\": \"该状态下的订单数量\"}, {\"index\": 2, \"meaning\": \"该状态下订单的最早预计发货日期\"}, {\"index\": 3, \"meaning\": \"该状态下订单的最晚预计发货日期\"}], \"content\": \"演示区域仓01（DEMOW01）中所有未逻辑删除的销售订单，按订单状态分组统计的数量及预计发货日期的最小值和最大值。\", \"limitations\": \"数据包含该仓库所有历史未删除订单，未按特定时间窗口（如2026-11-22至2026-11-30）过滤订单创建或审核时间，仅通过状态判断是否有未出库订单。当前结果仅显示已出库状态，暗示无其他状态订单存在。\"}}','2026-11-22 02:37:43.089517');
INSERT INTO `ai_agent_trace` (`id`, `user_id`, `conversation_id`, `task_id`, `agent_type`, `event_type`, `content`, `create_time`) VALUES (3096,1900000000000000001,2124210189346299906,'a0ed6dff-4850-4982-bb06-c5267e5d76f1','MAIN','TOOL_RESULT','{\"name\": \"query_sql_data\", \"text\": \"{\\\"sqlRunId\\\":\\\"sqlrun_f7ee89ef20fc4b759ae23da6fb0e5ba3\\\",\\\"status\\\":\\\"SUCCESS\\\",\\\"message\\\":\\\"已统计演示区域仓01（DEMOW01）未删除销售订单按状态分组的订单数及预计发货日期区间。结果显示该仓库当前仅有312个状态为\'OUTBOUND_DONE\'（已出库）的订单，其预计发货日期范围在2025-11-26至2026-11-06之间。由于不存在状态为\'SUBMITTED\'、\'APPROVED\'或\'PARTIAL_OUTBOUND\'等尚未完全出库的订单，表明在该仓库维度下，截至查询时刻没有待出库的销售需求。注意：此结果基于全量历史数据聚合，若需严格限定2026-11-22至2026-11-30期间的特定需求，需结合具体业务时间窗口过滤，但就“是否存在尚未出库订单”这一核心问题而言，结果为否。\\\",\\\"datasetId\\\":\\\"ds_d94d72f0bbaf4829bfa23dbaa84b1f99\\\",\\\"columns\\\":[{\\\"name\\\":\\\"status\\\",\\\"label\\\":\\\"status\\\",\\\"jdbcType\\\":12,\\\"typeName\\\":\\\"VARCHAR\\\",\\\"nullable\\\":false},{\\\"name\\\":\\\"order_count\\\",\\\"label\\\":\\\"order_count\\\",\\\"jdbcType\\\":-5,\\\"typeName\\\":\\\"BIGINT\\\",\\\"nullable\\\":false},{\\\"name\\\":\\\"earliest_expected_delivery_date\\\",\\\"label\\\":\\\"earliest_expected_delivery_date\\\",\\\"jdbcType\\\":91,\\\"typeName\\\":\\\"DATE\\\",\\\"nullable\\\":true},{\\\"name\\\":\\\"latest_expected_delivery_date\\\",\\\"label\\\":\\\"latest_expected_delivery_date\\\",\\\"jdbcType\\\":91,\\\"typeName\\\":\\\"DATE\\\",\\\"nullable\\\":true}],\\\"rowCount\\\":1,\\\"completed\\\":true,\\\"truncated\\\":false,\\\"businessFullResult\\\":true,\\\"limited\\\":false,\\\"summary\\\":\\\"已统计演示区域仓01（DEMOW01）未删除销售订单按状态分组的订单数及预计发货日期区间。结果显示该仓库当前仅有312个状态为\'OUTBOUND_DONE\'（已出库）的订单，其预计发货日期范围在2025-11-26至2026-11-06之间。由于不存在状态为\'SUBMITTED\'、\'APPROVED\'或\'PARTIAL_OUTBOUND\'等尚未完全出库的订单，表明在该仓库维度下，截至查询时刻没有待出库的销售需求。注意：此结果基于全量历史数据聚合，若需严格限定2026-11-22至2026-11-30期间的特定需求，需结合具体业务时间窗口过滤，但就“是否存在尚未出库订单”这一核心问题而言，结果为否。\\\",\\\"limitations\\\":\\\"\\\",\\\"dataDescription\\\":{\\\"content\\\":\\\"演示区域仓01（DEMOW01）中所有未逻辑删除的销售订单，按订单状态分组统计的数量及预计发货日期的最小值和最大值。\\\",\\\"grain\\\":\\\"每个销售订单状态一行\\\",\\\"fields\\\":[{\\\"index\\\":0,\\\"name\\\":\\\"status\\\",\\\"meaning\\\":\\\"销售订单状态（英文枚举值，如 OUTBOUND_DONE 表示已出库）\\\"},{\\\"index\\\":1,\\\"name\\\":\\\"order_count\\\",\\\"meaning\\\":\\\"该状态下的订单数量\\\"},{\\\"index\\\":2,\\\"name\\\":\\\"earliest_expected_delivery_date\\\",\\\"meaning\\\":\\\"该状态下订单的最早预计发货日期\\\"},{\\\"index\\\":3,\\\"name\\\":\\\"latest_expected_delivery_date\\\",\\\"meaning\\\":\\\"该状态下订单的最晚预计发货日期\\\"}],\\\"limitations\\\":\\\"数据包含该仓库所有历史未删除订单，未按特定时间窗口（如2026-11-22至2026-11-30）过滤订单创建或审核时间，仅通过状态判断是否有未出库订单。当前结果仅显示已出库状态，暗示无其他状态订单存在。\\\"},\\\"preview\\\":{\\\"message\\\":\\\"预览包含数据集全部行。\\\",\\\"containsAllRows\\\":true,\\\"rows\\\":[[\\\"OUTBOUND_DONE\\\",\\\"312\\\",\\\"2025-11-26\\\",\\\"2026-11-06\\\"]],\\\"returnedRows\\\":1,\\\"datasetRows\\\":1}}\", \"callId\": \"call_c6b62af235d543ccad7cdc54\"}','2026-11-22 02:37:43.268257');
INSERT INTO `ai_agent_trace` (`id`, `user_id`, `conversation_id`, `task_id`, `agent_type`, `event_type`, `content`, `create_time`) VALUES (3097,1900000000000000001,2124210189346299906,'a0ed6dff-4850-4982-bb06-c5267e5d76f1','MAIN','MODEL_OUTPUT','{\"text\": \"该仓也没有待出库销售订单。我再核实是否存在“已下单但尚有数量未到货”的采购明细，这是晚到批次最可能的落点。\"}','2026-11-22 02:37:48.180563');
INSERT INTO `ai_agent_trace` (`id`, `user_id`, `conversation_id`, `task_id`, `agent_type`, `event_type`, `content`, `create_time`) VALUES (3098,1900000000000000001,2124210189346299906,'a0ed6dff-4850-4982-bb06-c5267e5d76f1','MAIN','TOOL_CALL','{\"name\": \"query_sql_data\", \"text\": \"{\\\"requirement\\\": {\\\"dataRequirement\\\": \\\"FULL\\\", \\\"expectedFields\\\": [\\\"采购单号\\\", \\\"产品编码\\\", \\\"产品名称\\\", \\\"单位\\\", \\\"采购数量\\\", \\\"已入库数量\\\", \\\"未到货数量\\\", \\\"预计到货日期\\\"], \\\"goal\\\": \\\"查询演示区域仓 01（DEMOW01）下所有未删除且未取消采购订单中存在未到货数量的明细行（已入库数量小于采购数量），列出采购单号、产品、采购数量、已入库数量、未到货数量和预计到货日期，用于核定是否存在晚到的在途采购批次\\\", \\\"grain\\\": \\\"每条采购订单明细一行\\\", \\\"purpose\\\": \\\"核实是否存在已下单但尚未完全到货的在途采购\\\"}}\", \"callId\": \"call_096dd577918647228fc65967\"}','2026-11-22 02:37:48.184589');
INSERT INTO `ai_agent_trace` (`id`, `user_id`, `conversation_id`, `task_id`, `agent_type`, `event_type`, `content`, `create_time`) VALUES (3099,1900000000000000001,2124210189346299906,'sqlrun_3db3efe8e8574b8c95d635d46e158354','SQL_GENERATE','INPUT','{\"feedback\": \"\", \"pageSize\": 200, \"timeZone\": \"Asia/Shanghai\", \"currentDate\": \"2026-11-22\", \"previousSql\": \"\", \"requirement\": {\"goal\": \"查询演示区域仓 01（DEMOW01）下所有未删除且未取消采购订单中存在未到货数量的明细行（已入库数量小于采购数量），列出采购单号、产品、采购数量、已入库数量、未到货数量和预计到货日期，用于核定是否存在晚到的在途采购批次\", \"grain\": \"每条采购订单明细一行\", \"purpose\": \"核实是否存在已下单但尚未完全到货的在途采购\", \"expectedFields\": [\"采购单号\", \"产品编码\", \"产品名称\", \"单位\", \"采购数量\", \"已入库数量\", \"未到货数量\", \"预计到货日期\"], \"dataRequirement\": \"FULL\"}, \"supplements\": [], \"maxTotalRows\": 2000, \"schemaFingerprint\": \"8478e668ddad58adf8e5be7f317aee3f005d298092a4c5de9e147cb0635a8e53\"}','2026-11-22 02:37:48.250585');
INSERT INTO `ai_agent_trace` (`id`, `user_id`, `conversation_id`, `task_id`, `agent_type`, `event_type`, `content`, `create_time`) VALUES (3100,1900000000000000001,2124210189346299906,'sqlrun_3db3efe8e8574b8c95d635d46e158354','SQL_GENERATE','MODEL_OUTPUT','{\"sql\": \"SELECT po.purchase_no AS purchase_order_no, poi.product_code AS product_code, poi.product_name AS product_name, poi.unit_name AS unit_name, poi.quantity / 100.0 AS purchase_qty, poi.inbound_qty / 100.0 AS inbound_qty, (poi.quantity - poi.inbound_qty) / 100.0 AS pending_arrival_qty, po.expected_arrival_date AS expected_arrival_date FROM purchase_order po JOIN purchase_order_item poi ON po.id = poi.purchase_order_id JOIN warehouse w ON po.warehouse_id = w.id WHERE w.warehouse_code = \'DEMOW01\' AND w.deleted = 0 AND po.deleted = 0 AND po.status NOT IN (\'DRAFT\', \'CANCELLED\') AND poi.quantity > poi.inbound_qty\", \"decision\": \"QUERY\", \"needFullData\": true}','2026-11-22 02:37:52.529307');
INSERT INTO `ai_agent_trace` (`id`, `user_id`, `conversation_id`, `task_id`, `agent_type`, `event_type`, `content`, `create_time`) VALUES (3101,1900000000000000001,2124210189346299906,'sqlrun_3db3efe8e8574b8c95d635d46e158354','SQL_INSPECT','INPUT','{\"sql\": \"SELECT po.purchase_no AS purchase_order_no, poi.product_code AS product_code, poi.product_name AS product_name, poi.unit_name AS unit_name, poi.quantity / 100.0 AS purchase_qty, poi.inbound_qty / 100.0 AS inbound_qty, (poi.quantity - poi.inbound_qty) / 100.0 AS pending_arrival_qty, po.expected_arrival_date AS expected_arrival_date FROM purchase_order po JOIN purchase_order_item poi ON po.id = poi.purchase_order_id JOIN warehouse w ON po.warehouse_id = w.id WHERE w.warehouse_code = \'DEMOW01\' AND w.deleted = 0 AND po.deleted = 0 AND po.status NOT IN (\'DRAFT\', \'CANCELLED\') AND poi.quantity > poi.inbound_qty\", \"columns\": [{\"name\": \"purchase_no\", \"label\": \"purchase_order_no\", \"jdbcType\": 12, \"nullable\": false, \"typeName\": \"VARCHAR\"}, {\"name\": \"product_code\", \"label\": \"product_code\", \"jdbcType\": 12, \"nullable\": false, \"typeName\": \"VARCHAR\"}, {\"name\": \"product_name\", \"label\": \"product_name\", \"jdbcType\": 12, \"nullable\": false, \"typeName\": \"VARCHAR\"}, {\"name\": \"unit_name\", \"label\": \"unit_name\", \"jdbcType\": 12, \"nullable\": false, \"typeName\": \"VARCHAR\"}, {\"name\": \"purchase_qty\", \"label\": \"purchase_qty\", \"jdbcType\": 3, \"nullable\": true, \"typeName\": \"DECIMAL\"}, {\"name\": \"inbound_qty\", \"label\": \"inbound_qty\", \"jdbcType\": 3, \"nullable\": true, \"typeName\": \"DECIMAL\"}, {\"name\": \"pending_arrival_qty\", \"label\": \"pending_arrival_qty\", \"jdbcType\": 3, \"nullable\": true, \"typeName\": \"DECIMAL\"}, {\"name\": \"expected_arrival_date\", \"label\": \"expected_arrival_date\", \"jdbcType\": 91, \"nullable\": true, \"typeName\": \"DATE\"}], \"rowCount\": 0, \"timeZone\": \"Asia/Shanghai\", \"completed\": true, \"sampleRows\": [], \"currentDate\": \"2026-11-22\", \"limitations\": \"\", \"requirement\": {\"goal\": \"查询演示区域仓 01（DEMOW01）下所有未删除且未取消采购订单中存在未到货数量的明细行（已入库数量小于采购数量），列出采购单号、产品、采购数量、已入库数量、未到货数量和预计到货日期，用于核定是否存在晚到的在途采购批次\", \"grain\": \"每条采购订单明细一行\", \"purpose\": \"核实是否存在已下单但尚未完全到货的在途采购\", \"expectedFields\": [\"采购单号\", \"产品编码\", \"产品名称\", \"单位\", \"采购数量\", \"已入库数量\", \"未到货数量\", \"预计到货日期\"], \"dataRequirement\": \"FULL\"}, \"supplements\": [], \"needFullData\": true, \"schemaFingerprint\": \"8478e668ddad58adf8e5be7f317aee3f005d298092a4c5de9e147cb0635a8e53\"}','2026-11-22 02:37:52.749656');
INSERT INTO `ai_agent_trace` (`id`, `user_id`, `conversation_id`, `task_id`, `agent_type`, `event_type`, `content`, `create_time`) VALUES (3102,1900000000000000001,2124210189346299906,'sqlrun_3db3efe8e8574b8c95d635d46e158354','SQL_INSPECT','MODEL_OUTPUT','{\"message\": \"查询成功执行，返回0行数据。SQL逻辑正确筛选了演示区域仓DEMOW01下未删除、未取消且存在未到货数量（采购数量>已入库数量）的采购订单明细。结果为空表示当前该仓库下没有符合条件的在途采购批次，属于合法业务结果。\", \"decision\": \"PASS\", \"dataDescription\": {\"grain\": \"每条采购订单明细一行\", \"fields\": [{\"index\": 0, \"meaning\": \"采购单号\"}, {\"index\": 1, \"meaning\": \"产品编码\"}, {\"index\": 2, \"meaning\": \"产品名称\"}, {\"index\": 3, \"meaning\": \"单位\"}, {\"index\": 4, \"meaning\": \"采购数量（业务数值，已除以100还原）\"}, {\"index\": 5, \"meaning\": \"已入库数量（业务数值，已除以100还原）\"}, {\"index\": 6, \"meaning\": \"未到货数量（业务数值，已除以100还原，等于采购数量减已入库数量）\"}, {\"index\": 7, \"meaning\": \"预计到货日期\"}], \"content\": \"演示区域仓 DEMOW01 中状态非草稿/取消、且存在未到货数量（已入库量 < 采购量）的采购订单明细列表。用于核定是否存在晚到的在途采购批次。\", \"limitations\": \"\"}}','2026-11-22 02:37:59.687937');
INSERT INTO `ai_agent_trace` (`id`, `user_id`, `conversation_id`, `task_id`, `agent_type`, `event_type`, `content`, `create_time`) VALUES (3103,1900000000000000001,2124210189346299906,'a0ed6dff-4850-4982-bb06-c5267e5d76f1','MAIN','TOOL_RESULT','{\"name\": \"query_sql_data\", \"text\": \"{\\\"sqlRunId\\\":\\\"sqlrun_3db3efe8e8574b8c95d635d46e158354\\\",\\\"status\\\":\\\"SUCCESS\\\",\\\"message\\\":\\\"查询成功执行，返回0行数据。SQL逻辑正确筛选了演示区域仓DEMOW01下未删除、未取消且存在未到货数量（采购数量>已入库数量）的采购订单明细。结果为空表示当前该仓库下没有符合条件的在途采购批次，属于合法业务结果。\\\",\\\"datasetId\\\":\\\"ds_56056028842f4a5db296a1296af739be\\\",\\\"columns\\\":[{\\\"name\\\":\\\"purchase_no\\\",\\\"label\\\":\\\"purchase_order_no\\\",\\\"jdbcType\\\":12,\\\"typeName\\\":\\\"VARCHAR\\\",\\\"nullable\\\":false},{\\\"name\\\":\\\"product_code\\\",\\\"label\\\":\\\"product_code\\\",\\\"jdbcType\\\":12,\\\"typeName\\\":\\\"VARCHAR\\\",\\\"nullable\\\":false},{\\\"name\\\":\\\"product_name\\\",\\\"label\\\":\\\"product_name\\\",\\\"jdbcType\\\":12,\\\"typeName\\\":\\\"VARCHAR\\\",\\\"nullable\\\":false},{\\\"name\\\":\\\"unit_name\\\",\\\"label\\\":\\\"unit_name\\\",\\\"jdbcType\\\":12,\\\"typeName\\\":\\\"VARCHAR\\\",\\\"nullable\\\":false},{\\\"name\\\":\\\"purchase_qty\\\",\\\"label\\\":\\\"purchase_qty\\\",\\\"jdbcType\\\":3,\\\"typeName\\\":\\\"DECIMAL\\\",\\\"nullable\\\":true},{\\\"name\\\":\\\"inbound_qty\\\",\\\"label\\\":\\\"inbound_qty\\\",\\\"jdbcType\\\":3,\\\"typeName\\\":\\\"DECIMAL\\\",\\\"nullable\\\":true},{\\\"name\\\":\\\"pending_arrival_qty\\\",\\\"label\\\":\\\"pending_arrival_qty\\\",\\\"jdbcType\\\":3,\\\"typeName\\\":\\\"DECIMAL\\\",\\\"nullable\\\":true},{\\\"name\\\":\\\"expected_arrival_date\\\",\\\"label\\\":\\\"expected_arrival_date\\\",\\\"jdbcType\\\":91,\\\"typeName\\\":\\\"DATE\\\",\\\"nullable\\\":true}],\\\"rowCount\\\":0,\\\"completed\\\":true,\\\"truncated\\\":false,\\\"businessFullResult\\\":true,\\\"limited\\\":false,\\\"summary\\\":\\\"查询成功执行，返回0行数据。SQL逻辑正确筛选了演示区域仓DEMOW01下未删除、未取消且存在未到货数量（采购数量>已入库数量）的采购订单明细。结果为空表示当前该仓库下没有符合条件的在途采购批次，属于合法业务结果。\\\",\\\"limitations\\\":\\\"\\\",\\\"dataDescription\\\":{\\\"content\\\":\\\"演示区域仓 DEMOW01 中状态非草稿/取消、且存在未到货数量（已入库量 < 采购量）的采购订单明细列表。用于核定是否存在晚到的在途采购批次。\\\",\\\"grain\\\":\\\"每条采购订单明细一行\\\",\\\"fields\\\":[{\\\"index\\\":0,\\\"name\\\":\\\"purchase_order_no\\\",\\\"meaning\\\":\\\"采购单号\\\"},{\\\"index\\\":1,\\\"name\\\":\\\"product_code\\\",\\\"meaning\\\":\\\"产品编码\\\"},{\\\"index\\\":2,\\\"name\\\":\\\"product_name\\\",\\\"meaning\\\":\\\"产品名称\\\"},{\\\"index\\\":3,\\\"name\\\":\\\"unit_name\\\",\\\"meaning\\\":\\\"单位\\\"},{\\\"index\\\":4,\\\"name\\\":\\\"purchase_qty\\\",\\\"meaning\\\":\\\"采购数量（业务数值，已除以100还原）\\\"},{\\\"index\\\":5,\\\"name\\\":\\\"inbound_qty\\\",\\\"meaning\\\":\\\"已入库数量（业务数值，已除以100还原）\\\"},{\\\"index\\\":6,\\\"name\\\":\\\"pending_arrival_qty\\\",\\\"meaning\\\":\\\"未到货数量（业务数值，已除以100还原，等于采购数量减已入库数量）\\\"},{\\\"index\\\":7,\\\"name\\\":\\\"expected_arrival_date\\\",\\\"meaning\\\":\\\"预计到货日期\\\"}],\\\"limitations\\\":\\\"\\\"},\\\"preview\\\":{\\\"message\\\":\\\"预览包含数据集全部行。\\\",\\\"containsAllRows\\\":true,\\\"rows\\\":[],\\\"returnedRows\\\":0,\\\"datasetRows\\\":0}}\", \"callId\": \"call_096dd577918647228fc65967\"}','2026-11-22 02:37:59.907103');
INSERT INTO `ai_agent_trace` (`id`, `user_id`, `conversation_id`, `task_id`, `agent_type`, `event_type`, `content`, `create_time`) VALUES (3104,1900000000000000001,2124210189346299906,'a0ed6dff-4850-4982-bb06-c5267e5d76f1','MAIN','MODEL_OUTPUT','{\"text\": \"该仓同样没有未到货的采购明细。现在把“演示区域仓 01 + 全部产品 + 覆盖到 2026-11-30 + 期末不低于安全库存”的计算交给分析专家，重点检查当前缺口和现有库存能覆盖到什么时候。\"}','2026-11-22 02:38:06.974048');
INSERT INTO `ai_agent_trace` (`id`, `user_id`, `conversation_id`, `task_id`, `agent_type`, `event_type`, `content`, `create_time`) VALUES (3105,1900000000000000001,2124210189346299906,'a0ed6dff-4850-4982-bb06-c5267e5d76f1','MAIN','TOOL_CALL','{\"name\": \"analyzeData\", \"text\": \"{\\\"goal\\\": \\\"评估演示区域仓 01（warehouse_code=DEMOW01）在\\\\\\\"一批采购晚到\\\\\\\"情形下，现有库存能否接上。需要产出：1）该仓每个产品的当前库存数量、锁定数量、可用库存，与产品安全库存对比，逐条列出当前缺口（安全库存 - 可用库存，为正表示已经低于安全线）以及是否低于安全库存的标记；2）按近期真实出库速度估算每个产品的库存可支撑天数，并判断在\\\\\\\"该批采购到货日之前\\\\\\\"或\\\\\\\"到 2026-11-30 期末\\\\\\\"时点是否会出现断货或跌破安全库存，给出首次缺口日期；3）汇总层面：该仓有多少个产品已低于安全库存、合计缺口数量、断货风险评估。数量字段均按 100 倍整数存储，计算前需除以 100 还原；不同计量单位的产品严禁跨单位相加，如需汇总请分组按单位统计或折算金额；安全库存为 NULL 不可视为 0，需单独标记为\\\\\\\"无安全库存基准\\\\\\\"。需求来源说明：该仓当前没有任何未出库的销售订单，也没有在途采购，因此未来需求只能用历史出库事实测算，必须明确标注为\\\\\\\"基于历史出库速度的估算，非客户订单承诺\\\\\\\"。\\\", \\\"context\\\": \\\"已确认范围（用户选定）：仓库=演示区域仓 01（DEMOW01）；产品=该仓全部产品；评估期间=当前业务日期 2026-11-22 至 2026-11-30；期末目标=期末库存不低于安全库存。已核实事实：1）全系统未删除采购订单 1560 张，状态全部为 INBOUND_DONE（完全入库），不存在任何 APPROVED/PARTIAL_INBOUND/SUBMITTED 在途采购；2）全系统未删除采购入库单 1560 张也全部为 CONFIRMED；3）DEMOW01 下不存在已入库数量小于采购数量的采购明细行；4）DEMOW01 未删除销售订单 312 张全部为 OUTBOUND_DONE，无待出库订单。因此\\\\\\\"晚到的采购批次\\\\\\\"在系统内无单据可查，本次评估只能以现有库存对照安全库存和近期出库速度来判断承接能力。可用数据表：warehouse_stock（按100倍整数存储 stock_qty、locked_qty，可用=stock_qty-locked_qty）、product（safety_stock_qty 同口径按100倍存储，quantity_precision 为数量小数位，reference_purchase_price 用于金额折算）、stock_bill / stock_bill_item（已确认库存流水，change_qty 入库为正出库为负，confirmed_at 为确认时间，可用于统计近期实际出库量）。经验提示：多表 JOIN 容易导致查询失败，建议拆分为单表查询后在内存合并。\\\"}\", \"callId\": \"call_93c8651450a74f978508a3e7\"}','2026-11-22 02:38:06.978571');
INSERT INTO `ai_agent_trace` (`id`, `user_id`, `conversation_id`, `task_id`, `agent_type`, `event_type`, `content`, `create_time`) VALUES (3106,1900000000000000001,2124210189346299906,'41e82804-c9e3-424a-b917-0fc3228f7c5c','ANALYSIS','INPUT','{\"text\": \"评估演示区域仓 01（warehouse_code=DEMOW01）在\\\"一批采购晚到\\\"情形下，现有库存能否接上。需要产出：1）该仓每个产品的当前库存数量、锁定数量、可用库存，与产品安全库存对比，逐条列出当前缺口（安全库存 - 可用库存，为正表示已经低于安全线）以及是否低于安全库存的标记；2）按近期真实出库速度估算每个产品的库存可支撑天数，并判断在\\\"该批采购到货日之前\\\"或\\\"到 2026-11-30 期末\\\"时点是否会出现断货或跌破安全库存，给出首次缺口日期；3）汇总层面：该仓有多少个产品已低于安全库存、合计缺口数量、断货风险评估。数量字段均按 100 倍整数存储，计算前需除以 100 还原；不同计量单位的产品严禁跨单位相加，如需汇总请分组按单位统计或折算金额；安全库存为 NULL 不可视为 0，需单独标记为\\\"无安全库存基准\\\"。需求来源说明：该仓当前没有任何未出库的销售订单，也没有在途采购，因此未来需求只能用历史出库事实测算，必须明确标注为\\\"基于历史出库速度的估算，非客户订单承诺\\\"。\"}','2026-11-22 02:38:07.463673');
INSERT INTO `ai_agent_trace` (`id`, `user_id`, `conversation_id`, `task_id`, `agent_type`, `event_type`, `content`, `create_time`) VALUES (3107,1900000000000000001,2124210189346299906,'41e82804-c9e3-424a-b917-0fc3228f7c5c','ANALYSIS','TOOL_CALL','{\"name\": \"read_skill\", \"text\": \"{\\\"skill_name\\\": \\\"replenishment\\\"}\", \"callId\": \"call_996453085a93470f9f8b2382\"}','2026-11-22 02:38:10.082157');
INSERT INTO `ai_agent_trace` (`id`, `user_id`, `conversation_id`, `task_id`, `agent_type`, `event_type`, `content`, `create_time`) VALUES (3108,1900000000000000001,2124210189346299906,'41e82804-c9e3-424a-b917-0fc3228f7c5c','ANALYSIS','TOOL_RESULT','{\"name\": \"read_skill\", \"text\": \"\\\"# 补货计算\\\\n\\\\n## 能算出的结果\\\\n\\\\n| 结果 | 需要的数据 | 算法 | 输出 |\\\\n|---|---|---|---|\\\\n| 可用量 | 账面库存、仓储锁定 | H − R | A |\\\\n| 安全线差额 | 可用量、安全库存 | max(0, S − A) | G |\\\\n| 逐日需求 | 历史出库、锁定订单 | 移动平均、指数平滑、趋势、Croston | D(t) |\\\\n| 逐日余额 | 可用量、在途、逐日需求 | 滚动累加 | PAB(t) |\\\\n| 首次缺口 | 逐日余额 | 第一个负值 | 日期和数量 |\\\\n| 净补货量 | 期间需求、期末目标、可用量、在途 | 期末目标 − 可用 − 在途 + 需求 | Q |\\\\n| 安全库存 | 需求波动、交期波动 | max/min 或服务水平 Z 值 | SS |\\\\n| 经济批量 | 年需求、订货成本、持有成本 | EOQ | 批量 |\\\\n\\\\n## 算法选择\\\\n\\\\n- 需求平稳：移动平均 3 到 7 期，或指数平滑 α 0.2 到 0.4\\\\n- 有明显趋势：Holt 线性趋势\\\\n- 有季节性：Holt-Winters\\\\n- 间歇性需求、大量零值：Croston\\\\n- 历史不足 3 到 4 期：返回数据不足，不给预测\\\\n- 有服务水平要求和足够数据：Z 值法算安全库存\\\\n- 只有观测到的最大最小值：max/min 法\\\\n- 批量：EOQ 只作基准，最终按 MOQ 和数量精度取整\\\\n\\\\n预测方法的公式、参数和历史长度要求见 `references/forecasting.md`。\\\\n滚动余额、单批补救、取整和安全库存公式见 `references/inventory-calc.md`。\\\\n需要具体计算时先读取对应文件。\\\\n\\\\n## 计算步骤\\\\n\\\\n### 当前缺口\\\\n\\\\n1. 数量按库内值还原：库存、锁定、订单都除以 100；产品参考价是元，不再除\\\\n2. 可用量 A = H − R\\\\n   - H 或 R 缺失：该行标记未确认，不按零处理\\\\n   - A 小于 0，或 R 大于 H：停止对该行承诺可用量，其他正常行继续\\\\n3. 差额 G = max(0, S − A)\\\\n4. 分支：\\\\n   - A 大于 S：未低于安全线，G = 0\\\\n   - 0 小于 A 且 A 不大于 S：列低库存提示和 G\\\\n   - A 等于 0：说明没有未占用库存\\\\n   - S 缺失：只给 A，说明无法判断安全线差额\\\\n\\\\n输出：仓品差额表，列仓库、产品、单位、快照时点、H、R、A、S、G、异常说明。\\\\n\\\\n### 未来缺口\\\\n\\\\n1. 逐日需求：有总预测 F 和已锁定销售 C 时，D = max(0, F − C)；预测已排除订单时直接用 F\\\\n2. 从当前快照逐日滚动余额，可达到货只加当天可达且未被其他动作占用的量\\\\n3. 找第一个负值，记录日期和金额\\\\n4. 净补货量 = max(0, 期间新增需求合计 + 期末目标 − A − 期间可达到货)\\\\n\\\\n滚动公式和边界处理见 `references/inventory-calc.md`。\\\\n\\\\n### 到货延迟\\\\n\\\\n1. 未收量按明细算：订单数量 − 已入库数量\\\\n2. 按预计到货日排入日表，日期已过或失约的单列待确认，保守情景不计\\\\n3. 重新滚动余额，找最早未覆盖的日期\\\\n4. 单批补救时先检查更早的时点是否还有缺口\\\\n\\\\n单批补救公式见 `references/inventory-calc.md`。\\\\n\\\\n## 数据不足时\\\\n\\\\n- 安全库存缺失：只报可用量，不判断是否低于安全线\\\\n- 历史不足：返回数据不足，不给预测\\\\n- 到货日期缺失：给确定和不确定两张日表，不写保证不断供\\\\n- 数量精度缺失：不取整，标注未取整\\\\n\\\\n## 验证门\\\\n\\\\n- A = H − R，且 A 不小于 0；R 大于 H 时该行异常\\\\n- A 大于 S 时 G 必须为 0\\\\n- 逐日需求合计必须等于逐日明细之和，用第二种方式复算\\\\n- 首次缺口日之前余额不能为负，之后才允许\\\\n- 净补货量为 0 也要单独检查首次缺口，总量够不等于中途不断供\\\\n- 取整后重算金额和期末余量\\\\n\\\\n## 输出格式\\\\n\\\\n按顺序返回，没有的写未提供：\\\\n\\\\n1. 口径：范围、期间、期末目标、数据来源和快照时点\\\\n2. 当前状态：H、R、A、S、G\\\\n3. 时间线：逐日余额表，包含日期、当日需求、当日到货、余额\\\\n4. 首次缺口：日期和数量，全期无缺口写无\\\\n5. 净补货量：覆盖了哪些日期、哪些日期仍覆盖不到\\\\n6. 限制：缺失数据、假设参数、到货依据\\\"\", \"callId\": \"call_996453085a93470f9f8b2382\"}','2026-11-22 02:38:10.093032');
INSERT INTO `ai_agent_trace` (`id`, `user_id`, `conversation_id`, `task_id`, `agent_type`, `event_type`, `content`, `create_time`) VALUES (3109,1900000000000000001,2124210189346299906,'41e82804-c9e3-424a-b917-0fc3228f7c5c','ANALYSIS','TOOL_CALL','{\"name\": \"readSkillFile\", \"text\": \"{\\\"skill\\\": \\\"replenishment\\\", \\\"path\\\": \\\"references/inventory-calc.md\\\"}\", \"callId\": \"call_92ea80ef23524cc98f5f34d1\"}','2026-11-22 02:38:13.841747');
INSERT INTO `ai_agent_trace` (`id`, `user_id`, `conversation_id`, `task_id`, `agent_type`, `event_type`, `content`, `create_time`) VALUES (3110,1900000000000000001,2124210189346299906,'41e82804-c9e3-424a-b917-0fc3228f7c5c','ANALYSIS','TOOL_RESULT','{\"name\": \"readSkillFile\", \"text\": \"\\\"# 库存与缺口计算\\\\n\\\\n## 数量与金额口径\\\\n\\\\n| 输入 | 库内口径 | 进入计算 |\\\\n|---|---|---|\\\\n| 库存、锁定、订单数量 | 真实数量 × 100 | 除以 100 |\\\\n| 交易单价、金额 | 分 | 除以 100 |\\\\n| 产品参考价 | 元 | 直接用 |\\\\n| 评分 | 真实分值 × 100 | 除以 100 |\\\\n\\\\n- 历史数据用当时的单据快照，不用新精度改写旧单\\\\n- 缺失值不按零处理，单独标记\\\\n\\\\n## 可用量\\\\n\\\\n```text\\\\nA = H − R\\\\n```\\\\n\\\\n- H：账面库存\\\\n- R：仓储锁定\\\\n- R 大于 H 或 A 为负：该行停止承诺可用量，其他正常行继续\\\\n- 余额没有质量分桶，不能用历史次品量推算当前不可售量\\\\n\\\\n## 安全线差额\\\\n\\\\n```text\\\\nG = max(0, S − A)\\\\n```\\\\n\\\\n- S：产品安全库存\\\\n- A 大于 S 时 G 必须为 0\\\\n- S 缺失时只给 A，不判断差额\\\\n\\\\n## 逐日新增需求\\\\n\\\\n```text\\\\n有总预测 F(t) 且已锁定销售 C(t)：\\\\n  D(t) = max(0, F(t) − C(t))\\\\n\\\\n预测已排除订单：\\\\n  D(t) = F(t)\\\\n```\\\\n\\\\n- 期间合计是逐日相加，不能用期间总预测减期间总锁定一次相减\\\\n- 同一订单只扣一次，不在 A 和 C(t) 两处重复扣减\\\\n\\\\n## 逐日滚动余额\\\\n\\\\n```text\\\\nPAB(t) = A + Σ I(≤t) − Σ D(≤t)\\\\n```\\\\n\\\\n- I(≤t)：截至当天可达到货，只加未被其他动作占用的量\\\\n- 未来到货放在可达当天，不能倒填更早的缺口\\\\n- 余额为负表示未覆盖需求，不是允许的负库存\\\\n- 分析未来月份时，先衔接现在到月初的供需，不能把今天余额直接当月初余额\\\\n\\\\n## 首次缺口\\\\n\\\\n第一个 PAB(t) 小于 0 的日期，缺口量为该日余额的绝对值。\\\\n\\\\n跨期检查时，首次缺口只报告一次，不重复列出之后的连续负值。\\\\n\\\\n## 净补货量\\\\n\\\\n```text\\\\nQ = max(0, D_h + S_end − A − I_h)\\\\n```\\\\n\\\\n- D_h：期间新增需求合计\\\\n- S_end：期末目标\\\\n- I_h：期间内可达到货合计\\\\n- Q 为 0 不代表中途没有缺口，必须单独检查首次缺口日\\\\n- Q 只解决期末目标，不包含救急量；救急需求单独计算\\\\n\\\\n## 安全库存\\\\n\\\\n### max/min 法\\\\n\\\\n```text\\\\nSS = max_daily × max_lead − avg_daily × avg_lead\\\\nR = avg_daily × avg_lead + SS\\\\n```\\\\n\\\\n- 输入：观测到的日均和日最大需求、交期均值和最大值\\\\n- 适用：数据有限，需要一个保守估计\\\\n- 局限：只反映历史极值，不反映分布；极值异常时会明显偏大\\\\n\\\\n### 服务水平法\\\\n\\\\n```text\\\\nSS = Z × σd × √L\\\\n```\\\\n\\\\n- Z 与服务水平的对应：90% 约 1.28，95% 约 1.65，99% 约 2.33\\\\n- σd：日需求标准差，L：交期天数\\\\n- 需求稳定但交期波动时，改用 σL 项\\\\n- 需求和交期都波动时：\\\\n\\\\n```text\\\\nSS = Z × √(L × σd² + avg_daily² × σL²)\\\\n```\\\\n\\\\n- 输入：至少 8 到 12 期需求、交期记录\\\\n- 适用：用户明确提出服务水平且有足够数据\\\\n- 局限：数据不足时估计不可靠，应退回 max/min 法并说明\\\\n\\\\n## 起订量与取整\\\\n\\\\n- 取整步长 = 10 的负 quantity_precision 次方\\\\n- 满足最低需求时向上取整，不超过上限时向下取整\\\\n- MOQ 是下限，不是包装倍数\\\\n- 取整后必须重算金额和期末余量\\\\n- 最低所需量大于实际上限时，该候选不成立，不能削量后声称足量\\\\n\\\\n## 单批补救量\\\\n\\\\n单批在 τ 时点可用，其他供应和需求固定：\\\\n\\\\n```text\\\\n先检查所有 t < τ：若任一 B0(t) < 0，本批救不了更早的缺口\\\\n\\\\nq_min(τ) = max(0, max_{τ≤t≤h}[−B0(t)], S_end − B0(h))\\\\n```\\\\n\\\\n- B0(t)：尚未计入这批供应时的规划余额\\\\n- 该式同时覆盖到货后的中途缺口和期末目标，不重复计算同一需求\\\\n- 多批、多来源、原采购改期或设置期间保护线时不用这个简式，回完整日表逐项重算\\\\n\\\\n## 共享量核销\\\\n\\\\n- 多个目标仓使用同一来源时，分配量相加后必须不超过可承诺上限\\\\n- 已计入既有到货的采购量，不能再次作为新增采购覆盖同一缺口\\\\n- 调拨覆盖的部分从外购需求中扣掉，不重复下单\\\\n\\\\n## 异常处理\\\\n\\\\n| 情况 | 处理 |\\\\n|---|---|\\\\n| R 大于 H | 该行标异常，停止承诺可用量 |\\\\n| A 为负 | 同上，保留其他正常行 |\\\\n| 安全库存缺失 | 只报 A，不判断差额 |\\\\n| 到货日期过期或为空 | 保留未收事实，单列待确认，保守情景不计 |\\\\n| 到货日期只有历史均值 | 标注为情景，不承诺按时 |\\\\n| 数量精度缺失 | 不取整，标注未取整 |\\\\n| 预测历史不足 | 返回数据不足，不给预测 |\\\"\", \"callId\": \"call_92ea80ef23524cc98f5f34d1\"}','2026-11-22 02:38:13.852323');
INSERT INTO `ai_agent_trace` (`id`, `user_id`, `conversation_id`, `task_id`, `agent_type`, `event_type`, `content`, `create_time`) VALUES (3111,1900000000000000001,2124210189346299906,'41e82804-c9e3-424a-b917-0fc3228f7c5c','ANALYSIS','TOOL_CALL','{\"name\": \"listDatasets\", \"text\": \"{}\", \"callId\": \"call_81f053aa0b034365a1f1a3aa\"}','2026-11-22 02:38:16.875349');
INSERT INTO `ai_agent_trace` (`id`, `user_id`, `conversation_id`, `task_id`, `agent_type`, `event_type`, `content`, `create_time`) VALUES (3112,1900000000000000001,2124210189346299906,'41e82804-c9e3-424a-b917-0fc3228f7c5c','ANALYSIS','TOOL_RESULT','{\"name\": \"listDatasets\", \"text\": \"{\\\"message\\\":\\\"预览最多包含前两行，不能代表全部数据。\\\",\\\"datasets\\\":[{\\\"datasetId\\\":\\\"ds_56056028842f4a5db296a1296af739be\\\",\\\"description\\\":\\\"查询演示区域仓 01（DEMOW01）下所有未删除且未取消采购订单中存在未到货数量的明细行（已入库数量小于采购数量），列出采购单号、产品、采购数量、已入库数量、未到货数量和预计到货日期，用于核定是否存在晚到的在途采购批次\\\",\\\"columns\\\":[{\\\"name\\\":\\\"purchase_no\\\",\\\"label\\\":\\\"purchase_order_no\\\",\\\"jdbcType\\\":12,\\\"typeName\\\":\\\"VARCHAR\\\",\\\"nullable\\\":false},{\\\"name\\\":\\\"product_code\\\",\\\"label\\\":\\\"product_code\\\",\\\"jdbcType\\\":12,\\\"typeName\\\":\\\"VARCHAR\\\",\\\"nullable\\\":false},{\\\"name\\\":\\\"product_name\\\",\\\"label\\\":\\\"product_name\\\",\\\"jdbcType\\\":12,\\\"typeName\\\":\\\"VARCHAR\\\",\\\"nullable\\\":false},{\\\"name\\\":\\\"unit_name\\\",\\\"label\\\":\\\"unit_name\\\",\\\"jdbcType\\\":12,\\\"typeName\\\":\\\"VARCHAR\\\",\\\"nullable\\\":false},{\\\"name\\\":\\\"purchase_qty\\\",\\\"label\\\":\\\"purchase_qty\\\",\\\"jdbcType\\\":3,\\\"typeName\\\":\\\"DECIMAL\\\",\\\"nullable\\\":true},{\\\"name\\\":\\\"inbound_qty\\\",\\\"label\\\":\\\"inbound_qty\\\",\\\"jdbcType\\\":3,\\\"typeName\\\":\\\"DECIMAL\\\",\\\"nullable\\\":true},{\\\"name\\\":\\\"pending_arrival_qty\\\",\\\"label\\\":\\\"pending_arrival_qty\\\",\\\"jdbcType\\\":3,\\\"typeName\\\":\\\"DECIMAL\\\",\\\"nullable\\\":true},{\\\"name\\\":\\\"expected_arrival_date\\\",\\\"label\\\":\\\"expected_arrival_date\\\",\\\"jdbcType\\\":91,\\\"typeName\\\":\\\"DATE\\\",\\\"nullable\\\":true}],\\\"dataDescription\\\":{\\\"content\\\":\\\"演示区域仓 DEMOW01 中状态非草稿/取消、且存在未到货数量（已入库量 < 采购量）的采购订单明细列表。用于核定是否存在晚到的在途采购批次。\\\",\\\"grain\\\":\\\"每条采购订单明细一行\\\",\\\"fields\\\":[{\\\"index\\\":0,\\\"name\\\":\\\"purchase_order_no\\\",\\\"meaning\\\":\\\"采购单号\\\"},{\\\"index\\\":1,\\\"name\\\":\\\"product_code\\\",\\\"meaning\\\":\\\"产品编码\\\"},{\\\"index\\\":2,\\\"name\\\":\\\"product_name\\\",\\\"meaning\\\":\\\"产品名称\\\"},{\\\"index\\\":3,\\\"name\\\":\\\"unit_name\\\",\\\"meaning\\\":\\\"单位\\\"},{\\\"index\\\":4,\\\"name\\\":\\\"purchase_qty\\\",\\\"meaning\\\":\\\"采购数量（业务数值，已除以100还原）\\\"},{\\\"index\\\":5,\\\"name\\\":\\\"inbound_qty\\\",\\\"meaning\\\":\\\"已入库数量（业务数值，已除以100还原）\\\"},{\\\"index\\\":6,\\\"name\\\":\\\"pending_arrival_qty\\\",\\\"meaning\\\":\\\"未到货数量（业务数值，已除以100还原，等于采购数量减已入库数量）\\\"},{\\\"index\\\":7,\\\"name\\\":\\\"expected_arrival_date\\\",\\\"meaning\\\":\\\"预计到货日期\\\"}],\\\"limitations\\\":\\\"\\\"},\\\"rowCount\\\":0,\\\"completed\\\":true,\\\"completenessMessage\\\":\\\"数据集已完整读取。\\\",\\\"preview\\\":{\\\"rows\\\":[],\\\"returnedRows\\\":0,\\\"hasMore\\\":false,\\\"truncated\\\":false,\\\"status\\\":\\\"SUCCESS\\\"}},{\\\"datasetId\\\":\\\"ds_d94d72f0bbaf4829bfa23dbaa84b1f99\\\",\\\"description\\\":\\\"统计演示区域仓 01（DEMOW01）未删除销售订单按状态分组的订单数和预计发货日期区间，用于判断 2026-11-22 至 2026-11-30 期间是否存在尚未出库的确定性需求\\\",\\\"columns\\\":[{\\\"name\\\":\\\"status\\\",\\\"label\\\":\\\"status\\\",\\\"jdbcType\\\":12,\\\"typeName\\\":\\\"VARCHAR\\\",\\\"nullable\\\":false},{\\\"name\\\":\\\"order_count\\\",\\\"label\\\":\\\"order_count\\\",\\\"jdbcType\\\":-5,\\\"typeName\\\":\\\"BIGINT\\\",\\\"nullable\\\":false},{\\\"name\\\":\\\"earliest_expected_delivery_date\\\",\\\"label\\\":\\\"earliest_expected_delivery_date\\\",\\\"jdbcType\\\":91,\\\"typeName\\\":\\\"DATE\\\",\\\"nullable\\\":true},{\\\"name\\\":\\\"latest_expected_delivery_date\\\",\\\"label\\\":\\\"latest_expected_delivery_date\\\",\\\"jdbcType\\\":91,\\\"typeName\\\":\\\"DATE\\\",\\\"nullable\\\":true}],\\\"dataDescription\\\":{\\\"content\\\":\\\"演示区域仓01（DEMOW01）中所有未逻辑删除的销售订单，按订单状态分组统计的数量及预计发货日期的最小值和最大值。\\\",\\\"grain\\\":\\\"每个销售订单状态一行\\\",\\\"fields\\\":[{\\\"index\\\":0,\\\"name\\\":\\\"status\\\",\\\"meaning\\\":\\\"销售订单状态（英文枚举值，如 OUTBOUND_DONE 表示已出库）\\\"},{\\\"index\\\":1,\\\"name\\\":\\\"order_count\\\",\\\"meaning\\\":\\\"该状态下的订单数量\\\"},{\\\"index\\\":2,\\\"name\\\":\\\"earliest_expected_delivery_date\\\",\\\"meaning\\\":\\\"该状态下订单的最早预计发货日期\\\"},{\\\"index\\\":3,\\\"name\\\":\\\"latest_expected_delivery_date\\\",\\\"meaning\\\":\\\"该状态下订单的最晚预计发货日期\\\"}],\\\"limitations\\\":\\\"数据包含该仓库所有历史未删除订单，未按特定时间窗口（如2026-11-22至2026-11-30）过滤订单创建或审核时间，仅通过状态判断是否有未出库订单。当前结果仅显示已出库状态，暗示无其他状态订单存在。\\\"},\\\"rowCount\\\":1,\\\"completed\\\":true,\\\"completenessMessage\\\":\\\"数据集已完整读取。\\\",\\\"preview\\\":{\\\"rows\\\":[[\\\"OUTBOUND_DONE\\\",\\\"312\\\",\\\"2025-11-26\\\",\\\"2026-11-06\\\"]],\\\"returnedRows\\\":1,\\\"hasMore\\\":false,\\\"truncated\\\":false,\\\"status\\\":\\\"SUCCESS\\\"}},{\\\"datasetId\\\":\\\"ds_d1268f13637d4ef8b184bb1ee8b2031b\\\",\\\"description\\\":\\\"查询所有未删除的启用仓库清单，用于确定用户关心“哪批采购晚到”时可选的仓库范围\\\",\\\"columns\\\":[{\\\"name\\\":\\\"warehouse_code\\\",\\\"label\\\":\\\"仓库编码\\\",\\\"jdbcType\\\":12,\\\"typeName\\\":\\\"VARCHAR\\\",\\\"nullable\\\":false},{\\\"name\\\":\\\"warehouse_name\\\",\\\"label\\\":\\\"仓库名称\\\",\\\"jdbcType\\\":12,\\\"typeName\\\":\\\"VARCHAR\\\",\\\"nullable\\\":false},{\\\"name\\\":\\\"status\\\",\\\"label\\\":\\\"状态\\\",\\\"jdbcType\\\":-6,\\\"typeName\\\":\\\"TINYINT\\\",\\\"nullable\\\":false}],\\\"dataDescription\\\":{\\\"content\\\":\\\"所有未删除且处于启用状态（status=1）的仓库主档信息，用于提供业务操作时的仓库选项列表。\\\",\\\"grain\\\":\\\"每个仓库一行\\\",\\\"fields\\\":[{\\\"index\\\":0,\\\"name\\\":\\\"仓库编码\\\",\\\"meaning\\\":\\\"仓库编码\\\"},{\\\"index\\\":1,\\\"name\\\":\\\"仓库名称\\\",\\\"meaning\\\":\\\"仓库名称\\\"},{\\\"index\\\":2,\\\"name\\\":\\\"状态\\\",\\\"meaning\\\":\\\"仓库状态（1表示启用）\\\"}],\\\"limitations\\\":\\\"\\\"},\\\"rowCount\\\":5,\\\"completed\\\":true,\\\"completenessMessage\\\":\\\"数据集已完整读取。\\\",\\\"preview\\\":{\\\"rows\\\":[[\\\"DEMOW01\\\",\\\"演示区域仓 01\\\",1],[\\\"DEMOW02\\\",\\\"演示区域仓 02\\\",1]],\\\"returnedRows\\\":2,\\\"hasMore\\\":true,\\\"truncated\\\":false,\\\"status\\\":\\\"SUCCESS\\