INSERT INTO `ai_agent_trace` (`id`, `user_id`, `conversation_id`, `task_id`, `agent_type`, `event_type`, `content`, `create_time`) VALUES (3149,1900000000000000001,2124210189346299906,'41e82804-c9e3-424a-b917-0fc3228f7c5c','ANALYSIS','TOOL_CALL','{\"name\": \"executePython\", \"text\": \"{\\\"code\\\": \\\"import json, pandas as pd, numpy as np\\\\n\\\\ndef load(p, cols):\\\\n    recs=[]\\\\n    with open(p) as f:\\\\n        for line in f:\\\\n            line=line.strip()\\\\n            if line: recs.append(json.loads(line))\\\\n    df=pd.DataFrame(recs, columns=cols)\\\\n    return df\\\\n\\\\nstock=load(\'/tmp/erp-analysis/input/ds_53c1dd99ff8448d0998cbf9e7dfb4e9a.jsonl\',\\\\n           [\'warehouse_code\',\'warehouse_name\',\'product_id\',\'product_code\',\'product_name\',\'unit_name\',\'stock_qty\',\'locked_qty\',\'update_time\'])\\\\nprod=load(\'/tmp/erp-analysis/input/ds_139749954e62459586479075c009cf13.jsonl\',\\\\n          [\'product_id\',\'product_code\',\'product_name\',\'unit_name\',\'quantity_precision\',\'safety_stock_qty\',\'reference_purchase_price\',\'status\'])\\\\nout=load(\'/tmp/erp-analysis/input/ds_d9abcb6506754fbda458ce8c294149e4.jsonl\',\\\\n         [\'bill_no\',\'confirmed_at\',\'product_id\',\'product_code\',\'product_name\',\'unit_name\',\'change_qty\'])\\\\n\\\\nfor c in [\'stock_qty\',\'locked_qty\']: stock[c]=stock[c].astype(float)\\\\nfor c in [\'safety_stock_qty\']: prod[c]=prod[c].astype(float)\\\\nout[\'change_qty\']=out[\'change_qty\'].astype(float)\\\\nout[\'date\']=pd.to_datetime(out[\'confirmed_at\']).dt.date\\\\nstock[\'update_time\']=pd.to_datetime(stock[\'update_time\'])\\\\nprod[\'safety_stock_qty\']=pd.to_numeric(prod[\'safety_stock_qty\'], errors=\'coerce\')\\\\n\\\\nprint(\'rows:\', len(stock), len(prod), len(out))\\\\nprint(\'stock 仓库唯一:\', stock[\'warehouse_code\'].unique())\\\\nprint(\'stock product 唯一个数:\', stock[\'product_id\'].nunique(), \'重复:\', stock[\'product_id\'].duplicated().sum())\\\\nprint(\'prod 启用数:\', (prod[\'status\']==1).sum(), \'safety NULL:\', prod[\'safety_stock_qty\'].isna().sum(), \'safety==0:\', (prod[\'safety_stock_qty\']==0).sum())\\\\nprint(\'安全库存(还原后)分布:\'); print((prod[\'safety_stock_qty\']/100).describe())\\\\nprint(\'\\\\\\\\n单位分布 stock:\'); print(stock[\'unit_name\'].value_counts())\\\\nprint(\'单位分布 prod:\'); print(prod[\'unit_name\'].value_counts().head(10))\\\\nprint(\'\\\\\\\\nlock>0 行数:\', (stock[\'locked_qty\']>0).sum())\\\\nprint(\'stock_qty 还原后分布:\'); print((stock[\'stock_qty\']/100).describe())\\\\nprint(\'locked_qty 还原后分布:\'); print((stock[\'locked_qty\']/100).describe())\\\\nprint(\'\\\\\\\\n出库确认时间范围:\', out[\'confirmed_at\'].min(), out[\'confirmed_at\'].max())\\\\nprint(\'出库每产品行数分布:\'); print(out.groupby(\'product_id\').size().value_counts().sort_index())\\\\nprint(\'出库产品数:\', out[\'product_id\'].nunique())\\\\nprint(\'出库 change_qty 还原后合计:\', out[\'change_qty\'].sum()/100)\\\\nprint(\'\\\\\\\\n出库数量还原后分布:\'); print((out[\'change_qty\']/100).describe())\\\\nprint(\'入库(采购)时间范围：PURCHASE_IN 见上一步 2025-11-23 ~ 2026-11-03\')\\\\nprint(\'\\\\\\\\nstock 产品是否都在 prod:\', stock[\'product_id\'].isin(prod[\'product_id\']).all())\\\\nprint(\'out 产品是否都在 prod:\', out[\'product_id\'].isin(prod[\'product_id\']).all())\\\\nprint(\'stock 产品是否都在 out:\', stock[\'product_id\'].isin(out[\'product_id\']).all())\\\", \\\"datasetIds\\\": [\\\"ds_53c1dd99ff8448d0998cbf9e7dfb4e9a\\\", \\\"ds_139749954e62459586479075c009cf13\\\", \\\"ds_d9abcb6506754fbda458ce8c294149e4\\\"], \\\"saveResult\\\": false}\", \"callId\": \"call_b0af2bfe3d3c4695bbb1a990\"}','2026-11-22 02:39:37.170623');
