INSERT INTO `ai_agent_trace` (`id`, `user_id`, `conversation_id`, `task_id`, `agent_type`, `event_type`, `content`, `create_time`) VALUES (3161,1900000000000000001,2124210189346299906,'41e82804-c9e3-424a-b917-0fc3228f7c5c','ANALYSIS','TOOL_CALL','{\"name\": \"executePython\", \"text\": \"{\\\"code\\\": \\\"import json, pandas as pd, numpy as np\\\\n\\\\ndef load(p, cols):\\\\n    recs=[]\\\\n    with open(p) as f:\\\\n        for line in f:\\\\n            line=line.strip()\\\\n            if line: recs.append(json.loads(line))\\\\n    return pd.DataFrame(recs, columns=cols)\\\\n\\\\nstock=load(\'/tmp/erp-analysis/input/ds_53c1dd99ff8448d0998cbf9e7dfb4e9a.jsonl\',\\\\n           [\'warehouse_code\',\'warehouse_name\',\'product_id\',\'product_code\',\'product_name\',\'unit_name\',\'stock_qty\',\'locked_qty\',\'update_time\'])\\\\nprod=load(\'/tmp/erp-analysis/input/ds_139749954e62459586479075c009cf13.jsonl\',\\\\n          [\'product_id\',\'product_code\',\'product_name\',\'unit_name\',\'quantity_precision\',\'safety_stock_qty\',\'reference_purchase_price\',\'status\'])\\\\nout=load(\'/tmp/erp-analysis/input/ds_d9abcb6506754fbda458ce8c294149e4.jsonl\',\\\\n         [\'bill_no\',\'confirmed_at\',\'product_id\',\'product_code\',\'product_name\',\'unit_name\',\'change_qty\'])\\\\ninb=load(\'/tmp/erp-analysis/input/ds_4a11c76588d44a8b9187933aa5258b28.jsonl\',\\\\n         [\'bill_no\',\'confirmed_at\',\'product_id\',\'product_code\',\'product_name\',\'unit_name\',\'change_qty\'])\\\\n\\\\nfor df in (stock,prod,out,inb):\\\\n    df[\'product_id\']=df[\'product_id\'].astype(int)\\\\nstock[\'update_time\']=pd.to_datetime(stock[\'update_time\'])\\\\nout[\'dt\']=pd.to_datetime(out[\'confirmed_at\'])\\\\ninb[\'dt\']=pd.to_datetime(inb[\'confirmed_at\'])\\\\n\\\\nd=stock[[\'product_id\',\'product_code\',\'product_name\',\'unit_name\',\'stock_qty\',\'locked_qty\',\'update_time\']].copy()\\\\nd[\'H\']=d[\'stock_qty\']/100; d[\'R\']=d[\'locked_qty\']/100; d[\'A\']=d[\'H\']-d[\'R\']\\\\nd=d.merge(prod[[\'product_id\',\'quantity_precision\',\'safety_stock_qty\',\'reference_purchase_price\']], on=\'product_id\', how=\'left\')\\\\nd[\'S\']=d[\'safety_stock_qty\']/100\\\\no=out.groupby(\'product_id\').agg(out_qty=(\'change_qty\',\'sum\'), out_date=(\'dt\',\'max\'), out_cnt=(\'bill_no\',\'count\')).reset_index()\\\\no[\'out_qty\']=-o[\'out_qty\']/100\\\\ni=inb.groupby(\'product_id\').agg(in_qty=(\'change_qty\',\'sum\'), in_date=(\'dt\',\'max\'), in_cnt=(\'bill_no\',\'count\')).reset_index()\\\\ni[\'in_qty\']=i[\'in_qty\']/100\\\\nd=d.merge(o,on=\'product_id\',how=\'left\').merge(i,on=\'product_id\',how=\'left\')\\\\n\\\\nprint(\'合并行数:\', len(d), \'缺失检查: in\', d[\'in_qty\'].isna().sum(), \'out\', d[\'out_qty\'].isna().sum())\\\\n# 库存自洽: 入库-出库 = 账面库存\\\\nd[\'calc\']=d[\'in_qty\']-d[\'out_qty\']\\\\nd[\'diff\']=d[\'H\']-d[\'calc\']\\\\nprint(\'自洽完全匹配行数:\', (d[\'diff\'].abs()<1e-9).sum(), \'/\', len(d))\\\\nprint(\'diff分布:\'); print(d[\'diff\'].describe())\\\\nprint(\'\\\\\\\\n出库日是否都晚于入库日:\', (d[\'out_date\']>d[\'in_date\']).all(), \'数量:\', (d[\'out_date\']>d[\'in_date\']).sum())\\\\nprint(\'入库确认时间范围:\', inb[\'dt\'].min(), inb[\'dt\'].max())\\\\nprint(\'出库确认时间范围:\', out[\'dt\'].min(), out[\'dt\'].max())\\\\nprint(\'库存快照更新时间范围:\', stock[\'update_time\'].min(), stock[\'update_time\'].max())\\\\nEVAL=pd.Timestamp(\'2026-11-22\')\\\\nd[\'days_cycle\']=(EVAL-d[\'in_date\']).dt.days\\\\nd[\'days_hold\']=(d[\'out_date\']-d[\'in_date\']).dt.days\\\\nprint(\'\\\\\\\\n观测天数(入库->评估日)分布:\'); print(d[\'days_cycle\'].describe())\\\\nprint(\'入库->出库间隔分布:\'); print(d[\'days_hold\'].describe())\\\\nprint(\'\\\\\\\\n出库量分布:\'); print(d[\'out_qty\'].describe())\\\\nprint(\'按A与S比较: 低于安全库存行数=\', (d[\'A\']<d[\'S\']).sum(), \' 等于0行数=\', (d[\'A\']==0).sum())\\\\nprint(\'A最小/最大:\', d[\'A\'].min(), d[\'A\'].max(), \' S唯一:\', d[\'S\'].unique())\\\\nprint(\'\\\\\\\\nA<S 的样本:\'); print(d.loc[d[\'A\']<d[\'S\'],[\'product_code\',\'H\',\'R\',\'A\',\'S\']].head(10).to_string())\\\\nd.to_pickle(\'/tmp/erp-analysis/d_base.pkl\'); print(\'saved\')\\\", \\\"datasetIds\\\": [\\\"ds_53c1dd99ff8448d0998cbf9e7dfb4e9a\\\", \\\"ds_139749954e62459586479075c009cf13\\\", \\\"ds_d9abcb6506754fbda458ce8c294149e4\\\", \\\"ds_4a11c76588d44a8b9187933aa5258b28\\\"], \\\"saveResult\\\": false}\", \"callId\": \"call_5dcd619896b7477fb4560c65\"}','2026-11-22 02:40:08.442416');
