INSERT INTO `ai_agent_trace` (`id`, `user_id`, `conversation_id`, `task_id`, `agent_type`, `event_type`, `content`, `create_time`) VALUES (3163,1900000000000000001,2124210189346299906,'41e82804-c9e3-424a-b917-0fc3228f7c5c','ANALYSIS','MODEL_OUTPUT','{\"text\": \"数值字段含字符串，统一转数值后重算。\"}','2026-11-22 02:40:14.198536');
INSERT INTO `ai_agent_trace` (`id`, `user_id`, `conversation_id`, `task_id`, `agent_type`, `event_type`, `content`, `create_time`) VALUES (3164,1900000000000000001,2124210189346299906,'41e82804-c9e3-424a-b917-0fc3228f7c5c','ANALYSIS','TOOL_CALL','{\"name\": \"executePython\", \"text\": \"{\\\"code\\\": \\\"import json, pandas as pd, numpy as np\\\\n\\\\ndef load(p, cols):\\\\n    recs=[]\\\\n    with open(p) as f:\\\\n        for line in f:\\\\n            line=line.strip()\\\\n            if line: recs.append(json.loads(line))\\\\n    return pd.DataFrame(recs, columns=cols)\\\\n\\\\nstock=load(\'/tmp/erp-analysis/input/ds_53c1dd99ff8448d0998cbf9e7dfb4e9a.jsonl\',\\\\n           [\'warehouse_code\',\'warehouse_name\',\'product_id\',\'product_code\',\'product_name\',\'unit_name\',\'stock_qty\',\'locked_qty\',\'update_time\'])\\\\nprod=load(\'/tmp/erp-analysis/input/ds_139749954e62459586479075c009cf13.jsonl\',\\\\n          [\'product_id\',\'product_code\',\'product_name\',\'unit_name\',\'quantity_precision\',\'safety_stock_qty\',\'reference_purchase_price\',\'status\'])\\\\nout=load(\'/tmp/erp-analysis/input/ds_d9abcb6506754fbda458ce8c294149e4.jsonl\',\\\\n         [\'bill_no\',\'confirmed_at\',\'product_id\',\'product_code\',\'product_name\',\'unit_name\',\'change_qty\'])\\\\ninb=load(\'/tmp/erp-analysis/input/ds_4a11c76588d44a8b9187933aa5258b28.jsonl\',\\\\n         [\'bill_no\',\'confirmed_at\',\'product_id\',\'product_code\',\'product_name\',\'unit_name\',\'change_qty\'])\\\\n\\\\nfor df in (stock,prod,out,inb):\\\\n    df[\'product_id\']=pd.to_numeric(df[\'product_id\'])\\\\nfor c in [\'stock_qty\',\'locked_qty\']: stock[c]=pd.to_numeric(stock[c])\\\\nfor c in [\'quantity_precision\',\'safety_stock_qty\',\'reference_purchase_price\',\'status\']: prod[c]=pd.to_numeric(prod[c], errors=\'coerce\')\\\\nfor df in (out,inb): df[\'change_qty\']=pd.to_numeric(df[\'change_qty\'])\\\\nstock[\'update_time\']=pd.to_datetime(stock[\'update_time\'])\\\\nout[\'dt\']=pd.to_datetime(out[\'confirmed_at\']); inb[\'dt\']=pd.to_datetime(inb[\'confirmed_at\'])\\\\n\\\\nd=stock[[\'product_id\',\'product_code\',\'product_name\',\'unit_name\',\'stock_qty\',\'locked_qty\',\'update_time\']].copy()\\\\nd[\'H\']=d[\'stock_qty\']/100; d[\'R\']=d[\'locked_qty\']/100; d[\'A\']=d[\'H\']-d[\'R\']\\\\nd=d.merge(prod[[\'product_id\',\'quantity_precision\',\'safety_stock_qty\',\'reference_purchase_price\']], on=\'product_id\', how=\'left\')\\\\nd[\'S\']=d[\'safety_stock_qty\']/100\\\\no=out.groupby(\'product_id\').agg(out_qty=(\'change_qty\',\'sum\'), out_date=(\'dt\',\'max\'), out_cnt=(\'bill_no\',\'count\')).reset_index()\\\\no[\'out_qty\']=-o[\'out_qty\']/100\\\\ni=inb.groupby(\'product_id\').agg(in_qty=(\'change_qty\',\'sum\'), in_date=(\'dt\',\'max\'), in_cnt=(\'bill_no\',\'count\')).reset_index()\\\\ni[\'in_qty\']=i[\'in_qty\']/100\\\\nd=d.merge(o,on=\'product_id\',how=\'left\').merge(i,on=\'product_id\',how=\'left\')\\\\n\\\\nprint(\'合并行数:\', len(d), \'in缺失\', d[\'in_qty\'].isna().sum(), \'out缺失\', d[\'out_qty\'].isna().sum(), \'S缺失\', d[\'S\'].isna().sum())\\\\nd[\'calc\']=d[\'in_qty\']-d[\'out_qty\']; d[\'diff\']=d[\'H\']-d[\'calc\']\\\\nprint(\'自洽匹配行数:\', int((d[\'diff\'].abs()<1e-9).sum()), \'/\', len(d), \' diff范围:\', d[\'diff\'].min(), d[\'diff\'].max())\\\\nprint(\'出库确认时间范围:\', out[\'dt\'].min().date(), out[\'dt\'].max().date())\\\\nprint(\'入库确认时间范围:\', inb[\'dt\'].min().date(), inb[\'dt\'].max().date())\\\\nprint(\'库存快照更新时间范围:\', stock[\'update_time\'].min().date(), stock[\'update_time\'].max().date())\\\\nEVAL=pd.Timestamp(\'2026-11-22\')\\\\nd[\'lead_days\']=(EVAL-d[\'in_date\']).dt.days\\\\nd[\'hold_days\']=(d[\'out_date\']-d[\'in_date\']).dt.days\\\\nprint(\'\\\\\\\\n入库->评估日天数分位:\', d[\'lead_days\'].quantile([0,.25,.5,.75,1]).round(1).to_dict())\\\\nprint(\'入库->出库天数分位:\', d[\'hold_days\'].quantile([0,.25,.5,.75,1]).round(1).to_dict())\\\\nprint(\'出库量分位:\', d[\'out_qty\'].quantile([0,.25,.5,.75,1]).to_dict())\\\\nprint(\'\\\\\\\\nA 分位:\', d[\'A\'].quantile([0,.25,.5,.75,1]).to_dict(), \' S唯一:\', d[\'S\'].unique())\\\\nprint(\'A<S 行数:\', int((d[\'A\']<d[\'S\']).sum()), \' A==0:\', int((d[\'A\']==0).sum()), \' A<0:\', int((d[\'A\']<0).sum()))\\\\nprint(d.head(5)[[\'product_code\',\'H\',\'R\',\'A\',\'S\',\'in_qty\',\'out_qty\',\'in_date\',\'out_date\',\'lead_days\']].to_string())\\\\nd.to_pickle(\'/tmp/erp-analysis/d_base.pkl\')\\\\nprint(\'saved\')\\\", \\\"datasetIds\\\": [\\\"ds_53c1dd99ff8448d0998cbf9e7dfb4e9a\\\", \\\"ds_139749954e62459586479075c009cf13\\\", \\\"ds_d9abcb6506754fbda458ce8c294149e4\\\", \\\"ds_4a11c76588d44a8b9187933aa5258b28\\\"], \\\"saveResult\\\": false}\", \"callId\": \"call_b61b3a023cb94e248b11bf27\"}','2026-11-22 02:40:14.203898');
INSERT INTO `ai_agent_trace` (`id`, `user_id`, `conversation_id`, `task_id`, `agent_type`, `event_type`, `content`, `create_time`) VALUES (3165,1900000000000000001,2124210189346299906,'41e82804-c9e3-424a-b917-0fc3228f7c5c','ANALYSIS','TOOL_RESULT','{\"name\": \"executePython\", \"text\": \"{\\\"status\\\":\\\"SUCCESS\\\",\\\"textOutput\\\":{\\\"content\\\":\\\"合并行数: 312 in缺失 0 out缺失 0 S缺失 0\\\\n自洽匹配行数: 312 / 312  diff范围: 0.0 0.0\\\\n出库确认时间范围: 2025-11-26 2026-11-06\\\\n入库确认时间范围: 2025-11-23 2026-11-03\\\\n库存快照更新时间范围: 2025-11-26 2026-11-06\\\\n\\\\n入库->评估日天数分位: {0.0: 18.0, 0.25: 103.0, 0.5: 190.5, 0.75: 278.0, 1.0: 363.0}\\\\n入库->出库天数分位: {0.0: 3.0, 0.25: 3.0, 0.5: 3.0, 0.75: 3.0, 1.0: 3.0}\\\\n出库量分位: {0.0: 10.0, 0.25: 20.0, 0.5: 30.0, 0.75: 40.0, 1.0: 50.0}\\\\n\\\\nA 分位: {0.0: 32.0, 0.25: 61.0, 0.5: 78.0, 0.75: 96.0, 1.0: 123.0}  S唯一: [10.]\\\\nA<S 行数: 0  A==0: 0  A<0: 0\\\\n  product_code     H    R     A     S  in_qty  out_qty             in_date            out_date  lead_days\\\\n0      P000001  70.0  0.0  70.0  10.0    81.0     11.0 2025-12-28 09:00:00 2025-12-31 09:00:00        328\\\\n1      P000006  70.0  0.0  70.0  10.0    86.0     16.0 2026-07-01 09:00:00 2026-07-04 09:00:00        143\\\\n2      P000011  70.0  0.0  70.0  10.0    91.0     21.0 2026-01-17 09:00:00 2026-01-20 09:00:00        308\\\\n3      P000016  70.0  0.0  70.0  10.0    96.0     26.0 2026-07-21 09:00:00 2026-07-24 09:00:00        123\\\\n4      P000021  70.0  0.0  70.0  10.0   101.0     31.0 2026-02-06 09:00:00 2026-02-09 09:00:00        288\\\\nsaved\\\\n\\\",\\\"bytes\\\":1261,\\\"truncated\\\":false,\\\"saved\\\":false},\\\"files\\\":[],\\\"message\\\":\\\"本次执行完成。\\\"}\", \"callId\": \"call_b61b3a023cb94e248b11bf27\"}','2026-11-22 02:40:14.886951');
INSERT INTO `ai_agent_trace` (`id`, `user_id`, `conversation_id`, `task_id`, `agent_type`, `event_type`, `content`, `create_time`) VALUES (3166,1900000000000000001,2124210189346299906,'41e82804-c9e3-424a-b917-0fc3228f7c5c','ANALYSIS','MODEL_OUTPUT','{\"text\": \"按产品滚动逐日余额，计算日均出库速度、可支撑天数与首次跌破安全库存日期。\"}','2026-11-22 02:40:24.833691');
INSERT INTO `ai_agent_trace` (`id`, `user_id`, `conversation_id`, `task_id`, `agent_type`, `event_type`, `content`, `create_time`) VALUES (3167,1900000000000000001,2124210189346299906,'41e82804-c9e3-424a-b917-0fc3228f7c5c','ANALYSIS','TOOL_CALL','{\"name\": \"executePython\", \"text\": \"{\\\"code\\\": \\\"import pandas as pd, numpy as np\\\\nd=pd.read_pickle(\'/tmp/erp-analysis/d_base.pkl\')\\\\nEVAL=pd.Timestamp(\'2026-11-22\'); END=pd.Timestamp(\'2026-11-30\')\\\\nHORIZON=(END-EVAL).days  # 8 天需求量\\\\nd[\'obs_days\']=d[\'lead_days\'].astype(float)\\\\nif (d[\'obs_days\']<=0).any(): print(\'警告 obs_days<=0:\', (d[\'obs_days\']<=0).sum())\\\\nd[\'daily_rate\']=d[\'out_qty\']/d[\'obs_days\']\\\\nd[\'cover_days\']=np.where(d[\'daily_rate\']>0, d[\'A\']/d[\'daily_rate\'], np.inf)\\\\nd[\'period_demand\']=d[\'daily_rate\']*HORIZON\\\\nd[\'G_now\']=np.maximum(0, d[\'S\']-d[\'A\'])\\\\nd[\'gap_now_flag\']=d[\'A\']<d[\'S\']\\\\n# 逐日滚动\\\\ndates=pd.date_range(EVAL, END, freq=\'D\')\\\\nrows=[]\\\\nfor _,r in d.iterrows():\\\\n    bal=r[\'A\']; first_neg=None; first_below=None; end_bal=None\\\\n    for t in dates:\\\\n        if t>EVAL:\\\\n            bal=bal-r[\'daily_rate\']\\\\n        if first_neg is None and bal<0: first_neg=t.date()\\\\n        if first_below is None and bal<r[\'S\']: first_below=t.date()\\\\n        end_bal=bal\\\\n    rows.append((first_neg, first_below, end_bal))\\\\nd[\'first_stockout_date\']=[x[0] for x in rows]\\\\nd[\'first_below_safety_date\']=[x[1] for x in rows]\\\\nd[\'PAB_end\']=[x[2] for x in rows]\\\\nd[\'short_end\']=np.maximum(0, d[\'S\']-d[\'PAB_end\'])\\\\n# 压力情景: 期间发生一次与历史同等规模的出库\\\\nd[\'stress_A\']=d[\'A\']-d[\'out_qty\']\\\\nd[\'stress_below\']=d[\'stress_A\']<d[\'S\']\\\\n\\\\nprint(\'评估期天数(11-22->11-30):\', HORIZON)\\\\nprint(\'日均出库率分位:\', d[\'daily_rate\'].quantile([0,.25,.5,.75,1]).round(4).to_dict())\\\\nprint(\'可支撑天数分位:\', d[\'cover_days\'].quantile([0,.25,.5,.75,1]).round(2).to_dict())\\\\nprint(\'当前已低于安全库存:\', int(d[\'gap_now_flag\'].sum()))\\\\nprint(\'期间内跌破安全库存(逐日):\', int(d[\'first_below_safety_date\'].notna().sum()))\\\\nprint(\'期间内断货(A<0):\', int(d[\'first_stockout_date\'].notna().sum()))\\\\nprint(\'期末低于安全库存:\', int((d[\'PAB_end\']<d[\'S\']).sum()), \' 期末合计缺口:\', round(d[\'short_end\'].sum(),2))\\\\nprint(\'压力情景下低于安全库存:\', int(d[\'stress_below\'].sum()), \' 最低压力余额:\', round(d[\'stress_A\'].min(),2))\\\\nprint(\'\\\\\\\\n可支撑天数分布:\')\\\\nprint(pd.cut(d[\'cover_days\'], bins=[0,10,20,30,60,90,180,500]).value_counts().sort_index().to_string())\\\\nprint(\'\\\\\\\\n最低5个可支撑天数样本:\')\\\\nprint(d.nsmallest(5,\'cover_days\')[[\'product_code\',\'unit_name\',\'H\',\'A\',\'S\',\'out_qty\',\'obs_days\',\'daily_rate\',\'cover_days\',\'PAB_end\']].to_string())\\\\nprint(\'\\\\\\\\n最高5个:\')\\\\nprint(d.nlargest(5,\'cover_days\')[[\'product_code\',\'A\',\'S\',\'out_qty\',\'obs_days\',\'daily_rate\',\'cover_days\',\'PAB_end\']].to_string())\\\\nd.to_pickle(\'/tmp/erp-analysis/d_calc.pkl\')\\\", \\\"datasetIds\\\": [\\\"ds_53c1dd99ff8448d0998cbf9e7dfb4e9a\\\", \\\"ds_139749954e62459586479075c009cf13\\\", \\\"ds_d9abcb6506754fbda458ce8c294149e4\\\", \\\"ds_4a11c76588d44a8b9187933aa5258b28\\\"], \\\"saveResult\\\": false}\", \"callId\": \"call_67f3e89510dc45688056e819\"}','2026-11-22 02:40:24.838905');
INSERT INTO `ai_agent_trace` (`id`, `user_id`, `conversation_id`, `task_id`, `agent_type`, `event_type`, `content`, `create_time`) VALUES (3168,1900000000000000001,2124210189346299906,'41e82804-c9e3-424a-b917-0fc3228f7c5c','ANALYSIS','TOOL_RESULT','{\"name\": \"executePython\", \"text\": \"{\\\"status\\\":\\\"SUCCESS\\\",\\\"textOutput\\\":{\\\"content\\\":\\\"评估期天数(11-22->11-30): 8\\\\n日均出库率分位: {0.0: 0.0275, 0.25: 0.0986, 0.5: 0.1584, 0.75: 0.2901, 1.0: 2.1111}\\\\n可支撑天数分位: {0.0: 23.0, 0.25: 234.87, 0.5: 462.24, 0.75: 845.22, 1.0: 2894.6}\\\\n当前已低于安全库存: 0\\\\n期间内跌破安全库存(逐日): 0\\\\n期间内断货(A<0): 0\\\\n期末低于安全库存: 0  期末合计缺口: 0.0\\\\n压力情景下低于安全库存: 26  最低压力余额: -17.0\\\\n\\\\n可支撑天数分布:\\\\ncover_days\\\\n(0, 10]         0\\\\n(10, 20]        0\\\\n(20, 30]        2\\\\n(30, 60]       10\\\\n(60, 90]       11\\\\n(90, 180]      37\\\\n(180, 500]    109\\\\n\\\\n最低5个可支撑天数样本:\\\\n    product_code unit_name     H     A     S  out_qty  obs_days  daily_rate  cover_days    PAB_end\\\\n293      P001466         件  41.0  41.0  10.0     41.0      23.0    1.782609   23.000000  26.739130\\\\n136      P000681         件  55.0  55.0  10.0     35.0      18.0    1.944444   28.285714  39.444444\\\\n98       P000491         件  33.0  33.0  10.0     50.0      48.0    1.041667   31.680000  24.666667\\\\n221      P001106         件  38.0  38.0  10.0     50.0      43.0    1.162791   32.680000  28.697674\\\\n13       P000066         件  50.0  50.0  10.0     35.0      23.0    1.521739   32.857143  37.826087\\\\n\\\\n最高5个:\\\\n    product_code      A     S  out_qty  obs_days  daily_rate  cover_days     PAB_end\\\\n295      P001476   82.0  10.0     10.0     353.0    0.028329      2894.6   81.773371\\\\n254      P001271  121.0  10.0     10.0     238.0    0.042017      2879.8  120.663866\\\\n131      P000656  116.0  10.0     10.0     243.0    0.041152      2818.8  115.670782\\\\n172      P000861   77.0  10.0     10.0     358.0    0.027933      2756.6   76.776536\\\\n8        P000041  111.0  10.0     10.0     248.0    0.040323      2752.8  110.677419\\\\n\\\",\\\"bytes\\\":1747,\\\"truncated\\\":false,\\\"saved\\\":false},\\\"files\\\":[],\\\"message\\\":\\\"本次执行完成。\\\"}\", \"callId\": \"call_67f3e89510dc45688056e819\"}','2026-11-22 02:40:25.468796');
INSERT INTO `ai_agent_trace` (`id`, `user_id`, `conversation_id`, `task_id`, `agent_type`, `event_type`, `content`, `create_time`) VALUES (3169,1900000000000000001,2124210189346299906,'41e82804-c9e3-424a-b917-0fc3228f7c5c','ANALYSIS','MODEL_OUTPUT','{\"text\": \"复算校验（第二种算法）并生成逐产品明细、汇总与金额折算文件。\"}','2026-11-22 02:40:36.472544');
INSERT INTO `ai_agent_trace` (`id`, `user_id`, `conversation_id`, `task_id`, `agent_type`, `event_type`, `content`, `create_time`) VALUES (3170,1900000000000000001,2124210189346299906,'41e82804-c9e3-424a-b917-0fc3228f7c5c','ANALYSIS','TOOL_CALL','{\"name\": \"executePython\", \"text\": \"{\\\"code\\\": \\\"import pandas as pd, numpy as np, os\\\\nd=pd.read_pickle(\'/tmp/erp-analysis/d_calc.pkl\')\\\\nEVAL=pd.Timestamp(\'2026-11-22\'); END=pd.Timestamp(\'2026-11-30\')\\\\nos.makedirs(\'/tmp/erp-analysis/output\',exist_ok=True)\\\\n\\\\n# --- 第二算法复算 ---\\\\nalt_rate=d[\'out_qty\']/d[\'obs_days\']                      # 方式1\\\\nalt2_rate=(d[\'out_qty\']/ ( (pd.Timestamp(\'2026-11-22\')-d[\'in_date\']).dt.total_seconds()/86400 ))  # 方式2 同口径但用秒换算\\\\nprint(\'日均率两种算法最大差异:\', float((alt_rate-alt2_rate).abs().max()))\\\\nalt_cover=d[\'A\']*d[\'obs_days\']/d[\'out_qty\']              # 可支撑天数 = A/(out/obs) 展开\\\\nprint(\'可支撑天数复算最大差异:\', float((alt_cover-d[\'cover_days\']).abs().max()))\\\\n# 逐日余额向量复算（矩阵法）\\\\ndates=pd.date_range(EVAL,END,freq=\'D\'); n=len(dates)\\\\nDmat=np.array([r for r in d[\'daily_rate\']])\\\\nsteps=np.arange(n)\\\\nPAB=d[\'A\'].values[:,None]-Dmat[:,None]*steps[None,:]\\\\nprint(\'期末余额矩阵法与循环法最大差异:\', float(np.abs(PAB[:,-1]-d[\'PAB_end\'].values).max()))\\\\nprint(\'矩阵法期间是否出现过余额<安全库存:\', bool((PAB<d[\'S\'].values[:,None]).any()), \' 是否出现负余额:\', bool((PAB<0).any()))\\\\nprint(\'矩阵法期末最小余额:\', round(float(PAB[:,-1].min()),4), \'相对安全库存10的余量:\', round(float(PAB[:,-1].min()-10),4))\\\\n# 长期首次跌破安全库存 / 断货日期（无补货情景）\\\\nd[\'n_below_safety\']=np.floor((d[\'A\']-d[\'S\'])/d[\'daily_rate\'])+1\\\\nd[\'n_stockout\']=np.floor(d[\'A\']/d[\'daily_rate\'])+1\\\\nd[\'date_below_safety\']=[ (EVAL+pd.Timedelta(days=int(x))).date() if pd.notna(x) and np.isfinite(x) else None for x in d[\'n_below_safety\']]\\\\nd[\'date_stockout\']=[ (EVAL+pd.Timedelta(days=int(x))).date() if pd.notna(x) and np.isfinite(x) else None for x in d[\'n_stockout\']]\\\\nprint(\'\\\\\\\\n无补货情景下最早跌破安全库存日期（全仓）:\', min([x for x in d[\'date_below_safety\'] if x]))\\\\nprint(\'无补货情景下最早断货日期（全仓）:\', min([x for x in d[\'date_stockout\'] if x]))\\\\nprint(\'12个月内将跌破安全库存的产品数:\', int((d[\'n_below_safety\']<=365).sum()), \'/\', len(d))\\\\nprint(\'其中90天内:\', int((d[\'n_below_safety\']<=90).sum()), \' 30天内:\', int((d[\'n_below_safety\']<=30).sum()))\\\\nprint(\'12个月内断货产品数:\', int((d[\'n_stockout\']<=365).sum()))\\\\n\\\\n# 压力情景：期间一笔历史最大单笔出库\\\\nmax_single=d[\'out_qty\'].max()\\\\nd[\'stress_A\']=d[\'A\']-max_single\\\\nd[\'stress_below\']=d[\'stress_A\']<d[\'S\']\\\\nprint(\'\\\\\\\\n历史最大单笔出库量:\', max_single, \' 件；压力情景跌破安全库存产品数:\', int(d[\'stress_below\'].sum()))\\\\n\\\\n# 汇总\\\\nprint(\'\\\\\\\\n=== 汇总 ===\')\\\\nprint(\'产品数:\', len(d), \' 单位集合:\', set(d[\'unit_name\']))\\\\nprint(\'账面合计 H:\', d[\'H\'].sum(), \'锁定合计 R:\', d[\'R\'].sum(), \'可用合计 A:\', d[\'A\'].sum(), \'安全库存基数合计 S:\', d[\'S\'].sum())\\\\nprint(\'当前低于安全库存:\', int((d[\'A\']<d[\'S\']).sum()), \'合计缺口:\', round(d[\'G_now\'].sum(),2))\\\\nprint(\'期间(11-22~11-30)内跌破安全库存:\', int(d[\'first_below_safety_date\'].notna().sum()))\\\\nprint(\'期末(11-30)低于安全库存:\', int((d[\'PAB_end\']<d[\'S\']).sum()), \'期末缺口合计:\', round(d[\'short_end\'].sum(),2))\\\\nprint(\'断货产品数(期间内):\', int(d[\'first_stockout_date\'].notna().sum()))\\\\nprint(\'可用库存金额(按参考采购价):\', round(float((d[\'A\']*d[\'reference_purchase_price\']).sum()),2), \'元\')\\\\nprint(\'期末库存金额:\', round(float((d[\'PAB_end\']*d[\'reference_purchase_price\']).sum()),2), \'元\')\\\\nprint(\'可支撑天数最小/中位/最大:\', round(d[\'cover_days\'].min(),2), round(d[\'cover_days\'].median(),2), round(d[\'cover_days\'].max(),2))\\\\nprint(\'可支撑天数<30天产品数:\', int((d[\'cover_days\']<30).sum()), \' <60天:\', int((d[\'cover_days\']<60).sum()), \' <90天:\', int((d[\'cover_days\']<90).sum()))\\\\nprint(\'期末余额最低5个:\', d.nsmallest(5,\'PAB_end\')[[\'product_code\',\'A\',\'S\',\'PAB_end\']].values.tolist())\\\\nd.to_pickle(\'/tmp/erp-analysis/d_final.pkl\')\\\", \\\"datasetIds\\\": [\\\"ds_53c1dd99ff8448d0998cbf9e7dfb4e9a\\\", \\\"ds_139749954e62459586479075c009cf13\\\", \\\"ds_d9abcb6506754fbda458ce8c294149e4\\\", \\\"ds_4a11c76588d44a8b9187933aa5258b28\\\"], \\\"saveResult\\\": false}\", \"callId\": \"call_cfed1ce6040a470892a25f65\"}','2026-11-22 02:40:36.477899');
INSERT INTO `ai_agent_trace` (`id`, `user_id`, `conversation_id`, `task_id`, `agent_type`, `event_type`, `content`, `create_time`) VALUES (3171,1900000000000000001,2124210189346299906,'41e82804-c9e3-424a-b917-0fc3228f7c5c','ANALYSIS','TOOL_RESULT','{\"name\": \"executePython\", \"text\": \"{\\\"status\\\":\\\"SUCCESS\\\",\\\"textOutput\\\":{\\\"content\\\":\\\"日均率两种算法最大差异: 0.07084265473527207\\\\n可支撑天数复算最大差异: 4.547473508864641e-13\\\\n期末余额矩阵法与循环法最大差异: 5.684341886080802e-14\\\\n矩阵法期间是否出现过余额<安全库存: False  是否出现负余额: False\\\\n矩阵法期末最小余额: 24.6667 相对安全库存10的余量: 14.6667\\\\n\\\\n无补货情景下最早跌破安全库存日期（全仓）: 2026-12-10\\\\n无补货情景下最早断货日期（全仓）: 2026-12-16\\\\n12个月内将跌破安全库存的产品数: 143 / 312\\\\n其中90天内: 28  30天内: 5\\\\n12个月内断货产品数: 122\\\\n\\\\n历史最大单笔出库量: 50.0  件；压力情景跌破安全库存产品数: 66\\\\n\\\\n=== 汇总 ===\\\\n产品数: 312  单位集合: {\'件\'}\\\\n账面合计 H: 24862.0 锁定合计 R: 0.0 可用合计 A: 24862.0 安全库存基数合计 S: 3120.0\\\\n当前低于安全库存: 0 合计缺口: 0.0\\\\n期间(11-22~11-30)内跌破安全库存: 0\\\\n期末(11-30)低于安全库存: 0 期末缺口合计: 0.0\\\\n断货产品数(期间内): 0\\\\n可用库存金额(按参考采购价): 268928.6 元\\\\n期末库存金额: 261586.43 元\\\\n可支撑天数最小/中位/最大: 23.0 462.24 2894.6\\\\n可支撑天数<30天产品数: 2  <60天: 12  <90天: 23\\\\n期末余额最低5个: [[\'P000491\', 33.0, 10.0, 24.666666666666657], [\'P001466\', 41.0, 10.0, 26.739130434782624], [\'P001106\', 38.0, 10.0, 28.697674418604663], [\'P000366\', 32.0, 10.0, 28.878048780487802], [\'P000736\', 35.0, 10.0, 30.277108433734952]]\\\\n\\\",\\\"bytes\\\":1472,\\\"truncated\\\":false,\\\"saved\\\":false},\\\"files\\\":[],\\\"message\\\":\\\"本次执行完成。\\\"}\", \"callId\": \"call_cfed1ce6040a470892a25f65\"}','2026-11-22 02:40:37.185918');
INSERT INTO `ai_agent_trace` (`id`, `user_id`, `conversation_id`, `task_id`, `agent_type`, `event_type`, `content`, `create_time`) VALUES (3172,1900000000000000001,2124210189346299906,'41e82804-c9e3-424a-b917-0fc3228f7c5c','ANALYSIS','MODEL_OUTPUT','{\"text\": \"补充「出库事件强度」情景并生成交付文件。\"}','2026-11-22 02:40:49.944393');
INSERT INTO `ai_agent_trace` (`id`, `user_id`, `conversation_id`, `task_id`, `agent_type`, `event_type`, `content`, `create_time`) VALUES (3173,1900000000000000001,2124210189346299906,'41e82804-c9e3-424a-b917-0fc3228f7c5c','ANALYSIS','TOOL_CALL','{\"name\": \"executePython\", \"text\": \"{\\\"code\\\": \\\"import pandas as pd, numpy as np, os\\\\nd=pd.read_pickle(\'/tmp/erp-analysis/d_final.pkl\')\\\\nEVAL=pd.Timestamp(\'2026-11-22\'); END=pd.Timestamp(\'2026-11-30\')\\\\nos.makedirs(\'/tmp/erp-analysis/output\',exist_ok=True)\\\\n# 历史出库均为一次确认、入库后 3 天发生\\\\nd[\'burst_rate\']=d[\'out_qty\']/d[\'hold_days\']          # 事件窗口内日均\\\\nd[\'burst_cover\']=d[\'A\']/d[\'burst_rate\']\\\\nprint(\'事件窗口(入库->出库)天数唯一值:\', d[\'hold_days\'].unique())\\\\nprint(\'事件强度情景: 可支撑天数<8天产品数:\', int((d[\'burst_cover\']<8).sum()),\\\\n      \' <10天:\', int((d[\'burst_cover\']<10).sum()), \' 中位:\', round(d[\'burst_cover\'].median(),2))\\\\nd[\'burst_end\']=d[\'A\']-d[\'burst_rate\']*8\\\\nprint(\'事件强度情景期末跌破安全库存产品数:\', int((d[\'burst_end\']<d[\'S\']).sum()),\\\\n      \' 断货产品数:\', int((d[\'burst_end\']<0).sum()), \' 最低期末余额:\', round(d[\'burst_end\'].min(),2))\\\\nprint(\'该情景下若单次事件(任意时点发生)则跌破产品数:\', int(((d[\'A\']-d[\'out_qty\'])<d[\'S\']).sum()))\\\\n\\\\n# 分层风险(基准情景)\\\\ndef tier(r):\\\\n    if r[\'A\']<r[\'S\']: return \'A 已低于安全库存\'\\\\n    if r[\'cover_days\']<8: return \'B 支撑不足评估期(<8天)\'\\\\n    if r[\'cover_days\']<30: return \'C 支撑<30天\'\\\\n    if r[\'cover_days\']<90: return \'D 支撑30-90天\'\\\\n    return \'E 支撑≥90天\'\\\\nd[\'risk_tier\']=d.apply(tier,axis=1)\\\\nprint(\'\\\\\\\\n风险分层:\'); print(d[\'risk_tier\'].value_counts().sort_index().to_string())\\\\nprint(\'\\\\\\\\n各层可用库存金额(元):\')\\\\nprint((d.groupby(\'risk_tier\')[\'A\'].sum()*0).to_string())\\\\nd[\'A_amount\']=d[\'A\']*d[\'reference_purchase_price\']\\\\nprint(d.groupby(\'risk_tier\').apply(lambda x: pd.Series({\'产品数\':len(x),\'可用数量(件)\':x[\'A\'].sum(),\'可用金额(元)\':round(x[\'A_amount\'].sum(),2)})).to_string())\\\\n\\\\n# 明细输出\\\\ncols={\'product_code\':\'产品编码\',\'product_name\':\'产品名称\',\'unit_name\':\'单位\',\'H\':\'当前库存数量\',\'R\':\'锁定数量\',\'A\':\'可用库存\',\\\\n      \'S\':\'安全库存\',\'G_now\':\'当前缺口\',\'gap_now_flag\':\'是否低于安全库存\',\'out_qty\':\'历史出库量(观测期合计)\',\'out_date\':\'最后出库日\',\\\\n      \'obs_days\':\'观测天数\',\'daily_rate\':\'日均出库速度\',\'cover_days\':\'库存可支撑天数\',\'PAB_end\':\'期末(11-30)预计库存\',\\\\n      \'short_end\':\'期末缺口\',\'first_below_safety_date\':\'期间首次跌破安全库存日\',\'first_stockout_date\':\'期间首次断货日\',\\\\n      \'date_below_safety\':\'长期首次跌破安全库存日\',\'date_stockout\':\'长期首次断货日\',\'stress_A\':\'压力情景期末库存(单笔同级出库)\',\\\\n      \'burst_end\':\'事件强度情景期末库存\',\'reference_purchase_price\':\'参考采购价(元)\',\'A_amount\':\'可用库存金额(元)\',\'risk_tier\':\'风险分层\'}\\\\nout=d[list(cols)].rename(columns=cols).copy()\\\\nfor c in [\'日均出库速度\',\'库存可支撑天数\']: out[c]=out[c].round(4)\\\\nfor c in [\'期末(11-30)预计库存\',\'期末缺口\',\'压力情景期末库存(单笔同级出库)\',\'事件强度情景期末库存\',\'当前缺口\',\'可用库存金额(元)\']: out[c]=out[c].round(2)\\\\nout[\'是否低于安全库存\']=np.where(out[\'是否低于安全库存\'],\'是\',\'否\')\\\\nout[\'期间首次跌破安全库存日\']=out[\'期间首次跌破安全库存日\'].astype(str).replace({\'None\':\'无\',\'NaT\':\'无\'})\\\\nout[\'期间首次断货日\']=out[\'期间首次断货日\'].astype(str).replace({\'None\':\'无\'})\\\\nout=out.sort_values([\'库存可支撑天数\'])\\\\np1=\'/tmp/erp-analysis/output/DEMOW01_库存承接能力_逐产品明细.csv\'\\\\nout.to_csv(p1,index=False,encoding=\'utf-8-sig\')\\\\nprint(\'\\\\\\\\n明细行数:\', len(out), \'->\', p1)\\\\nprint(out.head(8)[[\'产品编码\',\'当前库存数量\',\'可用库存\',\'安全库存\',\'历史出库量(观测期合计)\',\'日均出库速度\',\'库存可支撑天数\',\'期末(11-30)预计库存\',\'风险分层\']].to_string())\\\\n\\\\n# 汇总文件\\\\nsumm=pd.DataFrame([\\\\n [\'产品数(该仓有库存记录)\',\'312 个\',\'\'],\\\\n [\'计量单位\',\'件（全部 312 个产品同一单位，可直接合计）\',\'\'],\\\\n [\'账面库存合计\',round(d[\'H\'].sum(),2),\'件\'],\\\\n [\'锁定库存合计\',round(d[\'R\'].sum(),2),\'件\'],\\\\n [\'可用库存合计\',round(d[\'A\'].sum(),2),\'件\'],\\\\n [\'安全库存基准合计\',round(d[\'S\'].sum(),2),\'件（312×10件；无 NULL 安全库存产品）\'],\\\\n [\'当前已低于安全库存产品数\',int((d[\'A\']<d[\'S\']).sum()),\'个\'],\\\\n [\'当前合计缺口(安全库存-可用)\',round(d[\'G_now\'].sum(),2),\'件\'],\\\\n [\'评估期(2026-11-22~11-30)内跌破安全库存产品数\',int(d[\'first_below_safety_date\'].notna().sum()),\'个\'],\\\\n [\'评估期内断货(A<0)产品数\',int(d[\'first_stockout_date\'].notna().sum()),\'个\'],\\\\n [\'期末(2026-11-30)低于安全库存产品数\',int((d[\'PAB_end\']<d[\'S\']).sum()),\'个\'],\\\\n [\'期末合计缺口\',round(d[\'short_end\'].sum(),2),\'件\'],\\\\n [\'期末预计库存最低值\',round(d[\'PAB_end\'].min(),2),\'件(P000491)\'],\\\\n [\'可用库存金额(按参考采购价)\',round(d[\'A_amount\'].sum(),2),\'元\'],\\\\n [\'期末预计库存金额\',round((d[\'PAB_end\']*d[\'reference_purchase_price\']).sum(),2),\'元\'],\\\\n [\'可支撑天数 最小/中位/最大\',f\\\\\\\"{d[\'cover_days\'].min():.2f} / {d[\'cover_days\'].median():.2f} / {d[\'cover_days\'].max():.2f}\\\\\\\",\'天\'],\\\\n [\'可支撑天数<30天产品数\',int((d[\'cover_days\']<30).sum()),\'个\'],\\\\n [\'可支撑天数30-90天产品数\',int(((d[\'cover_days\']>=30)&(d[\'cover_days\']<90)).sum()),\'个\'],\\\\n [\'可支撑天数≥90天产品数\',int((d[\'cover_days\']>=90).sum()),\'个\'],\\\\n [\'压力情景A(期间一笔历史同级出库)跌破安全库存产品数\',int(((d[\'A\']-d[\'out_qty\'])<d[\'S\']).sum()),\'个\'],\\\\n [\'压力情景A下跌破产品合计余量缺口\',round(float(((d[\'S\']-(d[\'A\']-d[\'out_qty\'])).clip(lower=0)).sum()),2),\'件\'],\\\\n [\'事件强度情景(按出库事件3天强度持续8天) 低于安全库存/断货产品数\',f\\\\\\\"{int((d[\'burst_end\']<d[\'S\']).sum())} / {int((d[\'burst_end\']<0).sum())}\\\\\\\",\'个\'],\\\\n [\'无补货情景下最早跌破安全库存日\',str(min([x for x in d[\'date_below_safety\'] if x])),\'\'],\\\\n [\'无补货情景下最早断货日\',str(min([x for x in d[\'date_stockout\'] if x])),\'\'],\\\\n [\'无补货情景下12个月内跌破安全库存产品数\',int((d[\'n_below_safety\']<=365).sum()),\'个\'],\\\\n [\'无补货情景下12个月内断货产品数\',int((d[\'n_stockout\']<=365).sum()),\'个\'],\\\\n], columns=[\'指标\',\'数值\',\'单位/说明\'])\\\\np2=\'/tmp/erp-analysis/output/DEMOW01_库存承接能力_汇总.csv\'\\\\nsumm.to_csv(p2,index=False,encoding=\'utf-8-sig\')\\\\nprint(\'\\\\\\\\n汇总已输出:\', p2)\\\\nprint(summ.to_string())\\\\nd.to_pickle(\'/tmp/erp-analysis/d_done.pkl\')\\\", \\\"datasetIds\\\": [\\\"ds_53c1dd99ff8448d0998cbf9e7dfb4e9a\\\", \\\"ds_139749954e62459586479075c009cf13\\\", \\\"ds_d9abcb6506754fbda458ce8c294149e4\\\", \\\"ds_4a11c76588d44a8b9187933aa5258b28\\\"], \\\"saveResult\\\": false}\", \"callId\": \"call_2af23e4a274346f88af8f543\"}','2026-11-22 02:40:49.949463');
