INSERT INTO `ai_agent_trace` (`id`, `user_id`, `conversation_id`, `task_id`, `agent_type`, `event_type`, `content`, `create_time`) VALUES (3176,1900000000000000001,2124210189346299906,'41e82804-c9e3-424a-b917-0fc3228f7c5c','ANALYSIS','TOOL_CALL','{\"name\": \"executePython\", \"text\": \"{\\\"code\\\": \\\"import pandas as pd, numpy as np\\\\nd=pd.read_pickle(\'/tmp/erp-analysis/d_done.pkl\')\\\\n# 净补货量: Q = max(0, 期间需求 + 期末目标 - 可用 - 期间到货)  期间到货=0\\\\nd[\'Q_base\']=np.maximum(0, d[\'period_demand\']+d[\'S\']-d[\'A\'])\\\\nd[\'Q_stress\']=np.maximum(0, d[\'out_qty\']+d[\'S\']-d[\'A\'])\\\\nprint(\'基准情景净补货量合计(件):\', round(d[\'Q_base\'].sum(),2), \' 非零产品数:\', int((d[\'Q_base\']>0).sum()))\\\\nprint(\'压力情景(期间一笔同级出库)净补货量合计:\', round(d[\'Q_stress\'].sum(),2), \' 非零产品数:\', int((d[\'Q_stress\']>0).sum()))\\\\nprint(\'单笔同级出库即断货的产品数(A-out<=0):\', int(((d[\'A\']-d[\'out_qty\'])<=0).sum()))\\\\nprint(\'单笔同级出库即跌破安全库存的产品数:\', int(((d[\'A\']-d[\'out_qty\'])<d[\'S\']).sum()))\\\\nprint(\'\\\\\\\\n安全库存 vs 单笔出库量: S=\',d[\'S\'].iloc[0],\' 出库量 min/median/max:\', d[\'out_qty\'].min(), d[\'out_qty\'].median(), d[\'out_qty\'].max())\\\\nprint(\'A/S 比值最低:\', round((d[\'A\']/d[\'S\']).min(),2), \' 最高:\', round((d[\'A\']/d[\'S\']).max(),2))\\\\n# 明细补充净补货量\\\\nimport os\\\\np=\'/tmp/erp-analysis/output/DEMOW01_库存承接能力_逐产品明细.csv\'\\\\nout=pd.read_csv(p)\\\\nout[\'基准情景净补货量\']=out[\'产品编码\'].map(dict(zip(d[\'product_code\'],d[\'Q_base\'].round(2))))\\\\nout[\'压力情景净补货量(单笔同级出库)\']=out[\'产品编码\'].map(dict(zip(d[\'product_code\'],d[\'Q_stress\'].round(2))))\\\\nout[\'单笔同级出库是否即断货\']=out[\'产品编码\'].map(dict(zip(d[\'product_code\'],np.where((d[\'A\']-d[\'out_qty\'])<=0,\'是\',\'否\'))))\\\\nout.to_csv(p,index=False,encoding=\'utf-8-sig\')\\\\nprint(\'\\\\\\\\n明细列:\', list(out.columns))\\\\nprint(\'行数:\', len(out))\\\\nprint(out.head(3).to_string())\\\\nprint(\'\\\\\\\\n最差10个(按可支撑天数):\')\\\\nprint(out.head(10)[[\'产品编码\',\'产品名称\',\'可用库存\',\'安全库存\',\'库存可支撑天数\',\'期末(11-30)预计库存\',\'压力情景期末库存(单笔同级出库)\',\'单笔同级出库是否即断货\',\'长期首次跌破安全库存日\']].to_string())\\\\nprint(\'\\\\\\\\n是否出现None字符串:\', out.astype(str).apply(lambda s: s.str.contains(\'None\',na=False)).any().any())\\\\nprint(\'期间首次跌破/断货列唯一值:\', out[\'期间首次跌破安全库存日\'].unique(), out[\'期间首次断货日\'].unique())\\\\nprint(\'长期首次跌破(90天内)样本:\')\\\\ns=d[d[\'n_below_safety\']<=90].nsmallest(5,\'n_below_safety\')[[\'product_code\',\'A\',\'S\',\'daily_rate\',\'n_below_safety\',\'date_below_safety\',\'n_stockout\',\'date_stockout\']]\\\\nprint(s.to_string())\\\", \\\"datasetIds\\\": [\\\"ds_53c1dd99ff8448d0998cbf9e7dfb4e9a\\\", \\\"ds_139749954e62459586479075c009cf13\\\", \\\"ds_d9abcb6506754fbda458ce8c294149e4\\\", \\\"ds_4a11c76588d44a8b9187933aa5258b28\\\"], \\\"saveResult\\\": false}\", \"callId\": \"call_531cd9b2ea09440a82e925f0\"}','2026-11-22 02:41:00.419020');
