INSERT INTO `ai_agent_trace` (`id`, `user_id`, `conversation_id`, `task_id`, `agent_type`, `event_type`, `content`, `create_time`) VALUES (3185,1900000000000000001,2124210189346299906,'41e82804-c9e3-424a-b917-0fc3228f7c5c','ANALYSIS','TOOL_CALL','{\"name\": \"executePython\", \"text\": \"{\\\"code\\\": \\\"import pandas as pd, numpy as np, os\\\\nd=pd.read_pickle(\'/tmp/erp-analysis/d_done.pkl\').copy()\\\\nEVAL=pd.Timestamp(\'2026-11-22\'); END=pd.Timestamp(\'2026-11-30\')\\\\nos.makedirs(\'/tmp/erp-analysis/output\',exist_ok=True)\\\\nMAXS=d[\'out_qty\'].max()  # 50\\\\n\\\\n# 情景B: 期间一笔与自身历史规模相同的出库\\\\nd[\'B_end\']=d[\'A\']-d[\'out_qty\']\\\\nd[\'B_short\']=np.maximum(0, d[\'S\']-d[\'B_end\'])\\\\nd[\'B_stockout\']=d[\'B_end\']<=0\\\\n# 情景C: 全仓历史最大单笔 50 件\\\\nd[\'C_end\']=d[\'A\']-MAXS\\\\nd[\'C_short\']=np.maximum(0, d[\'S\']-d[\'C_end\'])\\\\nd[\'C_stockout\']=d[\'C_end\']<=0\\\\n# 净补货量: max(0, 期间需求 + 期末目标 - 可用 - 期间到货)\\\\nd[\'Q_base\']=np.maximum(0, d[\'period_demand\']+d[\'S\']-d[\'A\'])\\\\nd[\'Q_B\']=np.maximum(0, d[\'out_qty\']+d[\'S\']-d[\'A\'])\\\\n\\\\ndef tier(r):\\\\n    if r[\'A\']<r[\'S\']: return \'A 当前已低于安全库存\'\\\\n    if r[\'cover_days\']<8: return \'B 支撑不足评估期(<8天)\'\\\\n    if r[\'cover_days\']<30: return \'C 支撑<30天\'\\\\n    if r[\'cover_days\']<90: return \'D 支撑30-90天\'\\\\n    return \'E 支撑≥90天\'\\\\nd[\'risk_tier\']=d.apply(tier,axis=1)\\\\nd[\'A_amount\']=d[\'A\']*d[\'reference_purchase_price\']\\\\nd[\'end_amount\']=d[\'PAB_end\']*d[\'reference_purchase_price\']\\\\n\\\\ncols={\'product_code\':\'产品编码\',\'product_name\':\'产品名称\',\'unit_name\':\'单位\',\'H\':\'当前库存数量\',\'R\':\'锁定数量\',\'A\':\'可用库存\',\\\\n      \'S\':\'安全库存\',\'G_now\':\'当前缺口(安全-可用)\',\'out_qty\':\'观测期出库量\',\'out_date\':\'最后出库日\',\'obs_days\':\'观测天数\',\\\\n      \'daily_rate\':\'日均出库速度\',\'cover_days\':\'库存可支撑天数\',\'period_demand\':\'评估期内预计需求(8天)\',\'PAB_end\':\'期末(11-30)预计库存\',\\\\n      \'short_end\':\'期末缺口\',\'first_below_safety_date\':\'期间首次跌破安全库存日\',\'first_stockout_date\':\'期间首次断货日\',\\\\n      \'date_below_safety\':\'无补货时首次跌破安全库存日\',\'date_stockout\':\'无补货时首次断货日\',\\\\n      \'B_end\':\'情景B期末库存(一笔同级出库)\',\'B_short\':\'情景B缺口\',\'B_stockout\':\'情景B是否断货\',\\\\n      \'C_end\':\'情景C期末库存(全仓最大单笔50件)\',\'C_short\':\'情景C缺口\',\'C_stockout\':\'情景C是否断货\',\\\\n      \'Q_base\':\'基准净补货量\',\'Q_B\':\'情景B净补货量\',\'reference_purchase_price\':\'参考采购价(元)\',\'A_amount\':\'可用库存金额(元)\',\'risk_tier\':\'风险分层\'}\\\\nout=d[list(cols)].rename(columns=cols).copy()\\\\nout[\'是否低于安全库存\']=np.where(d[\'A\']<d[\'S\'],\'是\',\'否\').values\\\\nfor c in [\'当前缺口(安全-可用)\',\'评估期内预计需求(8天)\',\'期末(11-30)预计库存\',\'期末缺口\',\'情景B期末库存(一笔同级出库)\',\'情景B缺口\',\'情景C期末库存(全仓最大单笔50件)\',\'情景C缺口\',\'基准净补货量\',\'情景B净补货量\',\'可用库存金额(元)\']:\\\\n    out[c]=out[c].round(2)\\\\nfor c in [\'日均出库速度\',\'库存可支撑天数\']: out[c]=out[c].round(4)\\\\nout[\'期间首次跌破安全库存日\']=out[\'期间首次跌破安全库存日\'].astype(str).replace(\'None\',\'无\')\\\\nout[\'期间首次断货日\']=out[\'期间首次断货日\'].astype(str).replace(\'None\',\'无\')\\\\nout[\'情景B是否断货\']=np.where(d[\'B_stockout\'],\'是\',\'否\').values\\\\nout[\'情景C是否断货\']=np.where(d[\'C_stockout\'],\'是\',\'否\').values\\\\nout=out.sort_values(\'库存可支撑天数\')\\\\np1=\'/tmp/erp-analysis/output/DEMOW01_库存承接能力_逐产品明细.csv\'\\\\nout.to_csv(p1,index=False,encoding=\'utf-8-sig\')\\\\n\\\\nsumm=pd.DataFrame([\\\\n [\'产品数（该仓有库存记录）\',312,\'个\'],[\'计量单位\',\'件\',\'全部 312 个产品同一单位，可安全合计\'],\\\\n [\'账面库存合计\',round(d[\'H\'].sum(),2),\'件\'],[\'锁定库存合计\',round(d[\'R\'].sum(),2),\'件\'],\\\\n [\'可用库存合计\',round(d[\'A\'].sum(),2),\'件\'],[\'安全库存基准合计\',round(d[\'S\'].sum(),2),\'件（312×10件，无 NULL 安全库存）\'],\\\\n [\'当前已低于安全库存产品数\',int((d[\'A\']<d[\'S\']).sum()),\'个\'],[\'当前合计缺口\',round(d[\'G_now\'].sum(),2),\'件\'],\\\\n [\'评估期(11-22~11-30)内跌破安全库存产品数\',int(d[\'first_below_safety_date\'].notna().sum()),\'个\'],\\\\n [\'评估期内断货产品数\',int(d[\'first_stockout_date\'].notna().sum()),\'个\'],\\\\n [\'期末(11-30)低于安全库存产品数\',int((d[\'PAB_end\']<d[\'S\']).sum()),\'个\'],[\'期末合计缺口\',round(d[\'short_end\'].sum(),2),\'件\'],\\\\n [\'期末预计库存最低值\',round(d[\'PAB_end\'].min(),2),\'件（P000491）\'],\\\\n [\'评估期内预计出库合计(8天)\',round(d[\'period_demand\'].sum(),2),\'件\'],\\\\n [\'可用库存金额（按参考采购价）\',round(d[\'A_amount\'].sum(),2),\'元\'],[\'期末预计库存金额\',round(d[\'end_amount\'].sum(),2),\'元\'],\\\\n [\'可支撑天数 最小/中位/最大\',f\\\\\\\"{d[\'cover_days\'].min():.2f} / {d[\'cover_days\'].median():.2f} / {d[\'cover_days\'].max():.2f}\\\\\\\",\'天\'],\\\\n [\'可支撑天数<8天产品数\',int((d[\'cover_days\']<8).sum()),\'个\'],[\'可支撑天数8-30天\',int(((d[\'cover_days\']>=8)&(d[\'cover_days\']<30)).sum()),\'个\'],\\\\n [\'可支撑天数30-90天\',int(((d[\'cover_days\']>=30)&(d[\'cover_days\']<90)).sum()),\'个\'],[\'可支撑天数≥90天\',int((d[\'cover_days\']>=90).sum()),\'个\'],\\\\n [\'情景B（一笔与自身历史同规模出库）跌破安全库存产品数\',int(((d[\'B_end\'])<d[\'S\']).sum()),\'个\'],\\\\n [\'情景B断货产品数\',int(d[\'B_stockout\'].sum()),\'个\'],[\'情景B合计缺口\',round(d[\'B_short\'].sum(),2),\'件\'],\\\\n [\'情景B净补货量合计\',round(d[\'Q_B\'].sum(),2),\'件\'],\\\\n [\'情景C（全仓最大单笔50件）跌破安全库存产品数\',int(((d[\'C_end\'])<d[\'S\']).sum()),\'个\'],\\\\n [\'情景C断货产品数\',int(d[\'C_stockout\'].sum()),\'个\'],[\'情景C合计缺口\',round(d[\'C_short\'].sum(),2),\'件\'],\\\\n [\'基准净补货量合计（覆盖期末目标）\',round(d[\'Q_base\'].sum(),2),\'件\'],\\\\n [\'无补货时最早跌破安全库存日\',str(min([x for x in d[\'date_below_safety\'] if x])),\'\'],\\\\n [\'无补货时最早断货日\',str(min([x for x in d[\'date_stockout\'] if x])),\'\'],\\\\n [\'无补货时12个月内跌破安全库存产品数\',int((d[\'n_below_safety\']<=365).sum()),\'个\'],\\\\n [\'无补货时12个月内断货产品数\',int((d[\'n_stockout\']<=365).sum()),\'个\'],\\\\n [\'其中90天内跌破安全库存产品数\',int((d[\'n_below_safety\']<=90).sum()),\'个\'],\\\\n [\'其中30天内跌破安全库存产品数\',int((d[\'n_below_safety\']<=30).sum()),\'个\'],\\\\n], columns=[\'指标\',\'数值\',\'单位/说明\'])\\\\np2=\'/tmp/erp-analysis/output/DEMOW01_库存承接能力_汇总.csv\'\\\\nsumm.to_csv(p2,index=False,encoding=\'utf-8-sig\')\\\\n\\\\nprint(summ.to_string())\\\\nprint(\'\\\\\\\\n明细行数:\', len(out), \' 列数:\', out.shape[1])\\\\nprint(\'自洽核对 —— 明细合计: A=\', out[\'可用库存\'].sum(), \' S=\', out[\'安全库存\'].sum(), \' 低于安全库存行数=\', (out[\'是否低于安全库存\']==\'是\').sum())\\\\nprint(\'情景B: 标记断货\', (out[\'情景B是否断货\']==\'是\').sum(), \'≡ B_end<=0?\', int(d[\'B_stockout\'].sum()))\\\\nprint(\'情景B跌破安全库存行数:\', int((out[\'情景B期末库存(一笔同级出库)\']<out[\'安全库存\']).sum()), \'缺口合计:\', out[\'情景B缺口\'].sum())\\\\nprint(\'情景C跌破行数:\', int((out[\'情景C期末库存(全仓最大单笔50件)\']<out[\'安全库存\']).sum()), \'缺口合计:\', out[\'情景C缺口\'].sum())\\\\nprint(\'B 与 C 差异(期末)最大:\', float((d[\'B_end\']-d[\'C_end\']).abs().max()))\\\\nd.to_pickle(\'/tmp/erp-analysis/d_report.pkl\')\\\", \\\"datasetIds\\\": [\\\"ds_53c1dd99ff8448d0998cbf9e7dfb4e9a\\\", \\\"ds_139749954e62459586479075c009cf13\\\", \\\"ds_d9abcb6506754fbda458ce8c294149e4\\\", \\\"ds_4a11c76588d44a8b9187933aa5258b28\\\"], \\\"saveResult\\\": false}\", \"callId\": \"call_9352cad6b3334389b9a8c6d7\"}','2026-11-22 02:41:23.097767');
