INSERT INTO `ai_agent_trace` (`id`, `user_id`, `conversation_id`, `task_id`, `agent_type`, `event_type`, `content`, `create_time`) VALUES (3188,1900000000000000001,2124210189346299906,'41e82804-c9e3-424a-b917-0fc3228f7c5c','ANALYSIS','TOOL_CALL','{\"name\": \"executePython\", \"text\": \"{\\\"code\\\": \\\"import pandas as pd, numpy as np, os\\\\nd=pd.read_pickle(\'/tmp/erp-analysis/d_done.pkl\').copy()\\\\nEVAL=pd.Timestamp(\'2026-11-22\'); END=pd.Timestamp(\'2026-11-30\')\\\\nMAXS=d[\'out_qty\'].max()\\\\nd[\'B_end\']=d[\'A\']-d[\'out_qty\']; d[\'B_short\']=np.maximum(0,d[\'S\']-d[\'B_end\']); d[\'B_stockout\']=d[\'B_end\']<=0\\\\nd[\'C_end\']=d[\'A\']-MAXS; d[\'C_short\']=np.maximum(0,d[\'S\']-d[\'C_end\']); d[\'C_stockout\']=d[\'C_end\']<=0\\\\nd[\'Q_base\']=np.maximum(0,d[\'period_demand\']+d[\'S\']-d[\'A\'])\\\\nd[\'Q_B\']=np.maximum(0,d[\'out_qty\']+d[\'S\']-d[\'A\'])\\\\ndef tier(r):\\\\n    if r[\'A\']<r[\'S\']: return \'A 当前已低于安全库存\'\\\\n    if r[\'cover_days\']<8: return \'B 支撑不足评估期(<8天)\'\\\\n    if r[\'cover_days\']<30: return \'C 支撑<30天\'\\\\n    if r[\'cover_days\']<90: return \'D 支撑30-90天\'\\\\n    return \'E 支撑≥90天\'\\\\nd[\'risk_tier\']=d.apply(tier,axis=1)\\\\nd[\'A_amount\']=d[\'A\']*d[\'reference_purchase_price\']; d[\'end_amount\']=d[\'PAB_end\']*d[\'reference_purchase_price\']\\\\n\\\\nout=pd.DataFrame({\\\\n \'产品编码\':d[\'product_code\'],\'产品名称\':d[\'product_name\'],\'单位\':d[\'unit_name\'],\\\\n \'当前库存数量\':d[\'H\'],\'锁定数量\':d[\'R\'],\'可用库存\':d[\'A\'],\'安全库存\':d[\'S\'],\\\\n \'当前缺口(安全-可用)\':d[\'G_now\'],\'是否低于安全库存\':np.where(d[\'A\']<d[\'S\'],\'是\',\'否\'),\\\\n \'观测期出库量\':d[\'out_qty\'],\'最后出库日\':d[\'out_date\'].astype(str),\'观测天数\':d[\'obs_days\'],\\\\n \'日均出库速度\':d[\'daily_rate\'].round(4),\'库存可支撑天数\':d[\'cover_days\'].round(4),\\\\n \'评估期内预计需求(8天)\':d[\'period_demand\'].round(2),\'期末(11-30)预计库存\':d[\'PAB_end\'].round(2),\\\\n \'期末缺口\':d[\'short_end\'].round(2),\\\\n \'期间首次跌破安全库存日\':d[\'first_below_safety_date\'].astype(str).replace(\'None\',\'无\'),\\\\n \'期间首次断货日\':d[\'first_stockout_date\'].astype(str).replace(\'None\',\'无\'),\\\\n \'无补货时首次跌破安全库存日\':d[\'date_below_safety\'].astype(str),\\\\n \'无补货时首次断货日\':d[\'date_stockout\'].astype(str),\\\\n \'情景B期末库存(一笔同级出库)\':d[\'B_end\'].round(2),\'情景B缺口\':d[\'B_short\'].round(2),\\\\n \'情景B是否断货\':np.where(d[\'B_stockout\'],\'是\',\'否\'),\\\\n \'情景C期末库存(全仓最大单笔50件)\':d[\'C_end\'].round(2),\'情景C缺口\':d[\'C_short\'].round(2),\\\\n \'情景C是否断货\':np.where(d[\'C_stockout\'],\'是\',\'否\'),\\\\n \'基准净补货量\':d[\'Q_base\'].round(2),\'情景B净补货量\':d[\'Q_B\'].round(2),\\\\n \'参考采购价(元)\':d[\'reference_purchase_price\'],\'可用库存金额(元)\':d[\'A_amount\'].round(2),\'风险分层\':d[\'risk_tier\'],\\\\n \'净补货量基期校验(需求+期末目标-可用)\':(d[\'period_demand\']+d[\'S\']-d[\'A\']).round(2)})\\\\nout[\'当前缺口(安全-可用)\']=out[\'当前缺口(安全-可用)\'].round(2)\\\\nout=out.sort_values(\'库存可支撑天数\').reset_index(drop=True)\\\\np1=\'/tmp/erp-analysis/output/DEMOW01_库存承接能力_逐产品明细.csv\'\\\\nout.to_csv(p1,index=False,encoding=\'utf-8-sig\')\\\\n\\\\nsumm=pd.DataFrame([\\\\n [\'产品数（该仓有库存记录）\',312,\'个\'],[\'计量单位\',\'件\',\'312 个产品同一单位，可安全合计\'],\\\\n [\'账面库存合计\',round(d[\'H\'].sum(),2),\'件\'],[\'锁定库存合计\',round(d[\'R\'].sum(),2),\'件\'],\\\\n [\'可用库存合计\',round(d[\'A\'].sum(),2),\'件\'],[\'安全库存基准合计\',round(d[\'S\'].sum(),2),\'件（312×10，无 NULL）\'],\\\\n [\'当前已低于安全库存产品数\',int((d[\'A\']<d[\'S\']).sum()),\'个\'],[\'当前合计缺口\',round(d[\'G_now\'].sum(),2),\'件\'],\\\\n [\'评估期(11-22~11-30)内跌破安全库存产品数\',int(d[\'first_below_safety_date\'].notna().sum()),\'个\'],\\\\n [\'评估期内断货产品数\',int(d[\'first_stockout_date\'].notna().sum()),\'个\'],\\\\n [\'期末(11-30)低于安全库存产品数\',int((d[\'PAB_end\']<d[\'S\']).sum()),\'个\'],[\'期末合计缺口\',round(d[\'short_end\'].sum(),2),\'件\'],\\\\n [\'期末预计库存最低值\',round(d[\'PAB_end\'].min(),2),\'件（P000491）\'],\\\\n [\'评估期内预计出库合计(8天)\',round(d[\'period_demand\'].sum(),2),\'件\'],\\\\n [\'可用库存金额（参考采购价）\',round(d[\'A_amount\'].sum(),2),\'元\'],[\'期末预计库存金额\',round(d[\'end_amount\'].sum(),2),\'元\'],\\\\n [\'可支撑天数 最小/中位/最大\',f\\\\\\\"{d[\'cover_days\'].min():.2f} / {d[\'cover_days\'].median():.2f} / {d[\'cover_days\'].max():.2f}\\\\\\\",\'天\'],\\\\n [\'可支撑天数<8天\',int((d[\'cover_days\']<8).sum()),\'个\'],[\'可支撑天数8-30天\',int(((d[\'cover_days\']>=8)&(d[\'cover_days\']<30)).sum()),\'个\'],\\\\n [\'可支撑天数30-90天\',int(((d[\'cover_days\']>=30)&(d[\'cover_days\']<90)).sum()),\'个\'],[\'可支撑天数≥90天\',int((d[\'cover_days\']>=90).sum()),\'个\'],\\\\n [\'情景B（一笔与自身历史同规模出库）跌破安全库存产品数\',int((d[\'B_end\']<d[\'S\']).sum()),\'个\'],\\\\n [\'情景B断货产品数\',int(d[\'B_stockout\'].sum()),\'个\'],[\'情景B合计缺口\',round(d[\'B_short\'].sum(),2),\'件\'],[\'情景B净补货量合计\',round(d[\'Q_B\'].sum(),2),\'件\'],\\\\n [\'情景C（全仓最大单笔50件）跌破安全库存产品数\',int((d[\'C_end\']<d[\'S\']).sum()),\'个\'],\\\\n [\'情景C断货产品数\',int(d[\'C_stockout\'].sum()),\'个\'],[\'情景C合计缺口\',round(d[\'C_short\'].sum(),2),\'件\'],\\\\n [\'基准净补货量合计（覆盖期末目标）\',round(d[\'Q_base\'].sum(),2),\'件\'],\\\\n [\'无补货时最早跌破安全库存日\',str(min([x for x in d[\'date_below_safety\'] if x])),\'\'],\\\\n [\'无补货时最早断货日\',str(min([x for x in d[\'date_stockout\'] if x])),\'\'],\\\\n [\'无补货时12个月内跌破安全库存产品数\',int((d[\'n_below_safety\']<=365).sum()),\'个\'],\\\\n [\'无补货时12个月内断货产品数\',int((d[\'n_stockout\']<=365).sum()),\'个\'],\\\\n [\'其中90天内跌破安全库存\',int((d[\'n_below_safety\']<=90).sum()),\'个\'],[\'其中30天内跌破安全库存\',int((d[\'n_below_safety\']<=30).sum()),\'个\'],\\\\n], columns=[\'指标\',\'数值\',\'单位/说明\'])\\\\np2=\'/tmp/erp-analysis/output/DEMOW01_库存承接能力_汇总.csv\'\\\\nsumm.to_csv(p2,index=False,encoding=\'utf-8-sig\')\\\\nprint(summ.to_string())\\\\nprint(\'\\\\\\\\n明细行数:\',len(out),\' 列数:\',out.shape[1])\\\\nprint(\'核对: A合计\',out[\'可用库存\'].sum(),\'S合计\',out[\'安全库存\'].sum(),\'低于安全库存行数\',(out[\'是否低于安全库存\']==\'是\').sum())\\\\nprint(\'情景B破线行数\',(out[\'情景B期末库存(一笔同级出库)\']<out[\'安全库存\']).sum(),\'断货\',(out[\'情景B是否断货\']==\'是\').sum(),\'缺口合计\',out[\'情景B缺口\'].sum())\\\\nprint(\'情景C破线行数\',(out[\'情景C期末库存(全仓最大单笔50件)\']<out[\'安全库存\']).sum(),\'断货\',(out[\'情景C是否断货\']==\'是\').sum(),\'缺口合计\',out[\'情景C缺口\'].sum())\\\\nprint(\'净补货量校验列最大差:\', float((out[\'基准净补货量\']-out[\'净补货量基期校验(需求+期末目标-可用)\']).abs().max()))\\\\nprint(\'明细A合计/金额核对: 可用金额\', round(out[\'可用库存金额(元)\'].sum(),2))\\\\nprint(out.head(5)[[\'产品编码\',\'产品名称\',\'可用库存\',\'安全库存\',\'库存可支撑天数\',\'期末(11-30)预计库存\',\'无补货时首次跌破安全库存日\',\'风险分层\']].to_string())\\\\nd.to_pickle(\'/tmp/erp-analysis/d_report.pkl\')\\\", \\\"datasetIds\\\": [\\\"ds_53c1dd99ff8448d0998cbf9e7dfb4e9a\\\", \\\"ds_139749954e62459586479075c009cf13\\\", \\\"ds_d9abcb6506754fbda458ce8c294149e4\\\", \\\"ds_4a11c76588d44a8b9187933aa5258b28\\\"], \\\"saveResult\\\": false}\", \"callId\": \"call_057a9c5b4ad34221a47f134a\"}','2026-11-22 02:41:32.398818');
