INSERT INTO `ai_agent_trace` (`id`, `user_id`, `conversation_id`, `task_id`, `agent_type`, `event_type`, `content`, `create_time`) VALUES (3307,1900000000000000001,2124221025439735809,'c5bccf29-985c-43b0-a4da-f1f16841c704','ANALYSIS','TOOL_CALL','{\"name\": \"prepareAnalysisData\", \"text\": \"{\\\"datasetIds\\\": [\\\"ds_acdb3fa1c4384b6d9037d65198606f6e\\\", \\\"ds_8964279acc574a78a384afdf26287248\\\", \\\"ds_69d77d679e6d402589d5a5923ef2ea5d\\\", \\\"ds_d7c189555e4e479789658c225adabdba\\\"]}\", \"callId\": \"call_f9ee7629c60c46f6ab9ad192\"}','2026-11-22 03:22:36.924618');
INSERT INTO `ai_agent_trace` (`id`, `user_id`, `conversation_id`, `task_id`, `agent_type`, `event_type`, `content`, `create_time`) VALUES (3308,1900000000000000001,2124221025439735809,'c5bccf29-985c-43b0-a4da-f1f16841c704','ANALYSIS','TOOL_RESULT','{\"name\": \"prepareAnalysisData\", \"text\": \"{\\\"files\\\":[{\\\"datasetId\\\":\\\"ds_acdb3fa1c4384b6d9037d65198606f6e\\\",\\\"filePath\\\":\\\"/tmp/erp-analysis/input/ds_acdb3fa1c4384b6d9037d65198606f6e.jsonl\\\",\\\"reprepared\\\":false},{\\\"datasetId\\\":\\\"ds_8964279acc574a78a384afdf26287248\\\",\\\"filePath\\\":\\\"/tmp/erp-analysis/input/ds_8964279acc574a78a384afdf26287248.jsonl\\\",\\\"reprepared\\\":false},{\\\"datasetId\\\":\\\"ds_69d77d679e6d402589d5a5923ef2ea5d\\\",\\\"filePath\\\":\\\"/tmp/erp-analysis/input/ds_69d77d679e6d402589d5a5923ef2ea5d.jsonl\\\",\\\"reprepared\\\":false},{\\\"datasetId\\\":\\\"ds_d7c189555e4e479789658c225adabdba\\\",\\\"filePath\\\":\\\"/tmp/erp-analysis/input/ds_d7c189555e4e479789658c225adabdba.jsonl\\\",\\\"reprepared\\\":false}],\\\"status\\\":\\\"SUCCESS\\\"}\", \"callId\": \"call_f9ee7629c60c46f6ab9ad192\"}','2026-11-22 03:22:50.290482');
INSERT INTO `ai_agent_trace` (`id`, `user_id`, `conversation_id`, `task_id`, `agent_type`, `event_type`, `content`, `create_time`) VALUES (3309,1900000000000000001,2124221025439735809,'c5bccf29-985c-43b0-a4da-f1f16841c704','ANALYSIS','TOOL_CALL','{\"name\": \"executePython\", \"text\": \"{\\\"code\\\": \\\"import json, pandas as pd\\\\n\\\\ndef load(path, cols):\\\\n    rows=[]\\\\n    with open(path) as f:\\\\n        for line in f:\\\\n            line=line.strip()\\\\n            if not line: continue\\\\n            rows.append(json.loads(line))\\\\n    return pd.DataFrame(rows, columns=cols)\\\\n\\\\ncols_stock=[\'warehouse_id\',\'warehouse_code\',\'warehouse_name\',\'product_id\',\'product_code\',\'product_name\',\'unit_name\',\'stock_qty\',\'locked_qty\']\\\\ncols_prod=[\'product_id\',\'product_code\',\'product_name\',\'category_id\',\'unit_name\',\'quantity_precision\',\'safety_stock_qty\',\'reference_purchase_price\',\'reference_sale_price\',\'status\']\\\\ncols_out=[\'warehouse_id\',\'warehouse_code\',\'product_id\',\'product_code\',\'product_name\',\'sales_out_qty\',\'last_sales_out_confirmed_at\',\'sales_out_bill_count\']\\\\ncols_in=[\'warehouse_id\',\'warehouse_code\',\'product_id\',\'product_code\',\'product_name\',\'last_purchase_in_confirmed_at\',\'purchase_in_bill_count\']\\\\n\\\\nstock=load(\'/tmp/erp-analysis/input/ds_acdb3fa1c4384b6d9037d65198606f6e.jsonl\',cols_stock)\\\\nprod=load(\'/tmp/erp-analysis/input/ds_8964279acc574a78a384afdf26287248.jsonl\',cols_prod)\\\\nout=load(\'/tmp/erp-analysis/input/ds_69d77d679e6d402589d5a5923ef2ea5d.jsonl\',cols_out)\\\\npin=load(\'/tmp/erp-analysis/input/ds_d7c189555e4e479789658c225adabdba.jsonl\',cols_in)\\\\n\\\\nfor df,numc in [(stock,[\'stock_qty\',\'locked_qty\']),(prod,[\'safety_stock_qty\',\'reference_purchase_price\',\'reference_sale_price\']),(out,[\'sales_out_qty\'])]:\\\\n    for c in numc: df[c]=pd.to_numeric(df[c], errors=\'coerce\')\\\\nprint(stock.dtypes.to_string())\\\\nprint(\'rows\', len(stock), len(prod), len(out), len(pin))\\\\nprint(\'stock nulls\\\\\\\\n\', stock.isna().sum().to_string())\\\\nprint(\'prod nulls\\\\\\\\n\', prod.isna().sum().to_string())\\\\nprint(\'out nulls\\\\\\\\n\', out.isna().sum().to_string())\\\\nprint(\'pin last in null count\', pin[\'last_purchase_in_confirmed_at\'].isna().sum())\\\\n\\\\n# 还原数量\\\\nstock[\'stock\']=stock[\'stock_qty\']/100\\\\nstock[\'locked\']=stock[\'locked_qty\']/100\\\\nstock[\'avail\']=stock[\'stock\']-stock[\'locked\']\\\\nprod[\'safety\']=prod[\'safety_stock_qty\']/100\\\\n\\\\n# 数据质量\\\\ndup=stock.duplicated(subset=[\'warehouse_id\',\'product_id\']).sum()\\\\nneg=(stock[\'stock\']<0).sum()\\\\nlock_gt=(stock[\'locked\']>stock[\'stock\']).sum()\\\\nprint(\'重复仓+SKU:\',dup,\'负库存:\',neg,\'锁定>账面:\',lock_gt)\\\\nprint(\'仓库数\', stock[\'warehouse_id\'].nunique(), \'SKU行数\', len(stock), \'产品数\', stock[\'product_id\'].nunique())\\\\nprint(\'单位\', stock[\'unit_name\'].unique())\\\\n\\\\n# 库存金额\\\\nstock=stock.merge(prod[[\'product_id\',\'reference_purchase_price\',\'reference_sale_price\',\'safety\',\'quantity_precision\',\'status\']],on=\'product_id\',how=\'left\',validate=\'m:1\')\\\\nprint(\'merge后行数\',len(stock),\'缺价格\',stock[\'reference_purchase_price\'].isna().sum(),\'缺safety\',stock[\'safety\'].isna().sum())\\\\nstock[\'stock_amt\']=stock[\'stock\']*stock[\'reference_purchase_price\']\\\\nstock[\'avail_amt\']=stock[\'avail\']*stock[\'reference_purchase_price\']\\\\n\\\\ng=stock.groupby([\'warehouse_code\']).agg(SKU=(\'product_id\',\'nunique\'),stock=(\'stock\',\'sum\'),locked=(\'locked\',\'sum\'),avail=(\'avail\',\'sum\'),amt=(\'stock_amt\',\'sum\')).reset_index()\\\\ntot=pd.DataFrame([{\'warehouse_code\':\'合计/全公司\',\'SKU\':stock[\'product_id\'].nunique(),\'stock\':stock[\'stock\'].sum(),\'locked\':stock[\'locked\'].sum(),\'avail\':stock[\'avail\'].sum(),\'amt\':stock[\'stock_amt\'].sum()}])\\\\noverview=pd.concat([g,tot],ignore_index=True)\\\\nfor c in [\'stock\',\'locked\',\'avail\',\'amt\']: overview[c]=overview[c].round(2)\\\\nprint(overview.to_string(index=False))\\\\nprint(\'锁定总量\', stock[\'locked\'].sum(), \'库存总量\', stock[\'stock\'].sum())\\\\nprint(\'总额校验 avail=stock-locked:\', round(stock[\'stock\'].sum()-stock[\'locked\'].sum(),2), round(stock[\'avail\'].sum(),2))\\\\n\\\\nstock.to_pickle(\'/tmp/erp-analysis/stock.pkl\')\\\\nprod.to_pickle(\'/tmp/erp-analysis/prod.pkl\')\\\\nout.to_pickle(\'/tmp/erp-analysis/out.pkl\')\\\\npin.to_pickle(\'/tmp/erp-analysis/pin.pkl\')\\\\noverview.to_pickle(\'/tmp/erp-analysis/overview.pkl\')\\\", \\\"datasetIds\\\": [\\\"ds_acdb3fa1c4384b6d9037d65198606f6e\\\", \\\"ds_8964279acc574a78a384afdf26287248\\\", \\\"ds_69d77d679e6d402589d5a5923ef2ea5d\\\", \\\"ds_d7c189555e4e479789658c225adabdba\\\"], \\\"saveResult\\\": true, \\\"outputTextName\\\": \\\"维度1_整体概览与数据质量\\\"}\", \"callId\": \"call_a432f2140b184ff3a3fb5fd2\"}','2026-11-22 03:22:56.134093');
