INSERT INTO `ai_agent_trace` (`id`, `user_id`, `conversation_id`, `task_id`, `agent_type`, `event_type`, `content`, `create_time`) VALUES (3311,1900000000000000001,2124221025439735809,'c5bccf29-985c-43b0-a4da-f1f16841c704','ANALYSIS','MODEL_OUTPUT','{\"text\": \"维度1 已完成；现在计算维度2 周转与积压、维度3 入库时间与呆滞。\"}','2026-11-22 03:23:07.500771');
INSERT INTO `ai_agent_trace` (`id`, `user_id`, `conversation_id`, `task_id`, `agent_type`, `event_type`, `content`, `create_time`) VALUES (3312,1900000000000000001,2124221025439735809,'c5bccf29-985c-43b0-a4da-f1f16841c704','ANALYSIS','TOOL_CALL','{\"name\": \"executePython\", \"text\": \"{\\\"code\\\": \\\"import pandas as pd, numpy as np\\\\nstock=pd.read_pickle(\'/tmp/erp-analysis/stock.pkl\')\\\\nout=pd.read_pickle(\'/tmp/erp-analysis/out.pkl\')\\\\npin=pd.read_pickle(\'/tmp/erp-analysis/pin.pkl\')\\\\n\\\\nWINDOW_DAYS=90\\\\nout[\'out_qty90\']=out[\'sales_out_qty\']/100\\\\no=out[[\'warehouse_id\',\'product_id\',\'out_qty90\',\'last_sales_out_confirmed_at\',\'sales_out_bill_count\']].copy()\\\\nsku=stock[[\'warehouse_id\',\'warehouse_code\',\'warehouse_name\',\'product_id\',\'product_code\',\'product_name\',\'stock\',\'locked\',\'avail\',\'stock_amt\',\'safety\']].merge(\\\\n    o, on=[\'warehouse_id\',\'product_id\'], how=\'left\', validate=\'1:1\')\\\\nsku[\'out_qty90\']=sku[\'out_qty90\'].fillna(0)\\\\nsku[\'has_out\']=sku[\'out_qty90\']>0\\\\nprint(\'窗口内有出库SKU:\', sku[\'has_out\'].sum(), \'零出库SKU:\', (~sku[\'has_out\']).sum())\\\\nprint(\'窗口出库总量(件):\', round(sku[\'out_qty90\'].sum(),2))\\\\nprint(\'出库单据数合计:\', out[\'sales_out_bill_count\'].sum())\\\\n\\\\nsku[\'daily\']=sku[\'out_qty90\']/WINDOW_DAYS\\\\nsku[\'turnover_days\']=np.where(sku[\'daily\']>0, sku[\'avail\']/sku[\'daily\'], np.nan)\\\\n\\\\n# 零出库规模\\\\nz=sku[~sku[\'has_out\']]\\\\nprint(\'\\\\\\\\n零出库SKU数:\',len(z),\'库存数量:\',round(z[\'stock\'].sum(),2),\'库存金额:\',round(z[\'stock_amt\'].sum(),2))\\\\nprint(\'零出库占库存金额比:\', round(z[\'stock_amt\'].sum()/sku[\'stock_amt\'].sum()*100,2),\'%\')\\\\n\\\\n# 有出库但周转慢\\\\nh=sku[sku[\'has_out\']].copy()\\\\nprint(\'\\\\\\\\n有出库SKU周转天数: 中位\', round(h[\'turnover_days\'].median(),1), \'均值\', round(h[\'turnover_days\'].mean(),1), \'最大\', round(h[\'turnover_days\'].max(),1))\\\\nprint(\'有出库SKU中周转>90天:\', (h[\'turnover_days\']>90).sum(), \'>180天:\', (h[\'turnover_days\']>180).sum())\\\\n# 分档\\\\nbins=[0,30,60,90,180,365,np.inf]; labels=[\'<=30天\',\'30-60天\',\'60-90天\',\'90-180天\',\'180-365天\',\'>365天\']\\\\nh[\'td_bin\']=pd.cut(h[\'turnover_days\'],bins=bins,labels=labels,right=True)\\\\ntb=h.groupby(\'td_bin\',observed=False).agg(SKU=(\'product_id\',\'size\'),库存数量=(\'stock\',\'sum\'),库存金额=(\'stock_amt\',\'sum\')).reset_index()\\\\nprint(tb.round(2).to_string(index=False))\\\\n\\\\ntop=h.sort_values(\'turnover_days\',ascending=False).head(20)[[\'product_code\',\'product_name\',\'warehouse_code\',\'avail\',\'out_qty90\',\'turnover_days\',\'stock_amt\']].copy()\\\\ntop[\'turnover_days\']=top[\'turnover_days\'].round(1)\\\\nfor c in [\'avail\',\'out_qty90\',\'stock_amt\']: top[c]=top[c].round(2)\\\\nprint(\'\\\\\\\\n== 有出库但周转最慢 TOP20 ==\')\\\\nprint(top.to_string(index=False))\\\\n\\\\nztop=z.sort_values(\'stock_amt\',ascending=False).head(20)[[\'product_code\',\'product_name\',\'warehouse_code\',\'stock\',\'stock_amt\']].copy()\\\\nfor c in [\'stock\',\'stock_amt\']: ztop[c]=ztop[c].round(2)\\\\nprint(\'\\\\\\\\n== 零出库按库存金额TOP20 ==\')\\\\nprint(ztop.to_string(index=False))\\\\n\\\\n# 维度3 最近入库\\\\npin[\'last_in\']=pd.to_datetime(pin[\'last_purchase_in_confirmed_at\'])\\\\nsku=sku.merge(pin[[\'warehouse_id\',\'product_id\',\'last_in\']],on=[\'warehouse_id\',\'product_id\'],how=\'left\',validate=\'1:1\')\\\\nBASE=pd.Timestamp(\'2026-11-22\')\\\\nsku[\'days_since_in\']=(BASE-sku[\'last_in\']).dt.days\\\\nprint(\'\\\\\\\\n最近入库距今天数: 缺失\',sku[\'days_since_in\'].isna().sum(),\'中位\',sku[\'days_since_in\'].median(),\'最大\',sku[\'days_since_in\'].max(),\'最小\',sku[\'days_since_in\'].min())\\\\nprint(\'最近入库时间范围\', sku[\'last_in\'].min(), sku[\'last_in\'].max())\\\\n\\\\n# 呆滞候选: 长期无入库(>90天) 且 90天零出库\\\\ncand=sku[(sku[\'days_since_in\']>90)&(~sku[\'has_out\'])].copy()\\\\nprint(\'\\\\\\\\n长期无入库(>90天)且90天零出库 SKU数:\',len(cand),\'库存量:\',round(cand[\'stock\'].sum(),2),\'金额:\',round(cand[\'stock_amt\'].sum(),2))\\\\n\\\\n# 分档（对全部SKU给出最近入库距今天数分档）\\\\nbins2=[-1,90,180,365,np.inf]; labels2=[\'<=90天\',\'90-180天\',\'180-365天\',\'>365天\']\\\\nsku[\'in_bin\']=pd.cut(sku[\'days_since_in\'],bins=bins2,labels=labels2)\\\\nt2=sku.groupby(\'in_bin\',observed=False).agg(SKU=(\'product_id\',\'size\'),库存数量=(\'stock\',\'sum\'),库存金额=(\'stock_amt\',\'sum\')).reset_index()\\\\nprint(\'\\\\\\\\n== 全部SKU最近入库距今天数分档 ==\')\\\\nprint(t2.round(2).to_string(index=False))\\\\n\\\\ncand[\'in_bin\']=pd.cut(cand[\'days_since_in\'],bins=bins2,labels=labels2)\\\\nt3=cand.groupby(\'in_bin\',observed=False).agg(呆滞SKU=(\'product_id\',\'size\'),库存数量=(\'stock\',\'sum\'),库存金额=(\'stock_amt\',\'sum\')).reset_index()\\\\nt3[\'金额占比%\']=(t3[\'库存金额\']/sku[\'stock_amt\'].sum()*100).round(2)\\\\nprint(\'\\\\\\\\n== 呆滞SKU(>90天无入库且90天零出库)按距今天数分档 ==\')\\\\nprint(t3.round(2).to_string(index=False))\\\\nprint(\'呆滞合计:\', len(cand), round(cand[\'stock\'].sum(),2), round(cand[\'stock_amt\'].sum(),2))\\\\n\\\\nctop=cand.sort_values(\'stock_amt\',ascending=False).head(20)[[\'product_code\',\'product_name\',\'warehouse_code\',\'stock\',\'stock_amt\',\'days_since_in\',\'last_in\']].copy()\\\\nfor c in [\'stock\',\'stock_amt\']: ctop[c]=ctop[c].round(2)\\\\nctop[\'last_in\']=ctop[\'last_in\'].dt.strftime(\'%Y-%m-%d\')\\\\nprint(\'\\\\\\\\n== 呆滞SKU按库存金额TOP20 ==\')\\\\nprint(ctop.to_string(index=False))\\\\n\\\\n# 零出库中\\\\\\\"近期有入库\\\\\\\"(<=90天)的部分 -> 可能季节性备货\\\\nfresh=sku[(~sku[\'has_out\'])&(sku[\'days_since_in\']<=90)]\\\\nprint(\'\\\\\\\\n零出库但近90天有入库的SKU数:\',len(fresh),\'库存量:\',round(fresh[\'stock\'].sum(),2),\'金额:\',round(fresh[\'stock_amt\'].sum(),2))\\\\n\\\\nsku.to_pickle(\'/tmp/erp-analysis/sku.pkl\')\\\\ntop.to_csv(\'/tmp/erp-analysis/t_top.csv\',index=False,encoding=\'utf-8-sig\')\\\\nztop.to_csv(\'/tmp/erp-analysis/t_zero.csv\',index=False,encoding=\'utf-8-sig\')\\\\nctop.to_csv(\'/tmp/erp-analysis/t_dead.csv\',index=False,encoding=\'utf-8-sig\')\\\", \\\"datasetIds\\\": [\\\"ds_acdb3fa1c4384b6d9037d65198606f6e\\\", \\\"ds_69d77d679e6d402589d5a5923ef2ea5d\\\", \\\"ds_d7c189555e4e479789658c225adabdba\\\"], \\\"saveResult\\\": true, \\\"outputTextName\\\": \\\"维度2_3_周转积压与呆滞\\\"}\", \"callId\": \"call_676b0a87a9d24222a6293bcd\"}','2026-11-22 03:23:07.505433');
