ax()))\\\\nprint(\\\\\\\"金额加权平均交期 %.2f\\\\\\\"%( (od.lead*od.total_amount).sum()/od.total_amount.sum()))\\\\nprint(\\\\\\\"逾期订单数\\\\\\\",od.overdue.sum(),\\\\\\\"逾期率 %.2f%%\\\\\\\"%(od.overdue.sum()/len(od)*100))\\\\nprint(\\\\\\\"订单金额合计 %.2f\\\\\\\"%(od.total_amount.sum()))\\\\nprint(\\\\\\\"\\\\\\\\n逐单交期:\\\\\\\")\\\\nprint(od[[\\\\\\\"purchase_no\\\\\\\",\\\\\\\"approved_at\\\\\\\",\\\\\\\"expected_arrival_date\\\\\\\",\\\\\\\"fully_received_at\\\\\\\",\\\\\\\"lead\\\\\\\",\\\\\\\"overdue\\\\\\\",\\\\\\\"total_amount\\\\\\\"]].sort_values(\\\\\\\"approved_at\\\\\\\").to_string(index=False))\\\\nprint(\\\\\\\"\\\\\\\\nP001143 在该供应商180d订单数:\\\\\\\", od[od.product_code==\\\\\\\"P001143\\\\\\\"].shape[0])\\\", \\\"datasetIds\\\": [\\\"ds_d7b8209ca0874c30bc2cac9586fc5a46\\\"], \\\"saveResult\\\": false}\", \"callId\": \"call_36800416404b4637903df743\"}','2026-11-22 16:33:36.430269');
