INSERT INTO `ai_agent_trace` (`id`, `user_id`, `conversation_id`, `task_id`, `agent_type`, `event_type`, `content`, `create_time`) VALUES (3933,1900000000000000001,2124421893103570946,'sqlrun_540242e3caca412eb748d71d70d57ec2','SQL_GENERATE','MODEL_OUTPUT','{\"sql\": \"SELECT ob.id AS outbound_bill_id, ob.outbound_no, ob.warehouse_id, ob.warehouse_name, ob.source_party_id, ob.source_party_name, ob.confirmed_at, obi.current_qty, obi.unit_name FROM outbound_bill ob JOIN outbound_bill_item obi ON ob.id = obi.outbound_bill_id WHERE ob.deleted = 0 AND ob.status = \'CONFIRMED\' AND ob.outbound_type = \'SALES_OUT\' AND obi.product_id = 8400000000005000173\", \"decision\": \"QUERY\", \"needFullData\": true}','2026-11-22 16:38:00.264286');
