INSERT INTO `ai_agent_trace` (`id`, `user_id`, `conversation_id`, `task_id`, `agent_type`, `event_type`, `content`, `create_time`) VALUES (3940,1900000000000000001,2124421893103570946,'sqlrun_e3f34d9a0a7b4aad903a8fa419b4c37f','SQL_GENERATE','MODEL_OUTPUT','{\"sql\": \"SELECT so.sales_no AS sales_no, so.customer_name AS customer_name, so.warehouse_name AS warehouse_name, so.status AS status, so.expected_delivery_date AS expected_delivery_date, soi.quantity AS quantity, soi.locked_qty AS locked_qty, soi.outbound_qty AS outbound_qty, (soi.quantity - soi.outbound_qty) AS unshipped_qty, soi.unit_price AS unit_price, so.approved_at AS approved_at FROM sales_order so JOIN sales_order_item soi ON so.id = soi.sales_order_id WHERE so.deleted = 0 AND so.status IN (\'APPROVED\', \'PARTIAL_OUTBOUND\') AND soi.product_id = 8400000000005000173\", \"decision\": \"QUERY\", \"needFullData\": true}','2026-11-22 16:38:15.372506');
