INSERT INTO `ai_agent_trace` (`id`, `user_id`, `conversation_id`, `task_id`, `agent_type`, `event_type`, `content`, `create_time`) VALUES (4121,1900000000000000001,2124424075508994050,'sqlrun_e9661f4a53464dbe89fdb09be9a88bff','SQL_GENERATE','MODEL_OUTPUT','{\"sql\": \"SELECT so.sales_no AS sales_no, so.status AS status, so.warehouse_name AS warehouse_name, so.customer_name AS customer_name, soi.quantity / 100.0 AS quantity, soi.locked_qty / 100.0 AS locked_qty, soi.outbound_qty / 100.0 AS outbound_qty, (soi.quantity - soi.outbound_qty) / 100.0 AS unshipped_qty, soi.unit_price / 100.0 AS unit_price, so.expected_delivery_date AS expected_delivery_date, so.approved_at AS approved_at FROM sales_order so JOIN sales_order_item soi ON so.id = soi.sales_order_id WHERE so.deleted = 0 AND so.warehouse_id = 8400000000004000004 AND so.status != \'CANCELLED\' AND soi.product_code = \'P000005\' AND soi.outbound_qty < soi.quantity\", \"decision\": \"QUERY\", \"needFullData\": true}','2026-11-22 16:47:15.389390');
