INSERT INTO `ai_agent_trace` (`id`, `user_id`, `conversation_id`, `task_id`, `agent_type`, `event_type`, `content`, `create_time`) VALUES (4310,1900000000000000001,2124465547335741442,'sqlrun_838ee2138bb84798861146ab09aa4c09','SQL_GENERATE','MODEL_OUTPUT','{\"sql\": \"SELECT \'CUR\' AS period, \'PURCHASE_IN\' AS flow_type, COUNT(DISTINCT ib.id) AS bill_count, SUM(ibi.current_qty) / 100.0 AS qty, SUM(ibi.current_qty * ibi.unit_price) / 10000.0 AS amount_yuan FROM inbound_bill ib JOIN inbound_bill_item ibi ON ib.id = ibi.inbound_bill_id WHERE ib.inbound_type = \'PURCHASE_IN\' AND ib.status = \'CONFIRMED\' AND ib.deleted = 0 AND ib.confirmed_at >= \'2026-05-25 00:00:00\' AND ib.confirmed_at <= \'2026-11-22 23:59:59\' UNION ALL SELECT \'PRE\' AS period, \'PURCHASE_IN\' AS flow_type, COUNT(DISTINCT ib.id) AS bill_count, SUM(ibi.current_qty) / 100.0 AS qty, SUM(ibi.current_qty * ibi.unit_price) / 10000.0 AS amount_yuan FROM inbound_bill ib JOIN inbound_bill_item ibi ON ib.id = ibi.inbound_bill_id WHERE ib.inbound_type = \'PURCHASE_IN\' AND ib.status = \'CONFIRMED\' AND ib.deleted = 0 AND ib.confirmed_at >= \'2025-11-23 00:00:00\' AND ib.confirmed_at <= \'2026-05-24 23:59:59\' UNION ALL SELECT \'CUR\' AS period, \'SALES_OUT\' AS flow_type, COUNT(DISTINCT ob.id) AS bill_count, SUM(obi.current_qty) / 100.0 AS qty, SUM(obi.current_qty * obi.unit_price) / 10000.0 AS amount_yuan FROM outbound_bill ob JOIN outbound_bill_item obi ON ob.id = obi.outbound_bill_id WHERE ob.outbound_type = \'SALES_OUT\' AND ob.status = \'CONFIRMED\' AND ob.deleted = 0 AND ob.confirmed_at >= \'2026-05-25 00:00:00\' AND ob.confirmed_at <= \'2026-11-22 23:59:59\' UNION ALL SELECT \'PRE\' AS period, \'SALES_OUT\' AS flow_type, COUNT(DISTINCT ob.id) AS bill_count, SUM(obi.current_qty) / 100.0 AS qty, SUM(obi.current_qty * obi.unit_price) / 10000.0 AS amount_yuan FROM outbound_bill ob JOIN outbound_bill_item obi ON ob.id = obi.outbound_bill_id WHERE ob.outbound_type = \'SALES_OUT\' AND ob.status = \'CONFIRMED\' AND ob.deleted = 0 AND ob.confirmed_at >= \'2025-11-23 00:00:00\' AND ob.confirmed_at <= \'2026-05-24 23:59:59\'\", \"decision\": \"QUERY\", \"needFullData\": true}','2026-11-22 19:32:06.926737');
