INSERT INTO `ai_agent_trace` (`id`, `user_id`, `conversation_id`, `task_id`, `agent_type`, `event_type`, `content`, `create_time`) VALUES (4324,1900000000000000001,2124465547335741442,'sqlrun_9ef84cf169e9450fa2f0ad1ed98f228d','SQL_GENERATE','MODEL_OUTPUT','{\"sql\": \"SELECT CASE WHEN ob.confirmed_at >= \'2026-05-25 00:00:00\' AND ob.confirmed_at <= \'2026-11-22 23:59:59\' THEN \'CUR\' ELSE \'PRE\' END AS period, COUNT(DISTINCT ob.id) AS bill_count, SUM(obi.current_qty) / 100.0 AS qty, SUM(obi.current_qty * obi.unit_price) / 10000.0 AS amount_yuan FROM outbound_bill ob JOIN outbound_bill_item obi ON ob.id = obi.outbound_bill_id WHERE ob.deleted = 0 AND ob.status = \'CONFIRMED\' AND ob.outbound_type = \'SALES_OUT\' AND ((ob.confirmed_at >= \'2026-05-25 00:00:00\' AND ob.confirmed_at <= \'2026-11-22 23:59:59\') OR (ob.confirmed_at >= \'2025-11-23 00:00:00\' AND ob.confirmed_at <= \'2026-05-24 23:59:59\')) GROUP BY CASE WHEN ob.confirmed_at >= \'2026-05-25 00:00:00\' AND ob.confirmed_at <= \'2026-11-22 23:59:59\' THEN \'CUR\' ELSE \'PRE\' END\", \"decision\": \"QUERY\", \"needFullData\": true}','2026-11-22 19:32:30.720585');
