INSERT INTO `ai_agent_trace` (`id`, `user_id`, `conversation_id`, `task_id`, `agent_type`, `event_type`, `content`, `create_time`) VALUES (4363,1900000000000000001,2124465547335741442,'6722a262-5c55-403c-9ef6-d80a099344b8','ANALYSIS','TOOL_CALL','{\"name\": \"executePython\", \"text\": \"{\\\"code\\\": \\\"import json, pandas as pd, numpy as np\\\\nB=\'/tmp/erp-analysis/input/\'\\\\ndef load(ds, cols):\\\\n    rows=[json.loads(l) for l in open(B+ds+\'.jsonl\',encoding=\'utf-8\') if l.strip()]\\\\n    return pd.DataFrame(rows, columns=cols)\\\\nro_cols=[\'id\',\'return_no\',\'return_type\',\'source_order_id\',\'source_order_no\',\'party_id\',\'party_code\',\'party_name\',\'warehouse_id\',\'warehouse_name\',\'expected_execution_date\',\'handling_type\',\'reason_code\',\'reason_raw\',\'return_reason\',\'total_amount\',\'status\',\'status_reason\',\'submitted_at\',\'approved_at\',\'create_time\',\'deleted\']\\\\nro=load(\'ds_37d891578535459393dcb70f762958da\',ro_cols)\\\\nri_cols=[\'id\',\'return_order_id\',\'source_order_item_id\',\'product_id\',\'product_code\',\'product_name\',\'unit_name\',\'quantity_precision\',\'source_fulfilled_qty\',\'requested_qty\',\'approved_qty\',\'processed_qty\',\'unit_price\',\'total_amount\',\'create_time\']\\\\nri=load(\'ds_fd1d7af2e5f14fc687f57a9602e84258\',ri_cols)\\\\nfor c in [\'total_amount\',\'party_id\']: ro[c]=pd.to_numeric(ro[c])\\\\nfor c in [\'requested_qty\',\'approved_qty\',\'processed_qty\',\'unit_price\',\'total_amount\',\'quantity_precision\']: ri[c]=pd.to_numeric(ri[c])\\\\nro[\'ct\']=pd.to_datetime(ro[\'create_time\']); ro[\'month\']=ro[\'ct\'].dt.strftime(\'%Y-%m\')\\\\nd=ro.merge(ri,left_on=\'id\',right_on=\'return_order_id\')\\\\nd[\'qty_prec\']=d[\'quantity_precision\']\\\\nd[\'req_q\']=d[\'requested_qty\']/100; d[\'app_q\']=d[\'approved_qty\']/100\\\\nd[\'proc_q\']=d[\'processed_qty\']/100; d[\'amt\']=d[\'total_amount_it\']/100\\\\nd[\'amt_hdr\']=d[\'total_amount\']/100\\\\nCUR=(d[\'ct\']>=\'2026-05-25\')&(d[\'ct\']<=\'2026-11-22 23:59:59\')\\\\nPRE=(d[\'ct\']>=\'2025-11-23\')&(d[\'ct\']<=\'2026-05-24 23:59:59\')\\\\nd[\'win\']=np.where(CUR,\'CUR\',np.where(PRE,\'PRE\',\'OUT\'))\\\\nprint(\'窗口外行数\',(d[\'win\']==\'OUT\').sum())\\\\nvalid=d[d[\'status\']!=\'CANCELLED\']\\\\nprint(\'\\\\\\\\n=== 排除CANCELLED后 按窗口×类型 ===\')\\\\ng=valid.groupby([\'win\',\'return_type\']).agg(单数=(\'id\',\'nunique\'),申请量=(\'req_q\',\'sum\'),审核量=(\'app_q\',\'sum\'),执行量=(\'proc_q\',\'sum\'),金额=(\'amt\',\'sum\'))\\\\nprint(g.round(2))\\\\nprint(\'\\\\\\\\n=== 单均金额/单均申请量 ===\')\\\\ng2=valid.groupby([\'win\',\'return_type\']).agg(单数=(\'id\',\'nunique\'),金额=(\'amt\',\'sum\'),申请量=(\'req_q\',\'sum\'))\\\\ng2[\'单均金额\']=g2[\'金额\']/g2[\'单数\']; g2[\'单均申请量\']=g2[\'申请量\']/g2[\'单数\']\\\\nprint(g2.round(2))\\\\nprint(\'\\\\\\\\n=== 仅已执行(PARTIAL_EXECUTED+COMPLETED) ===\')\\\\nex=valid[valid[\'status\'].isin([\'PARTIAL_EXECUTED\',\'COMPLETED\'])]\\\\nprint(ex.groupby([\'win\',\'return_type\']).agg(单数=(\'id\',\'nunique\'),申请量=(\'req_q\',\'sum\'),执行量=(\'proc_q\',\'sum\'),金额=(\'amt\',\'sum\')).round(2))\\\\nprint(\'\\\\\\\\n=== 状态×窗口 (单数) ===\')\\\\nprint(pd.crosstab([valid[\'return_type\'],valid[\'win\']],valid[\'status\']))\\\\nprint(\'\\\\\\\\n=== 月度趋势(排除CANCELLED) ===\')\\\\nmt=valid.groupby([\'month\',\'return_type\']).agg(单数=(\'id\',\'nunique\'),申请量=(\'req_q\',\'sum\'),金额=(\'amt\',\'sum\')).round(2)\\\\nprint(mt)\\\", \\\"datasetIds\\\": [\\\"ds_37d891578535459393dcb70f762958da\\\", \\\"ds_fd1d7af2e5f14fc687f57a9602e84258\\\"], \\\"saveResult\\\": false}\", \"callId\": \"call_c1d949a8b29a4041a389e24b\"}','2026-11-22 19:34:08.131090');
