INSERT INTO `ai_agent_trace` (`id`, `user_id`, `conversation_id`, `task_id`, `agent_type`, `event_type`, `content`, `create_time`) VALUES (4378,1900000000000000001,2124465547335741442,'6722a262-5c55-403c-9ef6-d80a099344b8','ANALYSIS','TOOL_CALL','{\"name\": \"executePython\", \"text\": \"{\\\"code\\\": \\\"import json, pandas as pd, numpy as np\\\\nB=\'/tmp/erp-analysis/input/\'\\\\ndef load(ds, cols):\\\\n    rows=[json.loads(l) for l in open(B+ds+\'.jsonl\',encoding=\'utf-8\') if l.strip()]\\\\n    return pd.DataFrame(rows, columns=cols)\\\\nsup_in=load(\'ds_6901927af0b54f08963498f6618085bc\',[\'period\',\'supplier_id\',\'supplier_name\',\'bill_count\',\'qty\',\'amount_yuan\'])\\\\nfor c in [\'qty\',\'amount_yuan\',\'bill_count\']: sup_in[c]=pd.to_numeric(sup_in[c])\\\\nsup_in[\'sid\']=sup_in[\'supplier_id\'].astype(str)\\\\nprint(sup_in[\'sid\'].head(3).tolist(), sup_in[\'period\'].unique())\\\\nd=pd.read_pickle(\'/tmp/erp-analysis/ret.pkl\')\\\\nd[\'pid\']=d[\'party_id\'].astype(\'int64\').astype(str)\\\\nvalid=d[d[\'status\']!=\'CANCELLED\'].copy()\\\\ncur=valid[(valid[\'win\']==\'CUR\')&(valid[\'return_type\']==\'PURCHASE_RETURN\')]\\\\nsup=cur.groupby([\'pid\',\'party_name\']).agg(单数=(\'id\',\'nunique\'),金额=(\'amt\',\'sum\'),申请量=(\'req_q\',\'sum\')).sort_values(\'金额\',ascending=False)\\\\nbase=sup_in[sup_in[\'period\']==\'CUR\'].set_index(\'sid\')\\\\nprint(\'CUR有采购入库供应商\',len(base),\' 采购退货供应商\',len(sup))\\\\nrows=[]\\\\nfor (pid,pname),r in sup.head(12).iterrows():\\\\n    b=base.loc[pid] if pid in base.index else None\\\\n    rows.append([pname,int(r[\'单数\']),round(r[\'金额\'],2),round(b[\'amount_yuan\'],2) if b is not None else 0,\\\\n                 round(r[\'金额\']/b[\'amount_yuan\']*100,4) if b is not None and b[\'amount_yuan\'] else None,\\\\n                 round(r[\'申请量\'],2), round(b[\'qty\'],2) if b is not None else 0,\\\\n                 round(r[\'申请量\']/b[\'qty\']*100,4) if b is not None and b[\'qty\'] else None])\\\\nprint(pd.DataFrame(rows,columns=[\'供应商\',\'退货单数\',\'退货金额元\',\'本期入库金额元\',\'金额退货率%\',\'退货量\',\'入库量\',\'数量退货率%\']).to_string(index=False))\\\\nprint(\'\\\\\\\\n本期无退货的供应商数:\',len(set(base.index)-set(sup.index)),\'/ 有入库供应商\',len(base))\\\\nprint(\'\\\\\\\\n=== 销售退货 客户集中度 CUR ===\')\\\\nsc=valid[(valid[\'win\']==\'CUR\')&(valid[\'return_type\']==\'SALES_RETURN\')]\\\\nt=sc[\'amt\'].sum()\\\\ncust=sc.groupby([\'pid\',\'party_name\']).agg(单数=(\'id\',\'nunique\'),金额=(\'amt\',\'sum\'),申请量=(\'req_q\',\'sum\'))\\\\ncust[\'金额占比%\']=cust[\'金额\']/t*100\\\\ncust=cust.sort_values(\'金额\',ascending=False)\\\\nprint(\'总额 %.2f 客户数 %d 前1 %.1f%% 前3 %.1f%% 前5 %.1f%% 集中度%.4f\'%(t,len(cust),cust[\'金额占比%\'].head(1).sum(),cust[\'金额占比%\'].head(3).sum(),cust[\'金额占比%\'].head(5).sum(),((cust[\'金额占比%\']/100)**2).sum()))\\\\nprint(cust.head(10).round(2).to_string())\\\\nprint(\'\\\\\\\\n=== 销售退货 产品集中度 CUR ===\')\\\\nsp=sc.groupby([\'product_id\',\'product_name\',\'unit_name\']).agg(单数=(\'id\',\'nunique\'),金额=(\'amt\',\'sum\'),申请量=(\'req_q\',\'sum\')).sort_values(\'金额\',ascending=False)\\\\nsp[\'金额占比%\']=sp[\'金额\']/t*100\\\\nprint(\'产品数\',len(sp),\'前1 %.1f%% 前5 %.1f%% 前10 %.1f%%\'%(sp[\'金额占比%\'].head(1).sum(),sp[\'金额占比%\'].head(5).sum(),sp[\'金额占比%\'].head(10).sum()))\\\\nprint(sp.head(10).round(2).to_string())\\\\nsup.to_pickle(\'/tmp/erp-analysis/sup_cur.pkl\'); sp.to_pickle(\'/tmp/erp-analysis/sp_cur.pkl\'); cust.to_pickle(\'/tmp/erp-analysis/cust_cur.pkl\')\\\", \\\"datasetIds\\\": [\\\"ds_6901927af0b54f08963498f6618085bc\\\", \\\"ds_37d891578535459393dcb70f762958da\\\", \\\"ds_fd1d7af2e5f14fc687f57a9602e84258\\\"], \\\"saveResult\\\": false}\", \"callId\": \"call_1f17030079eb4081901f0add\"}','2026-11-22 19:34:38.548088');
