INSERT INTO `ai_agent_trace` (`id`, `user_id`, `conversation_id`, `task_id`, `agent_type`, `event_type`, `content`, `create_time`) VALUES (4800,1900000000000000001,2124475847040573442,'06b20c72-d819-433d-a1c5-891d27b3e2ad','MAIN','TOOL_RESULT','{\"name\": \"listAnalysisResults\", \"text\": \"{\\\"results\\\":[],\\\"analysisTaskId\\\":\\\"c533621e-c266-4992-ad49-a7a84ab24230\\\"}\", \"callId\": \"call_fe25102d8e3a4f1881cb84b2\"}','2026-11-22 20:12:49.582706');
INSERT INTO `ai_agent_trace` (`id`, `user_id`, `conversation_id`, `task_id`, `agent_type`, `event_type`, `content`, `create_time`) VALUES (4801,1900000000000000001,2124475847040573442,'06b20c72-d819-433d-a1c5-891d27b3e2ad','MAIN','MODEL_OUTPUT','{\"text\": \"没有可复用的中间结果。我重新交办一次该分析，收窄表述但保持同一范围口径。\"}','2026-11-22 20:12:53.156515');
INSERT INTO `ai_agent_trace` (`id`, `user_id`, `conversation_id`, `task_id`, `agent_type`, `event_type`, `content`, `create_time`) VALUES (4802,1900000000000000001,2124475847040573442,'06b20c72-d819-433d-a1c5-891d27b3e2ad','MAIN','TOOL_CALL','{\"name\": \"analyzeData\", \"text\": \"{\\\"context\\\": \\\"仓库范围仅限成都双流西仓（warehouse_id=8400000000004000004，编码 WH000004），已通过仓库主档确认系统内唯一无同名仓。业务日期 2026-11-22。相关表：sales_order（warehouse_id、status、expected_delivery_date、customer_name）、sales_order_item（sales_order_id、product_id、product_name、quantity、outbound_qty、locked_qty）、warehouse_stock（warehouse_id、product_id、stock_qty、locked_qty）、purchase_order/purchase_order_item（warehouse_id、status、expected_arrival_date、product_id、quantity、inbound_qty）。数量与库存均按100倍整数存储需除以100。已确认待发状态含 SUBMITTED、APPROVED、PARTIAL_OUTBOUND，排除 DRAFT、CANCELLED；履约风险按库存总量与待发量之差判断，不用可用库存。系统无仓间运输时效、无发运单，调拨能否赶上交付日需物流确认，交付完成以出库确认为准。\\\", \\\"goal\\\": \\\"判断成都双流西仓（warehouse_id=8400000000004000004）当前哪些待发销售订单无法按期交付，并找出最紧急的订单。\\\\n\\\\n口径：待发订单状态为 SUBMITTED、APPROVED、PARTIAL_OUTBOUND，排除 DRAFT 与 CANCELLED；待发量 = sales_order_item.quantity − outbound_qty（100倍整数，除以100还原）；按产品在该仓汇总待发需求，与该仓 warehouse_stock.stock_qty 比较（履约判断用库存总量与待发量差，不用可用库存；locked_qty 只用于核对锁定是否覆盖待发量）；在途取该仓采购订单中未入库数量 quantity − inbound_qty，且 expected_arrival_date 早于对应订单 expected_delivery_date 才计入有效供给；同一产品多订单竞争同一批库存时，按交付日从早到晚分配库存后再判断各订单是否被覆盖。\\\\n\\\\n需输出：\\\\n1) 待发订单数量、待发总量、涉及产品数；\\\\n2) 按产品列出待发量与账面库存、在途、缺口；\\\\n3) 风险订单清单：客户、销售单号、产品、待发数量、交付日、缺口、风险类型（无风险/有条件风险/高风险/已逾期），按交付日从早到晚排序，并指出最紧急的前几个；\\\\n4) 该仓最早供给断点日期；\\\\n5) 对高风险订单给出处置方向（调拨/催采购/拆单/延期），说明能解决多少、剩余多少、需谁确认。\\\\n\\\\n数量与金额换算：数量除以100，金额（分）除以100。请说明各步骤口径与数据限制。\\\"}\", \"callId\": \"call_9a0d9dc3bd414b0fb2c5416c\"}','2026-11-22 20:12:53.163327');
INSERT INTO `ai_agent_trace` (`id`, `user_id`, `conversation_id`, `task_id`, `agent_type`, `event_type`, `content`, `create_time`) VALUES (4803,1900000000000000001,2124475847040573442,'f92d1352-99ff-4ba8-9100-2fdaa3f1ea3d','ANALYSIS','INPUT','{\"text\": \"判断成都双流西仓（warehouse_id=8400000000004000004）当前哪些待发销售订单无法按期交付，并找出最紧急的订单。\\n\\n口径：待发订单状态为 SUBMITTED、APPROVED、PARTIAL_OUTBOUND，排除 DRAFT 与 CANCELLED；待发量 = sales_order_item.quantity − outbound_qty（100倍整数，除以100还原）；按产品在该仓汇总待发需求，与该仓 warehouse_stock.stock_qty 比较（履约判断用库存总量与待发量差，不用可用库存；locked_qty 只用于核对锁定是否覆盖待发量）；在途取该仓采购订单中未入库数量 quantity − inbound_qty，且 expected_arrival_date 早于对应订单 expected_delivery_date 才计入有效供给；同一产品多订单竞争同一批库存时，按交付日从早到晚分配库存后再判断各订单是否被覆盖。\\n\\n需输出：\\n1) 待发订单数量、待发总量、涉及产品数；\\n2) 按产品列出待发量与账面库存、在途、缺口；\\n3) 风险订单清单：客户、销售单号、产品、待发数量、交付日、缺口、风险类型（无风险/有条件风险/高风险/已逾期），按交付日从早到晚排序，并指出最紧急的前几个；\\n4) 该仓最早供给断点日期；\\n5) 对高风险订单给出处置方向（调拨/催采购/拆单/延期），说明能解决多少、剩余多少、需谁确认。\\n\\n数量与金额换算：数量除以100，金额（分）除以100。请说明各步骤口径与数据限制。\"}','2026-11-22 20:12:53.260838');
