INSERT INTO `ai_agent_trace` (`id`, `user_id`, `conversation_id`, `task_id`, `agent_type`, `event_type`, `content`, `create_time`) VALUES (4853,1900000000000000001,2124475847040573442,'f92d1352-99ff-4ba8-9100-2fdaa3f1ea3d','ANALYSIS','MODEL_OUTPUT','{\"text\": \"JSONL 每一行是数组，因此需要显式指定列名后重新加载，并核对待发量与锁定。\"}','2026-11-22 20:14:20.057328');
INSERT INTO `ai_agent_trace` (`id`, `user_id`, `conversation_id`, `task_id`, `agent_type`, `event_type`, `content`, `create_time`) VALUES (4854,1900000000000000001,2124475847040573442,'f92d1352-99ff-4ba8-9100-2fdaa3f1ea3d','ANALYSIS','TOOL_CALL','{\"name\": \"executePython\", \"text\": \"{\\\"code\\\": \\\"import pandas as pd, numpy as np\\\\nbase=\'/tmp/erp-analysis/input/\'\\\\nso=pd.read_json(base+\'ds_a901e8bb0d7d4eb696e58d81421a7e06.jsonl\',lines=True,orient=\'records\')\\\\nso.columns=[\'sales_order_id\',\'sales_no\',\'customer_name\',\'status\',\'expected_delivery_date\',\'product_id\',\'product_code\',\'product_name\',\'unit_name\',\'quantity\',\'outbound_qty\',\'pending_qty\',\'locked_qty\',\'create_time\']\\\\nro=pd.read_json(base+\'ds_e0ce38f9f450403394e6860c89c7e44e.jsonl\',lines=True,orient=\'records\')\\\\nro.columns=[\'warehouse_id\',\'product_id\',\'product_code\',\'product_name\',\'unit_name\',\'stock_qty\',\'locked_qty\']\\\\npo=pd.read_json(base+\'ds_fd967aa0eea346bf8912f0779cfccbfe.jsonl\',lines=True,orient=\'records\')\\\\npo.columns=[\'purchase_no\',\'supplier_name\',\'status\',\'expected_arrival_date\',\'product_id\',\'product_code\',\'product_name\',\'unit_name\',\'quantity\',\'inbound_qty\',\'pending_qty\']\\\\npr=pd.read_json(base+\'ds_cb78e8a523e04a4a8be9ca6aad3f2c0b.jsonl\',lines=True,orient=\'records\')\\\\npr.columns=[\'product_id\',\'product_code\',\'product_name\',\'unit_name\',\'quantity_precision\',\'safety_stock_qty\',\'status\']\\\\n\\\\nnum_so=[\'quantity\',\'outbound_qty\',\'pending_qty\',\'locked_qty\']\\\\nfor c in num_so: so[c]=pd.to_numeric(so[c])\\\\nso[\'expected_delivery_date\']=pd.to_datetime(so[\'expected_delivery_date\']).dt.date\\\\nfor c in [\'stock_qty\',\'locked_qty\']: ro[c]=pd.to_numeric(ro[c])\\\\nfor c in [\'quantity\',\'inbound_qty\',\'pending_qty\']: po[c]=pd.to_numeric(po[c])\\\\npo[\'expected_arrival_date\']=pd.to_datetime(po[\'expected_arrival_date\']).dt.date\\\\npr[\'safety_stock_qty\']=pd.to_numeric(pr[\'safety_stock_qty\'])\\\\n\\\\n# checks\\\\nprint(\'calc pending vs given mismatch:\', (so.quantity-so.outbound_qty != so.pending_qty).sum())\\\\nprint(\'neg pending rows:\', (so.pending_qty<0).sum())\\\\nprint(\'dup (order,product):\', so.duplicated([\'sales_order_id\',\'product_id\']).sum())\\\\nprint(\'dup order-product-name:\', so.duplicated([\'sales_no\',\'product_code\']).sum())\\\\nprint(\'null delivery date:\', so.expected_delivery_date.isna().sum())\\\\nprint(\'date range:\', so.expected_delivery_date.min(), so.expected_delivery_date.max())\\\\nprint(\'status counts:\\\\\\\\n\', so.status.value_counts())\\\\nprint(\'orders:\', so.sales_order_id.nunique(), \'products:\', so.product_id.nunique())\\\\nprint(\'total pending (units/100):\', so.pending_qty.sum()/100)\\\\nprint(\'pending=0 rows:\', (so.pending_qty==0).sum())\\\\nprint(\'pending=0 orders:\', so[so.pending_qty==0].sales_order_id.nunique(), \'/\', so.sales_order_id.nunique())\\\\nprint(\'stock dup product:\', ro.product_id.duplicated().sum(), \'prod dup:\', pr.product_id.duplicated().sum())\\\\nprint(\'po status:\\\\\\\\n\', po.status.value_counts())\\\\nprint(\'po null arrival:\', po.expected_arrival_date.isna().sum())\\\", \\\"datasetIds\\\": [\\\"ds_a901e8bb0d7d4eb696e58d81421a7e06\\\", \\\"ds_e0ce38f9f450403394e6860c89c7e44e\\\", \\\"ds_fd967aa0eea346bf8912f0779cfccbfe\\\", \\\"ds_cb78e8a523e04a4a8be9ca6aad3f2c0b\\\"], \\\"saveResult\\\": false}\", \"callId\": \"call_50aba2f2eb744d68a7256939\"}','2026-11-22 20:14:20.063848');
