INSERT INTO `ai_agent_trace` (`id`, `user_id`, `conversation_id`, `task_id`, `agent_type`, `event_type`, `content`, `create_time`) VALUES (4863,1900000000000000001,2124475847040573442,'f92d1352-99ff-4ba8-9100-2fdaa3f1ea3d','ANALYSIS','TOOL_CALL','{\"name\": \"executePython\", \"text\": \"{\\\"code\\\": \\\"import json, pandas as pd, numpy as np\\\\nbase=\'/tmp/erp-analysis/input/\'\\\\ndef load(p,cols):\\\\n    with open(p,encoding=\'utf-8\') as f:\\\\n        df=pd.DataFrame([json.loads(l) for l in f if l.strip()])\\\\n    df.columns=cols; return df\\\\nso=load(base+\'ds_a901e8bb0d7d4eb696e58d81421a7e06.jsonl\',[\'sales_order_id\',\'sales_no\',\'customer_name\',\'status\',\'expected_delivery_date\',\'product_id\',\'product_code\',\'product_name\',\'unit_name\',\'quantity\',\'outbound_qty\',\'pending_qty\',\'locked_qty\',\'create_time\'])\\\\nro=load(base+\'ds_e0ce38f9f450403394e6860c89c7e44e.jsonl\',[\'warehouse_id\',\'product_id\',\'product_code\',\'product_name\',\'unit_name\',\'stock_qty\',\'locked_qty\'])\\\\npo=load(base+\'ds_fd967aa0eea346bf8912f0779cfccbfe.jsonl\',[\'purchase_no\',\'supplier_name\',\'status\',\'expected_arrival_date\',\'product_id\',\'product_code\',\'product_name\',\'unit_name\',\'quantity\',\'inbound_qty\',\'pending_qty\'])\\\\npr=load(base+\'ds_cb78e8a523e04a4a8be9ca6aad3f2c0b.jsonl\',[\'product_id\',\'product_code\',\'product_name\',\'unit_name\',\'quantity_precision\',\'safety_stock_qty\',\'status\'])\\\\n\\\\nfor c in [\'quantity\',\'outbound_qty\',\'pending_qty\',\'locked_qty\']: so[c]=so[c].astype(int)\\\\nso[\'edd\']=pd.to_datetime(so[\'expected_delivery_date\'])\\\\nfor c in [\'stock_qty\',\'locked_qty\']: ro[c]=ro[c].astype(int)\\\\nfor c in [\'quantity\',\'inbound_qty\',\'pending_qty\']: po[c]=po[c].astype(int)\\\\npo[\'ead\']=pd.to_datetime(po[\'expected_arrival_date\'])\\\\npr[\'safety_stock_qty\']=pr[\'safety_stock_qty\'].astype(int)\\\\n\\\\nprint(\'pending recompute mismatch\', (so.quantity-so.outbound_qty!=so.pending_qty).sum(), \'neg pending\', (so.pending_qty<0).sum())\\\\nprint(\'rows pending>0:\', (so.pending_qty>0).sum(), \'orders with pending>0:\', so[so.pending_qty>0].sales_order_id.nunique())\\\\nprint(\'\\\\\\\\ndelivery year counts:\'); print(so.edd.dt.year.value_counts().sort_index().to_string())\\\\nprint(\'\\\\\\\\norders by delivery date:\'); \\\\ng=so.groupby([\'sales_no\',\'customer_name\',\'status\'])[\'edd\'].first().reset_index().sort_values(\'edd\')\\\\nprint(g.to_string())\\\\nprint(\'\\\\\\\\nlocked vs pending totals:\', so.locked_qty.sum()/100, so.pending_qty.sum()/100)\\\\nprint(\'rows locked>pending:\', (so.locked_qty>so.pending_qty).sum(), \'rows locked<pending:\', (so.locked_qty<so.pending_qty).sum())\\\\nprint(\'stock dup:\',ro.product_id.duplicated().sum(),\'prod dup:\',pr.product_id.duplicated().sum())\\\\nprint(\'po rows with pending>0:\',(po.pending_qty>0).sum())\\\\nprint(\'prod status0 among pending products:\', pr[pr.status==0].product_id.nunique())\\\", \\\"datasetIds\\\": [], \\\"saveResult\\\": false}\", \"callId\": \"call_c6c343af14b743539f64d1b7\"}','2026-11-22 20:14:30.923444');
