INSERT INTO `ai_agent_trace` (`id`, `user_id`, `conversation_id`, `task_id`, `agent_type`, `event_type`, `content`, `create_time`) VALUES (4866,1900000000000000001,2124475847040573442,'f92d1352-99ff-4ba8-9100-2fdaa3f1ea3d','ANALYSIS','TOOL_CALL','{\"name\": \"executePython\", \"text\": \"{\\\"code\\\": \\\"import json, pandas as pd, numpy as np\\\\nbase=\'/tmp/erp-analysis/input/\'\\\\ndef load(p,cols):\\\\n    with open(p,encoding=\'utf-8\') as f:\\\\n        df=pd.DataFrame([json.loads(l) for l in f if l.strip()])\\\\n    df.columns=cols; return df\\\\nso=load(base+\'ds_a901e8bb0d7d4eb696e58d81421a7e06.jsonl\',[\'sales_order_id\',\'sales_no\',\'customer_name\',\'status\',\'expected_delivery_date\',\'product_id\',\'product_code\',\'product_name\',\'unit_name\',\'quantity\',\'outbound_qty\',\'pending_qty\',\'locked_qty\',\'create_time\'])\\\\nro=load(base+\'ds_e0ce38f9f450403394e6860c89c7e44e.jsonl\',[\'warehouse_id\',\'product_id\',\'product_code\',\'product_name\',\'unit_name\',\'stock_qty\',\'locked_qty\'])\\\\npo=load(base+\'ds_fd967aa0eea346bf8912f0779cfccbfe.jsonl\',[\'purchase_no\',\'supplier_name\',\'status\',\'expected_arrival_date\',\'product_id\',\'product_code\',\'product_name\',\'unit_name\',\'quantity\',\'inbound_qty\',\'pending_qty\'])\\\\npr=load(base+\'ds_cb78e8a523e04a4a8be9ca6aad3f2c0b.jsonl\',[\'product_id\',\'product_code\',\'product_name\',\'unit_name\',\'quantity_precision\',\'safety_stock_qty\',\'status\'])\\\\nfor c in [\'quantity\',\'outbound_qty\',\'pending_qty\',\'locked_qty\']: so[c]=so[c].astype(int)\\\\nso[\'edd\']=pd.to_datetime(so[\'expected_delivery_date\'])\\\\nfor c in [\'stock_qty\',\'locked_qty\']: ro[c]=ro[c].astype(int)\\\\nfor c in [\'quantity\',\'inbound_qty\',\'pending_qty\']: po[c]=po[c].astype(int)\\\\npo[\'ead\']=pd.to_datetime(po[\'expected_arrival_date\'])\\\\npr[\'safety_stock_qty\']=pr[\'safety_stock_qty\'].astype(int)\\\\nTODAY=pd.Timestamp(\'2026-11-22\')\\\\n\\\\n# product level supply\\\\nposum=po.groupby(\'product_id\').agg(po_pending=(\'pending_qty\',\'sum\'), po_earliest=(\'ead\',\'min\'), po_rows=(\'pending_qty\',\'size\')).reset_index()\\\\nstock=ro.set_index(\'product_id\')[\'stock_qty\']\\\\nsumm=so.groupby([\'product_id\',\'product_code\',\'product_name\',\'unit_name\']).agg(pending=(\'pending_qty\',\'sum\'), order_cnt=(\'sales_no\',\'nunique\'), earliest=(\'edd\',\'min\')).reset_index()\\\\nsumm[\'stock\']=summ.product_id.map(stock).fillna(0).astype(int)\\\\nsumm[\'stock_missing\']=~summ.product_id.isin(ro.product_id)\\\\nsumm=summ.merge(posum,on=\'product_id\',how=\'left\')\\\\nsumm[[\'po_pending\',\'po_rows\']]=summ[[\'po_pending\',\'po_rows\']].fillna(0).astype(int)\\\\nsumm[\'gap_stock\']=(summ.pending-summ.stock).clip(lower=0)\\\\nprint(\'products with pending:\', len(summ))\\\\nprint(\'sum pending/100\', summ.pending.sum()/100, \'sum stock/100\', summ.stock.sum()/100)\\\\nprint(\'products stock missing:\', summ.stock_missing.sum())\\\\nprint(\'products with gap_stock>0:\', (summ.gap_stock>0).sum(), \'gap sum/100\', summ.gap_stock.sum()/100)\\\\nprint(\'products with in-transit:\', (summ.po_pending>0).sum())\\\\nprint(\'\\\\\\\\ntop20 by gap:\'); print(summ.sort_values(\'gap_stock\',ascending=False).head(20)[[\'product_code\',\'product_name\',\'pending\',\'stock\',\'po_pending\',\'gap_stock\',\'earliest\']].assign(pending=lambda d:d.pending/100,stock=lambda d:d.stock/100,po_pending=lambda d:d.po_pending/100,gap_stock=lambda d:d.gap_stock/100).to_string())\\\\nsumm.to_csv(\'/tmp/erp-analysis/output/_prod_supply.csv\',index=False)\\\", \\\"datasetIds\\\": [], \\\"saveResult\\\": false}\", \"callId\": \"call_ddd49d164f3f4e1f8081c34d\"}','2026-11-22 20:14:41.646159');
