INSERT INTO `ai_agent_trace` (`id`, `user_id`, `conversation_id`, `task_id`, `agent_type`, `event_type`, `content`, `create_time`) VALUES (4872,1900000000000000001,2124475847040573442,'f92d1352-99ff-4ba8-9100-2fdaa3f1ea3d','ANALYSIS','TOOL_CALL','{\"name\": \"executePython\", \"text\": \"{\\\"code\\\": \\\"import json, pandas as pd, numpy as np, os\\\\nbase=\'/tmp/erp-analysis/input/\'\\\\ndef load(p,cols):\\\\n    with open(p,encoding=\'utf-8\') as f:\\\\n        df=pd.DataFrame([json.loads(l) for l in f if l.strip()])\\\\n    df.columns=cols; return df\\\\nso=load(base+\'ds_a901e8bb0d7d4eb696e58d81421a7e06.jsonl\',[\'sales_order_id\',\'sales_no\',\'customer_name\',\'status\',\'expected_delivery_date\',\'product_id\',\'product_code\',\'product_name\',\'unit_name\',\'quantity\',\'outbound_qty\',\'pending_qty\',\'locked_qty\',\'create_time\'])\\\\nro=load(base+\'ds_e0ce38f9f450403394e6860c89c7e44e.jsonl\',[\'warehouse_id\',\'product_id\',\'product_code\',\'product_name\',\'unit_name\',\'stock_qty\',\'locked_qty\'])\\\\npo=load(base+\'ds_fd967aa0eea346bf8912f0779cfccbfe.jsonl\',[\'purchase_no\',\'supplier_name\',\'status\',\'expected_arrival_date\',\'product_id\',\'product_code\',\'product_name\',\'unit_name\',\'quantity\',\'inbound_qty\',\'pending_qty\'])\\\\nfor c in [\'quantity\',\'outbound_qty\',\'pending_qty\',\'locked_qty\']: so[c]=so[c].astype(int)\\\\nso[\'edd\']=pd.to_datetime(so[\'expected_delivery_date\'])\\\\nfor c in [\'stock_qty\',\'locked_qty\']: ro[c]=ro[c].astype(int)\\\\nfor c in [\'quantity\',\'inbound_qty\',\'pending_qty\']: po[c]=po[c].astype(int)\\\\npo[\'ead\']=pd.to_datetime(po[\'expected_arrival_date\'])\\\\nalloc=pd.read_csv(\'/tmp/erp-analysis/output/_alloc.csv\')\\\\nalloc[\'edd\']=pd.to_datetime(alloc[\'edd\'])\\\\nTODAY=pd.Timestamp(\'2026-11-22\')\\\\n\\\\nprint(\'by unit pending:\'); print((so.groupby(\'unit_name\').pending_qty.sum()/100).to_string())\\\\nprint(\'\\\\\\\\norders by status among pending>0:\')\\\\no=so[so.pending_qty>0].groupby(\'status\').agg(orders=(\'sales_no\',\'nunique\'), lines=(\'sales_no\',\'size\'), pending=(\'pending_qty\',\'sum\'))\\\\no[\'pending\']=o.pending/100; print(o.to_string())\\\\nprint(\'\\\\\\\\noverdue:\')\\\\nov=so[so.edd<TODAY]\\\\nprint(\'overdue orders\', ov.sales_no.nunique(), \'lines\', len(ov), \'pending\', ov.pending_qty.sum()/100)\\\\nprint(\'overdue orders with partial shipped (outbound_qty>0 on some line):\', alloc[alloc.edd<TODAY].groupby(\'sales_no\').outbound_qty.max().gt(0).sum())\\\\nprint(\'max overdue days\', int((TODAY-ov.edd.min()).days), \'min overdue days\', int((TODAY-ov.edd.max()).days))\\\\nprint(\'overdue pending by status:\'); print((ov.groupby(\'status\').pending_qty.sum()/100).to_string())\\\\nprint(\'\\\\\\\\nfuture orders (edd>=today): lines\', len(alloc[alloc.edd>=TODAY]), \'orders\', alloc[alloc.edd>=TODAY].sales_no.nunique(), \'pending\', alloc[alloc.edd>=TODAY].pending_qty.sum()/100, \'gap\', alloc[alloc.edd>=TODAY].gap.sum()/100)\\\\nprint(\'earliest future delivery:\', alloc[alloc.edd>=TODAY].edd.min())\\\\nprint(\'\\\\\\\\nin-transit: total\', po.pending_qty.sum()/100, \'rows\', len(po), \'products\', po.product_id.nunique())\\\\nprint(\'in-transit arrival < today (overdue PO):\', (po.ead<TODAY).sum(), \'qty\', po[po.ead<TODAY].pending_qty.sum()/100)\\\\nprint(\'in-transit earliest arrival:\', po.ead.min(), \'latest:\', po.ead.max())\\\\nprint(\'PO DRAFT rows:\', (po.status==\'DRAFT\').sum(), \'qty\', po[po.status==\'DRAFT\'].pending_qty.sum()/100)\\\\nprint(\'\\\\\\\\nstock vs pending overall: stock\', ro.stock_qty.sum()/100, \'pending\', so.pending_qty.sum()/100)\\\\nprint(\'locked sum vs pending sum:\', ro.locked_qty.sum()/100, so.locked_qty.sum()/100)\\\\nprint(\'products with stock< pending:\', (ro.set_index(\'product_id\').stock_qty.reindex(so.product_id.unique()).fillna(0) < so.groupby(\'product_id\').pending_qty.sum()).sum())\\\\ncov=(so.groupby(\'product_id\').pending_qty.sum()/ ro.set_index(\'product_id\').stock_qty.reindex(so.product_id.unique()).fillna(0).replace(0,np.nan))\\\\nprint(\'min product coverage:\', round(cov.min(),3), \'products coverage<0.9:\', (cov<0.9).sum())\\\\nprint(\'5 products missing stock record:\', so.groupby(\'product_id\').pending_qty.sum()[~so.groupby(\'product_id\').pending_qty.sum().index.isin(ro.product_id)].div(100).to_dict())\\\", \\\"datasetIds\\\": [], \\\"saveResult\\\": false}\", \"callId\": \"call_a98f3bfd76834cca805e86c7\"}','2026-11-22 20:15:10.815410');
