INSERT INTO `ai_agent_trace` (`id`, `user_id`, `conversation_id`, `task_id`, `agent_type`, `event_type`, `content`, `create_time`) VALUES (4875,1900000000000000001,2124475847040573442,'f92d1352-99ff-4ba8-9100-2fdaa3f1ea3d','ANALYSIS','TOOL_CALL','{\"name\": \"executePython\", \"text\": \"{\\\"code\\\": \\\"import json, pandas as pd, numpy as np\\\\nbase=\'/tmp/erp-analysis/input/\'\\\\ndef load(p,cols):\\\\n    with open(p,encoding=\'utf-8\') as f:\\\\n        df=pd.DataFrame([json.loads(l) for l in f if l.strip()])\\\\n    df.columns=cols; return df\\\\nso=load(base+\'ds_a901e8bb0d7d4eb696e58d81421a7e06.jsonl\',[\'sales_order_id\',\'sales_no\',\'customer_name\',\'status\',\'expected_delivery_date\',\'product_id\',\'product_code\',\'product_name\',\'unit_name\',\'quantity\',\'outbound_qty\',\'pending_qty\',\'locked_qty\',\'create_time\'])\\\\nro=load(base+\'ds_e0ce38f9f450403394e6860c89c7e44e.jsonl\',[\'warehouse_id\',\'product_id\',\'product_code\',\'product_name\',\'unit_name\',\'stock_qty\',\'locked_qty\'])\\\\nfor c in [\'quantity\',\'outbound_qty\',\'pending_qty\',\'locked_qty\']: so[c]=so[c].astype(int)\\\\nso[\'edd\']=pd.to_datetime(so[\'expected_delivery_date\'])\\\\nfor c in [\'stock_qty\',\'locked_qty\']: ro[c]=ro[c].astype(int)\\\\n\\\\npend=so.groupby(\'product_id\').pending_qty.sum()\\\\nstock=ro.set_index(\'product_id\')[\'stock_qty\']\\\\nmissing=[p for p in pend.index if p not in stock.index]\\\\nprint(\'missing stock records products:\', len(missing))\\\\nprint(so[so.product_id.isin(missing)][[\'sales_no\',\'product_code\',\'product_name\',\'expected_delivery_date\',\'quantity\',\'outbound_qty\',\'pending_qty\',\'locked_qty\']].to_string())\\\\nal=stock.reindex(pend.index).fillna(0)\\\\ncov=pend/al.replace(0,np.nan)\\\\nprint(\'products with coverage<0.9:\', int((cov<0.9).sum()), \'min cov:\', round(float(cov.min()),3))\\\\nprint(\'products stock==0 but pending>0:\', int(((al==0)&(pend>0)).sum()))\\\\nprint(\'\\\\\\\\nproducts where pending == stock exactly:\', int((pend==al).sum()))\\\\n\\\\n# locked reconciliation\\\\nordlk=so.groupby(\'product_id\').locked_qty.sum()\\\\nstklk=ro.set_index(\'product_id\')[\'locked_qty\']\\\\nd=(stklk.reindex(ordlk.index).fillna(0)-ordlk)\\\\nprint(\'\\\\\\\\nlock diff total:\', d.sum()/100, \'products with diff!=0:\', int((d!=0).sum()))\\\\nprint(d[d!=0].div(100).to_string())\\\\nprint(\'\\\\\\\\nwarehouse stock locked>0 products:\', int((ro.locked_qty>0).sum()), \'total\', ro.locked_qty.sum()/100)\\\\n# products where stock locked > order locked\\\\nextra=(stklk-stklk.reindex(ordlk.index).fillna(0))\\\\nprint(\'stock locked on products with no pending orders:\', extra[~extra.index.isin(ordlk.index)].sum()/100)\\\", \\\"datasetIds\\\": [], \\\"saveResult\\\": false}\", \"callId\": \"call_01230d06da8340e988c0f98d\"}','2026-11-22 20:15:17.278183');
