INSERT INTO `ai_agent_trace` (`id`, `user_id`, `conversation_id`, `task_id`, `agent_type`, `event_type`, `content`, `create_time`) VALUES (4878,1900000000000000001,2124475847040573442,'f92d1352-99ff-4ba8-9100-2fdaa3f1ea3d','ANALYSIS','TOOL_CALL','{\"name\": \"executePython\", \"text\": \"{\\\"code\\\": \\\"import json, pandas as pd, numpy as np\\\\nbase=\'/tmp/erp-analysis/input/\'\\\\ndef load(p,cols):\\\\n    with open(p,encoding=\'utf-8\') as f:\\\\n        df=pd.DataFrame([json.loads(l) for l in f if l.strip()])\\\\n    df.columns=cols; return df\\\\nso=load(base+\'ds_a901e8bb0d7d4eb696e58d81421a7e06.jsonl\',[\'sales_order_id\',\'sales_no\',\'customer_name\',\'status\',\'expected_delivery_date\',\'product_id\',\'product_code\',\'product_name\',\'unit_name\',\'quantity\',\'outbound_qty\',\'pending_qty\',\'locked_qty\',\'create_time\'])\\\\nro=load(base+\'ds_e0ce38f9f450403394e6860c89c7e44e.jsonl\',[\'warehouse_id\',\'product_id\',\'product_code\',\'product_name\',\'unit_name\',\'stock_qty\',\'locked_qty\'])\\\\nfor c in [\'quantity\',\'outbound_qty\',\'pending_qty\',\'locked_qty\']: so[c]=so[c].astype(int)\\\\nfor c in [\'stock_qty\',\'locked_qty\']: ro[c]=ro[c].astype(int)\\\\npend=so.groupby(\'product_id\').pending_qty.sum()\\\\nstock=ro.set_index(\'product_id\')[\'stock_qty\']\\\\ndf=pd.DataFrame({\'pending\':pend,\'stock\':stock.reindex(pend.index)})\\\\ndf[\'gap\']=df.pending-df.stock\\\\nprint(\'rows\',len(df),\'nan stock\',df.stock.isna().sum())\\\\nprint(\'gap>0 count\', int((df.gap>0).sum()))\\\\nprint(df.sort_values(\'gap\',ascending=False).head(8).to_string())\\\\nprint(df.sort_values(\'gap\').head(8).to_string())\\\\n# recompute coverage properly\\\\ndf2=df.dropna()\\\\nprint(\'cov min\', round(float((df2.pending/df2.stock).min()),3), \'cov<0.9\', int((df2.pending/df2.stock<0.9).sum()))\\\\nprint(\'pend==stock rows\', int((df.gap==0).sum()))\\\", \\\"datasetIds\\\": [], \\\"saveResult\\\": false}\", \"callId\": \"call_baeebbbbc9924f8491c7a5e2\"}','2026-11-22 20:15:23.026676');
