INSERT INTO `ai_agent_trace` (`id`, `user_id`, `conversation_id`, `task_id`, `agent_type`, `event_type`, `content`, `create_time`) VALUES (4881,1900000000000000001,2124475847040573442,'f92d1352-99ff-4ba8-9100-2fdaa3f1ea3d','ANALYSIS','TOOL_CALL','{\"name\": \"executePython\", \"text\": \"{\\\"code\\\": \\\"import json, pandas as pd, numpy as np\\\\nbase=\'/tmp/erp-analysis/input/\'\\\\ndef load(p,cols):\\\\n    with open(p,encoding=\'utf-8\') as f:\\\\n        df=pd.DataFrame([json.loads(l) for l in f if l.strip()])\\\\n    df.columns=cols; return df\\\\nso=load(base+\'ds_a901e8bb0d7d4eb696e58d81421a7e06.jsonl\',[\'sales_order_id\',\'sales_no\',\'customer_name\',\'status\',\'expected_delivery_date\',\'product_id\',\'product_code\',\'product_name\',\'unit_name\',\'quantity\',\'outbound_qty\',\'pending_qty\',\'locked_qty\',\'create_time\'])\\\\nro=load(base+\'ds_e0ce38f9f450403394e6860c89c7e44e.jsonl\',[\'warehouse_id\',\'product_id\',\'product_code\',\'product_name\',\'unit_name\',\'stock_qty\',\'locked_qty\'])\\\\npo=load(base+\'ds_fd967aa0eea346bf8912f0779cfccbfe.jsonl\',[\'purchase_no\',\'supplier_name\',\'status\',\'expected_arrival_date\',\'product_id\',\'product_code\',\'product_name\',\'unit_name\',\'quantity\',\'inbound_qty\',\'pending_qty\'])\\\\npr=load(base+\'ds_cb78e8a523e04a4a8be9ca6aad3f2c0b.jsonl\',[\'product_id\',\'product_code\',\'product_name\',\'unit_name\',\'quantity_precision\',\'safety_stock_qty\',\'status\'])\\\\nfor c in [\'quantity\',\'outbound_qty\',\'pending_qty\',\'locked_qty\']: so[c]=so[c].astype(int)\\\\nso[\'edd\']=pd.to_datetime(so[\'expected_delivery_date\'])\\\\nfor c in [\'stock_qty\',\'locked_qty\']: ro[c]=ro[c].astype(int)\\\\nfor c in [\'quantity\',\'inbound_qty\',\'pending_qty\']: po[c]=po[c].astype(int)\\\\npo[\'ead\']=pd.to_datetime(po[\'expected_arrival_date\'])\\\\npr[\'safety_stock_qty\']=pr[\'safety_stock_qty\'].astype(int)\\\\nTODAY=pd.Timestamp(\'2026-11-22\')\\\\n\\\\nstock=ro.set_index(\'product_id\')[\'stock_qty\']; safety=pr.set_index(\'product_id\')[\'safety_stock_qty\']\\\\nposum=po.groupby(\'product_id\').agg(po_pending=(\'pending_qty\',\'sum\'), po_earliest=(\'ead\',\'min\'), po_n=(\'purchase_no\',\'nunique\'), po_suppliers=(\'supplier_name\',lambda s:\'；\'.join(sorted(set(s))))).reset_index()\\\\n\\\\n# sequential allocation per product\\\\nd=so.sort_values([\'product_id\',\'edd\',\'sales_no\']).copy()\\\\nused={}; alloc=[]\\\\nfor r in d.itertuples():\\\\n    s=int(stock.get(r.product_id,0)); u=used.get(r.product_id,0)\\\\n    give=max(0,min(s-u, r.pending_qty)); used[r.product_id]=u+give; alloc.append(give)\\\\nd[\'allocated\']=alloc; d[\'gap\']=d.pending_qty-d.allocated\\\\nd[\'remain_after\']=d.product_id.map(lambda p: int(stock.get(p,0))-used[p])\\\\nd[\'safety\']=d.product_id.map(lambda p: safety.get(p,np.nan))\\\\nd[\'overdue_days\']=(TODAY-d.edd).dt.days\\\\nd[\'prog\']=np.where(d.quantity>0, d.outbound_qty/d.quantity, 0)\\\\ndef risk(r):\\\\n    if r.pending_qty==0: return \'无风险\'\\\\n    if r.overdue_days>0: return \'已逾期\'\\\\n    if r.gap>0: return \'高风险\'\\\\n    if pd.notna(r.safety) and r.remain_after<r.safety: return \'潜在风险\'\\\\n    return \'无风险\'\\\\nd[\'risk\']=d.apply(risk,axis=1)\\\\nprint(d.risk.value_counts().to_string())\\\\n\\\\n# product table\\\\npt=d.groupby([\'product_id\',\'product_code\',\'product_name\',\'unit_name\']).agg(\\\\n    pending=(\'pending_qty\',\'sum\'), order_cnt=(\'sales_no\',\'nunique\'), first_edd=(\'edd\',\'min\'),\\\\n    order_locked=(\'locked_qty\',\'sum\')).reset_index()\\\\npt[\'stock\']=pt.product_id.map(stock)\\\\npt[\'stock_record_missing\']=pt.stock.isna()\\\\npt[\'stock\']=pt.stock.fillna(0).astype(int)\\\\npt=pt.merge(posum,on=\'product_id\',how=\'left\')\\\\nfor c in [\'po_pending\',\'po_n\']: pt[c]=pt[c].fillna(0).astype(int)\\\\npt[\'gap_stock\']=(pt.pending-pt.stock).clip(lower=0)\\\\npt[\'gap_after_transit\']=(pt.pending-pt.stock-pt.po_pending).clip(lower=0)\\\\npt[\'coverage\']=np.where(pt.pending>0,(pt.stock+pt.po_pending)/pt.pending,np.nan)\\\\npt[\'safety\']=pt.product_id.map(safety)\\\\npt[\'stock_after\']=pt.stock-pt.pending\\\\npt[\'below_safety_after\']=pt.stock_after < pt.safety.fillna(0)\\\\nprint(\'\\\\\\\\nproducts\',len(pt),\'| gap_stock>0:\',int((pt.gap_stock>0).sum()),\'| below safety after shipping:\',int(pt.below_safety_after.sum()))\\\\nprint(\'sum pending (mixed units) /100:\', pt.pending.sum()/100, \' stock:\', pt.stock.sum()/100)\\\\nprint(pt[pt.below_safety_after][[\'product_code\',\'product_name\',\'pending\',\'stock\',\'stock_after\',\'safety\',\'first_edd\']].to_string())\\\\n\\\\n# order table\\\\not=d.groupby([\'sales_order_id\',\'sales_no\',\'customer_name\',\'status\',\'expected_delivery_date\']).agg(\\\\n    lines=(\'product_id\',\'nunique\'), pending=(\'pending_qty\',\'sum\'), gap=(\'gap\',\'sum\'),\\\\n    min_prog=(\'prog\',\'min\'), max_prog=(\'prog\',\'max\')).reset_index()\\\\not[\'overdue_days\']=(TODAY-pd.to_datetime(ot.expected_delivery_date)).dt.days\\\\ndef orisk(r):\\\\n    if r.pending==0: return \'无风险\'\\\\n    if r.overdue_days>0: return \'已逾期\'\\\\n    if r.gap>0: return \'高风险\'\\\\n    return \'无风险\'\\\\not[\'risk\']=ot.apply(orisk,axis=1)\\\\not=ot.sort_values([\'expected_delivery_date\',\'sales_no\'])\\\\not[\'unit\']=ot.sales_order_id.map(d.groupby(\'sales_order_id\').unit_name.agg(lambda s:\'/\'.join(sorted(set(s)))))\\\\nprint(\'\\\\\\\\ncustomer counts:\')\\\\nprint(ot.risk.value_counts().to_string())\\\\nprint(\'overdue orders pending sum:\', ot[ot.risk==\'已逾期\'].pending.sum()/100, \'units mixed\')\\\\nprint(\'\\\\\\\\nfirst 10 urgent (by delivery date):\')\\\\nprint(ot.head(10)[[\'sales_no\',\'customer_name\',\'status\',\'expected_delivery_date\',\'overdue_days\',\'lines\',\'pending\',\'gap\',\'risk\']].assign(pending=lambda x:x.pending/100).to_string())\\\\nprint(\'\\\\\\\\nfuture 4:\')\\\\nprint(ot[ot.risk==\'无风险\'][[\'sales_no\',\'customer_name\',\'status\',\'expected_delivery_date\',\'pending\',\'gap\',\'risk\']].assign(pending=lambda x:x.pending/100).to_string())\\\\not.to_csv(\'/tmp/erp-analysis/output/fulfillment_risk_orders.csv\',index=False,encoding=\'utf-8-sig\')\\\\nd.to_csv(\'/tmp/erp-analysis/output/fulfillment_risk_detail.csv\',index=False,encoding=\'utf-8-sig\')\\\\npt.to_csv(\'/tmp/erp-analysis/output/fulfillment_product_gap.csv\',index=False,encoding=\'utf-8-sig\')\\\\nprint(\'\\\\\\\\nsaved\')\\\", \\\"datasetIds\\\": [], \\\"saveResult\\\": false}\", \"callId\": \"call_615ed3aa7b794dada0ad6069\"}','2026-11-22 20:15:35.209298');
