INSERT INTO `ai_agent_trace` (`id`, `user_id`, `conversation_id`, `task_id`, `agent_type`, `event_type`, `content`, `create_time`) VALUES (4887,1900000000000000001,2124475847040573442,'f92d1352-99ff-4ba8-9100-2fdaa3f1ea3d','ANALYSIS','TOOL_CALL','{\"name\": \"executePython\", \"text\": \"{\\\"code\\\": \\\"import json, pandas as pd, numpy as np\\\\nbase=\'/tmp/erp-analysis/input/\'\\\\ndef load(p,cols):\\\\n    with open(p,encoding=\'utf-8\') as f:\\\\n        df=pd.DataFrame([json.loads(l) for l in f if l.strip()])\\\\n    df.columns=cols; return df\\\\nso=load(base+\'ds_a901e8bb0d7d4eb696e58d81421a7e06.jsonl\',[\'sales_order_id\',\'sales_no\',\'customer_name\',\'status\',\'expected_delivery_date\',\'product_id\',\'product_code\',\'product_name\',\'unit_name\',\'quantity\',\'outbound_qty\',\'pending_qty\',\'locked_qty\',\'create_time\'])\\\\nro=load(base+\'ds_e0ce38f9f450403394e6860c89c7e44e.jsonl\',[\'warehouse_id\',\'product_id\',\'product_code\',\'product_name\',\'unit_name\',\'stock_qty\',\'locked_qty\'])\\\\npo=load(base+\'ds_fd967aa0eea346bf8912f0779cfccbfe.jsonl\',[\'purchase_no\',\'supplier_name\',\'status\',\'expected_arrival_date\',\'product_id\',\'product_code\',\'product_name\',\'unit_name\',\'quantity\',\'inbound_qty\',\'pending_qty\'])\\\\nfor c in [\'quantity\',\'outbound_qty\',\'pending_qty\',\'locked_qty\']: so[c]=so[c].astype(int)\\\\nso[\'edd\']=pd.to_datetime(so[\'expected_delivery_date\'])\\\\nfor c in [\'stock_qty\',\'locked_qty\']: ro[c]=ro[c].astype(int)\\\\nfor c in [\'quantity\',\'inbound_qty\',\'pending_qty\']: po[c]=po[c].astype(int)\\\\npo[\'ead\']=pd.to_datetime(po[\'expected_arrival_date\'])\\\\nTODAY=pd.Timestamp(\'2026-11-22\')\\\\n\\\\nordlk=so.groupby(\'product_id\').locked_qty.sum()\\\\nallp=pd.DataFrame({\'product_id\':sorted(set(ro.product_id)|set(ordlk.index))})\\\\nallp[\'stock_locked\']=allp.product_id.map(ro.set_index(\'product_id\').locked_qty).fillna(0)\\\\nallp[\'order_locked\']=allp.product_id.map(ordlk).fillna(0)\\\\nallp[\'lock_gap\']=allp.stock_locked-allp.order_locked\\\\nnz=allp[allp.lock_gap!=0].copy()\\\\nnz[\'stock_locked\']=nz.stock_locked/100; nz[\'order_locked\']=nz.order_locked/100; nz[\'lock_gap\']=nz.lock_gap/100\\\\nprint(\'lock diff nonzero products:\', len(nz)); print(nz.to_string())\\\\nprint(\'totals stock_locked\',allp.stock_locked.sum()/100,\'order_locked\',allp.order_locked.sum()/100)\\\\n\\\\nu=so.groupby(\'sales_no\').unit_name.nunique()\\\\nprint(\'\\\\\\\\norders with mixed units:\', int((u>1).sum()), \'multi-line orders:\', int((so.groupby(\'sales_no\').size()>1).sum()))\\\\nprint(\'mixed-unit orders:\', list(u[u>1].index))\\\\nod=po[po.ead<TODAY]\\\\nprint(\'\\\\\\\\noverdue PO arrivals:\'); print(od[[\'purchase_no\',\'supplier_name\',\'status\',\'expected_arrival_date\',\'product_code\',\'unit_name\',\'pending_qty\']].assign(pending_qty=lambda d:d.pending_qty/100).to_string())\\\\npend=so.groupby(\'product_id\').pending_qty.sum()\\\\npnd=po[~po.product_id.isin(pend.index)]\\\\nprint(\'\\\\\\\\ntransit for products w/o pending demand:\', pnd.product_id.nunique(), \'qty\', pnd.pending_qty.sum()/100)\\\\nprint(\'negative stock rows:\', int((ro.stock_qty<0).sum()), \'| stock<locked rows:\', int((ro.stock_qty<ro.locked_qty).sum()))\\\\nprint(\'outbound>quantity rows:\', int((so.outbound_qty>so.quantity).sum()), \'| inbound>quantity rows:\', int((po.inbound_qty>po.quantity).sum()))\\\\nprint(\'PO status detail:\'); print(po.groupby(\'status\').agg(n=(\'purchase_no\',\'nunique\'), qty=(\'pending_qty\',\'sum\')).assign(qty=lambda d:d.qty/100).to_string())\\\\nprint(\'\\\\\\\\nper-order line/product mix: max lines per order\', int(so.groupby(\'sales_no\').size().max()))\\\", \\\"datasetIds\\\": [], \\\"saveResult\\\": false}\", \"callId\": \"call_a64f7be28913477fb3de60c7\"}','2026-11-22 20:15:58.752970');
