INSERT INTO `ai_agent_trace` (`id`, `user_id`, `conversation_id`, `task_id`, `agent_type`, `event_type`, `content`, `create_time`) VALUES (4890,1900000000000000001,2124475847040573442,'f92d1352-99ff-4ba8-9100-2fdaa3f1ea3d','ANALYSIS','TOOL_CALL','{\"name\": \"executePython\", \"text\": \"{\\\"code\\\": \\\"import json, pandas as pd, numpy as np\\\\nbase=\'/tmp/erp-analysis/input/\'\\\\ndef load(p,cols):\\\\n    with open(p,encoding=\'utf-8\') as f:\\\\n        df=pd.DataFrame([json.loads(l) for l in f if l.strip()])\\\\n    df.columns=cols; return df\\\\nso=load(base+\'ds_a901e8bb0d7d4eb696e58d81421a7e06.jsonl\',[\'sales_order_id\',\'sales_no\',\'customer_name\',\'status\',\'expected_delivery_date\',\'product_id\',\'product_code\',\'product_name\',\'unit_name\',\'quantity\',\'outbound_qty\',\'pending_qty\',\'locked_qty\',\'create_time\'])\\\\nro=load(base+\'ds_e0ce38f9f450403394e6860c89c7e44e.jsonl\',[\'warehouse_id\',\'product_id\',\'product_code\',\'product_name\',\'unit_name\',\'stock_qty\',\'locked_qty\'])\\\\npo=load(base+\'ds_fd967aa0eea346bf8912f0779cfccbfe.jsonl\',[\'purchase_no\',\'supplier_name\',\'status\',\'expected_arrival_date\',\'product_id\',\'product_code\',\'product_name\',\'unit_name\',\'quantity\',\'inbound_qty\',\'pending_qty\'])\\\\npr=load(base+\'ds_cb78e8a523e04a4a8be9ca6aad3f2c0b.jsonl\',[\'product_id\',\'product_code\',\'product_name\',\'unit_name\',\'quantity_precision\',\'safety_stock_qty\',\'status\'])\\\\nfor c in [\'quantity\',\'outbound_qty\',\'pending_qty\',\'locked_qty\']: so[c]=so[c].astype(int)\\\\nso[\'edd\']=pd.to_datetime(so[\'expected_delivery_date\'])\\\\nfor c in [\'stock_qty\',\'locked_qty\']: ro[c]=ro[c].astype(int)\\\\nfor c in [\'quantity\',\'inbound_qty\',\'pending_qty\']: po[c]=po[c].astype(int)\\\\npo[\'ead\']=pd.to_datetime(po[\'expected_arrival_date\'])\\\\npr[\'safety_stock_qty\']=pr[\'safety_stock_qty\'].astype(int)\\\\nTODAY=pd.Timestamp(\'2026-11-22\')\\\\nstock=ro.set_index(\'product_id\')[\'stock_qty\']; safety=pr.set_index(\'product_id\')[\'safety_stock_qty\']\\\\npin=so[so.pending_qty>0]\\\\nprint(\'lines pending>0\',len(pin),\'orders\',pin.sales_no.nunique(),\'products\',pin.product_id.nunique(),\'total\',pin.pending_qty.sum()/100)\\\\n\\\\n# future orders product level\\\\nfut=pin[pin.edd>=TODAY].sort_values([\'edd\',\'sales_no\'])\\\\nfutx=fut.merge(po.groupby(\'product_id\').agg(po_qty=(\'pending_qty\',\'sum\'),po_ead=(\'ead\',\'min\')).reset_index(),on=\'product_id\',how=\'left\')\\\\nfutx[\'stock\']=futx.product_id.map(stock).fillna(0).astype(int)\\\\nfutx[\'safety\']=futx.product_id.map(safety)\\\\nfutx[\'po_qty\']=futx.po_qty.fillna(0).astype(int)\\\\nfutx[\'after\']=futx.stock-futx.pending_qty\\\\nfutx[\'days_left\']=(futx.edd-TODAY).dt.days\\\\nprint(\'\\\\\\\\nfuture order lines:\')\\\\nprint(futx[[\'sales_no\',\'customer_name\',\'status\',\'expected_delivery_date\',\'days_left\',\'product_code\',\'product_name\',\'unit_name\',\'pending_qty\',\'stock\',\'after\',\'safety\',\'po_qty\',\'po_ead\']].to_string())\\\\n\\\\n# products below safety after shipping (pending>0 only)\\\\npt=pin.groupby([\'product_id\',\'product_code\',\'product_name\',\'unit_name\']).agg(pending=(\'pending_qty\',\'sum\'),orders=(\'sales_no\',\'nunique\'),first_edd=(\'edd\',\'min\')).reset_index()\\\\npt[\'stock\']=pt.product_id.map(stock).fillna(0).astype(int); pt[\'safety\']=pt.product_id.map(safety)\\\\npt[\'po_qty\']=pt.product_id.map(po.groupby(\'product_id\').pending_qty.sum()).fillna(0).astype(int)\\\\npt[\'after\']=pt.stock-pt.pending\\\\npt[\'below_safety\']=pt.after<pt.safety.fillna(0)\\\\npt[\'gap_stock\']=(pt.pending-pt.stock).clip(lower=0)\\\\npt[\'gap_after_transit\']=(pt.pending-pt.stock-pt.po_qty).clip(lower=0)\\\\nprint(\'\\\\\\\\nproducts pending>0:\',len(pt),\'gap_stock>0:\',int((pt.gap_stock>0).sum()),\'below safety after:\',int(pt.below_safety.sum()))\\\\nprint(\'products exactly covered (stock==pending):\', int((pt.after==0).sum()))\\\\nprint(pt[pt.below_safety].sort_values(\'first_edd\')[[\'product_code\',\'product_name\',\'unit_name\',\'pending\',\'stock\',\'after\',\'safety\',\'po_qty\',\'first_edd\']].to_string())\\\\nprint(\'\\\\\\\\nshortfall vs safety total (mixed units):\', (pt[pt.below_safety].safety-pt[pt.below_safety].after).sum()/100)\\\\n\\\\n# overdue orders summary\\\\nov=so[so.edd<TODAY]\\\\nprint(\'\\\\\\\\noverdue orders\', ov.sales_no.nunique(), \'pending\', ov.pending_qty.sum()/100, \'lines\', len(ov))\\\\novx=ov.groupby([\'sales_no\',\'customer_name\',\'status\',\'expected_delivery_date\']).agg(lines=(\'product_id\',\'nunique\'),pending=(\'pending_qty\',\'sum\'),shipped=(\'outbound_qty\',\'sum\')).reset_index()\\\\novx[\'overdue_days\']=(TODAY-pd.to_datetime(ovx.expected_delivery_date)).dt.days\\\\novx[\'pending\']=ovx.pending/100; ovx[\'shipped\']=ovx.shipped/100\\\\novx=ovx.sort_values(\'expected_delivery_date\')\\\\nprint(ovx.head(8).to_string())\\\\novx.to_csv(\'/tmp/erp-analysis/output/overdue_orders.csv\',index=False,encoding=\'utf-8-sig\')\\\\nfutx.drop(columns=[\'create_time\']).to_csv(\'/tmp/erp-analysis/output/future_orders_supply.csv\',index=False,encoding=\'utf-8-sig\')\\\\npt.to_csv(\'/tmp/erp-analysis/output/product_gap_final.csv\',index=False,encoding=\'utf-8-sig\')\\\\nprint(\'saved final files\')\\\", \\\"datasetIds\\\": [], \\\"saveResult\\\": false}\", \"callId\": \"call_3d0873a5484e4781a56c15de\"}','2026-11-22 20:16:13.137230');
