INSERT INTO `ai_agent_trace` (`id`, `user_id`, `conversation_id`, `task_id`, `agent_type`, `event_type`, `content`, `create_time`) VALUES (5831,1900000000000000001,2124761984778977281,'sqlrun_c1e93d8cde0d4d53a65849960c955134','SQL_INSPECT','MODEL_OUTPUT','{\"message\": \"查询成功。返回了指定产品（P001253）在指定仓库（上海浦东中心仓）且状态为 SUBMITTED/APPROVED/PARTIAL_OUTBOUND 的销售订单明细共 1 条记录。数据包含销售单号、状态、数量、锁定量、出库量等关键字段，可用于核实库存锁定来源。注意：quantity/locked_qty/outbound_qty 均为放大100倍后的整数值。\", \"decision\": \"PASS\", \"dataDescription\": {\"grain\": \"每条销售订单明细一行\", \"fields\": [{\"index\": 0, \"meaning\": \"销售单号\"}, {\"index\": 1, \"meaning\": \"订单状态 (SUBMITTED:待审核, APPROVED:待出库, PARTIAL_OUTBOUND:部分出库)\"}, {\"index\": 2, \"meaning\": \"产品编码\"}, {\"index\": 3, \"meaning\": \"销售数量 (放大100倍整数存储，需除以100得到实际业务数量)\"}, {\"index\": 4, \"meaning\": \"已锁定库存数量 (放大100倍整数存储，需除以100得到实际业务数量)\"}, {\"index\": 5, \"meaning\": \"已出库数量 (放大100倍整数存储，需除以100得到实际业务数量)\"}, {\"index\": 6, \"meaning\": \"数量小数位精度快照 (0-2)\"}, {\"index\": 7, \"meaning\": \"单位名称快照\"}, {\"index\": 8, \"meaning\": \"预计发货日期\"}, {\"index\": 9, \"meaning\": \"提交时间\"}, {\"index\": 10, \"meaning\": \"审核时间\"}], \"content\": \"产品 P001253 在上海浦东中心仓的有效销售订单明细（状态：待审核、待出库、部分出库），用于分析库存锁定情况。\", \"limitations\": \"数量字段（quantity, locked_qty, outbound_qty）在数据库中按100倍整数存储，展示或计算时需除以100还原为业务单位数量。\"}}','2026-11-23 15:10:05.245807');
