INSERT INTO `ai_agent_trace` (`id`, `user_id`, `conversation_id`, `task_id`, `agent_type`, `event_type`, `content`, `create_time`) VALUES (5880,1900000000000000001,2124761984778977281,'4a455f1d-2da8-451f-b7dc-067ffcb3e4c6','ANALYSIS','TOOL_CALL','{\"name\": \"executePython\", \"text\": \"{\\\"code\\\": \\\"import json, math\\\\nfrom datetime import date, timedelta\\\\nimport pandas as pd\\\\n\\\\nbase=\'/tmp/erp-analysis/input/\'\\\\ndef load(ds, cols):\\\\n    rows=[]\\\\n    with open(base+ds+\'.jsonl\') as f:\\\\n        for line in f:\\\\n            line=line.strip()\\\\n            if line: rows.append(json.loads(line))\\\\n    return pd.DataFrame(rows, columns=cols) if rows else pd.DataFrame(columns=cols)\\\\n\\\\nstock=load(\'ds_87b7db8554a144b097b0957b92535283\',[\'warehouse_id\',\'warehouse_name\',\'product_id\',\'product_code\',\'product_name\',\'unit_name\',\'stock_qty\',\'locked_qty\'])\\\\nprod=load(\'ds_0ec4bee4d0f24143ac6f5d1eefd77d46\',[\'id\',\'product_code\',\'product_name\',\'unit_name\',\'quantity_precision\',\'safety_stock_qty\',\'reference_purchase_price\',\'status\'])\\\\nso=load(\'ds_a9ec41f66a7c42aeb1ee1fdd6bc8d524\',[\'sales_no\',\'status\',\'product_code\',\'quantity\',\'locked_qty\',\'outbound_qty\',\'quantity_precision\',\'unit_name\',\'expected_delivery_date\',\'submitted_at\',\'approved_at\'])\\\\nsp=load(\'ds_66d6d5334f0944f3bd3a66a08ac6f15f\',[\'supplier_id\',\'supplier_code\',\'supplier_name\',\'quoted_purchase_price\',\'latest_purchase_price\',\'quoted_price_reason\',\'quoted_price_updated_at\',\'quote_valid_until\',\'min_order_qty\',\'quality_score\',\'price_score\',\'recommend_score\',\'score_status\',\'avg_delivery_days\',\'last_purchase_at\',\'score_basis_amount\'])\\\\npo=load(\'ds_b14e25d19833420f94cf62e2db89b075\',[\'purchase_no\',\'status\',\'supplier_id\',\'supplier_name\',\'quantity\',\'inbound_qty\',\'unit_price\',\'expected_arrival_date\'])\\\\nib=load(\'ds_5840b79bb8dd421fa54d6adb4f02a7c9\',[\'inbound_no\',\'status\',\'source_no\',\'current_qty\',\'plan_qty\',\'unit_price\',\'create_time\'])\\\\n\\\\ns=stock.iloc[0]\\\\nprec=int(prod.iloc[0][\'quantity_precision\'])\\\\nsafety=float(prod.iloc[0][\'safety_stock_qty\'])/100\\\\nref_price=float(prod.iloc[0][\'reference_purchase_price\'])/100\\\\nstock_qty=float(s[\'stock_qty\']); locked=float(s[\'locked_qty\'])\\\\navail=round(stock_qty-locked,6)\\\\ngap=round(max(0.0,safety-avail),6)\\\\nprint(\'== 缺口(罐) ==\')\\\\nprint(\'精度\',prec,\'安全库存\',safety,\'参考采购价(元)\',ref_price)\\\\nprint(\'stock\',stock_qty,\'locked\',locked,\'available\',avail,\'gap\',gap)\\\\n\\\\nprint(\'\\\\\\\\n== 锁定来源核对 ==\')\\\\nlocked_sum=0.0; undelivered_sum=0.0\\\\nfor _,r in so.iterrows():\\\\n    q=float(r[\'quantity\'])/100; l=float(r[\'locked_qty\'])/100; o=float(r[\'outbound_qty\'])/100\\\\n    locked_sum+=l; undelivered_sum+=q-o\\\\n    print(r[\'sales_no\'],r[\'status\'],\'订单量\',q,\'锁定量\',l,\'已出库\',o,\'待出库\',q-o,\'锁定=待出库\',abs(l-(q-o))<1e-9,\\\\n          \'预计交货\',r[\'expected_delivery_date\'],\'审批\',r[\'approved_at\'])\\\\nprint(\'明细锁定合计\',round(locked_sum,2),\'仓库锁定\',locked,\'一致:\',abs(locked_sum-locked)<1e-9)\\\\nprint(\'待出库合计\',round(undelivered_sum,2))\\\\n\\\\nprint(\'\\\\\\\\n== 在途 ==\')\\\\nin_transit=0.0\\\\nif len(po):\\\\n    p=po.copy(); p[\'q\']=p[\'quantity\'].astype(float)/100; p[\'i\']=p[\'inbound_qty\'].astype(float)/100; p[\'un\']=p[\'q\']-p[\'i\']\\\\n    in_transit=p[\'un\'].sum(); print(p[[\'purchase_no\',\'status\',\'supplier_name\',\'q\',\'i\',\'un\',\'expected_arrival_date\']].to_string())\\\\nprint(\'在途采购未入库合计\',in_transit,\'未确认采购入库单行数\',len(ib))\\\\n\\\\ntoday=date(2026,11,23)\\\\nu=10.0**(-prec)\\\\nprint(\'\\\\\\\\n== 候选比较与取整(step=%s) ==\'%u)\\\\nout=[]\\\\nfor _,r in sp.iterrows():\\\\n    moq=float(r[\'min_order_qty\'])/100\\\\n    qp=float(r[\'quoted_purchase_price\'])/100 if pd.notna(r[\'quoted_purchase_price\']) else None\\\\n    lp=float(r[\'latest_purchase_price\'])/100 if pd.notna(r[\'latest_purchase_price\']) else None\\\\n    vu=pd.to_datetime(r[\'quote_valid_until\']).date() if pd.notna(r[\'quote_valid_until\']) else None\\\\n    valid = qp is not None and vu is not None and vu>=today\\\\n    price = qp if valid else lp\\\\n    qty = math.ceil(max(gap,moq)/u)*u\\\\n    value = round(qty*price,2) if price is not None else None\\\\n    days=float(r[\'avg_delivery_days\']) if pd.notna(r[\'avg_delivery_days\']) else None\\\\n    eta = today+timedelta(days=days) if days is not None else None\\\\n    out.append(dict(供应商=r[\'supplier_name\'],编码=r[\'supplier_code\'],MOQ=moq,报价=qp,最近成交价=lp,\\\\n        报价有效至=str(vu),报价有效=valid,计价单价=price,采购量=qty,超买量=qty-gap,货值=value,\\\\n        与参考价差=(round(price-ref_price,2) if price else None),avg交期=days,预计到货=str(eta) if eta else None,\\\\n        评分状态=r[\'score_status\'],质量分=r[\'quality_score\'] and r[\'quality_score\']/100,\\\\n        价格分=(r[\'price_score\']/100 if pd.notna(r[\'price_score\']) else None),\\\\n        推荐分=(r[\'recommend_score\']/100 if pd.notna(r[\'recommend_score\']) else None),\\\\n        最近采购=r[\'last_purchase_at\'],样本额元=float(r[\'score_basis_amount\'])/100))\\\\ncdf=pd.DataFrame(out)\\\\npd.set_option(\'display.width\',250)\\\\nprint(cdf.to_string())\\\\nprint(\'\\\\\\\\n校验: 采购量>=缺口\',all(cdf[\'采购量\']>=gap),\' 采购量>=MOQ\',all(cdf[\'采购量\']>=cdf[\'MOQ\']),\\\\n      \' 步长整数倍\',all(abs((cdf[\'采购量\']/u)%1)<1e-9))\\\\nprint(\'复算货值 = 采购量*单价:\',[round(a*b,2) for a,b in zip(cdf[\'采购量\'],cdf[\'计价单价\'])])\\\\nprint(\'货值合计\',round(cdf[\'货值\'].sum(),2),\'逐项相加\',round(sum(out[i][\'货值\'] for i in range(len(out))),2))\\\\nprint(\'采购后库存(无在途):\',list(cdf[\'采购量\']),\'+可用0 =>\',[round(avail+q,2) for q in cdf[\'采购量\']],\'相对安全库存\',safety)\\\\nprint(\'缺口口径复算: 安全库存-可用 =\',round(safety-avail,2))\\\", \\\"datasetIds\\\": [\\\"ds_87b7db8554a144b097b0957b92535283\\\", \\\"ds_0ec4bee4d0f24143ac6f5d1eefd77d46\\\", \\\"ds_a9ec41f66a7c42aeb1ee1fdd6bc8d524\\\", \\\"ds_66d6d5334f0944f3bd3a66a08ac6f15f\\\", \\\"ds_b14e25d19833420f94cf62e2db89b075\\\", \\\"ds_5840b79bb8dd421fa54d6adb4f02a7c9\\\"], \\\"saveResult\\\": true, \\\"outputTextName\\\": \\\"P001253缺口与采购测算\\\"}\", \"callId\": \"call_5a6c1de635b24ceea680e3ef\"}','2026-11-23 15:12:15.805401');
INSERT INTO `ai_agent_trace` (`id`, `user_id`, `conversation_id`, `task_id`, `agent_type`, `event_type`, `content`, `create_time`) VALUES (5881,1900000000000000001,2124761984778977281,'4a455f1d-2da8-451f-b7dc-067ffcb3e4c6','ANALYSIS','TOOL_RESULT','{\"name\": \"executePython\", \"text\": \"{\\\"status\\\":\\\"SUCCESS\\\",\\\"textOutput\\\":{\\\"content\\\":\\\"== 缺口(罐) ==\\\\n精度 0 安全库存 88.0 参考采购价(元) 20.78\\\\nstock 64.0 locked 64.0 available 0.0 gap 88.0\\\\n\\\\n== 锁定来源核对 ==\\\\nSO2026110200005 PARTIAL_OUTBOUND 订单量 270.0 锁定量 64.0 已出库 206.0 待出库 64.0 锁定=待出库 True 预计交货 2026-11-05 审批 2026-11-02T11:42:27\\\\n明细锁定合计 64.0 仓库锁定 64.0 一致: True\\\\n待出库合计 64.0\\\\n\\\\n== 在途 ==\\\\n在途采购未入库合计 0.0 未确认采购入库单行数 0\\\\n\\\\n== 候选比较与取整(step=1.0) ==\\\\n             供应商     编码  MOQ     报价  最近成交价       报价有效至   报价有效   计价单价   采购量  超买量       货值  与参考价差 avg交期  预计到货       评分状态    质量分   价格分   推荐分                 最近采购       样本额元\\\\n0  济南金桥食品供应链有限公司  S0099  5.0  21.07  21.07  2026-10-14  False  21.07  88.0  0.0  1854.16   0.29  None  None  NOT_READY  98.91  None  None  2026-07-27T08:51:06  140870.87\\\\n\\\\n校验: 采购量>=缺口 True  采购量>=MOQ True  步长整数倍 True\\\\n复算货值 = 采购量*单价: [1854.16]\\\\n货值合计 1854.16 逐项相加 1854.16\\\\n采购后库存(无在途): [88.0] +可用0 => [88.0] 相对安全库存 88.0\\\\n缺口口径复算: 安全库存-可用 = 88.0\\\\n\\\",\\\"bytes\\\":1287,\\\"truncated\\\":false,\\\"saved\\\":true,\\\"resultId\\\":\\\"3629e729-7db1-4f8d-a662-b2aea1ef7c53\\\",\\\"name\\\":\\\"P001253缺口与采购测算\\\"},\\\"files\\\":[],\\\"message\\\":\\\"本次执行完成。\\\"}\", \"callId\": \"call_5a6c1de635b24ceea680e3ef\"}','2026-11-23 15:12:16.691142');
INSERT INTO `ai_agent_trace` (`id`, `user_id`, `conversation_id`, `task_id`, `agent_type`, `event_type`, `content`, `create_time`) VALUES (5882,1900000000000000001,2124761984778977281,'4a455f1d-2da8-451f-b7dc-067ffcb3e4c6','ANALYSIS','FINAL','{\"text\": \"{\\\"completion\\\":\\\"COMPLETED\\\",\\\"summary\\\":\\\"## 主要结论\\\\n\\\\n**1) 当前缺口 88.00 罐，上海浦东中心仓已断货。**\\\\n- 账面 64.00 罐、锁定 64.00 罐，可用库存 0.00 罐；安全库存 88.00 罐，缺口 = 88.00 − 0.00 = **88.00 罐**（单位「罐」，quantity_precision=0）。\\\\n- 经核对，锁定量对应真实的待出库需求，不是重复扣减：销售订单 SO2026110200005（PARTIAL_OUTBOUND）订单量 270.00 罐、已出库 206.00 罐、锁定 64.00 罐，锁定量等于待出库量 64.00 罐，与仓库 locked_qty 64.00 完全一致。该单预计交货日 2026-11-05，已逾期 18 天，因此 **64 罐待发订单无货可发，处于无法履行状态**；可用库存为 0 也意味着新订单无法占用库存。\\\\n\\\\n**2) 在途与已确认供应均为 0，本次采购不会重复。**\\\\n- 在途采购（状态 SUBMITTED/APPROVED/PARTIAL_INBOUND，未入库量 = quantity − inbound_qty）：**0 行**。\\\\n- 未确认的采购入库单（PURCHASE_IN，状态 DRAFT/PENDING_CONFIRM）：**0 行**。\\\\n- 在途合计 0.00 罐，没有预计到货日期可供参考。\\\\n\\\\n**3) 候选供应商仅 1 家，无替补。**\\\\n产品 P001253 未删除的供货关系只有 S0099 济南金桥食品供应链有限公司（供货关系 status=1、供应商 status=1），不存在被禁用的备选供应商，属于单一供应来源。\\\\n\\\\n| 候选 | 编码 | 人工有效报价 | 最近成交价 | 报价有效期 | MOQ | 质量分 | 价格分 | 推荐分 | 评分状态 | 最近采购 | 样本额(元) |\\\\n|---|---|---|---|---|---|---|---|---|---|---|---|\\\\n| 济南金桥食品供应链有限公司 | S0099 | 21.07 元 | 21.07 元 | 2026-10-14（**已过期**） | 5.00 罐 | 98.91 | NULL | NULL | NOT_READY | 2026-07-27 | 140,870.87 |\\\\n\\\\n- 该报价已过期 40 天，因此只能作为参考，不能直接用于下单决策；由于最近成交价同为 21.07 元，**改用 21.07 元/罐计价**，下单前需要供应商重新报价确认。\\\\n- 评分状态为 NOT_READY（样本不足），价格分和推荐分为 NULL，**不重新计算**；只有质量分 98.91 可以引用。平均交期 avg_delivery_days 为 NULL。\\\\n\\\\n**4) 采购量与货值（步长 u=1 罐，因 quantity_precision=0）**\\\\n\\\\n| 候选 | 可采购量 | 调整后采购量 | 超买量 | 计价单价 | 货值 | 与参考价 20.78 元差异 |\\\\n|---|---|---|---|---|---|---|\\\\n| 济南金桥 | 88.00 罐 | **88 罐** | **0 罐** | 21.07 元 | **1,854.16 元** | 高 0.29 元/罐，整单高 25.52 元 |\\\\n\\\\n- 取整过程：ceil(max(88.00, MOQ 5.00)/1)×1 = 88 罐；满足采购量不小于缺口、不小于 MOQ、为步长整数倍这三项校验。\\\\n- 到货后可用库存为 88 罐，正好等于安全库存线，扣掉待发 64 罐后剩余 24 罐。\\\\n\\\\n**5) 到货可行性无法推算到货日，缺少历史交期依据。**\\\\n- 唯一候选的 avg_delivery_days 为 NULL（没有最近 180 天完全入库样本可用于加权交期），因此**不能按历史平均估算预计到货日**，只能标注为情景，并依赖供应商承诺交期。\\\\n- 结论：88 罐的数量可以补齐目标线，但**到货时间尚不能确认早于需求时点**（待发 64 罐已逾期、可用库存为 0），这属于「数量解决、时效未解决」，需要拿到供应商书面承诺到货日后再判断能否接上。\\\\n\\\\n**推荐**\\\\n- 主候选为 S0099 济南金桥食品供应链有限公司；替补无（唯一供货关系，建议同步拓展第二供应源）。\\\\n- 建议下单 88 罐，预估货值 1,854.16 元（按最近成交价 21.07 元/罐），没有超买。\\\\n- 提交审核前需要落实：①重新报价并确认有效期、币种、含税口径；②供应商承诺到货日（尤其优先补 64 罐逾期待发）。\\\\n\\\\n## 过程与依据\\\\n1. 读取库存余额（ds_87b7db8554a144b097b0957b92535283）和产品主档（ds_0ec4bee4d0f24143ac6f5d1eefd77d46），确认该产品仅在上海浦东中心仓有记录（账面 64.00、锁定 64.00，数值已是业务口径），安全库存 88.00 罐、参考采购价 20.78 元、精度 0。\\\\n2. 为核实锁定来源，补查该产品在该仓的有效销售订单明细（ds_a9ec41f66a7c42aeb1ee1fdd6bc8d524），取得 SO2026110200005 的订单/已出库/锁定为 270/206/64，锁定合计与 warehouse_stock.locked_qty 一致。\\\\n3. 为排除已有供应，分别查询在途采购订单明细（ds_b14e25d19833420f94cf62e2db89b075，0 行）和未确认采购入库单明细（ds_5840b79bb8dd421fa54d6adb4f02a7c9，0 行）；这两类实体无法合并查询，因此按要求分两次取数。\\\\n4. 取启用供货关系（ds_66d6d5334f0944f3bd3a66a08ac6f15f，1 行）用于候选对比；再查该产品全部未删除供货关系，确认没有禁用备选（ds_b4145943a6ae4aa2bb7bd3d7bcd98c46，同为 1 行）。\\\\n5. 用 Python 统一还原单位（数量除以100、金额除以100），按 purchase 技能公式计算缺口、取整采购量、超买量、货值和报价有效性，明细输出保存为结果文本 3629e729-7db1-4f8d-a662-b2aea1ef7c53。\\\\n\\\\n## 核对与局限\\\\n- 核对：锁定 64.00 = 明细锁定合计 64.00 = 待出库（270−206）；缺口用两种方式复算一致（88.00−0.00 与安全库存减可用）；采购量满足三项验证门；货值按调整后数量 88×21.07 复算等于 1,854.16 元，逐项相加一致。\\\\n- 局限：①唯一候选报价已过期（至 2026-10-14），货值基于最近成交价替代，正式下单前价格可能变动；②avg_delivery_days、price_score、recommend_score 为空，评分状态为 NOT_READY，无法做交期估计和系统评分横向比较；③全部数量只涉及「罐」一个单位，没有跨单位汇总；其他四仓该产品未铺货，未纳入合计。\\\"}\"}','2026-11-23 15:12:37.247164');
INSERT INTO `ai_agent_trace` (`id`, `user_id`, `conversation_id`, `task_id`, `agent_type`, `event_type`, `content`, `create_time`) VALUES (5883,1900000000000000001,2124761984778977281,'026275db-dfa3-4539-abec-3b9cba45fa14','MAIN','TOOL_RESULT','{\"name\": \"analyzeData\", \"text\": \"{\\\"completion\\\":\\\"COMPLETED\\\",\\\"analysisTaskId\\\":\\\"4a455f1d-2da8-451f-b7dc-067ffcb3e4c6\\\",\\\"summary\\\":\\\"## 主要结论\\\\n\\\\n**1) 当前缺口 88.00 罐，上海浦东中心仓已断货。**\\\\n- 账面 64.00 罐、锁定 64.00 罐，可用库存 0.00 罐；安全库存 88.00 罐，缺口 = 88.00 − 0.00 = **88.00 罐**（单位「罐」，quantity_precision=0）。\\\\n- 经核对，锁定量对应真实的待出库需求，不是重复扣减：销售订单 SO2026110200005（PARTIAL_OUTBOUND）订单量 270.00 罐、已出库 206.00 罐、锁定 64.00 罐，锁定量等于待出库量 64.00 罐，与仓库 locked_qty 64.00 完全一致。该单预计交货日 2026-11-05，已逾期 18 天，因此 **64 罐待发订单无货可发，处于无法履行状态**；可用库存为 0 也意味着新订单无法占用库存。\\\\n\\\\n**2) 在途与已确认供应均为 0，本次采购不会重复。**\\\\n- 在途采购（状态 SUBMITTED/APPROVED/PARTIAL_INBOUND，未入库量 = quantity − inbound_qty）：**0 行**。\\\\n- 未确认的采购入库单（PURCHASE_IN，状态 DRAFT/PENDING_CONFIRM）：**0 行**。\\\\n- 在途合计 0.00 罐，没有预计到货日期可供参考。\\\\n\\\\n**3) 候选供应商仅 1 家，无替补。**\\\\n产品 P001253 未删除的供货关系只有 S0099 济南金桥食品供应链有限公司（供货关系 status=1、供应商 status=1），不存在被禁用的备选供应商，属于单一供应来源。\\\\n\\\\n| 候选 | 编码 | 人工有效报价 | 最近成交价 | 报价有效期 | MOQ | 质量分 | 价格分 | 推荐分 | 评分状态 | 最近采购 | 样本额(元) |\\\\n|---|---|---|---|---|---|---|---|---|---|---|---|\\\\n| 济南金桥食品供应链有限公司 | S0099 | 21.07 元 | 21.07 元 | 2026-10-14（**已过期**） | 5.00 罐 | 98.91 | NULL | NULL | NOT_READY | 2026-07-27 | 140,870.87 |\\\\n\\\\n- 该报价已过期 40 天，因此只能作为参考，不能直接用于下单决策；由于最近成交价同为 21.07 元，**改用 21.07 元/罐计价**，下单前需要供应商重新报价确认。\\\\n- 评分状态为 NOT_READY（样本不足），价格分和推荐分为 NULL，**不重新计算**；只有质量分 98.91 可以引用。平均交期 avg_delivery_days 为 NULL。\\\\n\\\\n**4) 采购量与货值（步长 u=1 罐，因 quantity_precision=0）**\\\\n\\\\n| 候选 | 可采购量 | 调整后采购量 | 超买量 | 计价单价 | 货值 | 与参考价 20.78 元差异 |\\\\n|---|---|---|---|---|---|---|\\\\n| 济南金桥 | 88.00 罐 | **88 罐** | **0 罐** | 21.07 元 | **1,854.16 元** | 高 0.29 元/罐，整单高 25.52 元 |\\\\n\\\\n- 取整过程：ceil(max(88.00, MOQ 5.00)/1)×1 = 88 罐；满足采购量不小于缺口、不小于 MOQ、为步长整数倍这三项校验。\\\\n- 到货后可用库存为 88 罐，正好等于安全库存线，扣掉待发 64 罐后剩余 24 罐。\\\\n\\\\n**5) 到货可行性无法推算到货日，缺少历史交期依据。**\\\\n- 唯一候选的 avg_delivery_days 为 NULL（没有最近 180 天完全入库样本可用于加权交期），因此**不能按历史平均估算预计到货日**，只能标注为情景，并依赖供应商承诺交期。\\\\n- 结论：88 罐的数量可以补齐目标线，但**到货时间尚不能确认早于需求时点**（待发 64 罐已逾期、可用库存为 0），这属于「数量解决、时效未解决」，需要拿到供应商书面承诺到货日后再判断能否接上。\\\\n\\\\n**推荐**\\\\n- 主候选为 S0099 济南金桥食品供应链有限公司；替补无（唯一供货关系，建议同步拓展第二供应源）。\\\\n- 建议下单 88 罐，预估货值 1,854.16 元（按最近成交价 21.07 元/罐），没有超买。\\\\n- 提交审核前需要落实：①重新报价并确认有效期、币种、含税口径；②供应商承诺到货日（尤其优先补 64 罐逾期待发）。\\\\n\\\\n## 过程与依据\\\\n1. 读取库存余额（ds_87b7db8554a144b097b0957b92535283）和产品主档（ds_0ec4bee4d0f24143ac6f5d1eefd77d46），确认该产品仅在上海浦东中心仓有记录（账面 64.00、锁定 64.00，数值已是业务口径），安全库存 88.00 罐、参考采购价 20.78 元、精度 0。\\\\n2. 为核实锁定来源，补查该产品在该仓的有效销售订单明细（ds_a9ec41f66a7c42aeb1ee1fdd6bc8d524），取得 SO2026110200005 的订单/已出库/锁定为 270/206/64，锁定合计与 warehouse_stock.locked_qty 一致。\\\\n3. 为排除已有供应，分别查询在途采购订单明细（ds_b14e25d19833420f94cf62e2db89b075，0 行）和未确认采购入库单明细（ds_5840b79bb8dd421fa54d6adb4f02a7c9，0 行）；这两类实体无法合并查询，因此按要求分两次取数。\\\\n4. 取启用供货关系（ds_66d6d5334f0944f3bd3a66a08ac6f15f，1 行）用于候选对比；再查该产品全部未删除供货关系，确认没有禁用备选（ds_b4145943a6ae4aa2bb7bd3d7bcd98c46，同为 1 行）。\\\\n5. 用 Python 统一还原单位（数量除以100、金额除以100），按 purchase 技能公式计算缺口、取整采购量、超买量、货值和报价有效性，明细输出保存为结果文本 3629e729-7db1-4f8d-a662-b2aea1ef7c53。\\\\n\\\\n## 核对与局限\\\\n- 核对：锁定 64.00 = 明细锁定合计 64.00 = 待出库（270−206）；缺口用两种方式复算一致（88.00−0.00 与安全库存减可用）；采购量满足三项验证门；货值按调整后数量 88×21.07 复算等于 1,854.16 元，逐项相加一致。\\\\n- 局限：①唯一候选报价已过期（至 2026-10-14），货值基于最近成交价替代，正式下单前价格可能变动；②avg_delivery_days、price_score、recommend_score 为空，评分状态为 NOT_READY，无法做交期估计和系统评分横向比较；③全部数量只涉及「罐」一个单位，没有跨单位汇总；其他四仓该产品未铺货，未纳入合计。\\\",\\\"datasets\\\":[{\\\"datasetId\\\":\\\"ds_a9ec41f66a7c42aeb1ee1fdd6bc8d524\\\",\\\"description\\\":\\\"查询产品 product_id=8400000000005001253（编码P001253）、出库仓库 warehouse_id=8400000000004000001（上海浦东中心仓）的销售订单明细，仅取销售订单主表 status 为 SUBMITTED、APPROVED、PARTIAL_OUTBOUND 且 deleted=0 的记录，返回销售单号、订单状态、明细 quantity（100倍整数）、locked_qty（100倍整数）、outbound_qty（100倍整数）、quantity_precision、单位、预计发货日期、提交/审核时间，用于核实锁定库存 64.00 罐是否对应真实待出库需求\\\",\\\"rowCount\\\":1,\\\"completed\\\":true,\\\"completenessMessage\\\":\\\"数据集已完整读取。\\\"},{\\\"datasetId\\\":\\\"ds_b14e25d19833420f94cf62e2db89b075\\\",\\\"description\\\":\\\"查询产品 product_id=8400000000005001253、目标仓库 warehouse_id=8400000000004000001（上海浦东中心仓）的在途采购订单明细：采购订单主表 status 为 SUBMITTED、APPROVED、PARTIAL_INBOUND 且 deleted=0，返回采购单号、订单状态、供应商名称、quantity（100倍整数）、inbound_qty（100倍整数）、unit_price（分）、expected_arrival_date\\\",\\\"rowCount\\\":0,\\\"completed\\\":true,\\\"completenessMessage\\\":\\\"数据集已完整读取。\\\"},{\\\"datasetId\\\":\\\"ds_5840b79bb8dd421fa54d6adb4f02a7c9\\\",\\\"description\\\":\\\"查询目标仓库 warehouse_id=8400000000004000001（上海浦东中心仓）、产品 product_id=8400000000005001253 的未确认采购入库单明细：入库单主表 inbound_type=PURCHASE_IN、status 为 DRAFT 或 PENDING_CONFIRM、deleted=0，返回入库单号、单据状态、来源单据号、本次入库数量 current_qty（100倍整数）、计划数量 plan_qty（100倍整数）、创建时间，用于避免与本次采购重复\\\",\\\"rowCount\\\":0,\\\"completed\\\":true,\\\"completenessMessage\\\":\\\"数据集已完整读取。\\\"},{\\\"datasetId\\\":\\\"ds_66d6d5334f0944f3bd3a66a08ac6f15f\\\",\\\"description\\\":\\\"查询产品 product_id=8400000000005001253 的启用供货关系：supplier_product.status=1 且 deleted=0，关联 supplier.status=1 且 deleted=0，返回供应商ID、供应商编码、供应商名称、quoted_purchase_price（人工有效报价，分）、latest_purchase_price（最近成交价，分）、quoted_price_reason、quote_valid_until（报价有效截止日）、min_order_qty（100倍整数）、quality_score（INT×100）、price_score（INT×100）、recommend_score（INT×100）、score_status、avg_delivery_days、last_purchase_at、score_basis_amount，用于供应商比较和采购量取整\\\",\\\"rowCount\\\":1,\\\"completed\\\":true,\\\"completenessMessage\\\":\\\"数据集已完整读取。\\\"},{\\\"datasetId\\\":\\\"ds_b4145943a6ae4aa2bb7bd3d7bcd98c46\\\",\\\"description\\\":\\\"查询产品 product_id=8400000000005001253 的所有供应商供货关系（不做 status 过滤，deleted=0），返回供应商编码、供应商名称、供货关系状态、供应商主档状态、报价与MOQ，用于确认除已启用候选外是否存在被禁用或停用的备选供应商\\\",\\\"rowCount\\\":1,\\\"completed\\\":true,\\\"completenessMessage\\\":\\\"数据集已完整读取。\\\"},{\\\"datasetId\\\":\\\"ds_87b7db8554a144b097b0957b92535283\\\",\\\"description\\\":\\\"查询产品ID 8400000000005001253（编码P001253）在所有仓库的库存余额记录，包括仓库ID、仓库名称、库存数量、锁定数量\\\",\\\"rowCount\\\":1,\\\"completed\\\":true,\\\"completenessMessage\\\":\\\"数据集已完整读取。\\\"},{\\\"datasetId\\\":\\\"ds_0ec4bee4d0f24143ac6f5d1eefd77d46\\\",\\\"description\\\":\\\"查询产品编码 P001253 的产品主档信息，包括产品ID、名称、单位、数量小数位、安全库存、参考采购价和状态\\\",\\\"rowCount\\\":1,\\\"completed\\\":true,\\\"completenessMessage\\\":\\\"数据集已完整读取。\\\"}],\\\"providedDatasets\\\":[{\\\"datasetId\\\":\\\"ds_87b7db8554a144b097b0957b92535283\\\",\\\"description\\\":\\\"查询产品ID 8400000000005001253（编码P001253）在所有仓库的库存余额记录，包括仓库ID、仓库名称、库存数量、锁定数量\\\",\\\"rowCount\\\":1,\\\"completed\\\":true,\\\"completenessMessage\\\":\\\"数据集已完整读取。\\\"},{\\\"datasetId\\\":\\\"ds_0ec4bee4d0f24143ac6f5d1eefd77d46\\\",\\\"description\\\":\\\"查询产品编码 P001253 的产品主档信息，包括产品ID、名称、单位、数量小数位、安全库存、参考采购价和状态\\\",\\\"rowCount\\\":1,\\\"completed\\\":true,\\\"completenessMessage\\\":\\\"数据集已完整读取。\\\"},{\\\"datasetId\\\":\\\"ds_f79d3bd7f0f14e95a0e85c6bc28ad6c8\\\",\\\"description\\\":\\\"查询仓库主档中所有仓库的ID、仓库编码、仓库名称和状态，用于确认“上海浦东中心仓”在系统中的准确ID与编码\\\",\\\"rowCount\\\":5,\\\"completed\\\":true,\\\"completenessMessage\\\":\\\"数据集已完整读取。\\\"}],\\\"analysisResults\\\":[{\\\"resultId\\\":\\\"3629e729-7db1-4f8d-a662-b2aea1ef7c53\\\",\\\"name\\\":\\\"P001253缺口与采购测算\\\",\\\"resultType\\\":\\\"TEXT\\\",\\\"fileType\\\":\\\"txt\\\",\\\"size\\\":1287}],\\\"errorCode\\\":null}\", \"callId\": \"call_2dca45c9986e4e099b6ae30e\"}','2026-11-23 15:12:48.233182');
INSERT INTO `ai_agent_trace` (`id`, `user_id`, `conversation_id`, `task_id`, `agent_type`, `event_type`, `content`, `create_time`) VALUES (5884,1900000000000000001,2124761984778977281,'026275db-dfa3-4539-abec-3b9cba45fa14','MAIN','MODEL_OUTPUT','{\"text\": \"核算已完成。现在按采购执行与采购单操作规则生成草稿。\"}','2026-11-23 15:12:51.144575');
INSERT INTO `ai_agent_trace` (`id`, `user_id`, `conversation_id`, `task_id`, `agent_type`, `event_type`, `content`, `create_time`) VALUES (5885,1900000000000000001,2124761984778977281,'026275db-dfa3-4539-abec-3b9cba45fa14','MAIN','TOOL_CALL','{\"name\": \"read_skill\", \"text\": \"{\\\"skill_name\\\": \\\"purchase-order\\\"}\", \"callId\": \"call_aa17594c856342679868588f\"}','2026-11-23 15:12:51.149348');
INSERT INTO `ai_agent_trace` (`id`, `user_id`, `conversation_id`, `task_id`, `agent_type`, `event_type`, `content`, `create_time`) VALUES (5886,1900000000000000001,2124761984778977281,'026275db-dfa3-4539-abec-3b9cba45fa14','MAIN','TOOL_RESULT','{\"name\": \"read_skill\", \"text\": \"\\\"# 采购单操作\\\\n\\\\n## 动作一览\\\\n\\\\n| 用户意图 | 调用工具 | 前置条件 |\\\\n|---|---|---|\\\\n| 生成新采购单 | `prepare_purchase_order_draft` | 缺口和采购量已确定 |\\\\n| 修改已有采购单 | `update_purchase_order_draft` | 采购单已经存在，且状态为草稿或待审核 |\\\\n| 提交审核 | `submit_purchase_order` | 用户同意提交，且单据是草稿 |\\\\n| 取消 | `cancel_purchase_order` | 用户同意取消，且没有入库事实 |\\\\n\\\\n## 动作之间的关系\\\\n\\\\n- **创建 → 编辑**：只有创建成功、拿到采购单号之后才可能进入编辑。用户在创建前说要改什么，那是创建参数，走创建，不要调编辑。\\\\n- **创建/编辑 → 提交**：动作完成后主动问一句是否提交，用户同意才调提交。\\\\n- **取消**：可以主动建议（例如供应商交期赶不上、缺口已被其他来源覆盖），但必须先说明理由并询问用户，同意后才调。不要直接调，也不要反复劝。\\\\n- 状态不允许时不要硬调：待入库及之后不能编辑；已入库不能取消；已取消不用再取消。\\\\n\\\\n## 创建\\\\n\\\\n调用 `prepare_purchase_order_draft`，一次一份。\\\\n\\\\n参数要求：\\\\n\\\\n- 供应商、仓库：真实存在且启用\\\\n- 明细产品：属于该供应商的启用供货关系\\\\n- 数量：按起订量和精度取整，不是缺口原值\\\\n- 单价：有效报价，没有就留空\\\\n- 预计到货：补货场景按首次缺口日推算建议日期；无法推算才留空\\\\n- 备注：可填，只在用户明确要求记录说明时填写\\\\n\\\\n回执处理：\\\\n\\\\n- **用户确认创建**：给出单号，说明是草稿；然后问是否需要提交审核。\\\\n- **用户修改参数后创建**：先读用户说明和修改字段，复述调整意图，说明好处（缺口、库存、预算、交期）和弊端（多占资金、新增风险），数据依据调用 `analyzeData`；只改备注时只做一句确认。最后问是否需要提交审核。\\\\n- **用户驳回**：回应驳回原因，等用户给出新方向，不要按原参数再生成一次。\\\\n- **创建未通过**：判断是参数问题还是业务规则问题。参数问题修正后重新生成并说明改了什么；业务规则问题把规则原文告诉用户，给替代方案。\\\\n\\\\n## 编辑\\\\n\\\\n调用 `update_purchase_order_draft`，传 `purchaseOrderId` 和要改的字段。\\\\n\\\\n- 单据必须已经存在；不存在时不要调，先走创建\\\\n- 明细要传完整的 items，不要只传改动的那一行\\\\n- 不需要自己查当前单据，确认卡片会以单据详情为底\\\\n- 待审核状态编辑时，预计到货必须非空\\\\n\\\\n回执处理：\\\\n\\\\n- **用户确认修改**：说明已保存和当前状态；原来是草稿时问是否提交。\\\\n- **用户修改参数后保存**：同创建的修改处理，说明好处和弊端。\\\\n- **用户驳回**：采购单保持原样，回应原因即可。\\\\n- **修改未保存**：状态不允许就把当前状态告诉用户；参数问题给修复建议。\\\\n\\\\n## 提交\\\\n\\\\n调用 `submit_purchase_order`，只传 `purchaseOrderId`。\\\\n\\\\n- 提交不产生新参数；预计到货为空时用户在卡片上补，不要编造\\\\n- 单据不是草稿时先说明状态，不要调用\\\\n\\\\n回执处理：\\\\n\\\\n- **用户同意提交**：说明当前是待审核，下一步等主管审核，不要说成已入库。\\\\n- **用户暂不提交**：按原因回应，不要反复询问。\\\\n- **提交未通过**：看错误原文。\\\\n  - 缺预计到货：提醒用户在卡片上补，或走编辑补日期\\\\n  - 供货关系失效、数量精度：给修复建议，用户确认后走编辑修改，保存后再问是否重新提交\\\\n  - 价格低于参考价下限、状态不允许：不能靠改参数绕过，给替代方案\\\\n\\\\n## 取消\\\\n\\\\n调用 `cancel_purchase_order`，传 `purchaseOrderId` 和从用户话里提取的 `reason`。\\\\n\\\\n- 确认前提醒：取消是终态，不可恢复；待入库的采购单取消会同时作废未确认的入库单\\\\n- 只有草稿、待审核和未入库的已审核单据能取消\\\\n\\\\n回执处理：\\\\n\\\\n- **用户同意取消**：说明已取消和原因\\\\n- **用户暂不取消**：尊重决定，不再劝\\\\n- **取消失败**：按错误原文说明（例如已有入库事实不能取消），给下一步建议\\\\n\\\\n## 失败后的循环\\\\n\\\\n提交或修改失败时：\\\\n\\\\n1. 说明失败原因，给一句可执行的修复建议\\\\n2. 等用户确认或给出新参数\\\\n3. 同意后调用编辑工具修改\\\\n4. 保存成功后，问是否重新提交\\\\n5. 不要自动重试同一份参数，也不要在用户没有反馈时连续调用\\\\n\\\\n## 交付要求\\\\n\\\\n- 草稿参数必须能被系统直接校验通过，不提交明显会被拒的内容\\\\n- 说清楚草稿和正式采购单的区别：草稿创建后仍需提交审核\\\\n- 影响结论必须来自实际数据，不能凭变化方向推测幅度\\\\n- 用户驳回后先回应原因，再给方案\\\\n\\\\n## 常见误判\\\\n\\\\n- 把缺口数量直接写进草稿，忽略起订量和精度\\\\n- 用供应商名称或产品名称代替编号\\\\n- 用户修改后只复述数字变化，不解释影响\\\\n- 系统拒绝后不改参数就重复提交\\\\n- 用户驳回后不看原因，按原方案再生成一次\\\\n- 创建成功后没说还需要提交审核\\\\n- 用户没同意就调用提交或取消\\\\n\\\\n## 相关技能\\\\n\\\\n- 缺口计算：`replenishment`\\\\n- 采购量、货值、到货可行性：`purchase`\\\\n- 候选供应商和评分：`supplier-selection`\\\"\", \"callId\": \"call_aa17594c856342679868588f\"}','2026-11-23 15:12:51.246619');
INSERT INTO `ai_agent_trace` (`id`, `user_id`, `conversation_id`, `task_id`, `agent_type`, `event_type`, `content`, `create_time`) VALUES (5887,1900000000000000001,2124761984778977281,'026275db-dfa3-4539-abec-3b9cba45fa14','MAIN','TOOL_CALL','{\"name\": \"readDataset\", \"text\": \"{\\\"datasetId\\\": \\\"ds_66d6d5334f0944f3bd3a66a08ac6f15f\\\"}\", \"callId\": \"call_63eb2f22041d4f659bd58906\"}','2026-11-23 15:12:55.136547');
INSERT INTO `ai_agent_trace` (`id`, `user_id`, `conversation_id`, `task_id`, `agent_type`, `event_type`, `content`, `create_time`) VALUES (5888,1900000000000000001,2124761984778977281,'026275db-dfa3-4539-abec-3b9cba45fa14','MAIN','TOOL_RESULT','{\"name\": \"readDataset\", \"text\": \"{\\\"columns\\\":[{\\\"name\\\":\\\"supplier_id\\\",\\\"label\\\":\\\"supplier_id\\\",\\\"jdbcType\\\":-5,\\\"typeName\\\":\\\"BIGINT\\\",\\\"nullable\\\":false},{\\\"name\\\":\\\"supplier_code\\\",\\\"label\\\":\\\"supplier_code\\\",\\\"jdbcType\\\":12,\\\"typeName\\\":\\\"VARCHAR\\\",\\\"nullable\\\":false},{\\\"name\\\":\\\"supplier_name\\\",\\\"label\\\":\\\"supplier_name\\\",\\\"jdbcType\\\":12,\\\"typeName\\\":\\\"VARCHAR\\\",\\\"nullable\\\":false},{\\\"name\\\":\\\"quoted_purchase_price\\\",\\\"label\\\":\\\"quoted_purchase_price\\\",\\\"jdbcType\\\":-5,\\\"typeName\\\":\\\"BIGINT\\\",\\\"nullable\\\":true},{\\\"name\\\":\\\"latest_purchase_price\\\",\\\"label\\\":\\\"latest_purchase_price\\\",\\\"jdbcType\\\":-5,\\\"typeName\\\":\\\"BIGINT\\\",\\\"nullable\\\":true},{\\\"name\\\":\\\"quoted_price_reason\\\",\\\"label\\\":\\\"quoted_price_reason\\\",\\\"jdbcType\\\":12,\\\"typeName\\\":\\\"VARCHAR\\\",\\\"nullable\\\":false},{\\\"name\\\":\\\"quoted_price_updated_at\\\",\\\"label\\\":\\\"quoted_price_updated_at\\\",\\\"jdbcType\\\":93,\\\"typeName\\\":\\\"DATETIME\\\",\\\"nullable\\\":true},{\\\"name\\\":\\\"quote_valid_until\\\",\\\"label\\\":\\\"quote_valid_until\\\",\\\"jdbcType\\\":91,\\\"typeName\\\":\\\"DATE\\\",\\\"nullable\\\":true},{\\\"name\\\":\\\"min_order_qty\\\",\\\"label\\\":\\\"min_order_qty\\\",\\\"jdbcType\\\":-5,\\\"typeName\\\":\\\"BIGINT\\\",\\\"nullable\\\":false},{\\\"name\\\":\\\"quality_score\\\",\\\"label\\\":\\\"quality_score\\\",\\\"jdbcType\\\":4,\\\"typeName\\\":\\\"INT\\\",\\\"nullable\\\":true},{\\\"name\\\":\\\"price_score\\\",\\\"label\\\":\\\"price_score\\\",\\\"jdbcType\\\":4,\\\"typeName\\\":\\\"INT\\\",\\\"nullable\\\":true},{\\\"name\\\":\\\"recommend_score\\\",\\\"label\\\":\\\"recommend_score\\\",\\\"jdbcType\\\":4,\\\"typeName\\\":\\\"INT\\\",\\\"nullable\\\":true},{\\\"name\\\":\\\"score_status\\\",\\\"label\\\":\\\"score_status\\\",\\\"jdbcType\\\":12,\\\"typeName\\\":\\\"VARCHAR\\\",\\\"nullable\\\":false},{\\\"name\\\":\\\"avg_delivery_days\\\",\\\"label\\\":\\\"avg_delivery_days\\\",\\\"jdbcType\\\":3,\\\"typeName\\\":\\\"DECIMAL\\\",\\\"nullable\\\":true},{\\\"name\\\":\\\"last_purchase_at\\\",\\\"label\\\":\\\"last_purchase_at\\\",\\\"jdbcType\\\":93,\\\"typeName\\\":\\\"DATETIME\\\",\\\"nullable\\\":true},{\\\"name\\\":\\\"score_basis_amount\\\",\\\"label\\\":\\\"score_basis_amount\\\",\\\"jdbcType\\\":-5,\\\"typeName\\\":\\\"BIGINT\\\",\\\"nullable\\\":true}],\\\"rows\\\":[[\\\"8400000000002000099\\\",\\\"S0099\\\",\\\"济南金桥食品供应链有限公司\\\",\\\"2107\\\",\\\"2107\\\",\\\"年度框架协议报价\\\",\\\"2026-10-01T10:00:00\\\",\\\"2026-10-14\\\",\\\"500\\\",9891,null,null,\\\"NOT_READY\\\",null,\\\"2026-07-27T08:51:06\\\",\\\"14087087\\\"]],\\\"rowCount\\\":1,\\\"returnedRows\\\":1,\\\"hasMore\\\":false,\\\"truncated\\\":false,\\\"nextOffset\\\":null,\\\"datasetTruncated\\\":false,\\\"completenessMessage\\\":\\\"数据集已完整读取。\\\"}\", \"callId\": \"call_63eb2f22041d4f659bd58906\"}','2026-11-23 15:12:55.300444');
INSERT INTO `ai_agent_trace` (`id`, `user_id`, `conversation_id`, `task_id`, `agent_type`, `event_type`, `content`, `create_time`) VALUES (5889,1900000000000000001,2124761984778977281,'026275db-dfa3-4539-abec-3b9cba45fa14','MAIN','TOOL_CALL','{\"name\": \"prepare_purchase_order_draft\", \"text\": \"{\\\"request\\\": {\\\"items\\\": [{\\\"productId\\\": \\\"8400000000005001253\\\", \\\"quantity\\\": 88, \\\"unitPrice\\\": 21.07}], \\\"supplierId\\\": \\\"8400000000002000099\\\", \\\"warehouseId\\\": \\\"8400000000004000001\\\"}}\", \"callId\": \"call_9bc63053cbe9437d9f26ba4c\"}','2026-11-23 15:12:57.738262');
INSERT INTO `ai_agent_trace` (`id`, `user_id`, `conversation_id`, `task_id`, `agent_type`, `event_type`, `content`, `create_time`) VALUES (5890,1900000000000000001,2124761984778977281,'026275db-dfa3-4539-abec-3b9cba45fa14','MAIN','TOOL_RESULT','{\"name\": \"prepare_purchase_order_draft\", \"text\": \"\\\"用户确认创建，采购单 PO2026112300008 已生成草稿。\\\\n草稿单：{\\\\\\\"purchaseOrderId\\\\\\\":\\\\\\\"2124764053313241090\\\\\\\",\\\\\\\"orderNo\\\\\\\":\\\\\\\"PO2026112300008\\\\\\\"}\\\"\", \"callId\": \"call_9bc63053cbe9437d9f26ba4c\"}','2026-11-23 15:16:41.389230');
INSERT INTO `ai_agent_trace` (`id`, `user_id`, `conversation_id`, `task_id`, `agent_type`, `event_type`, `content`, `create_time`) VALUES (5891,1900000000000000001,2124761984778977281,'026275db-dfa3-4539-abec-3b9cba45fa14','MAIN','MODEL_OUTPUT','{\"text\": \"草稿已由你确认，单号 **PO2026112300008**。按你“确认后直接提交”的要求，我现在提交审核。\"}','2026-11-23 15:16:45.063628');
INSERT INTO `ai_agent_trace` (`id`, `user_id`, `conversation_id`, `task_id`, `agent_type`, `event_type`, `content`, `create_time`) VALUES (5892,1900000000000000001,2124761984778977281,'026275db-dfa3-4539-abec-3b9cba45fa14','MAIN','TOOL_CALL','{\"name\": \"submit_purchase_order\", \"text\": \"{\\\"request\\\": {\\\"purchaseOrderId\\\": \\\"2124764053313241090\\\", \\\"orderNo\\\": \\\"PO2026112300008\\\"}}\", \"callId\": \"call_81693cb36cdc4fc59ff6cd91\"}','2026-11-23 15:16:45.067986');
INSERT INTO `ai_agent_trace` (`id`, `user_id`, `conversation_id`, `task_id`, `agent_type`, `event_type`, `content`, `create_time`) VALUES (5893,1900000000000000001,2124761984778977281,'026275db-dfa3-4539-abec-3b9cba45fa14','MAIN','TOOL_RESULT','{\"name\": \"submit_purchase_order\", \"text\": \"\\\"用户同意提交，采购单 PO2026112300008 已提交审核，当前状态为待审核。\\\\n预计到货：2026-12-02\\\"\", \"callId\": \"call_81693cb36cdc4fc59ff6cd91\"}','2026-11-23 15:17:52.358566');
INSERT INTO `ai_agent_trace` (`id`, `user_id`, `conversation_id`, `task_id`, `agent_type`, `event_type`, `content`, `create_time`) VALUES (5894,1900000000000000001,2124761984778977281,'026275db-dfa3-4539-abec-3b9cba45fa14','MAIN','FINAL','{\"text\": \"**结论：补货单已提交，单号 PO2026112300008，当前状态为待审核；补货数量 88 罐，按最近成交价 21.07 元/罐估算货值 1,854.16 元。**\\n\\n**缺口情况（上海浦东中心仓，P001253 沁泉碳酸饮料便携装，单位罐）**\\n- 账面库存 64.00 罐，全部被锁定，可用库存 **0.00 罐**；安全库存 88.00 罐，因此当前缺口为 **88.00 罐**，实际上已经断货。\\n- 锁定量并非重复扣减：对应销售单 SO2026110200005（部分出库，订单量 270 罐、已出库 206 罐、待出库 64 罐），锁定量与待出库量一致。该单预计交货日为 2026-11-05，已逾期 18 天，**64 罐待发订单暂无货可发**。\\n- 在途采购和未确认的采购入库单均为 0 行，本次采购不会重复下单。\\n\\n**供应商选择**\\n- 该产品的启用供货关系只有 1 家：S0099 济南金桥食品供应链有限公司，**没有替补供应商**；质量评分 98.91 可以引用，但整体评分状态为 NOT_READY，价格分和推荐分为空，系统没有给出可比评分。\\n- 人工报价 21.07 元/罐，有效期至 2026-10-14，**已过期 40 天**；由于最近成交价同为 21.07 元，草稿按此价格下单，正式下单前仍需供应商重新确认价格。\\n- 最小起订量 5 罐，精度为整数：采购量为 88 罐正好覆盖缺口，没有超买；比参考采购价 20.78 元高 0.29 元/罐，整单贵 25.52 元。到货后账面 88 罐，扣除待发 64 罐后剩 24 罐。\\n\\n**需要你注意的限制**\\n1. **数量能补齐，但到货时间尚无法确认**：该供应商没有近 180 天完全入库样本，缺少平均到货周期，因此无法用历史数据推算到货日；单据上的预计到货 2026-12-02 是单据填写的日期，并非历史交期推算，建议拿到供应商书面承诺后再安排发运或催交。\\n2. 单价和交期都依赖供应商后续确认；报价已过期，存在变价风险。\\n3. 单一供应源，建议同步拓展第二供应商，避免下次断货时没有备选。\\n\\n提交后下一步是等待主管审核，审核通过才进入待入库，目前尚未产生入库事实。\"}','2026-11-23 15:17:59.484883');
INSERT INTO `ai_dataset` (`dataset_id`, `sql_run_id`, `attempt`, `ready_run_id`, `user_id`, `conversation_id`, `description`, `source_sql`, `columns_json`, `row_count`, `completed`, `storage_file`, `status`, `expires_at`, `created_at`, `data_description_json`, `truncation_reason`) VALUES ('ds_0821595dc2cc4a0997dec025c98df37e','sqlrun_381490aeec164891a32ef5cfa728e3a5',1,'sqlrun_381490aeec164891a32ef5cfa728e3a5',1900000000000000001,2124421893103570946,'查询产品编码 P000173（绿田 新鲜蔬菜量贩装）的产品主档信息：产品ID、产品名称、单位、数量精度、参考采购价（分）、参考销售价（分）、安全库存数量（100倍整数）、状态','SELECT id AS product_id, product_code, product_name, unit_name, quantity_precision, reference_purchase_price, reference_sale_price, safety_stock_qty, status FROM product WHERE product_code = \'P000173\' AND deleted = 0','[{\"name\":\"id\",\"label\":\"product_id\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"product_code\",\"label\":\"product_code\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"product_name\",\"label\":\"product_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"unit_name\",\"label\":\"unit_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"quantity_precision\",\"label\":\"quantity_precision\",\"jdbcType\":-6,\"typeName\":\"TINYINT\",\"nullable\":false},{\"name\":\"reference_purchase_price\",\"label\":\"reference_purchase_price\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"reference_sale_price\",\"label\":\"reference_sale_price\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"safety_stock_qty\",\"label\":\"safety_stock_qty\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"status\",\"label\":\"status\",\"jdbcType\":-6,\"typeName\":\"TINYINT\",\"nullable\":false}]',1,1,'ds_0821595dc2cc4a0997dec025c98df37e.jsonl','READY','2026-12-07 00:00:00.000000','2026-11-22 08:37:12.025692','{\"grain\": \"每个产品一行\", \"fields\": [{\"name\": \"product_id\", \"index\": 0, \"meaning\": \"产品ID\"}, {\"name\": \"product_code\", \"index\": 1, \"meaning\": \"产品编码\"}, {\"name\": \"product_name\", \"index\": 2, \"meaning\": \"产品名称\"}, {\"name\": \"unit_name\", \"index\": 3, \"meaning\": \"单位名称\"}, {\"name\": \"quantity_precision\", \"index\": 4, \"meaning\": \"数量小数位精度（0-2）\"}, {\"name\": \"reference_purchase_price\", \"index\": 5, \"meaning\": \"参考采购价（单位：分）\"}, {\"name\": \"reference_sale_price\", \"index\": 6, \"meaning\": \"参考销售价（单位：分）\"}, {\"name\": \"safety_stock_qty\", \"index\": 7, \"meaning\": \"安全库存数量（按100倍整数存储，例如2900表示29.00）\"}, {\"name\": \"status\", \"index\": 8, \"meaning\": \"状态（1启用，0禁用）\"}], \"content\": \"产品编码为 P000173（绿田 新鲜蔬菜量贩装）的产品主档详细信息，包括基础属性、价格参考和安全库存设置。\", \"limitations\": \"\"}',NULL);
INSERT INTO `ai_dataset` (`dataset_id`, `sql_run_id`, `attempt`, `ready_run_id`, `user_id`, `conversation_id`, `description`, `source_sql`, `columns_json`, `row_count`, `completed`, `storage_file`, `status`, `expires_at`, `created_at`, `data_description_json`, `truncation_reason`) VALUES ('ds_0ec4bee4d0f24143ac6f5d1eefd77d46','sqlrun_9bea2925500c49fbb928c1d0ac1749b1',1,'sqlrun_9bea2925500c49fbb928c1d0ac1749b1',1900000000000000001,2124761984778977281,'查询产品编码 P001253 的产品主档信息，包括产品ID、名称、单位、数量小数位、安全库存、参考采购价和状态','SELECT id, product_code, product_name, unit_name, quantity_precision, safety_stock_qty, reference_purchase_price, status FROM product WHERE product_code = \'P001253\' AND deleted = 0','[{\"name\":\"id\",\"label\":\"id\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"product_code\",\"label\":\"product_code\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"product_name\",\"label\":\"product_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"unit_name\",\"label\":\"unit_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"quantity_precision\",\"label\":\"quantity_precision\",\"jdbcType\":-6,\"typeName\":\"TINYINT\",\"nullable\":false},{\"name\":\"safety_stock_qty\",\"label\":\"safety_stock_qty\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"reference_purchase_price\",\"label\":\"reference_purchase_price\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"status\",\"label\":\"status\",\"jdbcType\":-6,\"typeName\":\"TINYINT\",\"nullable\":false}]',1,1,'ds_0ec4bee4d0f24143ac6f5d1eefd77d46.jsonl','READY','2026-12-08 00:00:00.000000','2026-11-23 07:09:08.057462','{\"grain\": \"每个产品一行\", \"fields\": [{\"name\": \"id\", \"index\": 0, \"meaning\": \"产品ID\"}, {\"name\": \"product_code\", \"index\": 1, \"meaning\": \"产品编码\"}, {\"name\": \"product_name\", \"index\": 2, \"meaning\": \"产品名称\"}, {\"name\": \"unit_name\", \"index\": 3, \"meaning\": \"单位名称\"}, {\"name\": \"quantity_precision\", \"index\": 4, \"meaning\": \"数量小数位精度（0-2）\"}, {\"name\": \"safety_stock_qty\", \"index\": 5, \"meaning\": \"安全库存数量（库内存储值为实际数量的100倍，需除以100得到业务值）\"}, {\"name\": \"reference_purchase_price\", \"index\": 6, \"meaning\": \"参考采购价（库内存储单位为分，需除以100得到元）\"}, {\"name\": \"status\", \"index\": 7, \"meaning\": \"产品状态（1启用，0禁用）\"}], \"content\": \"产品主档信息查询结果，针对特定产品编码 P001253，涵盖基础标识、计量属性及库存/价格策略字段。\", \"limitations\": \"safety_stock_qty 和 reference_purchase_price 为放大存储值，展示时需按口径换算（分别除以100）。\"}',NULL);
INSERT INTO `ai_dataset` (`dataset_id`, `sql_run_id`, `attempt`, `ready_run_id`, `user_id`, `conversation_id`, `description`, `source_sql`, `columns_json`, `row_count`, `completed`, `storage_file`, `status`, `expires_at`, `created_at`, `data_description_json`, `truncation_reason`) VALUES ('ds_10fd436e35d2450c9a9b30e3e69f7c8c','sqlrun_41fa7a4f7498499ba9f9bed8ca949604',1,'sqlrun_41fa7a4f7498499ba9f9bed8ca949604',1900000000000000001,2124423434279604226,'查询产品编码 P000005（果沁 碳酸饮料礼盒装）的产品主档信息：产品名称、单位、数量小数位、参考售价、参考采购价、安全库存、状态','SELECT product_code, product_name, unit_name, quantity_precision, reference_sale_price / 100.0 AS reference_sale_price, reference_purchase_price / 100.0 AS reference_purchase_price, safety_stock_qty / 100.0 AS safety_stock_qty, status FROM product WHERE product_code = \'P000005\' AND deleted = 0','[{\"name\":\"product_code\",\"label\":\"product_code\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"product_name\",\"label\":\"product_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"unit_name\",\"label\":\"unit_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"quantity_precision\",\"label\":\"quantity_precision\",\"jdbcType\":-6,\"typeName\":\"TINYINT\",\"nullable\":false},{\"name\":\"reference_sale_price\",\"label\":\"reference_sale_price\",\"jdbcType\":3,\"typeName\":\"DECIMAL\",\"nullable\":true},{\"name\":\"reference_purchase_price\",\"label\":\"reference_purchase_price\",\"jdbcType\":3,\"typeName\":\"DECIMAL\",\"nullable\":true},{\"name\":\"safety_stock_qty\",\"label\":\"safety_stock_qty\",\"jdbcType\":3,\"typeName\":\"DECIMAL\",\"nullable\":true},{\"name\":\"status\",\"label\":\"status\",\"jdbcType\":-6,\"typeName\":\"TINYINT\",\"nullable\":false}]',1,1,'ds_10fd436e35d2450c9a9b30e3e69f7c8c.jsonl','READY','2026-12-07 00:00:00.000000','2026-11-22 08:43:20.494766','{\"grain\": \"每个产品一行\", \"fields\": [{\"name\": \"product_code\", \"index\": 0, \"meaning\": \"产品编码\"}, {\"name\": \"product_name\", \"index\": 1, \"meaning\": \"产品名称\"}, {\"name\": \"unit_name\", \"index\": 2, \"meaning\": \"单位名称\"}, {\"name\": \"quantity_precision\", \"index\": 3, \"meaning\": \"数量小数位精度（0-2）\"}, {\"name\": \"reference_sale_price\", \"index\": 4, \"meaning\": \"参考销售价（元），由分换算而来\"}, {\"name\": \"reference_purchase_price\", \"index\": 5, \"meaning\": \"参考采购价（元），由分换算而来\"}, {\"name\": \"safety_stock_qty\", \"index\": 6, \"meaning\": \"安全库存数量（业务单位），由100倍整数还原而来\"}, {\"name\": \"status\", \"index\": 7, \"meaning\": \"产品状态：1启用，0禁用\"}], \"content\": \"产品 P000005（果沁 碳酸饮料礼盒装）的主档详细信息\", \"limitations\": \"\"}',NULL);
INSERT INTO `ai_dataset` (`dataset_id`, `sql_run_id`, `attempt`, `ready_run_id`, `user_id`, `conversation_id`, `description`, `source_sql`, `columns_json`, `row_count`, `completed`, `storage_file`, `status`, `expires_at`, `created_at`, `data_description_json`, `truncation_reason`) VALUES ('ds_139749954e62459586479075c009cf13','sqlrun_15790d9b5f554cf68ccf2b8baa79d5d5',1,'sqlrun_15790d9b5f554cf68ccf2b8baa79d5d5',1900000000000000001,2124210189346299906,'查询所有未删除且状态为启用（status=1）的产品主档信息，包括产品ID、产品编码、产品名称、单位、数量小数位、安全库存数量（100倍整数，NULL 表示未设定）、参考采购价（元）、状态','SELECT id AS product_id, product_code, product_name, unit_name, quantity_precision, safety_stock_qty, reference_purchase_price, status FROM product WHERE deleted = 0 AND status = 1','[{\"name\":\"id\",\"label\":\"product_id\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"product_code\",\"label\":\"product_code\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"product_name\",\"label\":\"product_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"unit_name\",\"label\":\"unit_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"quantity_precision\",\"label\":\"quantity_precision\",\"jdbcType\":-6,\"typeName\":\"TINYINT\",\"nullable\":false},{\"name\":\"safety_stock_qty\",\"label\":\"safety_stock_qty\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"reference_purchase_price\",\"label\":\"reference_purchase_price\",\"jdbcType\":3,\"typeName\":\"DECIMAL\",\"nullable\":false},{\"name\":\"status\",\"label\":\"status\",\"jdbcType\":-6,\"typeName\":\"TINYINT\",\"nullable\":false}]',1560,1,'ds_139749954e62459586479075c009cf13.jsonl','READY','2026-12-06 00:00:00.000000','2026-11-21 18:38:37.303862','{\"grain\": \"每个产品一行\", \"fields\": [{\"name\": \"product_id\", \"index\": 0, \"meaning\": \"产品ID\"}, {\"name\": \"product_code\", \"index\": 1, \"meaning\": \"产品编码\"}, {\"name\": \"product_name\", \"index\": 2, \"meaning\": \"产品名称\"}, {\"name\": \"unit_name\", \"index\": 3, \"meaning\": \"单位名称\"}, {\"name\": \"quantity_precision\", \"index\": 4, \"meaning\": \"数量小数位（0-2）\"}, {\"name\": \"safety_stock_qty\", \"index\": 5, \"meaning\": \"安全库存数量（按100倍整数存储，例如12.50存1250；NULL表示未设定）\"}, {\"name\": \"reference_purchase_price\", \"index\": 6, \"meaning\": \"参考采购价（单位：元）\"}, {\"name\": \"status\", \"index\": 7, \"meaning\": \"状态（1启用，0禁用）\"}], \"content\": \"所有未删除且状态为启用（status=1）的产品主档列表，用于低库存判断基准。\", \"limitations\": \"\"}',NULL);
INSERT INTO `ai_dataset` (`dataset_id`, `sql_run_id`, `attempt`, `ready_run_id`, `user_id`, `conversation_id`, `description`, `source_sql`, `columns_json`, `row_count`, `completed`, `storage_file`, `status`, `expires_at`, `created_at`, `data_description_json`, `truncation_reason`) VALUES ('ds_1637b626902f48838bd67ba3f53c90b8','sqlrun_5af400224ceb429c80e3e05f826b8441',1,'sqlrun_5af400224ceb429c80e3e05f826b8441',1900000000000000001,2124210189346299906,'查询当前所有尚未完全入库的采购订单（状态为 APPROVED、PARTIAL_INBOUND 或 SUBMITTED），列出采购单号、供应商、目标仓库、预计到货日期、订单金额，用于确认用户所指“要晚到”的是哪批采购','SELECT purchase_no AS `采购单号`, supplier_name AS `供应商名称`, warehouse_name AS `目标入库仓库`, status AS `状态`, expected_arrival_date AS `预计到货日期`, total_amount / 100.0 AS `订单总金额(元)`, approved_at AS `审核时间` FROM purchase_order WHERE deleted = 0 AND status IN (\'APPROVED\', \'PARTIAL_INBOUND\', \'SUBMITTED\')','[{\"name\":\"purchase_no\",\"label\":\"采购单号\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"supplier_name\",\"label\":\"供应商名称\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"warehouse_name\",\"label\":\"目标入库仓库\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"status\",\"label\":\"状态\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"expected_arrival_date\",\"label\":\"预计到货日期\",\"jdbcType\":91,\"typeName\":\"DATE\",\"nullable\":true},{\"name\":\"订单总金额(元)\",\"label\":\"订单总金额(元)\",\"jdbcType\":3,\"typeName\":\"DECIMAL\",\"nullable\":true},{\"name\":\"approved_at\",\"label\":\"审核时间\",\"jdbcType\":93,\"typeName\":\"DATETIME\",\"nullable\":true}]',0,1,'ds_1637b626902f48838bd67ba3f53c90b8.jsonl','READY','2026-12-06 00:00:00.000000','2026-11-21 18:35:57.338604','{\"grain\": \"每张采购订单一行\", \"fields\": [{\"name\": \"采购单号\", \"index\": 0, \"meaning\": \"采购单号\"}, {\"name\": \"供应商名称\", \"index\": 1, \"meaning\": \"供应商名称快照\"}, {\"name\": \"目标入库仓库\", \"index\": 2, \"meaning\": \"目标入库仓库名称快照\"}, {\"name\": \"状态\", \"index\": 3, \"meaning\": \"订单状态（SUBMITTED/APPROVED/PARTIAL_INBOUND）\"}, {\"name\": \"预计到货日期\", \"index\": 4, \"meaning\": \"预计到货日期\"}, {\"name\": \"订单总金额(元)\", \"index\": 5, \"meaning\": \"订单总金额，单位元\"}, {\"name\": \"审核时间\", \"index\": 6, \"meaning\": \"审核通过时间；若状态为SUBMITTED则可能为空\"}], \"content\": \"所有尚未完全入库（状态为待审核、待入库或部分入库）的有效采购订单列表，用于确认延迟到货范围。\", \"limitations\": \"\"}',NULL);
INSERT INTO `ai_dataset` (`dataset_id`, `sql_run_id`, `attempt`, `ready_run_id`, `user_id`, `conversation_id`, `description`, `source_sql`, `columns_json`, `row_count`, `completed`, `storage_file`, `status`, `expires_at`, `created_at`, `data_description_json`, `truncation_reason`) VALUES ('ds_17252d7433704650a16ae46b6e7b8929','sqlrun_e2e5a495267b4039bbc1fe28cfa8db79',1,'sqlrun_e2e5a495267b4039bbc1fe28cfa8db79',1900000000000000001,2124421893103570946,'查询产品ID 8400000000005000173（P000173）的全部采购订单明细历史（不限状态，包括 INBOUND_DONE、CANCELLED 等，deleted=0），逐行返回：采购单ID、采购单号、供应商ID、供应商名称、目标仓库、订单状态、采购数量quantity（100倍）、已入库数量inbound_qty（100倍）、采购单价unit_price（分）、明细金额total_amount（分）、完全入库时间fully_received_at。用于确定该产品的原采购来源、供应商与实际已入库数量，作为退供理论可退量基础。','SELECT poi.purchase_order_id AS purchase_order_id, poi.purchase_no AS purchase_no, po.supplier_id AS supplier_id, po.supplier_name AS supplier_name, po.warehouse_name AS warehouse_name, po.status AS status, poi.quantity AS quantity, poi.inbound_qty AS inbound_qty, poi.unit_price AS unit_price, poi.total_amount AS total_amount, po.fully_received_at AS fully_received_at, po.cancelled_at AS cancelled_at, poi.create_time AS create_time FROM purchase_order_item poi JOIN purchase_order po ON poi.purchase_order_id = po.id WHERE poi.product_id = 8400000000005000173 AND po.deleted = 0','[{\"name\":\"purchase_order_id\",\"label\":\"purchase_order_id\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"purchase_no\",\"label\":\"purchase_no\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"supplier_id\",\"label\":\"supplier_id\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"supplier_name\",\"label\":\"supplier_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"warehouse_name\",\"label\":\"warehouse_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"status\",\"label\":\"status\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"quantity\",\"label\":\"quantity\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"inbound_qty\",\"label\":\"inbound_qty\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"unit_price\",\"label\":\"unit_price\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"total_amount\",\"label\":\"total_amount\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"fully_received_at\",\"label\":\"fully_received_at\",\"jdbcType\":93,\"typeName\":\"DATETIME\",\"nullable\":true},{\"name\":\"cancelled_at\",\"label\":\"cancelled_at\",\"jdbcType\":93,\"typeName\":\"DATETIME\",\"nullable\":true},{\"name\":\"create_time\",\"label\":\"create_time\",\"jdbcType\":93,\"typeName\":\"DATETIME\",\"nullable\":false}]',1,1,'ds_17252d7433704650a16ae46b6e7b8929.jsonl','READY','2026-12-07 00:00:00.000000','2026-11-22 08:38:43.065673','{\"grain\": \"每张采购订单中该产品的一行明细记录\", \"fields\": [{\"name\": \"purchase_order_id\", \"index\": 0, \"meaning\": \"采购订单主表ID\"}, {\"name\": \"purchase_no\", \"index\": 1, \"meaning\": \"采购单号\"}, {\"name\": \"supplier_id\", \"index\": 2, \"meaning\": \"供应商ID\"}, {\"name\": \"supplier_name\", \"index\": 3, \"meaning\": \"供应商名称快照\"}, {\"name\": \"warehouse_name\", \"index\": 4, \"meaning\": \"目标入库仓库名称快照\"}, {\"name\": \"status\", \"index\": 5, \"meaning\": \"采购订单状态（如 INBOUND_DONE, CANCELLED 等）\"}, {\"name\": \"quantity\", \"index\": 6, \"meaning\": \"采购数量（存储值为实际数量的100倍）\"}, {\"name\": \"inbound_qty\", \"index\": 7, \"meaning\": \"已入库数量（存储值为实际数量的100倍）\"}, {\"name\": \"unit_price\", \"index\": 8, \"meaning\": \"采购单价（单位：分）\"}, {\"name\": \"total_amount\", \"index\": 9, \"meaning\": \"明细总金额（单位：分）\"}, {\"name\": \"fully_received_at\", \"index\": 10, \"meaning\": \"完全入库时间（最后一笔入库确认时间）\"}, {\"name\": \"cancelled_at\", \"index\": 11, \"meaning\": \"取消时间\"}, {\"name\": \"create_time\", \"index\": 12, \"meaning\": \"采购明细创建时间\"}], \"content\": \"产品ID 8400000000005000173 (P000173) 的全部有效采购订单明细历史，包含采购单号、供应商、仓库、状态及数量金额等关键信息。\", \"limitations\": \"\"}',NULL);
INSERT INTO `ai_dataset` (`dataset_id`, `sql_run_id`, `attempt`, `ready_run_id`, `user_id`, `conversation_id`, `description`, `source_sql`, `columns_json`, `row_count`, `completed`, `storage_file`, `status`, `expires_at`, `created_at`, `data_description_json`, `truncation_reason`) VALUES ('ds_17e76f24328b46a5ba96e81a69751aff','sqlrun_d56e7a6ea0e244f8b45c1f2681339a9a',1,'sqlrun_d56e7a6ea0e244f8b45c1f2681339a9a',1900000000000000001,2124420137200144385,'查询产品分类“坚果”（category_id=8400000000001000001）下全部产品在近180天（2026-05-26至2026-11-22）内由已完全入库（status=INBOUND_DONE）采购订单产生的采购金额合计与订单数，按供应商分行汇总，并同时给出该品类合计金额与合计订单数；用于计算品类供应商集中度','SELECT po.supplier_code AS supplier_code, po.supplier_name AS supplier_name, SUM(poi.total_amount) / 100.0 AS purchase_amount, COUNT(DISTINCT po.id) AS order_count, COUNT(DISTINCT poi.product_id) AS product_count FROM purchase_order po JOIN purchase_order_item poi ON po.id = poi.purchase_order_id JOIN product p ON poi.product_id = p.id WHERE po.deleted = 0 AND po.status = \'INBOUND_DONE\' AND po.fully_received_at >= \'2026-05-26 00:00:00\' AND po.fully_received_at <= \'2026-11-22 23:59:59\' AND p.deleted = 0 AND p.category_id = 8400000000001000001 GROUP BY po.supplier_code, po.supplier_name ORDER BY purchase_amount DESC','[{\"name\":\"supplier_code\",\"label\":\"supplier_code\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"supplier_name\",\"label\":\"supplier_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"purchase_amount\",\"label\":\"purchase_amount\",\"jdbcType\":3,\"typeName\":\"DECIMAL\",\"nullable\":true},{\"name\":\"order_count\",\"label\":\"order_count\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"product_count\",\"label\":\"product_count\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false}]',11,1,'ds_17e76f24328b46a5ba96e81a69751aff.jsonl','READY','2026-12-07 00:00:00.000000','2026-11-22 08:32:37.560671','{\"grain\": \"每个供应商一行\", \"fields\": [{\"name\": \"supplier_code\", \"index\": 0, \"meaning\": \"供应商编码\"}, {\"name\": \"supplier_name\", \"index\": 1, \"meaning\": \"供应商名称\"}, {\"name\": \"purchase_amount\", \"index\": 2, \"meaning\": \"该供应商在指定时间段内针对坚果品类的采购总金额（单位：元，由分转换）\"}, {\"name\": \"order_count\", \"index\": 3, \"meaning\": \"涉及该供应商且状态为已完全入库的采购订单数量\"}, {\"name\": \"product_count\", \"index\": 4, \"meaning\": \"该供应商在指定时间段内供应的坚果类产品种类数（去重后的产品ID计数）\"}], \"content\": \"近180天内坚果品类已完全入库采购订单按供应商汇总的金额与数量统计\", \"limitations\": \"\"}',NULL);
INSERT INTO `ai_dataset` (`dataset_id`, `sql_run_id`, `attempt`, `ready_run_id`, `user_id`, `conversation_id`, `description`, `source_sql`, `columns_json`, `row_count`, `completed`, `storage_file`, `status`, `expires_at`, `created_at`, `data_description_json`, `truncation_reason`) VALUES ('ds_270710dd5459418e85bacf851049521d','sqlrun_7fa03f72c3e149a3a7656d3f4e4be3ed',1,'sqlrun_7fa03f72c3e149a3a7656d3f4e4be3ed',1900000000000000001,2124420137200144385,'查询产品 P001143（product_id=8400000000005001143）在供应商 S0001（8400000000002000001）与 S0002（8400000000002000002）下的采购订单明细行，时间窗口 2026-05-26 至 2026-11-22（满足审核通过时间或完全入库时间落在该窗口即包含），字段包括供应商、采购单号、订单状态、审核通过时间、完全入库时间、预计到货日、采购数量、已入库数量、单价、明细金额；用于计算交付表现（订单数、完全入库单数、交期、逾期）与供应集中度','SELECT po.supplier_id AS supplier_id, po.supplier_name AS supplier_name, po.purchase_no AS purchase_no, po.status AS status, po.approved_at AS approved_at, po.fully_received_at AS fully_received_at, po.expected_arrival_date AS expected_arrival_date, poi.quantity / 100.0 AS quantity, poi.inbound_qty / 100.0 AS inbound_qty, poi.unit_price / 100.0 AS unit_price, poi.total_amount / 100.0 AS total_amount FROM purchase_order po JOIN purchase_order_item poi ON poi.purchase_order_id = po.id WHERE po.deleted = 0 AND po.supplier_id IN (8400000000002000001, 8400000000002000002) AND poi.product_id = 8400000000005001143 AND ((po.approved_at >= \'2026-05-26 00:00:00\' AND po.approved_at <= \'2026-11-22 23:59:59\') OR (po.fully_received_at >= \'2026-05-26 00:00:00\' AND po.fully_received_at <= \'2026-11-22 23:59:59\'))','[{\"name\":\"supplier_id\",\"label\":\"supplier_id\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"supplier_name\",\"label\":\"supplier_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"purchase_no\",\"label\":\"purchase_no\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"status\",\"label\":\"status\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"approved_at\",\"label\":\"approved_at\",\"jdbcType\":93,\"typeName\":\"DATETIME\",\"nullable\":true},{\"name\":\"fully_received_at\",\"label\":\"fully_received_at\",\"jdbcType\":93,\"typeName\":\"DATETIME\",\"nullable\":true},{\"name\":\"expected_arrival_date\",\"label\":\"expected_arrival_date\",\"jdbcType\":91,\"typeName\":\"DATE\",\"nullable\":true},{\"name\":\"quantity\",\"label\":\"quantity\",\"jdbcType\":3,\"typeName\":\"DECIMAL\",\"nullable\":true},{\"name\":\"inbound_qty\",\"label\":\"inbound_qty\",\"jdbcType\":3,\"typeName\":\"DECIMAL\",\"nullable\":true},{\"name\":\"unit_price\",\"label\":\"unit_price\",\"jdbcType\":3,\"typeName\":\"DECIMAL\",\"nullable\":true},{\"name\":\"total_amount\",\"label\":\"total_amount\",\"jdbcType\":3,\"typeName\":\"DECIMAL\",\"nullable\":true}]',2,1,'ds_270710dd5459418e85bacf851049521d.jsonl','READY','2026-12-07 00:00:00.000000','2026-11-22 08:31:21.580582','{\"grain\": \"每个采购订单明细行一行\", \"fields\": [{\"name\": \"supplier_id\", \"index\": 0, \"meaning\": \"供应商ID\"}, {\"name\": \"supplier_name\", \"index\": 1, \"meaning\": \"供应商名称\"}, {\"name\": \"purchase_no\", \"index\": 2, \"meaning\": \"采购单号\"}, {\"name\": \"status\", \"index\": 3, \"meaning\": \"订单状态 (如 APPROVED, INBOUND_DONE)\"}, {\"name\": \"approved_at\", \"index\": 4, \"meaning\": \"审核通过时间\"}, {\"name\": \"fully_received_at\", \"index\": 5, \"meaning\": \"完全入库时间\"}, {\"name\": \"expected_arrival_date\", \"index\": 6, \"meaning\": \"预计到货日期\"}, {\"name\": \"quantity\", \"index\": 7, \"meaning\": \"采购数量 (已还原为实际单位数值)\"}, {\"name\": \"inbound_qty\", \"index\": 8, \"meaning\": \"已入库数量 (已还原为实际单位数值)\"}, {\"name\": \"unit_price\", \"index\": 9, \"meaning\": \"单价 (元)\"}, {\"name\": \"total_amount\", \"index\": 10, \"meaning\": \"明细总金额 (元)\"}], \"content\": \"产品P001143在供应商S0001和S0002下的采购订单明细行，时间范围覆盖2026-05-26至2026-11-22内审核通过或完全入库的单据。\", \"limitations\": \"\"}',NULL);
INSERT INTO `ai_dataset` (`dataset_id`, `sql_run_id`, `attempt`, `ready_run_id`, `user_id`, `conversation_id`, `description`, `source_sql`, `columns_json`, `row_count`, `completed`, `storage_file`, `status`, `expires_at`, `created_at`, `data_description_json`, `truncation_reason`) VALUES ('ds_28d836d1013a4549b4823f6590219cdf','sqlrun_48e7484d04e44e8ca3c0ccf0ca0f27aa',1,'sqlrun_48e7484d04e44e8ca3c0ccf0ca0f27aa',1900000000000000001,2124221025439735809,'查询产品主档（排除已删除）的启用产品总数，按启用状态、计量单位、数量精度分组，并统计safety_stock_qty为NULL、为0、大于0的产品数，用于判断能否开展缺货风险判断及是否需要标注“无法判断”','SELECT status, unit_name, quantity_precision, COUNT(*) AS product_count, SUM(CASE WHEN safety_stock_qty IS NULL THEN 1 ELSE 0 END) AS safety_stock_null_count, SUM(CASE WHEN safety_stock_qty = 0 THEN 1 ELSE 0 END) AS safety_stock_zero_count, SUM(CASE WHEN safety_stock_qty > 0 THEN 1 ELSE 0 END) AS safety_stock_gt_zero_count FROM product WHERE deleted = 0 AND status = 1 GROUP BY status, unit_name, quantity_precision','[{\"name\":\"status\",\"label\":\"status\",\"jdbcType\":-6,\"typeName\":\"TINYINT\",\"nullable\":false},{\"name\":\"unit_name\",\"label\":\"unit_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"quantity_precision\",\"label\":\"quantity_precision\",\"jdbcType\":-6,\"typeName\":\"TINYINT\",\"nullable\":false},{\"name\":\"product_count\",\"label\":\"product_count\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"safety_stock_null_count\",\"label\":\"safety_stock_null_count\",\"jdbcType\":3,\"typeName\":\"DECIMAL\",\"nullable\":true},{\"name\":\"safety_stock_zero_count\",\"label\":\"safety_stock_zero_count\",\"jdbcType\":3,\"typeName\":\"DECIMAL\",\"nullable\":true},{\"name\":\"safety_stock_gt_zero_count\",\"label\":\"safety_stock_gt_zero_count\",\"jdbcType\":3,\"typeName\":\"DECIMAL\",\"nullable\":true}]',1,1,'ds_28d836d1013a4549b4823f6590219cdf.jsonl','READY','2026-12-06 00:00:00.000000','2026-11-21 19:20:11.942373','{\"grain\": \"每个status+unit_name+quantity_precision组合一行\", \"fields\": [{\"name\": \"status\", \"index\": 0, \"meaning\": \"产品启用状态（1表示启用）\"}, {\"name\": \"unit_name\", \"index\": 1, \"meaning\": \"计量单位名称\"}, {\"name\": \"quantity_precision\", \"index\": 2, \"meaning\": \"数量小数位精度（0-2）\"}, {\"name\": \"product_count\", \"index\": 3, \"meaning\": \"该组合下的产品总数\"}, {\"name\": \"safety_stock_null_count\", \"index\": 4, \"meaning\": \"安全库存字段为空(NULL)的产品数\"}, {\"name\": \"safety_stock_zero_count\", \"index\": 5, \"meaning\": \"安全库存字段为0的产品数\"}, {\"name\": \"safety_stock_gt_zero_count\", \"index\": 6, \"meaning\": \"安全库存字段大于0的产品数\"}], \"content\": \"统计启用且未删除的产品主档，按启用状态、计量单位、数量精度分组，汇总产品总数及安全库存为空、为0、大于0的产品数量。\", \"limitations\": \"\"}',NULL);
INSERT INTO `ai_dataset` (`dataset_id`, `sql_run_id`, `attempt`, `ready_run_id`, `user_id`, `conversation_id`, `description`, `source_sql`, `columns_json`, `row_count`, `completed`, `storage_file`, `status`, `expires_at`, `created_at`, `data_description_json`, `truncation_reason`) VALUES ('ds_2de41ada7ba34b68b9b0bb641fa7df8e','sqlrun_540242e3caca412eb748d71d70d57ec2',1,'sqlrun_540242e3caca412eb748d71d70d57ec2',1900000000000000001,2124421893103570946,'查询产品ID 8400000000005000173（P000173 绿田 新鲜蔬菜量贩装 1kg/袋）的全部历史销售出库明细事实，不限时间窗口，条件为出库单 outbound_type=SALES_OUT 且 outbound_bill.status=CONFIRMED、deleted=0。需要返回每张出库单一行：出库单ID、出库单号、仓库ID、仓库名称、客户ID(source_party_id)、客户名称(source_party_name)、确认时间 confirmed_at、该单该产品出库数量 current_qty（100倍整数）。用于核实该产品是否真的从未销售出库，并统计累计出库数量、首次与最近一次出库日期、涉及客户数与订单数。','SELECT ob.id AS outbound_bill_id, ob.outbound_no, ob.warehouse_id, ob.warehouse_name, ob.source_party_id, ob.source_party_name, ob.confirmed_at, obi.current_qty, obi.unit_name FROM outbound_bill ob JOIN outbound_bill_item obi ON ob.id = obi.outbound_bill_id WHERE ob.deleted = 0 AND ob.status = \'CONFIRMED\' AND ob.outbound_type = \'SALES_OUT\' AND obi.product_id = 8400000000005000173','[{\"name\":\"id\",\"label\":\"outbound_bill_id\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"outbound_no\",\"label\":\"outbound_no\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"warehouse_id\",\"label\":\"warehouse_id\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"warehouse_name\",\"label\":\"warehouse_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"source_party_id\",\"label\":\"source_party_id\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":true},{\"name\":\"source_party_name\",\"label\":\"source_party_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"confirmed_at\",\"label\":\"confirmed_at\",\"jdbcType\":93,\"typeName\":\"DATETIME\",\"nullable\":true},{\"name\":\"current_qty\",\"label\":\"current_qty\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"unit_name\",\"label\":\"unit_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false}]',0,1,'ds_2de41ada7ba34b68b9b0bb641fa7df8e.jsonl','READY','2026-12-07 00:00:00.000000','2026-11-22 08:38:00.301911','{\"grain\": \"每张已确认销售出库单中该特定产品的一行明细\", \"fields\": [{\"name\": \"outbound_bill_id\", \"index\": 0, \"meaning\": \"出库单主表ID\"}, {\"name\": \"outbound_no\", \"index\": 1, \"meaning\": \"出库单号\"}, {\"name\": \"warehouse_id\", \"index\": 2, \"meaning\": \"仓库ID\"}, {\"name\": \"warehouse_name\", \"index\": 3, \"meaning\": \"仓库名称快照\"}, {\"name\": \"source_party_id\", \"index\": 4, \"meaning\": \"客户ID（来源对象ID）\"}, {\"name\": \"source_party_name\", \"index\": 5, \"meaning\": \"客户名称快照（来源对象名称）\"}, {\"name\": \"confirmed_at\", \"index\": 6, \"meaning\": \"出库单确认时间\"}, {\"name\": \"current_qty\", \"index\": 7, \"meaning\": \"本次出库数量（按100倍整数存储，需除以100还原为业务数量）\"}, {\"name\": \"unit_name\", \"index\": 8, \"meaning\": \"单位名称快照\"}], \"content\": \"产品ID 8400000000005000173（P000173 绿田 新鲜蔬菜量贩装 1kg/袋）的全部历史已确认销售出库明细事实。查询条件限定为 outbound_type=\'SALES_OUT\'、status=\'CONFIRMED\'、deleted=0，且明细 product_id 匹配目标产品。当前返回行数为 0，表明该产品在系统中不存在任何已确认的销售出库记录。\", \"limitations\": \"\"}',NULL);
INSERT INTO `ai_dataset` (`dataset_id`, `sql_run_id`, `attempt`, `ready_run_id`, `user_id`, `conversation_id`, `description`, `source_sql`, `columns_json`, `row_count`, `completed`, `storage_file`, `status`, `expires_at`, `created_at`, `data_description_json`, `truncation_reason`) VALUES ('ds_3395f8121e3d4aa7a532e405d9f49080','sqlrun_e51deb3d143c4c84b9d649c51bffc24a',1,'sqlrun_e51deb3d143c4c84b9d649c51bffc24a',1900000000000000001,2124421893103570946,'查询产品ID 8400000000005000173（P000173）的全部库存流水明细（不限时间和单据类型），逐行返回：库存流水凭证ID、流水号、bill_type、仓库名称、确认时间confirmed_at、录入方式entry_mode、合格数量、不合格数量、变动前库存before_qty（100倍）、库存变动数量change_qty（100倍、入库为正出库为负）、变动后inventory after_qty（100倍）。用于核实该产品历史出入库构成、最近一次入库时间与是否存在任何出库消耗。','SELECT sb.id AS bill_id, sb.bill_no AS bill_no, sb.bill_type AS bill_type, sb.warehouse_name AS warehouse_name, sb.confirmed_at AS confirmed_at, sb.entry_mode AS entry_mode, sbi.work_bill_item_id AS work_bill_item_id, sbi.qualified_qty AS qualified_qty, sbi.defective_qty AS defective_qty, sbi.before_qty AS before_qty, sbi.change_qty AS change_qty, sbi.after_qty AS after_qty FROM stock_bill sb INNER JOIN stock_bill_item sbi ON sb.id = sbi.bill_id WHERE sbi.product_id = 8400000000005000173 ORDER BY sb.confirmed_at ASC, sb.id ASC','[{\"name\":\"id\",\"label\":\"bill_id\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"bill_no\",\"label\":\"bill_no\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"bill_type\",\"label\":\"bill_type\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"warehouse_name\",\"label\":\"warehouse_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"confirmed_at\",\"label\":\"confirmed_at\",\"jdbcType\":93,\"typeName\":\"DATETIME\",\"nullable\":false},{\"name\":\"entry_mode\",\"label\":\"entry_mode\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"work_bill_item_id\",\"label\":\"work_bill_item_id\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"qualified_qty\",\"label\":\"qualified_qty\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"defective_qty\",\"label\":\"defective_qty\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"before_qty\",\"label\":\"before_qty\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"change_qty\",\"label\":\"change_qty\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"after_qty\",\"label\":\"after_qty\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false}]',2,1,'ds_3395f8121e3d4aa7a532e405d9f49080.jsonl','READY','2026-12-07 00:00:00.000000','2026-11-22 08:40:01.868963','{\"grain\": \"每条库存流水凭证明细一行\", \"fields\": [{\"name\": \"bill_id\", \"index\": 0, \"meaning\": \"库存流水凭证ID\"}, {\"name\": \"bill_no\", \"index\": 1, \"meaning\": \"库存流水号\"}, {\"name\": \"bill_type\", \"index\": 2, \"meaning\": \"单据类型 (如 PURCHASE_IN, ADJUST_IN)\"}, {\"name\": \"warehouse_name\", \"index\": 3, \"meaning\": \"仓库名称快照\"}, {\"name\": \"confirmed_at\", \"index\": 4, \"meaning\": \"确认时间\"}, {\"name\": \"entry_mode\", \"index\": 5, \"meaning\": \"录入方式 (如 SOURCE_GENERATED, MANUAL_ADJUSTMENT)\"}, {\"name\": \"work_bill_item_id\", \"index\": 6, \"meaning\": \"关联的出入库单明细ID\"}, {\"name\": \"qualified_qty\", \"index\": 7, \"meaning\": \"合格数量 (存储值，需除以100得到实际业务数量)\"}, {\"name\": \"defective_qty\", \"index\": 8, \"meaning\": \"不合格数量 (存储值，需除以100得到实际业务数量)\"}, {\"name\": \"before_qty\", \"index\": 9, \"meaning\": \"变动前库存 (存储值，需除以100得到实际业务数量)\"}, {\"name\": \"change_qty\", \"index\": 10, \"meaning\": \"库存变动数量 (存储值，入库为正/出库为负，需除以100得到实际业务数量)\"}, {\"name\": \"after_qty\", \"index\": 11, \"meaning\": \"变动后库存 (存储值，需除以100得到实际业务数量)\"}], \"content\": \"产品ID 8400000000005000173 (P000173) 的全部库存流水明细，包含入库、出库及调整记录。\", \"limitations\": \"数量字段（qualified_qty, defective_qty, before_qty, change_qty, after_qty）在数据库中按100倍整数存储，展示或分析时需除以100还原为实际业务数量。\"}',NULL);
INSERT INTO `ai_dataset` (`dataset_id`, `sql_run_id`, `attempt`, `ready_run_id`, `user_id`, `conversation_id`, `description`, `source_sql`, `columns_json`, `row_count`, `completed`, `storage_file`, `status`, `expires_at`, `created_at`, `data_description_json`, `truncation_reason`) VALUES ('ds_35f20421168e4b87b16915d328aefd8a','sqlrun_1a4a8d53627142508bca9769f1147aea',3,'sqlrun_1a4a8d53627142508bca9769f1147aea',1900000000000000001,2124221025439735809,'查询所有仓库清单及各仓库的库存商品SKU数、库存总量，用于确认库存健康诊断的仓库范围和数据规模','SELECT w.id AS warehouse_id, w.warehouse_code, w.warehouse_name, w.status AS warehouse_status, ws.unit_name, COUNT(DISTINCT ws.product_id) AS sku_count, SUM(ws.stock_qty / 100.0) AS total_stock_qty FROM warehouse w INNER JOIN warehouse_stock ws ON w.id = ws.warehouse_id WHERE w.deleted = 0 GROUP BY w.id, w.warehouse_code, w.warehouse_name, w.status, ws.unit_name','[{\"name\":\"id\",\"label\":\"warehouse_id\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"warehouse_code\",\"label\":\"warehouse_code\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"warehouse_name\",\"label\":\"warehouse_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"status\",\"label\":\"warehouse_status\",\"jdbcType\":-6,\"typeName\":\"TINYINT\",\"nullable\":false},{\"name\":\"unit_name\",\"label\":\"unit_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"sku_count\",\"label\":\"sku_count\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"total_stock_qty\",\"label\":\"total_stock_qty\",\"jdbcType\":3,\"typeName\":\"DECIMAL\",\"nullable\":true}]',5,1,'ds_35f20421168e4b87b16915d328aefd8a.jsonl','READY','2026-12-06 00:00:00.000000','2026-11-21 19:19:11.458674','{\"grain\": \"每个仓库每种单位一行\", \"fields\": [{\"name\": \"warehouse_id\", \"index\": 0, \"meaning\": \"仓库ID\"}, {\"name\": \"warehouse_code\", \"index\": 1, \"meaning\": \"仓库编码\"}, {\"name\": \"warehouse_name\", \"index\": 2, \"meaning\": \"仓库名称\"}, {\"name\": \"warehouse_status\", \"index\": 3, \"meaning\": \"仓库状态：1启用，0禁用\"}, {\"name\": \"unit_name\", \"index\": 4, \"meaning\": \"单位名称\"}, {\"name\": \"sku_count\", \"index\": 5, \"meaning\": \"该仓库该单位下的库存商品SKU数\"}, {\"name\": \"total_stock_qty\", \"index\": 6, \"meaning\": \"该仓库该单位下的库存总量（业务单位）\"}], \"content\": \"所有未删除仓库的库存商品SKU数及库存总量（按单位分组）\", \"limitations\": \"需求期望每仓库一行，但SQL按单位分组导致多行；若需严格每仓库一行且汇总数量，需确认是否允许跨单位求和或仅统计单一单位。当前数据中各仓库似乎只有一种单位“件”，故实际表现为每仓库一行，但逻辑上存在风险。\"}',NULL);
INSERT INTO `ai_dataset` (`dataset_id`, `sql_run_id`, `attempt`, `ready_run_id`, `user_id`, `conversation_id`, `description`, `source_sql`, `columns_json`, `row_count`, `completed`, `storage_file`, `status`, `expires_at`, `created_at`, `data_description_json`, `truncation_reason`) VALUES ('ds_37d891578535459393dcb70f762958da','sqlrun_da89285a2b23475087540fba9536014d',2,'sqlrun_da89285a2b23475087540fba9536014d',1900000000000000001,2124465547335741442,'查询统一退货单主表 return_order 的全部记录，时间范围覆盖 2025-11-23 至 2026-11-22（含端点，按 create_time），包含所有 return_type（PURCHASE_RETURN、SALES_RETURN）和所有状态（含 CANCELLED/DRAFT/PENDING），全部仓库、全部供应商与客户，不限定产品或分类。需要 deleted 字段用于过滤逻辑删除，需要 reason_code 原始值用于原因归一，需要 status 用于确定纳入统计的状态范围。','SELECT id, return_no, return_type, source_order_id, source_order_no, party_id, party_code, party_name, warehouse_id, warehouse_name, expected_execution_date, handling_type, reason_code, reason_code AS reason_code_raw, return_reason, total_amount, status, status_reason, submitted_at, approved_at, create_time, deleted FROM return_order WHERE deleted = 0 AND create_time >= \'2025-11-23 00:00:00\' AND create_time <= \'2026-11-22 23:59:59\'','[{\"name\":\"id\",\"label\":\"id\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"return_no\",\"label\":\"return_no\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"return_type\",\"label\":\"return_type\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"source_order_id\",\"label\":\"source_order_id\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"source_order_no\",\"label\":\"source_order_no\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"party_id\",\"label\":\"party_id\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"party_code\",\"label\":\"party_code\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"party_name\",\"label\":\"party_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"warehouse_id\",\"label\":\"warehouse_id\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"warehouse_name\",\"label\":\"warehouse_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"expected_execution_date\",\"label\":\"expected_execution_date\",\"jdbcType\":91,\"typeName\":\"DATE\",\"nullable\":true},{\"name\":\"handling_type\",\"label\":\"handling_type\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"reason_code\",\"label\":\"reason_code\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"reason_code\",\"label\":\"reason_code_raw\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"return_reason\",\"label\":\"return_reason\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"total_amount\",\"label\":\"total_amount\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"status\",\"label\":\"status\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"status_reason\",\"label\":\"status_reason\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"submitted_at\",\"label\":\"submitted_at\",\"jdbcType\":93,\"typeName\":\"DATETIME\",\"nullable\":true},{\"name\":\"approved_at\",\"label\":\"approved_at\",\"jdbcType\":93,\"typeName\":\"DATETIME\",\"nullable\":true},{\"name\":\"create_time\",\"label\":\"create_time\",\"jdbcType\":93,\"typeName\":\"DATETIME\",\"nullable\":false},{\"name\":\"deleted\",\"label\":\"deleted\",\"jdbcType\":-6,\"typeName\":\"TINYINT\",\"nullable\":false}]',366,1,'ds_37d891578535459393dcb70f762958da.jsonl','READY','2026-12-07 00:00:00.000000','2026-11-22 11:31:06.479712','{\"grain\": \"每张退货单一行\", \"fields\": [{\"name\": \"id\", \"index\": 0, \"meaning\": \"退货单ID\"}, {\"name\": \"return_no\", \"index\": 1, \"meaning\": \"退货单号\"}, {\"name\": \"return_type\", \"index\": 2, \"meaning\": \"退货类型：SALES_RETURN(销售退货)或PURCHASE_RETURN(采购退货)\"}, {\"name\": \"source_order_id\", \"index\": 3, \"meaning\": \"原订单ID（销售订单或采购订单）\"}, {\"name\": \"source_order_no\", \"index\": 4, \"meaning\": \"原订单号快照\"}, {\"name\": \"party_id\", \"index\": 5, \"meaning\": \"对象ID：销售退货为客户ID，采购退货为供应商ID\"}, {\"name\": \"party_code\", \"index\": 6, \"meaning\": \"客户或供应商编码快照\"}, {\"name\": \"party_name\", \"index\": 7, \"meaning\": \"客户或供应商名称快照\"}, {\"name\": \"warehouse_id\", \"index\": 8, \"meaning\": \"退货执行仓库ID\"}, {\"name\": \"warehouse_name\", \"index\": 9, \"meaning\": \"退货执行仓库名称快照\"}, {\"name\": \"expected_execution_date\", \"index\": 10, \"meaning\": \"预计退货执行日期\"}, {\"name\": \"handling_type\", \"index\": 11, \"meaning\": \"处理方式：REFUND(退款), EXCHANGE(换货), OTHER(其他)\"}, {\"name\": \"reason_code\", \"index\": 12, \"meaning\": \"退货原因编码（规范值）\"}, {\"name\": \"reason_code_raw\", \"index\": 13, \"meaning\": \"退货原因编码原始值（用于归一分析，当前SQL中同reason_code）\"}, {\"name\": \"return_reason\", \"index\": 14, \"meaning\": \"退货原因补充说明文本\"}, {\"name\": \"total_amount\", \"index\": 15, \"meaning\": \"当前有效退货总金额，单位分（放大100倍存储）\"}, {\"name\": \"status\", \"index\": 16, \"meaning\": \"单据状态：DRAFT, SUBMITTED, APPROVED, PARTIAL_EXECUTED, COMPLETED, CANCELLED等\"}, {\"name\": \"status_reason\", \"index\": 17, \"meaning\": \"最近一次审核退回或取消原因\"}, {\"name\": \"submitted_at\", \"index\": 18, \"meaning\": \"提交时间\"}, {\"name\": \"approved_at\", \"index\": 19, \"meaning\": \"审核通过时间\"}, {\"name\": \"create_time\", \"index\": 20, \"meaning\": \"创建时间\"}, {\"name\": \"deleted\", \"index\": 21, \"meaning\": \"逻辑删除标记：0正常，1删除（查询已过滤为0）\"}], \"content\": \"统一退货单主表（return_order）在2025-11-23至2026-11-22期间创建的全部有效记录，包含所有退货类型、状态、仓库及供应商/客户，用于口径核对与维度汇总。\", \"limitations\": \"\"}',NULL);
INSERT INTO `ai_dataset` (`dataset_id`, `sql_run_id`, `attempt`, `ready_run_id`, `user_id`, `conversation_id`, `description`, `source_sql`, `columns_json`, `row_count`, `completed`, `storage_file`, `status`, `expires_at`, `created_at`, `data_description_json`, `truncation_reason`) VALUES ('ds_38b263873f7d4950af19f9fa51ae70cb','sqlrun_ecfae20f11fc438b889ed30157795e3c',1,'sqlrun_ecfae20f11fc438b889ed30157795e3c',1900000000000000001,2123852411582849025,'查询库存流水凭证表 stock_bill 中，业务时间覆盖 2026-06-01 至 2026-11-21 的全部凭证记录（含凭证ID、流水号、类型、确认时间、创建时间、仓库），用于按月统计出入库数量','SELECT id AS bill_id, bill_no, bill_type, confirmed_at, create_time, warehouse_name FROM stock_bill WHERE confirmed_at >= \'2026-06-01 00:00:00\' AND confirmed_at < \'2026-11-22 00:00:00\'','[{\"name\":\"id\",\"label\":\"bill_id\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"bill_no\",\"label\":\"bill_no\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"bill_type\",\"label\":\"bill_type\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"confirmed_at\",\"label\":\"confirmed_at\",\"jdbcType\":93,\"typeName\":\"DATETIME\",\"nullable\":false},{\"name\":\"create_time\",\"label\":\"create_time\",\"jdbcType\":93,\"typeName\":\"DATETIME\",\"nullable\":false},{\"name\":\"warehouse_name\",\"label\":\"warehouse_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false}]',1420,1,'ds_38b263873f7d4950af19f9fa51ae70cb.jsonl','READY','2026-12-05 00:00:00.000000','2026-11-20 18:54:33.538365','{\"grain\": \"每张库存流水凭证一行\", \"fields\": [{\"name\": \"bill_id\", \"index\": 0, \"meaning\": \"库存流水凭证ID\"}, {\"name\": \"bill_no\", \"index\": 1, \"meaning\": \"库存流水号\"}, {\"name\": \"bill_type\", \"index\": 2, \"meaning\": \"凭证类型（如PURCHASE_IN, SALES_OUT等）\"}, {\"name\": \"confirmed_at\", \"index\": 3, \"meaning\": \"确认时间（业务发生时间）\"}, {\"name\": \"create_time\", \"index\": 4, \"meaning\": \"创建时间\"}, {\"name\": \"warehouse_name\", \"index\": 5, \"meaning\": \"仓库名称快照\"}], \"content\": \"库存流水凭证主表记录，业务时间（确认时间）覆盖2026-06-01至2026-11-21\", \"limitations\": \"\"}',NULL);
INSERT INTO `ai_dataset` (`dataset_id`, `sql_run_id`, `attempt`, `ready_run_id`, `user_id`, `conversation_id`, `description`, `source_sql`, `columns_json`, `row_count`, `completed`, `storage_file`, `status`, `expires_at`, `created_at`, `data_description_json`, `truncation_reason`) VALUES ('ds_3ecccc691f874ceeb088af390301f5d6','sqlrun_886eaa13595f4ff58ace3c7693ff62ca',2,'sqlrun_886eaa13595f4ff58ace3c7693ff62ca',1900000000000000001,2124423434279604226,'查询产品编码 P000005（果沁 碳酸饮料礼盒装 330ml×24罐）自2026-05-26至2026-11-22（近180天）的销售出库明细，按月汇总：出库数量、出库金额、按金额除数量的加权成交均价，用于估计基线销量与基线成交价','SELECT DATE_FORMAT(ob.confirmed_at, \'%Y-%m\') AS month, SUM(obi.current_qty) / 100.0 AS outbound_quantity, SUM(obi.current_qty * soi.unit_price) / 10000.0 AS outbound_amount, CASE WHEN SUM(obi.current_qty) = 0 THEN NULL ELSE (SUM(obi.current_qty * soi.unit_price) / 10000.0) / (SUM(obi.current_qty) / 100.0) END AS weighted_avg_price FROM outbound_bill ob JOIN outbound_bill_item obi ON ob.id = obi.outbound_bill_id JOIN sales_order so ON ob.source_type = \'SALES_ORDER\' AND ob.source_id = so.id JOIN sales_order_item soi ON obi.source_item_id = soi.id WHERE ob.deleted = 0 AND ob.outbound_type = \'SALES_OUT\' AND ob.status = \'CONFIRMED\' AND ob.confirmed_at >= \'2026-05-26 00:00:00\' AND ob.confirmed_at <= \'2026-11-22 23:59:59\' AND obi.product_code = \'P000005\' AND so.deleted = 0 GROUP BY DATE_FORMAT(ob.confirmed_at, \'%Y-%m\') ORDER BY month','[{\"name\":\"month\",\"label\":\"month\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":true},{\"name\":\"outbound_quantity\",\"label\":\"outbound_quantity\",\"jdbcType\":3,\"typeName\":\"DECIMAL\",\"nullable\":true},{\"name\":\"outbound_amount\",\"label\":\"outbound_amount\",\"jdbcType\":3,\"typeName\":\"DECIMAL\",\"nullable\":true},{\"name\":\"weighted_avg_price\",\"label\":\"weighted_avg_price\",\"jdbcType\":3,\"typeName\":\"DECIMAL\",\"nullable\":true}]',5,1,'ds_3ecccc691f874ceeb088af390301f5d6.jsonl','READY','2026-12-07 00:00:00.000000','2026-11-22 08:43:39.897070','{\"grain\": \"每个月份一行\", \"fields\": [{\"name\": \"month\", \"index\": 0, \"meaning\": \"月份，格式为 YYYY-MM\"}, {\"name\": \"outbound_quantity\", \"index\": 1, \"meaning\": \"当月销售出库总数量（业务单位：件/盒等，根据产品定义），由出库明细数量除以100还原得到\"}, {\"name\": \"outbound_amount\", \"index\": 2, \"meaning\": \"当月销售出库总金额（单位：元），由出库明细数量乘以销售单价后除以10000还原得到（因数量和单价均放大100倍存储）\"}, {\"name\": \"weighted_avg_price\", \"index\": 3, \"meaning\": \"当月加权平均成交单价（单位：元/件），计算公式为 总金额 / 总数量\"}], \"content\": \"产品编码 P000005（果沁 碳酸饮料礼盒装 330ml×24罐）自2026年5月26日至2026年11月22日的月度销售出库汇总数据，包括出库数量、出库金额和加权平均成交价。\", \"limitations\": \"\"}',NULL);
INSERT INTO `ai_dataset` (`dataset_id`, `sql_run_id`, `attempt`, `ready_run_id`, `user_id`, `conversation_id`, `description`, `source_sql`, `columns_json`, `row_count`, `completed`, `storage_file`, `status`, `expires_at`, `created_at`, `data_description_json`, `truncation_reason`) VALUES ('ds_42305c4efbdc4054848c6af7b7d686ec','sqlrun_d6a488a3d06145f3b00fef9a29496935',2,'sqlrun_d6a488a3d06145f3b00fef9a29496935',1900000000000000001,2124210189346299906,'统计仓库编码 DEMOW01 的已确认库存流水凭证，按 bill_type（PURCHASE_IN、SALES_OUT、PURCHASE_RETURN、SALES_RETURN、ADJUST_IN、ADJUST_OUT）分组，返回单据数、明细行数、最早与最晚确认时间、变动数量合计（100倍整数），用于确认可用的出库历史时间范围','SELECT sb.bill_type AS bill_type, COUNT(DISTINCT sb.id) AS bill_count, COUNT(sbi.id) AS line_count, MIN(sb.confirmed_at) AS min_confirmed_at, MAX(sb.confirmed_at) AS max_confirmed_at, SUM(sbi.change_qty) AS sum_change_qty FROM stock_bill sb JOIN warehouse w ON sb.warehouse_id = w.id JOIN stock_bill_item sbi ON sbi.bill_id = sb.id WHERE w.warehouse_code = \'DEMOW01\' AND w.deleted = 0 GROUP BY sb.bill_type','[{\"name\":\"bill_type\",\"label\":\"bill_type\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"bill_count\",\"label\":\"bill_count\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"line_count\",\"label\":\"line_count\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"min_confirmed_at\",\"label\":\"min_confirmed_at\",\"jdbcType\":93,\"typeName\":\"DATETIME\",\"nullable\":true},{\"name\":\"max_confirmed_at\",\"label\":\"max_confirmed_at\",\"jdbcType\":93,\"typeName\":\"DATETIME\",\"nullable\":true},{\"name\":\"sum_change_qty\",\"label\":\"sum_change_qty\",\"jdbcType\":3,\"typeName\":\"DECIMAL\",\"nullable\":true}]',2,1,'ds_42305c4efbdc4054848c6af7b7d686ec.jsonl','READY','2026-12-06 00:00:00.000000','2026-11-21 18:38:54.910260','{\"grain\": \"每个 bill_type 一行\", \"fields\": [{\"name\": \"bill_type\", \"index\": 0, \"meaning\": \"单据类型 (bill_type)\"}, {\"name\": \"bill_count\", \"index\": 1, \"meaning\": \"单据数量 (bill_count)\"}, {\"name\": \"line_count\", \"index\": 2, \"meaning\": \"明细行数 (line_count)\"}, {\"name\": \"min_confirmed_at\", \"index\": 3, \"meaning\": \"最早确认时间 (min_confirmed_at)\"}, {\"name\": \"max_confirmed_at\", \"index\": 4, \"meaning\": \"最晚确认时间 (max_confirmed_at)\"}, {\"name\": \"sum_change_qty\", \"index\": 5, \"meaning\": \"变动数量合计 (sum_change_qty)，存储值为业务数量的100倍\"}], \"content\": \"仓库编码 DEMOW01 的已确认库存流水凭证统计，按单据类型（PURCHASE_IN, SALES_OUT）分组。包含单据数、明细行数、最早与最晚确认时间以及变动数量合计（×100整数）。\", \"limitations\": \"\"}',NULL);
INSERT INTO `ai_dataset` (`dataset_id`, `sql_run_id`, `attempt`, `ready_run_id`, `user_id`, `conversation_id`, `description`, `source_sql`, `columns_json`, `row_count`, `completed`, `storage_file`, `status`, `expires_at`, `created_at`, `data_description_json`, `truncation_reason`) VALUES ('ds_450c1ec3fa8b477d819fabe140cd3b70','sqlrun_342f5dff507b4f11a89da2b25e84f61e',1,'sqlrun_342f5dff507b4f11a89da2b25e84f61e',1900000000000000001,2124424075508994050,'查询产品 P000005（果沁 碳酸饮料礼盒装）的全部采购订单明细（订单未删除，覆盖所有状态包括 DRAFT/SUBMITTED/APPROVED/PARTIAL_INBOUND/INBOUND_DONE/CANCELLED），返回采购单号、供应商、目标仓库、订单状态、明细采购数量、已入库数量、剩余未入库数量、单价、预计到货日期、审核时间、完全入库时间','SELECT po.purchase_no AS purchase_no, po.supplier_id AS supplier_id, po.supplier_name AS supplier_name, po.warehouse_id AS warehouse_id, po.warehouse_name AS warehouse_name, po.status AS status, poi.quantity / 100.0 AS order_qty, poi.inbound_qty / 100.0 AS inbound_qty, (poi.quantity - poi.inbound_qty) / 100.0 AS remaining_qty, poi.unit_price / 100.0 AS unit_price, po.expected_arrival_date AS expected_arrival_date, po.approved_at AS approved_at, po.fully_received_at AS fully_received_at FROM purchase_order po JOIN purchase_order_item poi ON po.id = poi.purchase_order_id WHERE po.deleted = 0 AND poi.product_code = \'P000005\'','[{\"name\":\"purchase_no\",\"label\":\"purchase_no\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"supplier_id\",\"label\":\"supplier_id\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"supplier_name\",\"label\":\"supplier_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"warehouse_id\",\"label\":\"warehouse_id\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"warehouse_name\",\"label\":\"warehouse_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"status\",\"label\":\"status\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"order_qty\",\"label\":\"order_qty\",\"jdbcType\":3,\"typeName\":\"DECIMAL\",\"nullable\":true},{\"name\":\"inbound_qty\",\"label\":\"inbound_qty\",\"jdbcType\":3,\"typeName\":\"DECIMAL\",\"nullable\":true},{\"name\":\"remaining_qty\",\"label\":\"remaining_qty\",\"jdbcType\":3,\"typeName\":\"DECIMAL\",\"nullable\":true},{\"name\":\"unit_price\",\"label\":\"unit_price\",\"jdbcType\":3,\"typeName\":\"DECIMAL\",\"nullable\":true},{\"name\":\"expected_arrival_date\",\"label\":\"expected_arrival_date\",\"jdbcType\":91,\"typeName\":\"DATE\",\"nullable\":true},{\"name\":\"approved_at\",\"label\":\"approved_at\",\"jdbcType\":93,\"typeName\":\"DATETIME\",\"nullable\":true},{\"name\":\"fully_received_at\",\"label\":\"fully_received_at\",\"jdbcType\":93,\"typeName\":\"DATETIME\",\"nullable\":true}]',9,1,'ds_450c1ec3fa8b477d819fabe140cd3b70.jsonl','READY','2026-12-07 00:00:00.000000','2026-11-22 08:47:28.527193','{\"grain\": \"每笔采购订单中的一条产品明细记录\", \"fields\": [{\"name\": \"purchase_no\", \"index\": 0, \"meaning\": \"采购单号\"}, {\"name\": \"supplier_id\", \"index\": 1, \"meaning\": \"供应商ID\"}, {\"name\": \"supplier_name\", \"index\": 2, \"meaning\": \"供应商名称\"}, {\"name\": \"warehouse_id\", \"index\": 3, \"meaning\": \"目标入库仓库ID\"}, {\"name\": \"warehouse_name\", \"index\": 4, \"meaning\": \"目标入库仓库名称\"}, {\"name\": \"status\", \"index\": 5, \"meaning\": \"采购订单状态\"}, {\"name\": \"order_qty\", \"index\": 6, \"meaning\": \"订单采购数量（业务单位，已除以100）\"}, {\"name\": \"inbound_qty\", \"index\": 7, \"meaning\": \"已入库数量（业务单位，已除以100）\"}, {\"name\": \"remaining_qty\", \"index\": 8, \"meaning\": \"剩余未入库数量（业务单位，计算得出：采购数量-已入库数量）\"}, {\"name\": \"unit_price\", \"index\": 9, \"meaning\": \"采购单价（元，已除以100）\"}, {\"name\": \"expected_arrival_date\", \"index\": 10, \"meaning\": \"预计到货日期\"}, {\"name\": \"approved_at\", \"index\": 11, \"meaning\": \"审核通过时间\"}, {\"name\": \"fully_received_at\", \"index\": 12, \"meaning\": \"完全入库时间\"}], \"content\": \"产品P000005（果沁 碳酸饮料礼盒装）的所有有效采购订单明细，包括各状态下的订单信息、数量、价格及时间节点。\", \"limitations\": \"\"}',NULL);
INSERT INTO `ai_dataset` (`dataset_id`, `sql_run_id`, `attempt`, `ready_run_id`, `user_id`, `conversation_id`, `description`, `source_sql`, `columns_json`, `row_count`, `completed`, `storage_file`, `status`, `expires_at`, `created_at`, `data_description_json`, `truncation_reason`) VALUES ('ds_47ae2e5cc7244ff09b78289057d2de3c','sqlrun_e2b4d235bcdf48fd90d444b18aea44a8',1,'sqlrun_e2b4d235bcdf48fd90d444b18aea44a8',1900000000000000001,2124421893103570946,'查询包含产品ID 8400000000005000173（P000173）明细的全部入库单（不限状态与类型，deleted=0），逐行返回：入库单ID、入库单号、入库类型inbound_type、来源类型source_type、来源单据号source_no、来源对象名称source_party_name、仓库名称、单据状态、录入方式entry_mode、确认时间confirmed_at、手工补录或调整原因manual_reason、该产品本次入库数量current_qty（100倍）。用于核实1405袋库存的来源构成与696袋手工调整入库的原因。','SELECT ib.id AS inbound_bill_id, ib.inbound_no, ib.inbound_type, ib.source_type, ib.source_no, ib.source_party_name, ib.warehouse_name, ib.status, ib.entry_mode, ib.confirmed_at, ib.manual_reason, ibi.current_qty FROM inbound_bill ib JOIN inbound_bill_item ibi ON ib.id = ibi.inbound_bill_id WHERE ib.deleted = 0 AND ibi.product_id = 8400000000005000173','[{\"name\":\"id\",\"label\":\"inbound_bill_id\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"inbound_no\",\"label\":\"inbound_no\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"inbound_type\",\"label\":\"inbound_type\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"source_type\",\"label\":\"source_type\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"source_no\",\"label\":\"source_no\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"source_party_name\",\"label\":\"source_party_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"warehouse_name\",\"label\":\"warehouse_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"status\",\"label\":\"status\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"entry_mode\",\"label\":\"entry_mode\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"confirmed_at\",\"label\":\"confirmed_at\",\"jdbcType\":93,\"typeName\":\"DATETIME\",\"nullable\":true},{\"name\":\"manual_reason\",\"label\":\"manual_reason\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"current_qty\",\"label\":\"current_qty\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false}]',2,1,'ds_47ae2e5cc7244ff09b78289057d2de3c.jsonl','READY','2026-12-07 00:00:00.000000','2026-11-22 08:40:58.304174','{\"grain\": \"每张入库单中该特定产品的一行明细\", \"fields\": [{\"name\": \"inbound_bill_id\", \"index\": 0, \"meaning\": \"入库单主表ID\"}, {\"name\": \"inbound_no\", \"index\": 1, \"meaning\": \"入库单号\"}, {\"name\": \"inbound_type\", \"index\": 2, \"meaning\": \"入库类型 (如 PURCHASE_IN, ADJUST_IN)\"}, {\"name\": \"source_type\", \"index\": 3, \"meaning\": \"来源类型 (如 PURCHASE_ORDER, STOCK_ADJUST)\"}, {\"name\": \"source_no\", \"index\": 4, \"meaning\": \"来源单据号\"}, {\"name\": \"source_party_name\", \"index\": 5, \"meaning\": \"来源对象名称快照 (供应商/客户/仓库)\"}, {\"name\": \"warehouse_name\", \"index\": 6, \"meaning\": \"仓库名称快照\"}, {\"name\": \"status\", \"index\": 7, \"meaning\": \"单据状态 (如 CONFIRMED)\"}, {\"name\": \"entry_mode\", \"index\": 8, \"meaning\": \"录入方式 (如 SOURCE_GENERATED, MANUAL_ADJUSTMENT)\"}, {\"name\": \"confirmed_at\", \"index\": 9, \"meaning\": \"确认时间\"}, {\"name\": \"manual_reason\", \"index\": 10, \"meaning\": \"手工补录或调整原因\"}, {\"name\": \"current_qty\", \"index\": 11, \"meaning\": \"本次入库数量 (存储值为实际数量的100倍，例如70900表示709.00)\"}], \"content\": \"产品ID为8400000000005000173的所有未删除入库单明细记录，包括采购入库和库存调整入库。\", \"limitations\": \"\"}',NULL);
INSERT INTO `ai_dataset` (`dataset_id`, `sql_run_id`, `attempt`, `ready_run_id`, `user_id`, `conversation_id`, `description`, `source_sql`, `columns_json`, `row_count`, `completed`, `storage_file`, `status`, `expires_at`, `created_at`, `data_description_json`, `truncation_reason`) VALUES ('ds_4a11c76588d44a8b9187933aa5258b28','sqlrun_f9940f5a352543b58cf0616e9c790831',1,'sqlrun_f9940f5a352543b58cf0616e9c790831',1900000000000000001,2124210189346299906,'查询仓库编码 DEMOW01 的全部已确认采购入库流水明细（stock_bill.bill_type=PURCHASE_IN 对应的 stock_bill_item 行），返回流水号、确认时间、产品ID、产品编码、产品名称、单位、变动数量 change_qty（100倍整数，入库为正值）','SELECT sb.bill_no AS bill_no, sb.confirmed_at AS confirmed_at, sbi.product_id AS product_id, sbi.product_code AS product_code, sbi.product_name AS product_name, sbi.unit_name AS unit_name, sbi.change_qty AS change_qty FROM stock_bill sb JOIN stock_bill_item sbi ON sb.id = sbi.bill_id JOIN warehouse w ON sb.warehouse_id = w.id WHERE w.warehouse_code = \'DEMOW01\' AND w.deleted = 0 AND sb.bill_type = \'PURCHASE_IN\'','[{\"name\":\"bill_no\",\"label\":\"bill_no\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"confirmed_at\",\"label\":\"confirmed_at\",\"jdbcType\":93,\"typeName\":\"DATETIME\",\"nullable\":false},{\"name\":\"product_id\",\"label\":\"product_id\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"product_code\",\"label\":\"product_code\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"product_name\",\"label\":\"product_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"unit_name\",\"label\":\"unit_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"change_qty\",\"label\":\"change_qty\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false}]',312,1,'ds_4a11c76588d44a8b9187933aa5258b28.jsonl','READY','2026-12-06 00:00:00.000000','2026-11-21 18:39:51.001403','{\"grain\": \"每条库存流水明细一行\", \"fields\": [{\"name\": \"bill_no\", \"index\": 0, \"meaning\": \"库存流水号\"}, {\"name\": \"confirmed_at\", \"index\": 1, \"meaning\": \"入库确认时间\"}, {\"name\": \"product_id\", \"index\": 2, \"meaning\": \"产品ID\"}, {\"name\": \"product_code\", \"index\": 3, \"meaning\": \"产品编码\"}, {\"name\": \"product_name\", \"index\": 4, \"meaning\": \"产品名称快照\"}, {\"name\": \"unit_name\", \"index\": 5, \"meaning\": \"单位名称快照\"}, {\"name\": \"change_qty\", \"index\": 6, \"meaning\": \"库存变动数量（×100整数，入库为正值）\"}], \"content\": \"仓库 DEMOW01 的已确认采购入库库存流水明细\", \"limitations\": \"\"}',NULL);
INSERT INTO `ai_dataset` (`dataset_id`, `sql_run_id`, `attempt`, `ready_run_id`, `user_id`, `conversation_id`, `description`, `source_sql`, `columns_json`, `row_count`, `completed`, `storage_file`, `status`, `expires_at`, `created_at`, `data_description_json`, `truncation_reason`) VALUES ('ds_53c1dd99ff8448d0998cbf9e7dfb4e9a','sqlrun_006ae7a4991d4201af79a022b1f5fa02',1,'sqlrun_006ae7a4991d4201af79a022b1f5fa02',1900000000000000001,2124210189346299906,'查询仓库编码 DEMOW01（演示区域仓 01）的全部库存余额记录，返回仓库编码、仓库名称、产品ID、产品编码、产品名称、单位、账面库存数量 stock_qty（100倍整数）、锁定数量 locked_qty（100倍整数）、更新时间','SELECT ws.warehouse_code AS warehouse_code, ws.warehouse_name AS warehouse_name, ws.product_id AS product_id, ws.product_code AS product_code, ws.product_name AS product_name, ws.unit_name AS unit_name, ws.stock_qty AS stock_qty, ws.locked_qty AS locked_qty, ws.update_time AS update_time FROM warehouse_stock ws INNER JOIN warehouse w ON ws.warehouse_id = w.id WHERE w.warehouse_code = \'DEMOW01\' AND w.deleted = 0','[{\"name\":\"warehouse_code\",\"label\":\"warehouse_code\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"warehouse_name\",\"label\":\"warehouse_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"product_id\",\"label\":\"product_id\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"product_code\",\"label\":\"product_code\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"product_name\",\"label\":\"product_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"unit_name\",\"label\":\"unit_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"stock_qty\",\"label\":\"stock_qty\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"locked_qty\",\"label\":\"locked_qty\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"update_time\",\"label\":\"update_time\",\"jdbcType\":93,\"typeName\":\"DATETIME\",\"nullable\":false}]',312,1,'ds_53c1dd99ff8448d0998cbf9e7dfb4e9a.jsonl','READY','2026-12-06 00:00:00.000000','2026-11-21 18:38:23.457859','{\"grain\": \"每行代表一个特定产品在指定仓库（DEMOW01）中的唯一库存记录。\", \"fields\": [{\"name\": \"warehouse_code\", \"index\": 0, \"meaning\": \"仓库编码\"}, {\"name\": \"warehouse_name\", \"index\": 1, \"meaning\": \"仓库名称\"}, {\"name\": \"product_id\", \"index\": 2, \"meaning\": \"产品ID\"}, {\"name\": \"product_code\", \"index\": 3, \"meaning\": \"产品编码\"}, {\"name\": \"product_name\", \"index\": 4, \"meaning\": \"产品名称\"}, {\"name\": \"unit_name\", \"index\": 5, \"meaning\": \"单位名称\"}, {\"name\": \"stock_qty\", \"index\": 6, \"meaning\": \"账面库存数量（存储值为实际业务数量的100倍整数）\"}, {\"name\": \"locked_qty\", \"index\": 7, \"meaning\": \"锁定库存数量（存储值为实际业务数量的100倍整数）\"}, {\"name\": \"update_time\", \"index\": 8, \"meaning\": \"库存记录最后更新时间\"}], \"content\": \"仓库 DEMOW01 下所有产品的当前库存余额快照，包括账面库存和锁定库存。\", \"limitations\": \"stock_qty 和 locked_qty 为 ×100 整数存储，计算可用库存或与安全库存对比时需除以 100 还原为业务数量。\"}',NULL);
INSERT INTO `ai_dataset` (`dataset_id`, `sql_run_id`, `attempt`, `ready_run_id`, `user_id`, `conversation_id`, `description`, `source_sql`, `columns_json`, `row_count`, `completed`, `storage_file`, `status`, `expires_at`, `created_at`, `data_description_json`, `truncation_reason`) VALUES ('ds_550c51342d614317bc90dbac2d70f2e5','sqlrun_df6d721ddb214f29a45aa37dddfac25d',1,'sqlrun_df6d721ddb214f29a45aa37dddfac25d',1900000000000000001,2124465547335741442,'统计 warehouse_stock 当前库存规模（全部仓库、全部商品，不过滤），按仓库分组输出：商品记录数、总库存量（sum(stock_qty)/100）、总锁定库存量（sum(locked_qty)/100）。用于计算近半年退货数量相对当前库存的占比，评估退货对库存的实际规模影响。','SELECT warehouse_name AS warehouse_name, COUNT(product_id) AS product_count, SUM(stock_qty) / 100.0 AS stock_qty, SUM(locked_qty) / 100.0 AS locked_qty FROM warehouse_stock GROUP BY warehouse_name','[{\"name\":\"warehouse_name\",\"label\":\"warehouse_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"product_count\",\"label\":\"product_count\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"stock_qty\",\"label\":\"stock_qty\",\"jdbcType\":3,\"typeName\":\"DECIMAL\",\"nullable\":true},{\"name\":\"locked_qty\",\"label\":\"locked_qty\",\"jdbcType\":3,\"typeName\":\"DECIMAL\",\"nullable\":true}]',5,1,'ds_550c51342d614317bc90dbac2d70f2e5.jsonl','READY','2026-12-07 00:00:00.000000','2026-11-22 11:35:34.584322','{\"grain\": \"每个仓库一行\", \"fields\": [{\"name\": \"warehouse_name\", \"index\": 0, \"meaning\": \"仓库名称\"}, {\"name\": \"product_count\", \"index\": 1, \"meaning\": \"该仓库下的商品库存记录数（SKU 数量）\"}, {\"name\": \"stock_qty\", \"index\": 2, \"meaning\": \"该仓库所有商品的总库存数量（原始值除以100后的业务数值）\"}, {\"name\": \"locked_qty\", \"index\": 3, \"meaning\": \"该仓库所有商品的总锁定库存数量（原始值除以100后的业务数值）\"}], \"content\": \"统计 warehouse_stock 表中全部仓库、全部商品的当前库存规模，按仓库名称分组。包含每个仓库的商品记录数（即 SKU 行数）、总库存量（已还原为业务单位）和总锁定库存量（已还原为业务单位）。\", \"limitations\": \"\"}',NULL);
INSERT INTO `ai_dataset` (`dataset_id`, `sql_run_id`, `attempt`, `ready_run_id`, `user_id`, `conversation_id`, `description`, `source_sql`, `columns_json`, `row_count`, `completed`, `storage_file`, `status`, `expires_at`, `created_at`, `data_description_json`, `truncation_reason`) VALUES ('ds_55b21af7d93b40ad9cfee06eb568a5e2','sqlrun_a452613fc4684435b28f2f64fc86d135',1,'sqlrun_a452613fc4684435b28f2f64fc86d135',1900000000000000001,2124465547335741442,'按确认月份聚合统计 inbound_bill 中 inbound_type=PURCHASE_IN、status=CONFIRMED、deleted=0 的记录，confirmed_at 在 2025-11-23 至 2026-11-22（含端点），全部仓库。每月输出：入库单数、入库数量合计（current_qty，100倍口径，请同时给出除100后的业务数量）、入库金额合计（由 inbound_bill_item.current_qty 与 unit_price 计算，单位元）。用于计算近半年与上一半年的采购退货率分母及月度趋势。','SELECT DATE_FORMAT(ib.confirmed_at, \'%Y-%m\') AS `month`, COUNT(DISTINCT ib.id) AS bill_count, SUM(ibi.current_qty) / 100.0 AS inbound_qty, SUM(ibi.current_qty * ibi.unit_price) / 10000.0 AS inbound_amount_yuan FROM inbound_bill ib JOIN inbound_bill_item ibi ON ib.id = ibi.inbound_bill_id WHERE ib.inbound_type = \'PURCHASE_IN\' AND ib.status = \'CONFIRMED\' AND ib.deleted = 0 AND ib.confirmed_at >= \'2025-11-23 00:00:00\' AND ib.confirmed_at <= \'2026-11-22 23:59:59\' GROUP BY DATE_FORMAT(ib.confirmed_at, \'%Y-%m\')','[{\"name\":\"month\",\"label\":\"month\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":true},{\"name\":\"bill_count\",\"label\":\"bill_count\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"inbound_qty\",\"label\":\"inbound_qty\",\"jdbcType\":3,\"typeName\":\"DECIMAL\",\"nullable\":true},{\"name\":\"inbound_amount_yuan\",\"label\":\"inbound_amount_yuan\",\"jdbcType\":3,\"typeName\":\"DECIMAL\",\"nullable\":true}]',13,1,'ds_55b21af7d93b40ad9cfee06eb568a5e2.jsonl','READY','2026-12-07 00:00:00.000000','2026-11-22 11:31:50.428833','{\"grain\": \"每个确认月份一行\", \"fields\": [{\"name\": \"month\", \"index\": 0, \"meaning\": \"确认月份，格式YYYY-MM\"}, {\"name\": \"bill_count\", \"index\": 1, \"meaning\": \"当月确认的采购入库单数量\"}, {\"name\": \"inbound_qty\", \"index\": 2, \"meaning\": \"当月入库总数量（业务口径，已除以100）\"}, {\"name\": \"inbound_amount_yuan\", \"index\": 3, \"meaning\": \"当月入库总金额（单位：元，由明细数量*单价/10000计算得出）\"}], \"content\": \"近一年（2025-11-23至2026-11-22）按月统计的采购入库（PURCHASE_IN, CONFIRMED）单据数量、入库总数量及总金额。\", \"limitations\": \"\"}',NULL);
INSERT INTO `ai_dataset` (`dataset_id`, `sql_run_id`, `attempt`, `ready_run_id`, `user_id`, `conversation_id`, `description`, `source_sql`, `columns_json`, `row_count`, `completed`, `storage_file`, `status`, `expires_at`, `created_at`, `data_description_json`, `truncation_reason`) VALUES ('ds_56056028842f4a5db296a1296af739be','sqlrun_3db3efe8e8574b8c95d635d46e158354',1,'sqlrun_3db3efe8e8574b8c95d635d46e158354',1900000000000000001,2124210189346299906,'查询演示区域仓 01（DEMOW01）下所有未删除且未取消采购订单中存在未到货数量的明细行（已入库数量小于采购数量），列出采购单号、产品、采购数量、已入库数量、未到货数量和预计到货日期，用于核定是否存在晚到的在途采购批次','SELECT po.purchase_no AS purchase_order_no, poi.product_code AS product_code, poi.product_name AS product_name, poi.unit_name AS unit_name, poi.quantity / 100.0 AS purchase_qty, poi.inbound_qty / 100.0 AS inbound_qty, (poi.quantity - poi.inbound_qty) / 100.0 AS pending_arrival_qty, po.expected_arrival_date AS expected_arrival_date FROM purchase_order po JOIN purchase_order_item poi ON po.id = poi.purchase_order_id JOIN warehouse w ON po.warehouse_id = w.id WHERE w.warehouse_code = \'DEMOW01\' AND w.deleted = 0 AND po.deleted = 0 AND po.status NOT IN (\'DRAFT\', \'CANCELLED\') AND poi.quantity > poi.inbound_qty','[{\"name\":\"purchase_no\",\"label\":\"purchase_order_no\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"product_code\",\"label\":\"product_code\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"product_name\",\"label\":\"product_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"unit_name\",\"label\":\"unit_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"purchase_qty\",\"label\":\"purchase_qty\",\"jdbcType\":3,\"typeName\":\"DECIMAL\",\"nullable\":true},{\"name\":\"inbound_qty\",\"label\":\"inbound_qty\",\"jdbcType\":3,\"typeName\":\"DECIMAL\",\"nullable\":true},{\"name\":\"pending_arrival_qty\",\"label\":\"pending_arrival_qty\",\"jdbcType\":3,\"typeName\":\"DECIMAL\",\"nullable\":true},{\"name\":\"expected_arrival_date\",\"label\":\"expected_arrival_date\",\"jdbcType\":91,\"typeName\":\"DATE\",\"nullable\":true}]',0,1,'ds_56056028842f4a5db296a1296af739be.jsonl','READY','2026-12-06 00:00:00.000000','2026-11-21 18:37:52.592897','{\"grain\": \"每条采购订单明细一行\", \"fields\": [{\"name\": \"purchase_order_no\", \"index\": 0, \"meaning\": \"采购单号\"}, {\"name\": \"product_code\", \"index\": 1, \"meaning\": \"产品编码\"}, {\"name\": \"product_name\", \"index\": 2, \"meaning\": \"产品名称\"}, {\"name\": \"unit_name\", \"index\": 3, \"meaning\": \"单位\"}, {\"name\": \"purchase_qty\", \"index\": 4, \"meaning\": \"采购数量（业务数值，已除以100还原）\"}, {\"name\": \"inbound_qty\", \"index\": 5, \"meaning\": \"已入库数量（业务数值，已除以100还原）\"}, {\"name\": \"pending_arrival_qty\", \"index\": 6, \"meaning\": \"未到货数量（业务数值，已除以100还原，等于采购数量减已入库数量）\"}, {\"name\": \"expected_arrival_date\", \"index\": 7, \"meaning\": \"预计到货日期\"}], \"content\": \"演示区域仓 DEMOW01 中状态非草稿/取消、且存在未到货数量（已入库量 < 采购量）的采购订单明细列表。用于核定是否存在晚到的在途采购批次。\", \"limitations\": \"\"}',NULL);
INSERT INTO `ai_dataset` (`dataset_id`, `sql_run_id`, `attempt`, `ready_run_id`, `user_id`, `conversation_id`, `description`, `source_sql`, `columns_json`, `row_count`, `completed`, `storage_file`, `status`, `expires_at`, `created_at`, `data_description_json`, `truncation_reason`) VALUES ('ds_5840b79bb8dd421fa54d6adb4f02a7c9','sqlrun_4effdef83d694c7aa67f696051d9691e',1,'sqlrun_4effdef83d694c7aa67f696051d9691e',1900000000000000001,2124761984778977281,'查询目标仓库 warehouse_id=8400000000004000001（上海浦东中心仓）、产品 product_id=8400000000005001253 的未确认采购入库单明细：入库单主表 inbound_type=PURCHASE_IN、status 为 DRAFT 或 PENDING_CONFIRM、deleted=0，返回入库单号、单据状态、来源单据号、本次入库数量 current_qty（100倍整数）、计划数量 plan_qty（100倍整数）、创建时间，用于避免与本次采购重复','SELECT ib.inbound_no AS inbound_no, ib.status AS status, ib.source_no AS source_no, ibi.current_qty AS current_qty, ibi.plan_qty AS plan_qty, ibi.unit_price AS unit_price, ib.create_time AS create_time FROM inbound_bill ib JOIN inbound_bill_item ibi ON ib.id = ibi.inbound_bill_id WHERE ib.warehouse_id = 8400000000004000001 AND ib.inbound_type = \'PURCHASE_IN\' AND ib.status IN (\'DRAFT\', \'PENDING_CONFIRM\') AND ib.deleted = 0 AND ibi.product_id = 8400000000005001253','[{\"name\":\"inbound_no\",\"label\":\"inbound_no\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"status\",\"label\":\"status\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"source_no\",\"label\":\"source_no\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"current_qty\",\"label\":\"current_qty\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"plan_qty\",\"label\":\"plan_qty\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"unit_price\",\"label\":\"unit_price\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"create_time\",\"label\":\"create_time\",\"jdbcType\":93,\"typeName\":\"DATETIME\",\"nullable\":false}]',0,1,'ds_5840b79bb8dd421fa54d6adb4f02a7c9.jsonl','READY','2026-12-08 00:00:00.000000','2026-11-23 07:10:37.640627','{\"grain\": \"每条未确认入库单明细一行\", \"fields\": [{\"name\": \"inbound_no\", \"index\": 0, \"meaning\": \"入库单号\"}, {\"name\": \"status\", \"index\": 1, \"meaning\": \"单据状态（DRAFT或PENDING_CONFIRM）\"}, {\"name\": \"source_no\", \"index\": 2, \"meaning\": \"来源单据号（通常为采购订单号）\"}, {\"name\": \"current_qty\", \"index\": 3, \"meaning\": \"本次入库数量（100倍整数存储）\"}, {\"name\": \"plan_qty\", \"index\": 4, \"meaning\": \"计划数量（100倍整数存储）\"}, {\"name\": \"unit_price\", \"index\": 5, \"meaning\": \"入库单价快照（单位：分）\"}, {\"name\": \"create_time\", \"index\": 6, \"meaning\": \"创建时间\"}], \"content\": \"目标仓库（上海浦东中心仓）指定产品的未确认采购入库单明细列表\", \"limitations\": \"\"}',NULL);
INSERT INTO `ai_dataset` (`dataset_id`, `sql_run_id`, `attempt`, `ready_run_id`, `user_id`, `conversation_id`, `description`, `source_sql`, `columns_json`, `row_count`, `completed`, `storage_file`, `status`, `expires_at`, `created_at`, `data_description_json`, `truncation_reason`) VALUES ('ds_58d5a2989c4049ef9ac463e5e2b3b921','sqlrun_bface6168eb94038b40916c279a77d99',1,'sqlrun_bface6168eb94038b40916c279a77d99',1900000000000000001,2124210189346299906,'统计未删除入库单按入库类型（PURCHASE_IN、SALES_RETURN、ADJUST_IN）和状态（DRAFT、PENDING_CONFIRM、CONFIRMED、CANCELLED）分组的单据数与预计到货日期区间，用于定位尚未确认到货的采购入库单','SELECT inbound_type AS `入库类型`, status AS `状态`, COUNT(*) AS `单数`, MIN(expected_arrival_date) AS `最早预计到货日期`, MAX(expected_arrival_date) AS `最晚预计到货日期` FROM inbound_bill WHERE deleted = 0 AND inbound_type IN (\'PURCHASE_IN\', \'SALES_RETURN\', \'ADJUST_IN\') AND status IN (\'DRAFT\', \'PENDING_CONFIRM\', \'CONFIRMED\', \'CANCELLED\') GROUP BY inbound_type, status','[{\"name\":\"inbound_type\",\"label\":\"入库类型\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"status\",\"label\":\"状态\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"单数\",\"label\":\"单数\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"最早预计到货日期\",\"label\":\"最早预计到货日期\",\"jdbcType\":91,\"typeName\":\"DATE\",\"nullable\":true},{\"name\":\"最晚预计到货日期\",\"label\":\"最晚预计到货日期\",\"jdbcType\":91,\"typeName\":\"DATE\",\"nullable\":true}]',1,1,'ds_58d5a2989c4049ef9ac463e5e2b3b921.jsonl','READY','2026-12-06 00:00:00.000000','2026-11-21 18:36:23.316786','{\"grain\": \"每个入库类型与状态的组合一行\", \"fields\": [{\"name\": \"入库类型\", \"index\": 0, \"meaning\": \"入库类型\"}, {\"name\": \"状态\", \"index\": 1, \"meaning\": \"单据状态\"}, {\"name\": \"单数\", \"index\": 2, \"meaning\": \"该类型和状态下的单据总数\"}, {\"name\": \"最早预计到货日期\", \"index\": 3, \"meaning\": \"该组内最早预计到货日期（仅采购入库有值，其他类型为空）\"}, {\"name\": \"最晚预计到货日期\", \"index\": 4, \"meaning\": \"该组内最晚预计到货日期（仅采购入库有值，其他类型为空）\"}], \"content\": \"统计未删除的入库单，按入库类型（PURCHASE_IN, SALES_RETURN, ADJUST_IN）和状态（DRAFT, PENDING_CONFIRM, CONFIRMED, CANCELLED）分组，返回每组单据数量及预计到货日期的最小值和最大值。\", \"limitations\": \"\"}',NULL);
INSERT INTO `ai_dataset` (`dataset_id`, `sql_run_id`, `attempt`, `ready_run_id`, `user_id`, `conversation_id`, `description`, `source_sql`, `columns_json`, `row_count`, `completed`, `storage_file`, `status`, `expires_at`, `created_at`, `data_description_json`, `truncation_reason`) VALUES ('ds_5a63562778d542f8af7c443bdd3fd02b','sqlrun_4d5eb8671e914b47821f6bd574a1518d',1,'sqlrun_4d5eb8671e914b47821f6bd574a1518d',1900000000000000001,2124421893103570946,'查询产品ID 8400000000005000173（P000173）的所有供应商供货产品记录，不限状态，逐行返回：供应商ID、供应商名称（关联supplier表）、最近成交单价latest_purchase_price（分）、人工报价quoted_purchase_price（分）、最小起订量、最后采购时间、供货状态。用于确认该产品的供应商来源与最近成交单价。','SELECT sp.supplier_id AS supplier_id, s.supplier_name AS supplier_name, sp.product_id AS product_id, sp.latest_purchase_price AS latest_purchase_price, sp.quoted_purchase_price AS quoted_purchase_price, sp.quoted_price_reason AS quoted_price_reason, sp.quote_valid_until AS quote_valid_until, sp.min_order_qty AS min_order_qty, sp.last_purchase_at AS last_purchase_at, sp.avg_delivery_days AS avg_delivery_days, sp.score_status AS score_status, sp.status AS status FROM supplier_product sp JOIN supplier s ON sp.supplier_id = s.id WHERE sp.deleted = 0 AND s.deleted = 0 AND sp.product_id = 8400000000005000173','[{\"name\":\"supplier_id\",\"label\":\"supplier_id\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"supplier_name\",\"label\":\"supplier_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"product_id\",\"label\":\"product_id\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"latest_purchase_price\",\"label\":\"latest_purchase_price\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":true},{\"name\":\"quoted_purchase_price\",\"label\":\"quoted_purchase_price\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":true},{\"name\":\"quoted_price_reason\",\"label\":\"quoted_price_reason\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"quote_valid_until\",\"label\":\"quote_valid_until\",\"jdbcType\":91,\"typeName\":\"DATE\",\"nullable\":true},{\"name\":\"min_order_qty\",\"label\":\"min_order_qty\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"last_purchase_at\",\"label\":\"last_purchase_at\",\"jdbcType\":93,\"typeName\":\"DATETIME\",\"nullable\":true},{\"name\":\"avg_delivery_days\",\"label\":\"avg_delivery_days\",\"jdbcType\":3,\"typeName\":\"DECIMAL\",\"nullable\":true},{\"name\":\"score_status\",\"label\":\"score_status\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"status\",\"label\":\"status\",\"jdbcType\":-6,\"typeName\":\"TINYINT\",\"nullable\":false}]',2,1,'ds_5a63562778d542f8af7c443bdd3fd02b.jsonl','READY','2026-12-07 00:00:00.000000','2026-11-22 08:40:37.236509','{\"grain\": \"每个供应商对该产品的供货记录一行\", \"fields\": [{\"name\": \"supplier_id\", \"index\": 0, \"meaning\": \"供应商ID\"}, {\"name\": \"supplier_name\", \"index\": 1, \"meaning\": \"供应商名称\"}, {\"name\": \"product_id\", \"index\": 2, \"meaning\": \"产品ID\"}, {\"name\": \"latest_purchase_price\", \"index\": 3, \"meaning\": \"最近成交单价（单位：分）\"}, {\"name\": \"quoted_purchase_price\", \"index\": 4, \"meaning\": \"人工有效报价（单位：分）\"}, {\"name\": \"quoted_price_reason\", \"index\": 5, \"meaning\": \"当前人工有效报价原因\"}, {\"name\": \"quote_valid_until\", \"index\": 6, \"meaning\": \"报价有效截止日\"}, {\"name\": \"min_order_qty\", \"index\": 7, \"meaning\": \"最小起订量（放大100倍保存，例如3000表示30.00）\"}, {\"name\": \"last_purchase_at\", \"index\": 8, \"meaning\": \"当前最近成交价对应的最后一次已确认采购入库时间\"}, {\"name\": \"avg_delivery_days\", \"index\": 9, \"meaning\": \"最近180天完全入库采购单的金额加权平均到货周期（天）\"}, {\"name\": \"score_status\", \"index\": 10, \"meaning\": \"评分状态（NOT_READY表示样本不足，READY表示可参与评分）\"}, {\"name\": \"status\", \"index\": 11, \"meaning\": \"供货状态（1启用，0禁用）\"}], \"content\": \"产品P000173的供应商供货关系明细，用于确认供应商来源及价格信息\", \"limitations\": \"\"}',NULL);
INSERT INTO `ai_dataset` (`dataset_id`, `sql_run_id`, `attempt`, `ready_run_id`, `user_id`, `conversation_id`, `description`, `source_sql`, `columns_json`, `row_count`, `completed`, `storage_file`, `status`, `expires_at`, `created_at`, `data_description_json`, `truncation_reason`) VALUES ('ds_5bb563fb97fa458c9ddbb2ff3f68467c','sqlrun_4c84e885dee94b83ba605c431782af28',1,'sqlrun_4c84e885dee94b83ba605c431782af28',1900000000000000001,2124364502374834178,'查询销售订单明细表 sales_order_item 中产品编码为 P000227（最佳选择 全麦饼干）的全部销售明细，返回所属销售单号、销售数量、已出库数量、单价、金额、创建时间，用于统计该产品的需求规模','SELECT soi.sales_order_id AS sales_order_id, soi.sales_no AS sales_no, soi.product_code AS product_code, soi.quantity / 100.0 AS quantity, soi.outbound_qty / 100.0 AS outbound_qty, soi.unit_price / 100.0 AS unit_price, soi.total_amount / 100.0 AS total_amount, soi.create_time AS create_time FROM sales_order_item soi INNER JOIN sales_order so ON soi.sales_order_id = so.id WHERE soi.product_code = \'P000227\' AND so.deleted = 0','[{\"name\":\"sales_order_id\",\"label\":\"sales_order_id\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"sales_no\",\"label\":\"sales_no\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"product_code\",\"label\":\"product_code\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"quantity\",\"label\":\"quantity\",\"jdbcType\":3,\"typeName\":\"DECIMAL\",\"nullable\":true},{\"name\":\"outbound_qty\",\"label\":\"outbound_qty\",\"jdbcType\":3,\"typeName\":\"DECIMAL\",\"nullable\":true},{\"name\":\"unit_price\",\"label\":\"unit_price\",\"jdbcType\":3,\"typeName\":\"DECIMAL\",\"nullable\":true},{\"name\":\"total_amount\",\"label\":\"total_amount\",\"jdbcType\":3,\"typeName\":\"DECIMAL\",\"nullable\":true},{\"name\":\"create_time\",\"label\":\"create_time\",\"jdbcType\":93,\"typeName\":\"DATETIME\",\"nullable\":false}]',1,1,'ds_5bb563fb97fa458c9ddbb2ff3f68467c.jsonl','READY','2026-12-07 00:00:00.000000','2026-11-22 04:50:51.531916','{\"grain\": \"每条销售订单明细一行\", \"fields\": [{\"name\": \"sales_order_id\", \"index\": 0, \"meaning\": \"所属销售订单ID\"}, {\"name\": \"sales_no\", \"index\": 1, \"meaning\": \"销售单号\"}, {\"name\": \"product_code\", \"index\": 2, \"meaning\": \"产品编码\"}, {\"name\": \"quantity\", \"index\": 3, \"meaning\": \"销售数量（业务单位，已从存储值除以100还原）\"}, {\"name\": \"outbound_qty\", \"index\": 4, \"meaning\": \"已出库数量（业务单位，已从存储值除以100还原）\"}, {\"name\": \"unit_price\", \"index\": 5, \"meaning\": \"销售单价（元，已从存储分值除以100还原）\"}, {\"name\": \"total_amount\", \"index\": 6, \"meaning\": \"明细总金额（元，已从存储分值除以100还原）\"}, {\"name\": \"create_time\", \"index\": 7, \"meaning\": \"明细创建时间\"}], \"content\": \"产品编码 P000227 (最佳选择 全麦饼干) 在销售订单明细中的全部有效记录，包含销售单号、数量、出库进度、价格及时间信息。\", \"limitations\": \"\"}',NULL);
INSERT INTO `ai_dataset` (`dataset_id`, `sql_run_id`, `attempt`, `ready_run_id`, `user_id`, `conversation_id`, `description`, `source_sql`, `columns_json`, `row_count`, `completed`, `storage_file`, `status`, `expires_at`, `created_at`, `data_description_json`, `truncation_reason`) VALUES ('ds_5d479a9dda2e46bf83927956ca53ff4e','sqlrun_8fecf176ede8485db97faf9a7505c098',1,'sqlrun_8fecf176ede8485db97faf9a7505c098',1900000000000000001,2124424075508994050,'查询产品 P000005 的全部库存流水明细汇总：按仓库、库存流水类型（bill_type：PURCHASE_IN/SALES_OUT/PURCHASE_RETURN/SALES_RETURN/ADJUST_IN/ADJUST_OUT）、录入方式分组，返回单数、change_qty 合计（100倍整数原值）、最早和最晚确认时间；数据来自 stock_bill_item 关联 stock_bill，不限时间范围','SELECT sb.warehouse_id AS warehouse_id, sb.warehouse_name AS warehouse_name, sb.bill_type AS bill_type, sb.entry_mode AS entry_mode, COUNT(DISTINCT sb.id) AS bill_count, SUM(sbi.change_qty) AS sum_change_qty, MIN(sb.confirmed_at) AS first_confirmed_at, MAX(sb.confirmed_at) AS last_confirmed_at FROM stock_bill_item sbi JOIN stock_bill sb ON sbi.bill_id = sb.id WHERE sbi.product_code = \'P000005\' GROUP BY sb.warehouse_id, sb.warehouse_name, sb.bill_type, sb.entry_mode','[{\"name\":\"warehouse_id\",\"label\":\"warehouse_id\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"warehouse_name\",\"label\":\"warehouse_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"bill_type\",\"label\":\"bill_type\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"entry_mode\",\"label\":\"entry_mode\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"bill_count\",\"label\":\"bill_count\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"sum_change_qty\",\"label\":\"sum_change_qty\",\"jdbcType\":3,\"typeName\":\"DECIMAL\",\"nullable\":true},{\"name\":\"first_confirmed_at\",\"label\":\"first_confirmed_at\",\"jdbcType\":93,\"typeName\":\"DATETIME\",\"nullable\":true},{\"name\":\"last_confirmed_at\",\"label\":\"last_confirmed_at\",\"jdbcType\":93,\"typeName\":\"DATETIME\",\"nullable\":true}]',5,1,'ds_5d479a9dda2e46bf83927956ca53ff4e.jsonl','READY','2026-12-07 00:00:00.000000','2026-11-22 08:47:44.343649','{\"grain\": \"每个仓库ID + 流水类型(bill_type) + 录入方式(entry_mode) 组合为一行。\", \"fields\": [{\"name\": \"warehouse_id\", \"index\": 0, \"meaning\": \"仓库ID\"}, {\"name\": \"warehouse_name\", \"index\": 1, \"meaning\": \"仓库名称快照\"}, {\"name\": \"bill_type\", \"index\": 2, \"meaning\": \"库存流水类型 (如 PURCHASE_IN, SALES_OUT, ADJUST_IN 等)\"}, {\"name\": \"entry_mode\", \"index\": 3, \"meaning\": \"录入方式 (如 SOURCE_GENERATED, MANUAL_ADJUSTMENT 等)\"}, {\"name\": \"bill_count\", \"index\": 4, \"meaning\": \"该分组下的库存流水凭证单数 (COUNT DISTINCT bill_id)\"}, {\"name\": \"sum_change_qty\", \"index\": 5, \"meaning\": \"库存变动数量合计 (SUM change_qty)，单位为100倍整数原值 (例如 35200 表示 352.00)\"}, {\"name\": \"first_confirmed_at\", \"index\": 6, \"meaning\": \"该分组下最早的确认时间\"}, {\"name\": \"last_confirmed_at\", \"index\": 7, \"meaning\": \"该分组下最晚的确认时间\"}], \"content\": \"产品 P000005 的历史库存流水明细汇总，按仓库、业务单据类型、录入方式分组统计。\", \"limitations\": \"\"}',NULL);
INSERT INTO `ai_dataset` (`dataset_id`, `sql_run_id`, `attempt`, `ready_run_id`, `user_id`, `conversation_id`, `description`, `source_sql`, `columns_json`, `row_count`, `completed`, `storage_file`, `status`, `expires_at`, `created_at`, `data_description_json`, `truncation_reason`) VALUES ('ds_610f31ff851a4854ad696f4a5e0a9937','sqlrun_c4d5936262ac4ab3b0c934bf541f03ae',1,'sqlrun_c4d5936262ac4ab3b0c934bf541f03ae',1900000000000000001,2124420137200144385,'查询供应商编码 S0001（supplier_id=8400000000002000001，上海万隆食品贸易有限责任公司）和 S0002（supplier_id=8400000000002000002，佛山宏远商贸有限责任公司）的供应商主档：supplier_code、supplier_name、status（启用状态）、service_score（人工服务评分，放大100倍）、service_score_reason（人工服务评分原因）、payment_terms、score_status','SELECT supplier_code, supplier_name, status, service_score, service_score_reason, payment_terms, score_status FROM supplier WHERE id IN (8400000000002000001, 8400000000002000002) AND deleted = 0','[{\"name\":\"supplier_code\",\"label\":\"supplier_code\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"supplier_name\",\"label\":\"supplier_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"status\",\"label\":\"status\",\"jdbcType\":-6,\"typeName\":\"TINYINT\",\"nullable\":false},{\"name\":\"service_score\",\"label\":\"service_score\",\"jdbcType\":4,\"typeName\":\"INT\",\"nullable\":true},{\"name\":\"service_score_reason\",\"label\":\"service_score_reason\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"payment_terms\",\"label\":\"payment_terms\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"score_status\",\"label\":\"score_status\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false}]',2,1,'ds_610f31ff851a4854ad696f4a5e0a9937.jsonl','READY','2026-12-07 00:00:00.000000','2026-11-22 08:31:03.869687','{\"grain\": \"每个供应商一行\", \"fields\": [{\"name\": \"supplier_code\", \"index\": 0, \"meaning\": \"供应商编码\"}, {\"name\": \"supplier_name\", \"index\": 1, \"meaning\": \"供应商名称\"}, {\"name\": \"status\", \"index\": 2, \"meaning\": \"启用状态：1表示启用，0表示禁用\"}, {\"name\": \"service_score\", \"index\": 3, \"meaning\": \"人工服务评分，放大100倍存储的整数值（例如9708代表97.08分），NULL表示尚未设定\"}, {\"name\": \"service_score_reason\", \"index\": 4, \"meaning\": \"人工服务评分原因说明\"}, {\"name\": \"payment_terms\", \"index\": 5, \"meaning\": \"付款条件\"}, {\"name\": \"score_status\", \"index\": 6, \"meaning\": \"评分状态：READY表示可参与评分，NOT_READY表示样本不足\"}], \"content\": \"供应商主档信息查询结果，包含供应商编码、名称、启用状态、人工服务评分、评分原因、付款条件和评分状态。\", \"limitations\": \"\"}',NULL);
INSERT INTO `ai_dataset` (`dataset_id`, `sql_run_id`, `attempt`, `ready_run_id`, `user_id`, `conversation_id`, `description`, `source_sql`, `columns_json`, `row_count`, `completed`, `storage_file`, `status`, `expires_at`, `created_at`, `data_description_json`, `truncation_reason`) VALUES ('ds_625aa1ad9c6d4a0bafecf9d07ae388bd','sqlrun_e30f05eac2a345d0b23693009f42f6fa',2,'sqlrun_e30f05eac2a345d0b23693009f42f6fa',1900000000000000001,2124221025439735809,'查询库存流水凭证（stock_bill）的最早和最晚确认时间，以及按bill_type、按月统计的单据数和变动数量合计，用于判断可用于计算库存周转的历史出库数据时间跨度','SELECT sb.bill_type AS bill_type, DATE_FORMAT(sb.confirmed_at, \'%Y-%m\') AS month, sbi.unit_name AS unit_name, COUNT(DISTINCT sb.id) AS bill_count, SUM(sbi.change_qty) / 100.0 AS total_change_qty_business_unit, MIN(sb.confirmed_at) AS earliest_confirmed_time_in_group, MAX(sb.confirmed_at) AS latest_confirmed_time_in_group FROM stock_bill sb JOIN stock_bill_item sbi ON sb.id = sbi.bill_id GROUP BY sb.bill_type, DATE_FORMAT(sb.confirmed_at, \'%Y-%m\'), sbi.unit_name','[{\"name\":\"bill_type\",\"label\":\"bill_type\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"month\",\"label\":\"month\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":true},{\"name\":\"unit_name\",\"label\":\"unit_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"bill_count\",\"label\":\"bill_count\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"total_change_qty_business_unit\",\"label\":\"total_change_qty_business_unit\",\"jdbcType\":3,\"typeName\":\"DECIMAL\",\"nullable\":true},{\"name\":\"earliest_confirmed_time_in_group\",\"label\":\"earliest_confirmed_time_in_group\",\"jdbcType\":93,\"typeName\":\"DATETIME\",\"nullable\":true},{\"name\":\"latest_confirmed_time_in_group\",\"label\":\"latest_confirmed_time_in_group\",\"jdbcType\":93,\"typeName\":\"DATETIME\",\"nullable\":true}]',26,1,'ds_625aa1ad9c6d4a0bafecf9d07ae388bd.jsonl','READY','2026-12-06 00:00:00.000000','2026-11-21 19:19:45.816879','{\"grain\": \"每个bill_type、每个月份、每种计量单位一行\", \"fields\": [{\"name\": \"bill_type\", \"index\": 0, \"meaning\": \"库存流水单据类型 (如 PURCHASE_IN, SALES_OUT)\"}, {\"name\": \"month\", \"index\": 1, \"meaning\": \"确认时间所属的自然月 (格式: YYYY-MM)\"}, {\"name\": \"unit_name\", \"index\": 2, \"meaning\": \"计量单位名称快照 (用于区分不同单位的数量，避免跨单位错误汇总)\"}, {\"name\": \"bill_count\", \"index\": 3, \"meaning\": \"该组内的库存流水凭证主表记录数 (去重后的单据ID计数)\"}, {\"name\": \"total_change_qty_business_unit\", \"index\": 4, \"meaning\": \"该组内库存变动数量的合计，已除以100还原为业务单位数值\"}, {\"name\": \"earliest_confirmed_time_in_group\", \"index\": 5, \"meaning\": \"该组内最早的库存流水确认时间\"}, {\"name\": \"latest_confirmed_time_in_group\", \"index\": 6, \"meaning\": \"该组内最晚的库存流水确认时间\"}], \"content\": \"库存流水凭证按单据类型(bill_type)、自然月(month)和计量单位(unit_name)分组的统计数据，包括单据数、变动数量合计(业务单位)及时间跨度。\", \"limitations\": \"\"}',NULL);
INSERT INTO `ai_dataset` (`dataset_id`, `sql_run_id`, `attempt`, `ready_run_id`, `user_id`, `conversation_id`, `description`, `source_sql`, `columns_json`, `row_count`, `completed`, `storage_file`, `status`, `expires_at`, `created_at`, `data_description_json`, `truncation_reason`) VALUES ('ds_66d6d5334f0944f3bd3a66a08ac6f15f','sqlrun_fe304f33326b4ec38bccf249a549f9af',2,'sqlrun_fe304f33326b4ec38bccf249a549f9af',1900000000000000001,2124761984778977281,'查询产品 product_id=8400000000005001253 的启用供货关系：supplier_product.status=1 且 deleted=0，关联 supplier.status=1 且 deleted=0，返回供应商ID、供应商编码、供应商名称、quoted_purchase_price（人工有效报价，分）、latest_purchase_price（最近成交价，分）、quoted_price_reason、quote_valid_until（报价有效截止日）、min_order_qty（100倍整数）、quality_score（INT×100）、price_score（INT×100）、recommend_score（INT×100）、score_status、avg_delivery_days、last_purchase_at、score_basis_amount，用于供应商比较和采购量取整','SELECT sp.supplier_id AS supplier_id, s.supplier_code AS supplier_code, s.supplier_name AS supplier_name, sp.quoted_purchase_price AS quoted_purchase_price, sp.latest_purchase_price AS latest_purchase_price, sp.quoted_price_reason AS quoted_price_reason, sp.quoted_price_updated_at AS quoted_price_updated_at, sp.quote_valid_until AS quote_valid_until, sp.min_order_qty AS min_order_qty, sp.quality_score AS quality_score, sp.price_score AS price_score, sp.recommend_score AS recommend_score, sp.score_status AS score_status, sp.avg_delivery_days AS avg_delivery_days, sp.last_purchase_at AS last_purchase_at, sp.score_basis_amount AS score_basis_amount FROM supplier_product sp JOIN supplier s ON sp.supplier_id = s.id WHERE sp.product_id = 8400000000005001253 AND sp.status = 1 AND sp.deleted = 0 AND s.status = 1 AND s.deleted = 0','[{\"name\":\"supplier_id\",\"label\":\"supplier_id\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"supplier_code\",\"label\":\"supplier_code\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"supplier_name\",\"label\":\"supplier_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"quoted_purchase_price\",\"label\":\"quoted_purchase_price\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":true},{\"name\":\"latest_purchase_price\",\"label\":\"latest_purchase_price\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":true},{\"name\":\"quoted_price_reason\",\"label\":\"quoted_price_reason\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"quoted_price_updated_at\",\"label\":\"quoted_price_updated_at\",\"jdbcType\":93,\"typeName\":\"DATETIME\",\"nullable\":true},{\"name\":\"quote_valid_until\",\"label\":\"quote_valid_until\",\"jdbcType\":91,\"typeName\":\"DATE\",\"nullable\":true},{\"name\":\"min_order_qty\",\"label\":\"min_order_qty\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"quality_score\",\"label\":\"quality_score\",\"jdbcType\":4,\"typeName\":\"INT\",\"nullable\":true},{\"name\":\"price_score\",\"label\":\"price_score\",\"jdbcType\":4,\"typeName\":\"INT\",\"nullable\":true},{\"name\":\"recommend_score\",\"label\":\"recommend_score\",\"jdbcType\":4,\"typeName\":\"INT\",\"nullable\":true},{\"name\":\"score_status\",\"label\":\"score_status\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"avg_delivery_days\",\"label\":\"avg_delivery_days\",\"jdbcType\":3,\"typeName\":\"DECIMAL\",\"nullable\":true},{\"name\":\"last_purchase_at\",\"label\":\"last_purchase_at\",\"jdbcType\":93,\"typeName\":\"DATETIME\",\"nullable\":true},{\"name\":\"score_basis_amount\",\"label\":\"score_basis_amount\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":true}]',1,1,'ds_66d6d5334f0944f3bd3a66a08ac6f15f.jsonl','READY','2026-12-08 00:00:00.000000','2026-11-23 07:11:05.668360','{\"grain\": \"每行代表一个特定供应商与该产品之间的有效供货关系记录。\", \"fields\": [{\"name\": \"supplier_id\", \"index\": 0, \"meaning\": \"供应商ID\"}, {\"name\": \"supplier_code\", \"index\": 1, \"meaning\": \"供应商编码\"}, {\"name\": \"supplier_name\", \"index\": 2, \"meaning\": \"供应商名称\"}, {\"name\": \"quoted_purchase_price\", \"index\": 3, \"meaning\": \"参考采购价（单位：分，存储值为实际金额×100）\"}, {\"name\": \"latest_purchase_price\", \"index\": 4, \"meaning\": \"最近成交价（单位：分，存储值为实际金额×100）\"}, {\"name\": \"quoted_price_reason\", \"index\": 5, \"meaning\": \"报价原因/备注\"}, {\"name\": \"quoted_price_updated_at\", \"index\": 6, \"meaning\": \"报价更新时间\"}, {\"name\": \"quote_valid_until\", \"index\": 7, \"meaning\": \"报价有效期截止日\"}, {\"name\": \"min_order_qty\", \"index\": 8, \"meaning\": \"最小起订量（存储值需除以100得到实际数量）\"}, {\"name\": \"quality_score\", \"index\": 9, \"meaning\": \"质量评分（存储值需除以100得到0-100分值）\"}, {\"name\": \"price_score\", \"index\": 10, \"meaning\": \"价格评分（存储值需除以100得到0-100分值）\"}, {\"name\": \"recommend_score\", \"index\": 11, \"meaning\": \"推荐评分（存储值需除以100得到0-100分值）\"}, {\"name\": \"score_status\", \"index\": 12, \"meaning\": \"评分状态（如NOT_READY表示样本不足或未计算）\"}, {\"name\": \"avg_delivery_days\", \"index\": 13, \"meaning\": \"平均交付天数（历史统计值）\"}, {\"name\": \"last_purchase_at\", \"index\": 14, \"meaning\": \"最后采购时间\"}, {\"name\": \"score_basis_amount\", \"index\": 15, \"meaning\": \"评分依据金额（用于加权计算的基数，单位：分）\"}], \"content\": \"指定产品（ID: 8400000000005001253）的有效供应商供货关系明细，包括供应商基本信息、采购报价、历史价格、起订量及多维评分。\", \"limitations\": \"部分评分字段可能为NULL，表示该维度样本不足或尚未计算；金额和数量字段均为放大100倍后的整数值，使用时需注意还原。\"}',NULL);
INSERT INTO `ai_dataset` (`dataset_id`, `sql_run_id`, `attempt`, `ready_run_id`, `user_id`, `conversation_id`, `description`, `source_sql`, `columns_json`, `row_count`, `completed`, `storage_file`, `status`, `expires_at`, `created_at`, `data_description_json`, `truncation_reason`) VALUES ('ds_6718ae63ed4b4059b5d3f4bb5c3a19b1','sqlrun_9eae0f9dd966432da41ce535ac751a60',2,'sqlrun_9eae0f9dd966432da41ce535ac751a60',1900000000000000001,2124221025439735809,'核实 stock_bill 整体：按 bill_type 统计最早/最晚确认时间、单据数，并额外统计确认时间在 2026-11-09 00:00:00 至 2026-11-22 23:59:59（最近14天）之间的单据数，用于验证“近14天无库存变动”前提','SELECT sb.bill_type AS bill_type, MIN(sb.confirmed_at) AS min_confirmed_at, MAX(sb.confirmed_at) AS max_confirmed_at, COUNT(*) AS bill_count, SUM(CASE WHEN sb.confirmed_at >= \'2026-11-09 00:00:00\' AND sb.confirmed_at <= \'2026-11-22 23:59:59\' THEN 1 ELSE 0 END) AS bills_in_last_14_days FROM stock_bill sb GROUP BY sb.bill_type','[{\"name\":\"bill_type\",\"label\":\"bill_type\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"min_confirmed_at\",\"label\":\"min_confirmed_at\",\"jdbcType\":93,\"typeName\":\"DATETIME\",\"nullable\":true},{\"name\":\"max_confirmed_at\",\"label\":\"max_confirmed_at\",\"jdbcType\":93,\"typeName\":\"DATETIME\",\"nullable\":true},{\"name\":\"bill_count\",\"label\":\"bill_count\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"bills_in_last_14_days\",\"label\":\"bills_in_last_14_days\",\"jdbcType\":3,\"typeName\":\"DECIMAL\",\"nullable\":true}]',2,1,'ds_6718ae63ed4b4059b5d3f4bb5c3a19b1.jsonl','READY','2026-12-06 00:00:00.000000','2026-11-21 19:22:24.340820','{\"grain\": \"每个 bill_type 一行\", \"fields\": [{\"name\": \"bill_type\", \"index\": 0, \"meaning\": \"库存流水单据类型 (如 PURCHASE_IN, SALES_OUT)\"}, {\"name\": \"min_confirmed_at\", \"index\": 1, \"meaning\": \"该类型单据的最早确认时间\"}, {\"name\": \"max_confirmed_at\", \"index\": 2, \"meaning\": \"该类型单据的最晚确认时间\"}, {\"name\": \"bill_count\", \"index\": 3, \"meaning\": \"该类型单据的总数量\"}, {\"name\": \"bills_in_last_14_days\", \"index\": 4, \"meaning\": \"该类型单据在指定最近14天窗口(2026-11-09 00:00:00 至 2026-11-22 23:59:59)内的数量\"}], \"content\": \"库存流水凭证(stock_bill)按单据类型(bill_type)统计的整体概况，包括每种类型的最早确认时间、最晚确认时间、总单据数，以及在最近14天(2026-11-09至2026-11-22)内的单据数量。\", \"limitations\": \"\"}',NULL);
INSERT INTO `ai_dataset` (`dataset_id`, `sql_run_id`, `attempt`, `ready_run_id`, `user_id`, `conversation_id`, `description`, `source_sql`, `columns_json`, `row_count`, `completed`, `storage_file`, `status`, `expires_at`, `created_at`, `data_description_json`, `truncation_reason`) VALUES ('ds_6865377367514a2cb33380ae609b723b','sqlrun_404a6ec099fc4992a0c0af89225b8e8c',2,'sqlrun_404a6ec099fc4992a0c0af89225b8e8c',1900000000000000001,2124424075508994050,'查询产品 P000005 的全部退货单明细（含 SALES_RETURN 与 PURCHASE_RETURN，含已取消状态以外的全部状态），返回退货单号、退货类型、状态、原订单号、客户或供应商、仓库、申请退货数量、审核通过数量、已处理数量、创建时间','SELECT \n    ro.return_no AS return_no,\n    ro.return_type AS return_type,\n    ro.status AS status,\n    ro.source_order_no AS source_order_no,\n    ro.party_name AS party_name,\n    ro.warehouse_name AS warehouse_name,\n    roi.requested_qty / 100.0 AS requested_qty,\n    roi.approved_qty / 100.0 AS approved_qty,\n    roi.processed_qty / 100.0 AS processed_qty,\n    ro.create_time AS create_time\nFROM return_order ro\nJOIN return_order_item roi ON ro.id = roi.return_order_id\nWHERE ro.deleted = 0\n  AND ro.status != \'CANCELLED\'\n  AND roi.product_code = \'P000005\'','[{\"name\":\"return_no\",\"label\":\"return_no\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"return_type\",\"label\":\"return_type\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"status\",\"label\":\"status\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"source_order_no\",\"label\":\"source_order_no\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"party_name\",\"label\":\"party_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"warehouse_name\",\"label\":\"warehouse_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"requested_qty\",\"label\":\"requested_qty\",\"jdbcType\":3,\"typeName\":\"DECIMAL\",\"nullable\":true},{\"name\":\"approved_qty\",\"label\":\"approved_qty\",\"jdbcType\":3,\"typeName\":\"DECIMAL\",\"nullable\":true},{\"name\":\"processed_qty\",\"label\":\"processed_qty\",\"jdbcType\":3,\"typeName\":\"DECIMAL\",\"nullable\":true},{\"name\":\"create_time\",\"label\":\"create_time\",\"jdbcType\":93,\"typeName\":\"DATETIME\",\"nullable\":false}]',0,1,'ds_6865377367514a2cb33380ae609b723b.jsonl','READY','2026-12-07 00:00:00.000000','2026-11-22 08:48:27.172695','{\"grain\": \"每张退货单的每个产品明细行一行（若一张退货单包含多个产品，仅返回P000005对应的行；若一张退货单有多个P000005明细行，则每行一条）。根据需求“每张退货单一行”的表述，通常隐含针对特定产品的查询，此处粒度为退货单-产品明细级别。\", \"fields\": [{\"name\": \"return_no\", \"index\": 0, \"meaning\": \"退货单号\"}, {\"name\": \"return_type\", \"index\": 1, \"meaning\": \"退货类型：SALES_RETURN(销售退货) 或 PURCHASE_RETURN(采购退货)\"}, {\"name\": \"status\", \"index\": 2, \"meaning\": \"退货单状态：DRAFT/SUBMITTED/APPROVED/PARTIAL_EXECUTED/COMPLETED\"}, {\"name\": \"source_order_no\", \"index\": 3, \"meaning\": \"原订单号（销售订单号或采购订单号）\"}, {\"name\": \"party_name\", \"index\": 4, \"meaning\": \"客户名称（销售退货）或供应商名称（采购退货）\"}, {\"name\": \"warehouse_name\", \"index\": 5, \"meaning\": \"退货执行仓库名称\"}, {\"name\": \"requested_qty\", \"index\": 6, \"meaning\": \"申请退货数量（已还原为实际单位，如件/kg）\"}, {\"name\": \"approved_qty\", \"index\": 7, \"meaning\": \"审核通过数量（已还原为实际单位）\"}, {\"name\": \"processed_qty\", \"index\": 8, \"meaning\": \"已处理数量（仓库累计确认的实际处理总量，已还原为实际单位）\"}, {\"name\": \"create_time\", \"index\": 9, \"meaning\": \"退货单创建时间\"}], \"content\": \"产品 P000005 的全部非取消状态退货单明细（含销售退货和采购退货），用于核算可退量时扣除已有占用。\", \"limitations\": \"\"}',NULL);
INSERT INTO `ai_dataset` (`dataset_id`, `sql_run_id`, `attempt`, `ready_run_id`, `user_id`, `conversation_id`, `description`, `source_sql`, `columns_json`, `row_count`, `completed`, `storage_file`, `status`, `expires_at`, `created_at`, `data_description_json`, `truncation_reason`) VALUES ('ds_6901927af0b54f08963498f6618085bc','sqlrun_517c90b00d3d454bb80603cb93c9069b',2,'sqlrun_517c90b00d3d454bb80603cb93c9069b',1900000000000000001,2124465547335741442,'按供应商统计采购入库规模，用于供应商维度采购退货率分母。范围：inbound_bill 中 inbound_type=\'PURCHASE_IN\'、status=\'CONFIRMED\'、deleted=0，按 confirmed_at 分两个等长窗口（period=\'CUR\' 为 2026-05-25 至 2026-11-22 含端点，period=\'PRE\' 为 2025-11-23 至 2026-05-24 含端点）。按 source_party_id（供应商ID）和 source_party_name 分组，每行输出 period、供应商ID、供应商名称、入库单数、数量合计（sum(inbound_bill_item.current_qty)/100）、金额合计（sum(current_qty*unit_price)/10000 元）。全部仓库。','SELECT CASE WHEN ib.confirmed_at >= \'2026-05-25 00:00:00\' AND ib.confirmed_at <= \'2026-11-22 23:59:59\' THEN \'CUR\' ELSE \'PRE\' END AS period, ib.source_party_id AS supplier_id, ib.source_party_name AS supplier_name, COUNT(DISTINCT ib.id) AS bill_count, SUM(ibi.current_qty) / 100.0 AS qty, SUM(ibi.current_qty * ibi.unit_price) / 10000.0 AS amount_yuan FROM inbound_bill ib INNER JOIN inbound_bill_item ibi ON ib.id = ibi.inbound_bill_id WHERE ib.inbound_type = \'PURCHASE_IN\' AND ib.status = \'CONFIRMED\' AND ib.deleted = 0 AND ((ib.confirmed_at >= \'2026-05-25 00:00:00\' AND ib.confirmed_at <= \'2026-11-22 23:59:59\') OR (ib.confirmed_at >= \'2025-11-23 00:00:00\' AND ib.confirmed_at <= \'2026-05-24 23:59:59\')) GROUP BY CASE WHEN ib.confirmed_at >= \'2026-05-25 00:00:00\' AND ib.confirmed_at <= \'2026-11-22 23:59:59\' THEN \'CUR\' ELSE \'PRE\' END, ib.source_party_id, ib.source_party_name','[{\"name\":\"period\",\"label\":\"period\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"source_party_id\",\"label\":\"supplier_id\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":true},{\"name\":\"source_party_name\",\"label\":\"supplier_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"bill_count\",\"label\":\"bill_count\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"qty\",\"label\":\"qty\",\"jdbcType\":3,\"typeName\":\"DECIMAL\",\"nullable\":true},{\"name\":\"amount_yuan\",\"label\":\"amount_yuan\",\"jdbcType\":3,\"typeName\":\"DECIMAL\",\"nullable\":true}]',354,1,'ds_6901927af0b54f08963498f6618085bc.jsonl','READY','2026-12-07 00:00:00.000000','2026-11-22 11:33:30.003742','{\"grain\": \"每行代表一个特定统计周期（period）下某个供应商（source_party_id）的采购入库汇总数据。\", \"fields\": [{\"name\": \"period\", \"index\": 0, \"meaning\": \"统计周期标识，\'CUR\'表示当前期（2026-05-25至2026-11-22），\'PRE\'表示前期（2025-11-23至2026-05-24）。\"}, {\"name\": \"supplier_id\", \"index\": 1, \"meaning\": \"供应商ID，取自入库单的来源对象ID（source_party_id）。\"}, {\"name\": \"supplier_name\", \"index\": 2, \"meaning\": \"供应商名称，取自入库单的来源对象名称快照（source_party_name）。\"}, {\"name\": \"bill_count\", \"index\": 3, \"meaning\": \"入库单数量，该周期内该供应商已确认的采购入库单据去重计数。\"}, {\"name\": \"qty\", \"index\": 4, \"meaning\": \"入库数量合计，单位为基本计量单位（由明细表current_qty除以100还原得到）。\"}, {\"name\": \"amount_yuan\", \"index\": 5, \"meaning\": \"入库金额合计，单位为元（由明细表current_qty*unit_price除以10000还原得到，因单价存储单位为分，数量放大100倍）。\"}], \"content\": \"按供应商和统计周期（当前期/前期）汇总的采购入库业务指标，包括入库单据数量、商品总数量和总金额，用于计算采购退货率的分母。\", \"limitations\": \"\"}',NULL);
INSERT INTO `ai_dataset` (`dataset_id`, `sql_run_id`, `attempt`, `ready_run_id`, `user_id`, `conversation_id`, `description`, `source_sql`, `columns_json`, `row_count`, `completed`, `storage_file`, `status`, `expires_at`, `created_at`, `data_description_json`, `truncation_reason`) VALUES ('ds_691c1633baff4cc19d1021647ff96fe8','sqlrun_f5619b758e9e47d090fb97b115da3d80',1,'sqlrun_f5619b758e9e47d090fb97b115da3d80',1900000000000000001,2124420137200144385,'查询产品编码 P001143（香满屋 坚果便携装）在供应商供货产品表中的全部记录，包括供应商ID、供应商名称、最近成交价、人工报价及报价有效期、最小起订量、质量评分、价格评分、推荐评分、评分状态、最近成交时间、平均交期','SELECT sp.supplier_id AS supplier_id, s.supplier_code AS supplier_code, s.supplier_name AS supplier_name, sp.product_id AS product_id, p.product_code AS product_code, p.product_name AS product_name, sp.latest_purchase_price AS latest_purchase_price, sp.quoted_purchase_price AS quoted_purchase_price, sp.quote_valid_until AS quote_valid_until, sp.min_order_qty AS min_order_qty, sp.quality_score AS quality_score, sp.price_score AS price_score, sp.recommend_score AS recommend_score, sp.score_status AS score_status, sp.last_purchase_at AS last_purchase_at, sp.avg_delivery_days AS avg_delivery_days, sp.status AS status FROM supplier_product sp JOIN supplier s ON sp.supplier_id = s.id AND s.deleted = 0 JOIN product p ON sp.product_id = p.id AND p.deleted = 0 WHERE sp.deleted = 0 AND p.product_code = \'P001143\'','[{\"name\":\"supplier_id\",\"label\":\"supplier_id\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"supplier_code\",\"label\":\"supplier_code\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"supplier_name\",\"label\":\"supplier_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"product_id\",\"label\":\"product_id\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"product_code\",\"label\":\"product_code\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"product_name\",\"label\":\"product_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"latest_purchase_price\",\"label\":\"latest_purchase_price\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":true},{\"name\":\"quoted_purchase_price\",\"label\":\"quoted_purchase_price\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":true},{\"name\":\"quote_valid_until\",\"label\":\"quote_valid_until\",\"jdbcType\":91,\"typeName\":\"DATE\",\"nullable\":true},{\"name\":\"min_order_qty\",\"label\":\"min_order_qty\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"quality_score\",\"label\":\"quality_score\",\"jdbcType\":4,\"typeName\":\"INT\",\"nullable\":true},{\"name\":\"price_score\",\"label\":\"price_score\",\"jdbcType\":4,\"typeName\":\"INT\",\"nullable\":true},{\"name\":\"recommend_score\",\"label\":\"recommend_score\",\"jdbcType\":4,\"typeName\":\"INT\",\"nullable\":true},{\"name\":\"score_status\",\"label\":\"score_status\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"last_purchase_at\",\"label\":\"last_purchase_at\",\"jdbcType\":93,\"typeName\":\"DATETIME\",\"nullable\":true},{\"name\":\"avg_delivery_days\",\"label\":\"avg_delivery_days\",\"jdbcType\":3,\"typeName\":\"DECIMAL\",\"nullable\":true},{\"name\":\"status\",\"label\":\"status\",\"jdbcType\":-6,\"typeName\":\"TINYINT\",\"nullable\":false}]',2,1,'ds_691c1633baff4cc19d1021647ff96fe8.jsonl','READY','2026-12-07 00:00:00.000000','2026-11-22 08:30:13.263784','{\"grain\": \"每个供应商对该特定产品的供货关系记录一行\", \"fields\": [{\"name\": \"supplier_id\", \"index\": 0, \"meaning\": \"供应商ID\"}, {\"name\": \"supplier_code\", \"index\": 1, \"meaning\": \"供应商编码\"}, {\"name\": \"supplier_name\", \"index\": 2, \"meaning\": \"供应商名称\"}, {\"name\": \"product_id\", \"index\": 3, \"meaning\": \"产品ID\"}, {\"name\": \"product_code\", \"index\": 4, \"meaning\": \"产品编码\"}, {\"name\": \"product_name\", \"index\": 5, \"meaning\": \"产品名称\"}, {\"name\": \"latest_purchase_price\", \"index\": 6, \"meaning\": \"最近成交单价（单位：分）\"}, {\"name\": \"quoted_purchase_price\", \"index\": 7, \"meaning\": \"人工有效报价（单位：分）\"}, {\"name\": \"quote_valid_until\", \"index\": 8, \"meaning\": \"报价有效截止日\"}, {\"name\": \"min_order_qty\", \"index\": 9, \"meaning\": \"最小起订量（放大100倍存储，需除以100得到实际数量）\"}, {\"name\": \"quality_score\", \"index\": 10, \"meaning\": \"供应产品质量评分（放大100倍存储，NULL表示样本不足）\"}, {\"name\": \"price_score\", \"index\": 11, \"meaning\": \"供应产品价格评分（放大100倍存储，NULL表示样本不足）\"}, {\"name\": \"recommend_score\", \"index\": 12, \"meaning\": \"供应产品推荐评分（放大100倍存储，NULL表示样本不足）\"}, {\"name\": \"score_status\", \"index\": 13, \"meaning\": \"评分状态（READY:可参与评分, NOT_READY:样本不足）\"}, {\"name\": \"last_purchase_at\", \"index\": 14, \"meaning\": \"最近成交时间（最后一次已确认采购入库时间）\"}, {\"name\": \"avg_delivery_days\", \"index\": 15, \"meaning\": \"平均到货周期（天，近180天金额加权平均）\"}, {\"name\": \"status\", \"index\": 16, \"meaning\": \"供货关系状态（1:启用, 0:禁用）\"}], \"content\": \"产品P001143的供应商供货档案列表，包括供应商基本信息、采购价格、报价信息、起订量、评分及交付指标。\", \"limitations\": \"\"}',NULL);
INSERT INTO `ai_dataset` (`dataset_id`, `sql_run_id`, `attempt`, `ready_run_id`, `user_id`, `conversation_id`, `description`, `source_sql`, `columns_json`, `row_count`, `completed`, `storage_file`, `status`, `expires_at`, `created_at`, `data_description_json`, `truncation_reason`) VALUES ('ds_69d77d679e6d402589d5a5923ef2ea5d','sqlrun_0bef17ae3e884d609c3aaf7955f66447',2,'sqlrun_0bef17ae3e884d609c3aaf7955f66447',1900000000000000001,2124221025439735809,'以 stock_bill.confirmed_at 在 2026-08-10 00:00:00 至 2026-11-08 23:59:59 区间、bill_type=SALES_OUT 为条件，按仓库+产品汇总 stock_bill_item.change_qty 的绝对值（100倍整数原值），返回仓库ID、仓库编码、产品ID、产品编码、名称、窗口出库数量合计、最后一次出库确认时间、出库单据数','SELECT sb.warehouse_id AS warehouse_id, w.warehouse_code AS warehouse_code, sbi.product_id AS product_id, sbi.product_code AS product_code, sbi.product_name AS product_name, SUM(ABS(sbi.change_qty)) AS sales_out_qty, MAX(sb.confirmed_at) AS last_sales_out_confirmed_at, COUNT(DISTINCT sb.id) AS sales_out_bill_count FROM stock_bill sb JOIN stock_bill_item sbi ON sb.id = sbi.bill_id JOIN warehouse w ON sb.warehouse_id = w.id WHERE sb.bill_type = \'SALES_OUT\' AND sb.confirmed_at >= \'2026-08-10 00:00:00\' AND sb.confirmed_at <= \'2026-11-08 23:59:59\' AND w.deleted = 0 GROUP BY sb.warehouse_id, w.warehouse_code, sbi.product_id, sbi.product_code, sbi.product_name','[{\"name\":\"warehouse_id\",\"label\":\"warehouse_id\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"warehouse_code\",\"label\":\"warehouse_code\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"product_id\",\"label\":\"product_id\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"product_code\",\"label\":\"product_code\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"product_name\",\"label\":\"product_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"sales_out_qty\",\"label\":\"sales_out_qty\",\"jdbcType\":3,\"typeName\":\"DECIMAL\",\"nullable\":true},{\"name\":\"last_sales_out_confirmed_at\",\"label\":\"last_sales_out_confirmed_at\",\"jdbcType\":93,\"typeName\":\"DATETIME\",\"nullable\":true},{\"name\":\"sales_out_bill_count\",\"label\":\"sales_out_bill_count\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false}]',406,1,'ds_69d77d679e6d402589d5a5923ef2ea5d.jsonl','READY','2026-12-06 00:00:00.000000','2026-11-21 19:21:18.070438','{\"grain\": \"每个仓库与产品的组合一行\", \"fields\": [{\"name\": \"warehouse_id\", \"index\": 0, \"meaning\": \"仓库ID\"}, {\"name\": \"warehouse_code\", \"index\": 1, \"meaning\": \"仓库编码\"}, {\"name\": \"product_id\", \"index\": 2, \"meaning\": \"产品ID\"}, {\"name\": \"product_code\", \"index\": 3, \"meaning\": \"产品编码\"}, {\"name\": \"product_name\", \"index\": 4, \"meaning\": \"产品名称\"}, {\"name\": \"sales_out_qty\", \"index\": 5, \"meaning\": \"窗口期内出库数量合计（原始值，×100存储）\"}, {\"name\": \"last_sales_out_confirmed_at\", \"index\": 6, \"meaning\": \"最后一次出库确认时间\"}, {\"name\": \"sales_out_bill_count\", \"index\": 7, \"meaning\": \"涉及的出库单据数量\"}], \"content\": \"指定时间窗口内销售出库的库存流水汇总数据，涵盖所有启用仓库的有效出库记录。\", \"limitations\": \"sales_out_qty字段值为数据库原始存储值（放大100倍），例如3600表示实际业务数量36.00；计算日均或周转时需自行换算。\"}',NULL);
INSERT INTO `ai_dataset` (`dataset_id`, `sql_run_id`, `attempt`, `ready_run_id`, `user_id`, `conversation_id`, `description`, `source_sql`, `columns_json`, `row_count`, `completed`, `storage_file`, `status`, `expires_at`, `created_at`, `data_description_json`, `truncation_reason`) VALUES ('ds_6afd11e487a14e00a563ca0efef75e59','sqlrun_02ac3c167c724f29be4cb1045c8560b9',1,'sqlrun_02ac3c167c724f29be4cb1045c8560b9',1900000000000000001,2124424075508994050,'查询产品编码 P000005（果沁 碳酸饮料礼盒装 330ml×24罐）在全部仓库的库存余额记录，返回仓库ID、仓库名称、产品编码、产品名称、单位、数量精度、安全库存、账面库存 stock_qty、锁定库存 locked_qty 以及净可用量 stock_qty - locked_qty（数量均按100倍整数存储原值返回，由我自行换算）；只取产品未删除的记录','SELECT ws.warehouse_id AS warehouse_id, ws.warehouse_name AS warehouse_name, p.product_code AS product_code, p.product_name AS product_name, p.unit_name AS unit_name, p.quantity_precision AS quantity_precision, p.safety_stock_qty AS safety_stock_qty, ws.stock_qty AS stock_qty, ws.locked_qty AS locked_qty, (ws.stock_qty - ws.locked_qty) AS available_qty FROM warehouse_stock ws INNER JOIN product p ON ws.product_id = p.id WHERE p.product_code = \'P000005\' AND p.deleted = 0','[{\"name\":\"warehouse_id\",\"label\":\"warehouse_id\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"warehouse_name\",\"label\":\"warehouse_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"product_code\",\"label\":\"product_code\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"product_name\",\"label\":\"product_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"unit_name\",\"label\":\"unit_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"quantity_precision\",\"label\":\"quantity_precision\",\"jdbcType\":-6,\"typeName\":\"TINYINT\",\"nullable\":false},{\"name\":\"safety_stock_qty\",\"label\":\"safety_stock_qty\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"stock_qty\",\"label\":\"stock_qty\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"locked_qty\",\"label\":\"locked_qty\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"available_qty\",\"label\":\"available_qty\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false}]',3,1,'ds_6afd11e487a14e00a563ca0efef75e59.jsonl','READY','2026-12-07 00:00:00.000000','2026-11-22 08:46:42.894633','{\"grain\": \"每行代表该产品在一个特定仓库中的库存状态记录。\", \"fields\": [{\"name\": \"warehouse_id\", \"index\": 0, \"meaning\": \"仓库唯一标识ID\"}, {\"name\": \"warehouse_name\", \"index\": 1, \"meaning\": \"仓库名称\"}, {\"name\": \"product_code\", \"index\": 2, \"meaning\": \"产品编码\"}, {\"name\": \"product_name\", \"index\": 3, \"meaning\": \"产品名称\"}, {\"name\": \"unit_name\", \"index\": 4, \"meaning\": \"计量单位名称（如：罐）\"}, {\"name\": \"quantity_precision\", \"index\": 5, \"meaning\": \"数量小数位精度（0-2），用于还原业务数量时参考\"}, {\"name\": \"safety_stock_qty\", \"index\": 6, \"meaning\": \"安全库存阈值（100倍整数存储，需除以100得到实际业务数值）\"}, {\"name\": \"stock_qty\", \"index\": 7, \"meaning\": \"账面库存数量（100倍整数存储，需除以100得到实际业务数值）\"}, {\"name\": \"locked_qty\", \"index\": 8, \"meaning\": \"锁定库存数量（100倍整数存储，需除以100得到实际业务数值）\"}, {\"name\": \"available_qty\", \"index\": 9, \"meaning\": \"净可用库存数量（账面库存 - 锁定库存，100倍整数存储，需除以100得到实际业务数值）\"}], \"content\": \"产品编码为 P000005（果沁 碳酸饮料礼盒装 330ml×24罐）在所有仓库中的当前库存余额详情，包括各仓库的账面库存、锁定库存及净可用库存。\", \"limitations\": \"所有数量字段（safety_stock_qty, stock_qty, locked_qty, available_qty）均按系统内部100倍整数存储，展示或计算时需自行除以100换算为实际业务数量。\"}',NULL);
INSERT INTO `ai_dataset` (`dataset_id`, `sql_run_id`, `attempt`, `ready_run_id`, `user_id`, `conversation_id`, `description`, `source_sql`, `columns_json`, `row_count`, `completed`, `storage_file`, `status`, `expires_at`, `created_at`, `data_description_json`, `truncation_reason`) VALUES ('ds_6be2a8af3147499da930fe35db3af2b5','sqlrun_62ce1943d6bf4ac2b06d565dbbc4ac18',1,'sqlrun_62ce1943d6bf4ac2b06d565dbbc4ac18',1900000000000000001,2124418644136972290,'查询 warehouse_id = 8400000000004000002（广州白云分拨仓）的全部 warehouse_stock 库存余额记录，关联 product 取产品编码、产品名称、单位、quantity_precision、safety_stock_qty，仅保留 product.status=1 且 product.deleted=0 的产品。每行一个仓库×产品，含 stock_qty、locked_qty（100倍整数）','SELECT ws.warehouse_id AS warehouse_id, ws.warehouse_name AS warehouse_name, ws.product_id AS product_id, p.product_code AS product_code, p.product_name AS product_name, p.unit_name AS unit_name, p.quantity_precision AS quantity_precision, ws.stock_qty AS stock_qty, ws.locked_qty AS locked_qty, p.safety_stock_qty AS safety_stock_qty FROM warehouse_stock ws INNER JOIN product p ON ws.product_id = p.id WHERE ws.warehouse_id = 8400000000004000002 AND p.status = 1 AND p.deleted = 0','[{\"name\":\"warehouse_id\",\"label\":\"warehouse_id\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"warehouse_name\",\"label\":\"warehouse_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"product_id\",\"label\":\"product_id\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"product_code\",\"label\":\"product_code\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"product_name\",\"label\":\"product_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"unit_name\",\"label\":\"unit_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"quantity_precision\",\"label\":\"quantity_precision\",\"jdbcType\":-6,\"typeName\":\"TINYINT\",\"nullable\":false},{\"name\":\"stock_qty\",\"label\":\"stock_qty\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"locked_qty\",\"label\":\"locked_qty\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"safety_stock_qty\",\"label\":\"safety_stock_qty\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false}]',454,1,'ds_6be2a8af3147499da930fe35db3af2b5.jsonl','READY','2026-12-07 00:00:00.000000','2026-11-22 08:25:40.428811','{\"grain\": \"每个仓库×产品一行\", \"fields\": [{\"name\": \"warehouse_id\", \"index\": 0, \"meaning\": \"仓库ID\"}, {\"name\": \"warehouse_name\", \"index\": 1, \"meaning\": \"仓库名称\"}, {\"name\": \"product_id\", \"index\": 2, \"meaning\": \"产品ID\"}, {\"name\": \"product_code\", \"index\": 3, \"meaning\": \"产品编码\"}, {\"name\": \"product_name\", \"index\": 4, \"meaning\": \"产品名称\"}, {\"name\": \"unit_name\", \"index\": 5, \"meaning\": \"单位名称\"}, {\"name\": \"quantity_precision\", \"index\": 6, \"meaning\": \"数量小数位精度\"}, {\"name\": \"stock_qty\", \"index\": 7, \"meaning\": \"当前库存数量（放大100倍整数存储）\"}, {\"name\": \"locked_qty\", \"index\": 8, \"meaning\": \"锁定库存数量（放大100倍整数存储）\"}, {\"name\": \"safety_stock_qty\", \"index\": 9, \"meaning\": \"安全库存数量（放大100倍整数存储）\"}], \"content\": \"广州白云分拨仓（warehouse_id = 8400000000004000002）中所有启用且未删除产品的库存余额记录，包含产品编码、名称、单位、精度及库存数量。\", \"limitations\": \"\"}',NULL);
INSERT INTO `ai_dataset` (`dataset_id`, `sql_run_id`, `attempt`, `ready_run_id`, `user_id`, `conversation_id`, `description`, `source_sql`, `columns_json`, `row_count`, `completed`, `storage_file`, `status`, `expires_at`, `created_at`, `data_description_json`, `truncation_reason`) VALUES ('ds_6c12192f8c6745caac8b5baaea9d5b30','sqlrun_349471d71dfe40b5ab0c04f29e2ae781',4,'sqlrun_349471d71dfe40b5ab0c04f29e2ae781',1900000000000000001,2123852411582849025,'查询产品分类表 product_category 的全部分类记录，含分类ID、上级分类ID、分类名称、状态、逻辑删除标记，用于把库存商品映射到分类名称并识别已删除分类','SELECT id AS category_id, parent_id, category_name, status, deleted FROM product_category WHERE deleted = 0','[{\"name\":\"id\",\"label\":\"category_id\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"parent_id\",\"label\":\"parent_id\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"category_name\",\"label\":\"category_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"status\",\"label\":\"status\",\"jdbcType\":-6,\"typeName\":\"TINYINT\",\"nullable\":false},{\"name\":\"deleted\",\"label\":\"deleted\",\"jdbcType\":-6,\"typeName\":\"TINYINT\",\"nullable\":false}]',102,1,'ds_6c12192f8c6745caac8b5baaea9d5b30.jsonl','READY','2026-12-05 00:00:00.000000','2026-11-20 18:56:07.566356','{\"grain\": \"每个产品分类一行\", \"fields\": [{\"name\": \"category_id\", \"index\": 0, \"meaning\": \"分类ID\"}, {\"name\": \"parent_id\", \"index\": 1, \"meaning\": \"上级分类ID，顶级分类为0\"}, {\"name\": \"category_name\", \"index\": 2, \"meaning\": \"分类名称\"}, {\"name\": \"status\", \"index\": 3, \"meaning\": \"状态：1启用，0禁用\"}, {\"name\": \"deleted\", \"index\": 4, \"meaning\": \"逻辑删除标记：0正常，1删除（当前结果均为0）\"}], \"content\": \"产品分类主档数据，仅包含未逻辑删除的有效分类记录\", \"limitations\": \"SQL 执行了 WHERE deleted = 0 过滤，因此结果集不包含已逻辑删除的分类记录。如需直接查看已删除分类的详细信息，需移除该过滤条件。\"}',NULL);
INSERT INTO `ai_dataset` (`dataset_id`, `sql_run_id`, `attempt`, `ready_run_id`, `user_id`, `conversation_id`, `description`, `source_sql`, `columns_json`, `row_count`, `completed`, `storage_file`, `status`, `expires_at`, `created_at`, `data_description_json`, `truncation_reason`) VALUES ('ds_71939b42a85c4ad1a54dd5078f7dc69b','sqlrun_22f43fe23b9d45a386a1bd4e47b1d873',1,'sqlrun_22f43fe23b9d45a386a1bd4e47b1d873',1900000000000000001,2124421893103570946,'查询产品ID 8400000000005000173（P000173）的全部销售订单明细（不限订单状态，包括 DRAFT、SUBMITTED、APPROVED、PARTIAL_OUTBOUND、OUTBOUND_DONE、CANCELLED，主表deleted=0），逐行返回：销售单号、客户名称、出库仓库名称、订单状态、预计发货日期、数量quantity（100倍）、已锁定locked_qty、已出库outbound_qty、单价unit_price（分）、创建时间。用于核实该产品历史上是否存在任何销售需求痕迹与销售价格。','SELECT so.sales_no AS sales_no, so.customer_name AS customer_name, so.warehouse_name AS warehouse_name, so.status AS status, so.expected_delivery_date AS expected_delivery_date, soi.quantity AS quantity, soi.locked_qty AS locked_qty, soi.outbound_qty AS outbound_qty, soi.unit_price AS unit_price, soi.create_time AS create_time, so.approved_at AS approved_at FROM sales_order so INNER JOIN sales_order_item soi ON so.id = soi.sales_order_id WHERE so.deleted = 0 AND soi.product_id = 8400000000005000173','[{\"name\":\"sales_no\",\"label\":\"sales_no\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"customer_name\",\"label\":\"customer_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"warehouse_name\",\"label\":\"warehouse_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"status\",\"label\":\"status\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"expected_delivery_date\",\"label\":\"expected_delivery_date\",\"jdbcType\":91,\"typeName\":\"DATE\",\"nullable\":true},{\"name\":\"quantity\",\"label\":\"quantity\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"locked_qty\",\"label\":\"locked_qty\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"outbound_qty\",\"label\":\"outbound_qty\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"unit_price\",\"label\":\"unit_price\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"create_time\",\"label\":\"create_time\",\"jdbcType\":93,\"typeName\":\"DATETIME\",\"nullable\":false},{\"name\":\"approved_at\",\"label\":\"approved_at\",\"jdbcType\":93,\"typeName\":\"DATETIME\",\"nullable\":true}]',0,1,'ds_71939b42a85c4ad1a54dd5078f7dc69b.jsonl','READY','2026-12-07 00:00:00.000000','2026-11-22 08:40:24.293137','{\"grain\": \"每张销售订单中该产品的一行记录\", \"fields\": [{\"name\": \"sales_no\", \"index\": 0, \"meaning\": \"销售单号\"}, {\"name\": \"customer_name\", \"index\": 1, \"meaning\": \"客户名称快照\"}, {\"name\": \"warehouse_name\", \"index\": 2, \"meaning\": \"出库仓库名称快照\"}, {\"name\": \"status\", \"index\": 3, \"meaning\": \"销售订单状态\"}, {\"name\": \"expected_delivery_date\", \"index\": 4, \"meaning\": \"预计发货日期\"}, {\"name\": \"quantity\", \"index\": 5, \"meaning\": \"销售数量（放大100倍存储，需除以100还原为业务数量）\"}, {\"name\": \"locked_qty\", \"index\": 6, \"meaning\": \"已锁定库存数量（放大100倍存储，需除以100还原为业务数量）\"}, {\"name\": \"outbound_qty\", \"index\": 7, \"meaning\": \"已出库数量（放大100倍存储，需除以100还原为业务数量）\"}, {\"name\": \"unit_price\", \"index\": 8, \"meaning\": \"销售单价（单位：分，需除以100还原为元）\"}, {\"name\": \"create_time\", \"index\": 9, \"meaning\": \"明细创建时间\"}, {\"name\": \"approved_at\", \"index\": 10, \"meaning\": \"订单审核通过时间\"}], \"content\": \"产品ID 8400000000005000173（P000173）的全部销售订单明细查询结果。\", \"limitations\": \"查询结果为空（rowCount=0），表示在授权数据范围内未找到该产品相关的销售订单明细记录。\"}',NULL);
INSERT INTO `ai_dataset` (`dataset_id`, `sql_run_id`, `attempt`, `ready_run_id`, `user_id`, `conversation_id`, `description`, `source_sql`, `columns_json`, `row_count`, `completed`, `storage_file`, `status`, `expires_at`, `created_at`, `data_description_json`, `truncation_reason`) VALUES ('ds_757f918cd11c498584e099345185423a','sqlrun_5e20303187344551b2e70c9985a084b6',1,'sqlrun_5e20303187344551b2e70c9985a084b6',1900000000000000001,2124418644136972290,'查询 warehouse_id = 8400000000004000005（武汉江夏南仓）的全部 warehouse_stock 库存余额记录，关联 product 取产品编码、产品名称、单位、quantity_precision、safety_stock_qty，仅保留 product.status=1 且 product.deleted=0 的产品。每行一个仓库×产品，含 stock_qty、locked_qty（100倍整数）','SELECT ws.warehouse_id AS warehouse_id, ws.warehouse_name AS warehouse_name, ws.product_id AS product_id, p.product_code AS product_code, p.product_name AS product_name, p.unit_name AS unit_name, p.quantity_precision AS quantity_precision, ws.stock_qty AS stock_qty, ws.locked_qty AS locked_qty, p.safety_stock_qty AS safety_stock_qty FROM warehouse_stock ws INNER JOIN product p ON ws.product_id = p.id WHERE ws.warehouse_id = 8400000000004000005 AND p.status = 1 AND p.deleted = 0','[{\"name\":\"warehouse_id\",\"label\":\"warehouse_id\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"warehouse_name\",\"label\":\"warehouse_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"product_id\",\"label\":\"product_id\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"product_code\",\"label\":\"product_code\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"product_name\",\"label\":\"product_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"unit_name\",\"label\":\"unit_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"quantity_precision\",\"label\":\"quantity_precision\",\"jdbcType\":-6,\"typeName\":\"TINYINT\",\"nullable\":false},{\"name\":\"stock_qty\",\"label\":\"stock_qty\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"locked_qty\",\"label\":\"locked_qty\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"safety_stock_qty\",\"label\":\"safety_stock_qty\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false}]',305,1,'ds_757f918cd11c498584e099345185423a.jsonl','READY','2026-12-07 00:00:00.000000','2026-11-22 08:26:14.377600','{\"grain\": \"每个仓库×产品一行\", \"fields\": [{\"name\": \"warehouse_id\", \"index\": 0, \"meaning\": \"仓库ID\"}, {\"name\": \"warehouse_name\", \"index\": 1, \"meaning\": \"仓库名称\"}, {\"name\": \"product_id\", \"index\": 2, \"meaning\": \"产品ID\"}, {\"name\": \"product_code\", \"index\": 3, \"meaning\": \"产品编码\"}, {\"name\": \"product_name\", \"index\": 4, \"meaning\": \"产品名称\"}, {\"name\": \"unit_name\", \"index\": 5, \"meaning\": \"计量单位名称\"}, {\"name\": \"quantity_precision\", \"index\": 6, \"meaning\": \"数量小数位精度（0-2）\"}, {\"name\": \"stock_qty\", \"index\": 7, \"meaning\": \"当前库存数量（按100倍整数存储，例如35200表示352.00）\"}, {\"name\": \"locked_qty\", \"index\": 8, \"meaning\": \"锁定库存数量（按100倍整数存储，可用库存=stock_qty-locked_qty）\"}, {\"name\": \"safety_stock_qty\", \"index\": 9, \"meaning\": \"安全库存数量（按100倍整数存储，与stock_qty同口径可直接比较）\"}], \"content\": \"武汉江夏南仓的库存余额明细，仅包含启用且未删除的产品。每行代表该仓库中一个特定产品的当前库存状态，包括账面库存、锁定库存及对应的安全库存阈值。\", \"limitations\": \"\"}',NULL);
INSERT INTO `ai_dataset` (`dataset_id`, `sql_run_id`, `attempt`, `ready_run_id`, `user_id`, `conversation_id`, `description`, `source_sql`, `columns_json`, `row_count`, `completed`, `storage_file`, `status`, `expires_at`, `created_at`, `data_description_json`, `truncation_reason`) VALUES ('ds_76a4d196e568404d9d8a44bd4818eea3','sqlrun_3872abd17a5f4be694e58bc25bb02a21',1,'sqlrun_3872abd17a5f4be694e58bc25bb02a21',1900000000000000001,2124424075508994050,'查询产品 P000005 的全部供应商供货产品记录（含供应商名称、最近成交价、人工报价、最小起订量、最近成交时间、平均到货周期、评分状态、报价有效期），包括供应商状态','SELECT sp.supplier_id AS supplier_id, s.supplier_name AS supplier_name, p.product_code AS product_code, sp.latest_purchase_price / 100.0 AS latest_purchase_price, sp.quoted_purchase_price / 100.0 AS quoted_purchase_price, sp.min_order_qty / 100.0 AS min_order_qty, sp.last_purchase_at AS last_purchase_at, sp.avg_delivery_days AS avg_delivery_days, sp.score_status AS score_status, sp.quote_valid_until AS quote_valid_until, s.status AS supplier_status FROM supplier_product sp JOIN supplier s ON sp.supplier_id = s.id AND s.deleted = 0 JOIN product p ON sp.product_id = p.id AND p.deleted = 0 WHERE sp.deleted = 0 AND p.product_code = \'P000005\'','[{\"name\":\"supplier_id\",\"label\":\"supplier_id\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"supplier_name\",\"label\":\"supplier_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"product_code\",\"label\":\"product_code\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"latest_purchase_price\",\"label\":\"latest_purchase_price\",\"jdbcType\":3,\"typeName\":\"DECIMAL\",\"nullable\":true},{\"name\":\"quoted_purchase_price\",\"label\":\"quoted_purchase_price\",\"jdbcType\":3,\"typeName\":\"DECIMAL\",\"nullable\":true},{\"name\":\"min_order_qty\",\"label\":\"min_order_qty\",\"jdbcType\":3,\"typeName\":\"DECIMAL\",\"nullable\":true},{\"name\":\"last_purchase_at\",\"label\":\"last_purchase_at\",\"jdbcType\":93,\"typeName\":\"DATETIME\",\"nullable\":true},{\"name\":\"avg_delivery_days\",\"label\":\"avg_delivery_days\",\"jdbcType\":3,\"typeName\":\"DECIMAL\",\"nullable\":true},{\"name\":\"score_status\",\"label\":\"score_status\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"quote_valid_until\",\"label\":\"quote_valid_until\",\"jdbcType\":91,\"typeName\":\"DATE\",\"nullable\":true},{\"name\":\"status\",\"label\":\"supplier_status\",\"jdbcType\":-6,\"typeName\":\"TINYINT\",\"nullable\":false}]',1,1,'ds_76a4d196e568404d9d8a44bd4818eea3.jsonl','READY','2026-12-07 00:00:00.000000','2026-11-22 08:48:08.979202','{\"grain\": \"每个供应商-产品组合一行\", \"fields\": [{\"name\": \"supplier_id\", \"index\": 0, \"meaning\": \"供应商ID\"}, {\"name\": \"supplier_name\", \"index\": 1, \"meaning\": \"供应商名称\"}, {\"name\": \"product_code\", \"index\": 2, \"meaning\": \"产品编码\"}, {\"name\": \"latest_purchase_price\", \"index\": 3, \"meaning\": \"最近成交单价（元），由分转换为元\"}, {\"name\": \"quoted_purchase_price\", \"index\": 4, \"meaning\": \"人工有效报价（元），由分转换为元\"}, {\"name\": \"min_order_qty\", \"index\": 5, \"meaning\": \"最小起订量（业务数量），由100倍整数还原\"}, {\"name\": \"last_purchase_at\", \"index\": 6, \"meaning\": \"最近一次已确认采购入库时间\"}, {\"name\": \"avg_delivery_days\", \"index\": 7, \"meaning\": \"最近180天金额加权平均到货周期（天）\"}, {\"name\": \"score_status\", \"index\": 8, \"meaning\": \"评分状态：NOT_READY表示样本不足，READY表示可参与评分\"}, {\"name\": \"quote_valid_until\", \"index\": 9, \"meaning\": \"报价有效截止日\"}, {\"name\": \"supplier_status\", \"index\": 10, \"meaning\": \"供应商状态：1启用，0禁用\"}], \"content\": \"产品 P000005 的供应商供货关系记录，包含供应商名称、最近成交价、人工报价、最小起订量、最近成交时间、平均到货周期、评分状态、报价有效期及供应商状态。\", \"limitations\": \"\"}',NULL);
INSERT INTO `ai_dataset` (`dataset_id`, `sql_run_id`, `attempt`, `ready_run_id`, `user_id`, `conversation_id`, `description`, `source_sql`, `columns_json`, `row_count`, `completed`, `storage_file`, `status`, `expires_at`, `created_at`, `data_description_json`, `truncation_reason`) VALUES ('ds_776cb5755c5145a7861a6323c2367543','sqlrun_a0b0aa56a3644872947f1518f4d66bc8',2,'sqlrun_a0b0aa56a3644872947f1518f4d66bc8',1900000000000000001,2124465547335741442,'统计 outbound_bill 中 outbound_type=\'SALES_OUT\'、status=\'CONFIRMED\'、deleted=0，按 confirmed_at 分两个等长窗口（period=\'CUR\' 为 2026-05-25 至 2026-11-22 含端点，period=\'PRE\' 为 2025-11-23 至 2026-05-24 含端点）。每行输出：单据数（count distinct outbound_bill.id）、数量合计（sum(outbound_bill_item.current_qty)/100）、无单价数量（关联不到 sales_order_item 或 unit_price 为空时该部分 current_qty 的 sum/100）、金额合计（sum(outbound_bill_item.current_qty * sales_order_item.unit_price)/10000，单位元，通过 outbound_bill_item.source_item_id = sales_order_item.id 左关联取单价快照）。全部仓库。','SELECT CASE WHEN ob.confirmed_at >= \'2026-05-25 00:00:00\' AND ob.confirmed_at <= \'2026-11-22 23:59:59\' THEN \'CUR\' ELSE \'PRE\' END AS period, COUNT(DISTINCT ob.id) AS bill_count, SUM(obi.current_qty) / 100.0 AS qty, SUM(CASE WHEN soi.unit_price IS NULL THEN obi.current_qty ELSE 0 END) / 100.0 AS qty_no_price, SUM(obi.current_qty * COALESCE(soi.unit_price, 0)) / 10000.0 AS amount_yuan FROM outbound_bill ob JOIN outbound_bill_item obi ON ob.id = obi.outbound_bill_id JOIN sales_order_item soi ON obi.source_item_id = soi.id WHERE ob.outbound_type = \'SALES_OUT\' AND ob.status = \'CONFIRMED\' AND ob.deleted = 0 AND ((ob.confirmed_at >= \'2026-05-25 00:00:00\' AND ob.confirmed_at <= \'2026-11-22 23:59:59\') OR (ob.confirmed_at >= \'2025-11-23 00:00:00\' AND ob.confirmed_at <= \'2026-05-24 23:59:59\')) GROUP BY CASE WHEN ob.confirmed_at >= \'2026-05-25 00:00:00\' AND ob.confirmed_at <= \'2026-11-22 23:59:59\' THEN \'CUR\' ELSE \'PRE\' END','[{\"name\":\"period\",\"label\":\"period\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"bill_count\",\"label\":\"bill_count\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"qty\",\"label\":\"qty\",\"jdbcType\":3,\"typeName\":\"DECIMAL\",\"nullable\":true},{\"name\":\"qty_no_price\",\"label\":\"qty_no_price\",\"jdbcType\":3,\"typeName\":\"DECIMAL\",\"nullable\":true},{\"name\":\"amount_yuan\",\"label\":\"amount_yuan\",\"jdbcType\":3,\"typeName\":\"DECIMAL\",\"nullable\":true}]',2,1,'ds_776cb5755c5145a7861a6323c2367543.jsonl','READY','2026-12-07 00:00:00.000000','2026-11-22 11:32:49.928891','{\"grain\": \"每个半年时间窗口一行\", \"fields\": [{\"name\": \"period\", \"index\": 0, \"meaning\": \"时间窗口标识：\'CUR\'代表当前半年(2026-05-25至2026-11-22)，\'PRE\'代表前半年(2025-11-23至2026-05-24)\"}, {\"name\": \"bill_count\", \"index\": 1, \"meaning\": \"去重后的出库单据数量\"}, {\"name\": \"qty\", \"index\": 2, \"meaning\": \"出库明细数量合计（业务单位，由存储值/100还原）\"}, {\"name\": \"qty_no_price\", \"index\": 3, \"meaning\": \"关联不到销售订单明细或单价为空的出库明细数量合计（业务单位）\"}, {\"name\": \"amount_yuan\", \"index\": 4, \"meaning\": \"出库金额合计（元），计算方式为 sum(数量*单价)/10000，其中单价来自关联的销售订单明细快照\"}], \"content\": \"统计了2025-11-23至2026-05-24（PRE）和2026-05-25至2026-11-22（CUR）两个半年窗口内，已确认的销售出库单（SALES_OUT, CONFIRMED, deleted=0）的单据数、数量合计、无单价数量及金额合计。\", \"limitations\": \"\"}',NULL);
INSERT INTO `ai_dataset` (`dataset_id`, `sql_run_id`, `attempt`, `ready_run_id`, `user_id`, `conversation_id`, `description`, `source_sql`, `columns_json`, `row_count`, `completed`, `storage_file`, `status`, `expires_at`, `created_at`, `data_description_json`, `truncation_reason`) VALUES ('ds_797888b05dce4dcb89518472fdf93981','sqlrun_0cd815ddf1444720a8b772eb250c16e3',1,'sqlrun_0cd815ddf1444720a8b772eb250c16e3',1900000000000000001,2124364502374834178,'查询采购订单明细表 purchase_order_item 中产品编码为 P000227（最佳选择 全麦饼干）的全部采购明细，返回所属采购单ID与单号、采购数量、已入库数量、单价、金额、创建时间，用于识别历史采购来源和成交价格','SELECT purchase_order_id, purchase_no, product_code, product_name, quantity / 100.0 AS quantity, inbound_qty / 100.0 AS inbound_qty, unit_price / 100.0 AS unit_price, total_amount / 100.0 AS total_amount, create_time FROM purchase_order_item WHERE product_code = \'P000227\'','[{\"name\":\"purchase_order_id\",\"label\":\"purchase_order_id\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"purchase_no\",\"label\":\"purchase_no\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"product_code\",\"label\":\"product_code\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"product_name\",\"label\":\"product_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"quantity\",\"label\":\"quantity\",\"jdbcType\":3,\"typeName\":\"DECIMAL\",\"nullable\":true},{\"name\":\"inbound_qty\",\"label\":\"inbound_qty\",\"jdbcType\":3,\"typeName\":\"DECIMAL\",\"nullable\":true},{\"name\":\"unit_price\",\"label\":\"unit_price\",\"jdbcType\":3,\"typeName\":\"DECIMAL\",\"nullable\":true},{\"name\":\"total_amount\",\"label\":\"total_amount\",\"jdbcType\":3,\"typeName\":\"DECIMAL\",\"nullable\":true},{\"name\":\"create_time\",\"label\":\"create_time\",\"jdbcType\":93,\"typeName\":\"DATETIME\",\"nullable\":false}]',1,1,'ds_797888b05dce4dcb89518472fdf93981.jsonl','READY','2026-12-07 00:00:00.000000','2026-11-22 04:50:21.723584','{\"grain\": \"每条采购订单明细行代表一次具体的采购下单记录。\", \"fields\": [{\"name\": \"purchase_order_id\", \"index\": 0, \"meaning\": \"所属采购订单主表ID\"}, {\"name\": \"purchase_no\", \"index\": 1, \"meaning\": \"采购订单单号\"}, {\"name\": \"product_code\", \"index\": 2, \"meaning\": \"产品编码\"}, {\"name\": \"product_name\", \"index\": 3, \"meaning\": \"产品名称快照\"}, {\"name\": \"quantity\", \"index\": 4, \"meaning\": \"采购数量（业务单位，已从库内×100整数还原）\"}, {\"name\": \"inbound_qty\", \"index\": 5, \"meaning\": \"累计已入库数量（业务单位，已从库内×100整数还原）\"}, {\"name\": \"unit_price\", \"index\": 6, \"meaning\": \"采购单价（元，已从库内分单位还原）\"}, {\"name\": \"total_amount\", \"index\": 7, \"meaning\": \"明细总金额（元，已从库内分单位还原）\"}, {\"name\": \"create_time\", \"index\": 8, \"meaning\": \"明细创建时间\"}], \"content\": \"产品编码 P000227 (最佳选择 全麦饼干) 的历史采购订单明细记录，包含采购来源单据信息及成交数量、价格详情。\", \"limitations\": \"\"}',NULL);
INSERT INTO `ai_dataset` (`dataset_id`, `sql_run_id`, `attempt`, `ready_run_id`, `user_id`, `conversation_id`, `description`, `source_sql`, `columns_json`, `row_count`, `completed`, `storage_file`, `status`, `expires_at`, `created_at`, `data_description_json`, `truncation_reason`) VALUES ('ds_7d3e402f51244b748bd4a310cdc2cba8','sqlrun_e9e210ceb8764b94b9c410b2c0234142',5,'sqlrun_e9e210ceb8764b94b9c410b2c0234142',1900000000000000001,2123852411582849025,'在库存流水明细表 stock_bill_item 中，按 create_time 所在自然月（2026-06 至 2026-11，业务日期截至 2026-11-21）汇总：change_qty 为正的合计（入库）与为负的绝对值合计（出库），用于独立复核近6个月出入库趋势数值。仅使用该单表，不做多表关联。','SELECT DATE_FORMAT(create_time, \'%Y-%m\') AS month_str, SUM(CASE WHEN change_qty > 0 THEN change_qty ELSE 0 END) / 100.0 AS inbound_qty, SUM(CASE WHEN change_qty < 0 THEN -change_qty ELSE 0 END) / 100.0 AS outbound_qty FROM stock_bill_item WHERE create_time >= \'2026-06-01 00:00:00\' AND create_time < \'2026-12-01 00:00:00\' GROUP BY DATE_FORMAT(create_time, \'%Y-%m\') ORDER BY month_str','[{\"name\":\"month_str\",\"label\":\"month_str\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":true},{\"name\":\"inbound_qty\",\"label\":\"inbound_qty\",\"jdbcType\":3,\"typeName\":\"DECIMAL\",\"nullable\":true},{\"name\":\"outbound_qty\",\"label\":\"outbound_qty\",\"jdbcType\":3,\"typeName\":\"DECIMAL\",\"nullable\":true}]',6,1,'ds_7d3e402f51244b748bd4a310cdc2cba8.jsonl','READY','2026-12-05 00:00:00.000000','2026-11-20 18:59:02.159659','{\"grain\": \"每个自然月一行\", \"fields\": [{\"name\": \"month_str\", \"index\": 0, \"meaning\": \"统计月份，格式YYYY-MM\"}, {\"name\": \"inbound_qty\", \"index\": 1, \"meaning\": \"当月入库数量合计（业务单位）\"}, {\"name\": \"outbound_qty\", \"index\": 2, \"meaning\": \"当月出库数量合计（业务单位）\"}], \"content\": \"近6个月（2026-06至2026-11）库存流水明细的月度出入库数量汇总。入库数量为change_qty为正值的合计，出库数量为change_qty为负值的绝对值合计。数值已按业务口径除以100还原。\", \"limitations\": \"数据基于stock_bill_item表的create_time归期。根据通用业务口径，库存事实通常建议按关联单据的confirmed_at归期，但本需求明确指定使用单表且按create_time归期以进行独立复核，故SQL符合特定取数要求。跨单位数量直接求和可能掩盖具体商品构成，仅适用于总量趋势观察。\"}',NULL);
INSERT INTO `ai_dataset` (`dataset_id`, `sql_run_id`, `attempt`, `ready_run_id`, `user_id`, `conversation_id`, `description`, `source_sql`, `columns_json`, `row_count`, `completed`, `storage_file`, `status`, `expires_at`, `created_at`, `data_description_json`, `truncation_reason`) VALUES ('ds_7df4e1cb63d745c38cb39096a2f246a8','sqlrun_f6f5b2b20452463fa64e5b0f8cb2fbbb',1,'sqlrun_f6f5b2b20452463fa64e5b0f8cb2fbbb',1900000000000000001,2124210189346299906,'统计所有未删除采购订单按状态分组（DRAFT、SUBMITTED、APPROVED、PARTIAL_INBOUND、INBOUND_DONE、CANCELLED）的订单数、总金额和预计到货日期区间，用于核实是否存在尚未到货的采购订单','SELECT status AS `状态`, COUNT(id) AS `订单数`, SUM(total_amount) / 100.0 AS `总金额(元)`, MIN(expected_arrival_date) AS `最早预计到货日期`, MAX(expected_arrival_date) AS `最晚预计到货日期` FROM purchase_order WHERE deleted = 0 GROUP BY status','[{\"name\":\"status\",\"label\":\"状态\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"订单数\",\"label\":\"订单数\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"总金额(元)\",\"label\":\"总金额(元)\",\"jdbcType\":3,\"typeName\":\"DECIMAL\",\"nullable\":true},{\"name\":\"最早预计到货日期\",\"label\":\"最早预计到货日期\",\"jdbcType\":91,\"typeName\":\"DATE\",\"nullable\":true},{\"name\":\"最晚预计到货日期\",\"label\":\"最晚预计到货日期\",\"jdbcType\":91,\"typeName\":\"DATE\",\"nullable\":true}]',1,1,'ds_7df4e1cb63d745c38cb39096a2f246a8.jsonl','READY','2026-12-06 00:00:00.000000','2026-11-21 18:36:10.025132','{\"grain\": \"每个采购订单状态一行\", \"fields\": [{\"name\": \"状态\", \"index\": 0, \"meaning\": \"采购订单状态英文枚举值\"}, {\"name\": \"订单数\", \"index\": 1, \"meaning\": \"该状态下的订单数量\"}, {\"name\": \"总金额(元)\", \"index\": 2, \"meaning\": \"该状态下所有订单的总金额合计，单位元（由库内分口径除以100换算）\"}, {\"name\": \"最早预计到货日期\", \"index\": 3, \"meaning\": \"该状态下所有订单中最早的预计到货日期\"}, {\"name\": \"最晚预计到货日期\", \"index\": 4, \"meaning\": \"该状态下所有订单中最晚的预计到货日期\"}], \"content\": \"统计所有未删除采购订单按状态分组的订单数、总金额（元）及预计到货日期区间。当前数据仅包含状态为 INBOUND_DONE 的订单，其他状态无记录。\", \"limitations\": \"样本显示仅有 INBOUND_DONE 状态数据，若业务上预期存在其他状态（如 DRAFT, APPROVED 等）的在途或历史订单，需确认是否因数据缺失或过滤条件导致未返回；总金额已按需求转换为元。\"}',NULL);
INSERT INTO `ai_dataset` (`dataset_id`, `sql_run_id`, `attempt`, `ready_run_id`, `user_id`, `conversation_id`, `description`, `source_sql`, `columns_json`, `row_count`, `completed`, `storage_file`, `status`, `expires_at`, `created_at`, `data_description_json`, `truncation_reason`) VALUES ('ds_7fa8bca3fa54443da9e112765de5fb58','sqlrun_c9934f04e9764eeea0e69e775315de35',1,'sqlrun_c9934f04e9764eeea0e69e775315de35',1900000000000000001,2124364502374834178,'查询采购订单主表 purchase_order 中 id = 8400000000007000227（PO2026110300227，包含 P000227 全麦饼干的采购单）的记录，返回供应商ID与名称、收货仓库、状态、总金额、预计到货日、审核与完全入库时间','SELECT id, purchase_no, supplier_id, supplier_name, warehouse_name, status, total_amount, expected_arrival_date, submitted_at, approved_at, fully_received_at, create_time FROM purchase_order WHERE id = 8400000000007000227 AND deleted = 0','[{\"name\":\"id\",\"label\":\"id\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"purchase_no\",\"label\":\"purchase_no\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"supplier_id\",\"label\":\"supplier_id\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"supplier_name\",\"label\":\"supplier_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"warehouse_name\",\"label\":\"warehouse_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"status\",\"label\":\"status\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"total_amount\",\"label\":\"total_amount\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"expected_arrival_date\",\"label\":\"expected_arrival_date\",\"jdbcType\":91,\"typeName\":\"DATE\",\"nullable\":true},{\"name\":\"submitted_at\",\"label\":\"submitted_at\",\"jdbcType\":93,\"typeName\":\"DATETIME\",\"nullable\":true},{\"name\":\"approved_at\",\"label\":\"approved_at\",\"jdbcType\":93,\"typeName\":\"DATETIME\",\"nullable\":true},{\"name\":\"fully_received_at\",\"label\":\"fully_received_at\",\"jdbcType\":93,\"typeName\":\"DATETIME\",\"nullable\":true},{\"name\":\"create_time\",\"label\":\"create_time\",\"jdbcType\":93,\"typeName\":\"DATETIME\",\"nullable\":false}]',1,1,'ds_7fa8bca3fa54443da9e112765de5fb58.jsonl','READY','2026-12-07 00:00:00.000000','2026-11-22 04:50:34.609904','{\"grain\": \"每行代表一张采购订单主表记录。\", \"fields\": [{\"name\": \"id\", \"index\": 0, \"meaning\": \"采购订单ID\"}, {\"name\": \"purchase_no\", \"index\": 1, \"meaning\": \"采购单号\"}, {\"name\": \"supplier_id\", \"index\": 2, \"meaning\": \"供应商ID\"}, {\"name\": \"supplier_name\", \"index\": 3, \"meaning\": \"供应商名称快照\"}, {\"name\": \"warehouse_name\", \"index\": 4, \"meaning\": \"目标入库仓库名称快照\"}, {\"name\": \"status\", \"index\": 5, \"meaning\": \"订单状态枚举值（如 INBOUND_DONE 表示已入库）\"}, {\"name\": \"total_amount\", \"index\": 6, \"meaning\": \"订单总金额，单位分（×100存储），需除以100得元\"}, {\"name\": \"expected_arrival_date\", \"index\": 7, \"meaning\": \"预计到货日期（承诺日）\"}, {\"name\": \"submitted_at\", \"index\": 8, \"meaning\": \"提交时间\"}, {\"name\": \"approved_at\", \"index\": 9, \"meaning\": \"审核通过时间\"}, {\"name\": \"fully_received_at\", \"index\": 10, \"meaning\": \"整单完全入库的最后一笔确认时间\"}, {\"name\": \"create_time\", \"index\": 11, \"meaning\": \"记录创建时间\"}], \"content\": \"采购订单主表 purchase_order 中 id=8400000000007000227（单号 PO2026110300227）的单条记录，包含供应商、收货仓库、状态、总金额、预计到货日及关键时间节点。\", \"limitations\": \"total_amount 为库内原始整数（单位分），展示时需换算为元；status 为英文枚举，业务含义需按口径映射（INBOUND_DONE=已入库）。\"}',NULL);
INSERT INTO `ai_dataset` (`dataset_id`, `sql_run_id`, `attempt`, `ready_run_id`, `user_id`, `conversation_id`, `description`, `source_sql`, `columns_json`, `row_count`, `completed`, `storage_file`, `status`, `expires_at`, `created_at`, `data_description_json`, `truncation_reason`) VALUES ('ds_829ecd8fec7745e98e8d30918f3934eb','sqlrun_54fea6e440454cca876b819a327f229d',1,'sqlrun_54fea6e440454cca876b819a327f229d',1900000000000000001,2124424075508994050,'查询全部未删除的仓库（含启用/禁用状态），用于确认产品 P000005 仅在哪些仓有库存记录，其余仓视为0','SELECT id AS warehouse_id, warehouse_name, status FROM warehouse WHERE deleted = 0','[{\"name\":\"id\",\"label\":\"warehouse_id\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"warehouse_name\",\"label\":\"warehouse_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"status\",\"label\":\"status\",\"jdbcType\":-6,\"typeName\":\"TINYINT\",\"nullable\":false}]',5,1,'ds_829ecd8fec7745e98e8d30918f3934eb.jsonl','READY','2026-12-07 00:00:00.000000','2026-11-22 08:48:59.439455','{\"grain\": \"每个仓库一行\", \"fields\": [{\"name\": \"warehouse_id\", \"index\": 0, \"meaning\": \"仓库ID\"}, {\"name\": \"warehouse_name\", \"index\": 1, \"meaning\": \"仓库名称\"}, {\"name\": \"status\", \"index\": 2, \"meaning\": \"仓库状态：1表示启用，0表示禁用\"}], \"content\": \"全部未逻辑删除的仓库主档信息，用于核对产品P000005的库存分布范围。\", \"limitations\": \"\"}',NULL);
INSERT INTO `ai_dataset` (`dataset_id`, `sql_run_id`, `attempt`, `ready_run_id`, `user_id`, `conversation_id`, `description`, `source_sql`, `columns_json`, `row_count`, `completed`, `storage_file`, `status`, `expires_at`, `created_at`, `data_description_json`, `truncation_reason`) VALUES ('ds_86a31f4a22fe46b4a1fac632a996c2d1','sqlrun_3c461d81c5204938bc3f7ca19cdc3f6b',1,'sqlrun_3c461d81c5204938bc3f7ca19cdc3f6b',1900000000000000001,2124421893103570946,'查询产品编码 P000173 在各仓库的库存余额：仓库名称、库存数量（100倍整数）、锁定数量（100倍整数）','SELECT ws.warehouse_id AS warehouse_id, ws.warehouse_name AS warehouse_name, ws.product_code AS product_code, ws.stock_qty AS stock_qty, ws.locked_qty AS locked_qty FROM warehouse_stock ws WHERE ws.product_code = \'P000173\'','[{\"name\":\"warehouse_id\",\"label\":\"warehouse_id\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"warehouse_name\",\"label\":\"warehouse_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"product_code\",\"label\":\"product_code\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"stock_qty\",\"label\":\"stock_qty\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"locked_qty\",\"label\":\"locked_qty\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false}]',1,1,'ds_86a31f4a22fe46b4a1fac632a996c2d1.jsonl','READY','2026-12-07 00:00:00.000000','2026-11-22 08:37:26.463241','{\"grain\": \"每个仓库针对该产品的一行库存快照记录\", \"fields\": [{\"name\": \"warehouse_id\", \"index\": 0, \"meaning\": \"仓库唯一标识ID\"}, {\"name\": \"warehouse_name\", \"index\": 1, \"meaning\": \"仓库名称\"}, {\"name\": \"product_code\", \"index\": 2, \"meaning\": \"产品编码\"}, {\"name\": \"stock_qty\", \"index\": 3, \"meaning\": \"当前库存数量，按100倍整数存储（例如140500表示1405.00袋）\"}, {\"name\": \"locked_qty\", \"index\": 4, \"meaning\": \"锁定库存数量，按100倍整数存储（可用库存 = stock_qty - locked_qty）\"}], \"content\": \"产品编码为 P000173 的所有仓库库存余额记录，包括账面库存和锁定库存。\", \"limitations\": \"\"}',NULL);
INSERT INTO `ai_dataset` (`dataset_id`, `sql_run_id`, `attempt`, `ready_run_id`, `user_id`, `conversation_id`, `description`, `source_sql`, `columns_json`, `row_count`, `completed`, `storage_file`, `status`, `expires_at`, `created_at`, `data_description_json`, `truncation_reason`) VALUES ('ds_87505fad32cd4d28a7561ac33c2cbd22','sqlrun_d5209c14dfbb4ceba33bb4931d2ab1f7',1,'sqlrun_d5209c14dfbb4ceba33bb4931d2ab1f7',1900000000000000001,2124423434279604226,'查询产品编码 P000005 在各仓库的当前库存余额：库存数量、锁定数量、可用库存，用于判断活动可承接供给上限','SELECT ws.warehouse_name AS warehouse_name, ws.stock_qty / 100.0 AS stock_qty, ws.locked_qty / 100.0 AS locked_qty, (ws.stock_qty - ws.locked_qty) / 100.0 AS available_stock FROM warehouse_stock ws WHERE ws.product_code = \'P000005\'','[{\"name\":\"warehouse_name\",\"label\":\"warehouse_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"stock_qty\",\"label\":\"stock_qty\",\"jdbcType\":3,\"typeName\":\"DECIMAL\",\"nullable\":true},{\"name\":\"locked_qty\",\"label\":\"locked_qty\",\"jdbcType\":3,\"typeName\":\"DECIMAL\",\"nullable\":true},{\"name\":\"available_stock\",\"label\":\"available_stock\",\"jdbcType\":3,\"typeName\":\"DECIMAL\",\"nullable\":true}]',3,1,'ds_87505fad32cd4d28a7561ac33c2cbd22.jsonl','READY','2026-12-07 00:00:00.000000','2026-11-22 08:43:51.045075','{\"grain\": \"每行代表一个特定仓库中该产品的一条库存记录。\", \"fields\": [{\"name\": \"warehouse_name\", \"index\": 0, \"meaning\": \"仓库名称\"}, {\"name\": \"stock_qty\", \"index\": 1, \"meaning\": \"当前库存数量（业务单位，已从数据库放大值还原）\"}, {\"name\": \"locked_qty\", \"index\": 2, \"meaning\": \"锁定库存数量（业务单位，已从数据库放大值还原）\"}, {\"name\": \"available_stock\", \"index\": 3, \"meaning\": \"可用库存数量（业务单位，等于库存数量减去锁定数量）\"}], \"content\": \"产品编码 P000005 在所有仓库中的当前库存状态，包括账面库存、已锁定库存及计算得出的可用库存。\", \"limitations\": \"\"}',NULL);
INSERT INTO `ai_dataset` (`dataset_id`, `sql_run_id`, `attempt`, `ready_run_id`, `user_id`, `conversation_id`, `description`, `source_sql`, `columns_json`, `row_count`, `completed`, `storage_file`, `status`, `expires_at`, `created_at`, `data_description_json`, `truncation_reason`) VALUES ('ds_87b7db8554a144b097b0957b92535283','sqlrun_31cc27bc138a414a8ffbb3dbdf11c640',1,'sqlrun_31cc27bc138a414a8ffbb3dbdf11c640',1900000000000000001,2124761984778977281,'查询产品ID 8400000000005001253（编码P001253）在所有仓库的库存余额记录，包括仓库ID、仓库名称、库存数量、锁定数量','SELECT ws.warehouse_id AS warehouse_id, w.warehouse_name AS warehouse_name, ws.product_id AS product_id, ws.product_code AS product_code, p.product_name AS product_name, ws.unit_name AS unit_name, ws.stock_qty / 100.0 AS stock_qty, ws.locked_qty / 100.0 AS locked_qty FROM warehouse_stock ws JOIN warehouse w ON ws.warehouse_id = w.id AND w.deleted = 0 JOIN product p ON ws.product_id = p.id AND p.deleted = 0 WHERE ws.product_id = 8400000000005001253','[{\"name\":\"warehouse_id\",\"label\":\"warehouse_id\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"warehouse_name\",\"label\":\"warehouse_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"product_id\",\"label\":\"product_id\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"product_code\",\"label\":\"product_code\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"product_name\",\"label\":\"product_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"unit_name\",\"label\":\"unit_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"stock_qty\",\"label\":\"stock_qty\",\"jdbcType\":3,\"typeName\":\"DECIMAL\",\"nullable\":true},{\"name\":\"locked_qty\",\"label\":\"locked_qty\",\"jdbcType\":3,\"typeName\":\"DECIMAL\",\"nullable\":true}]',1,1,'ds_87b7db8554a144b097b0957b92535283.jsonl','READY','2026-12-08 00:00:00.000000','2026-11-23 07:09:26.626461','{\"grain\": \"每个仓库×产品一行\", \"fields\": [{\"name\": \"warehouse_id\", \"index\": 0, \"meaning\": \"仓库ID\"}, {\"name\": \"warehouse_name\", \"index\": 1, \"meaning\": \"仓库名称\"}, {\"name\": \"product_id\", \"index\": 2, \"meaning\": \"产品ID\"}, {\"name\": \"product_code\", \"index\": 3, \"meaning\": \"产品编码\"}, {\"name\": \"product_name\", \"index\": 4, \"meaning\": \"产品名称\"}, {\"name\": \"unit_name\", \"index\": 5, \"meaning\": \"单位名称\"}, {\"name\": \"stock_qty\", \"index\": 6, \"meaning\": \"当前库存数量（业务口径，已除以100还原）\"}, {\"name\": \"locked_qty\", \"index\": 7, \"meaning\": \"锁定库存数量（业务口径，已除以100还原）\"}], \"content\": \"产品ID 8400000000005001253（编码P001253）在所有仓库的库存余额记录，包含仓库ID、仓库名称、产品ID、产品编码、产品名称、单位、库存数量（已换算为业务数量）、锁定数量（已换算为业务数量）。\", \"limitations\": \"\"}',NULL);
INSERT INTO `ai_dataset` (`dataset_id`, `sql_run_id`, `attempt`, `ready_run_id`, `user_id`, `conversation_id`, `description`, `source_sql`, `columns_json`, `row_count`, `completed`, `storage_file`, `status`, `expires_at`, `created_at`, `data_description_json`, `truncation_reason`) VALUES ('ds_88ee4fcab427438d972edd2bb390a87d','sqlrun_93d78336e646472286a2a593e4739b3c',1,'sqlrun_93d78336e646472286a2a593e4739b3c',1900000000000000001,2124210189346299906,'取预计到货日期最近的 20 张采购订单，关注预计到货日期、完全入库时间与实际到货是否有延迟，用于定位用户所指“要晚到”的采购批次','SELECT po.purchase_no AS `采购单号`, po.supplier_name AS `供应商名称`, po.warehouse_name AS `目标入库仓库`, po.status AS `状态`, po.expected_arrival_date AS `预计到货日期`, po.fully_received_at AS `完全入库时间`, po.total_amount / 100.0 AS `订单总金额(元)` FROM purchase_order po WHERE po.deleted = 0 AND po.status NOT IN (\'DRAFT\', \'CANCELLED\') ORDER BY po.expected_arrival_date ASC LIMIT 20','[{\"name\":\"purchase_no\",\"label\":\"采购单号\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"supplier_name\",\"label\":\"供应商名称\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"warehouse_name\",\"label\":\"目标入库仓库\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"status\",\"label\":\"状态\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"expected_arrival_date\",\"label\":\"预计到货日期\",\"jdbcType\":91,\"typeName\":\"DATE\",\"nullable\":true},{\"name\":\"fully_received_at\",\"label\":\"完全入库时间\",\"jdbcType\":93,\"typeName\":\"DATETIME\",\"nullable\":true},{\"name\":\"订单总金额(元)\",\"label\":\"订单总金额(元)\",\"jdbcType\":3,\"typeName\":\"DECIMAL\",\"nullable\":true}]',20,1,'ds_88ee4fcab427438d972edd2bb390a87d.jsonl','READY','2026-12-06 00:00:00.000000','2026-11-21 18:36:43.264179','{\"grain\": \"每张采购订单一行\", \"fields\": [{\"name\": \"采购单号\", \"index\": 0, \"meaning\": \"采购单号\"}, {\"name\": \"供应商名称\", \"index\": 1, \"meaning\": \"供应商名称快照\"}, {\"name\": \"目标入库仓库\", \"index\": 2, \"meaning\": \"目标入库仓库名称快照\"}, {\"name\": \"状态\", \"index\": 3, \"meaning\": \"订单状态（英文枚举，如 INBOUND_DONE）\"}, {\"name\": \"预计到货日期\", \"index\": 4, \"meaning\": \"预计到货日期\"}, {\"name\": \"完全入库时间\", \"index\": 5, \"meaning\": \"完全入库时间（最后一笔入库确认时间，未完成时为空）\"}, {\"name\": \"订单总金额(元)\", \"index\": 6, \"meaning\": \"订单总金额（单位：元，由库内分值除以100换算）\"}], \"content\": \"预计到货日期最近的20张有效采购订单明细，用于定位可能延迟的批次。\", \"limitations\": \"仅返回前20条记录，不代表全部数据；未直接计算延迟天数，需结合当前日期与完全入库时间对比判断。\"}',NULL);
INSERT INTO `ai_dataset` (`dataset_id`, `sql_run_id`, `attempt`, `ready_run_id`, `user_id`, `conversation_id`, `description`, `source_sql`, `columns_json`, `row_count`, `completed`, `storage_file`, `status`, `expires_at`, `created_at`, `data_description_json`, `truncation_reason`) VALUES ('ds_8964279acc574a78a384afdf26287248','sqlrun_78d9098d26e74a70807f11afcb9f5abe',1,'sqlrun_78d9098d26e74a70807f11afcb9f5abe',1900000000000000001,2124221025439735809,'查询全部启用且未删除（status=1, deleted=0）产品主档的全量记录，返回产品ID、编码、名称、分类ID、单位、数量精度、安全库存safety_stock_qty（100倍整数原值）、参考采购价、参考销售价（元）','SELECT id AS product_id, product_code, product_name, category_id, unit_name, quantity_precision, safety_stock_qty, reference_purchase_price, reference_sale_price, status FROM product WHERE deleted = 0 AND status = 1','[{\"name\":\"id\",\"label\":\"product_id\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"product_code\",\"label\":\"product_code\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"product_name\",\"label\":\"product_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"category_id\",\"label\":\"category_id\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":true},{\"name\":\"unit_name\",\"label\":\"unit_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"quantity_precision\",\"label\":\"quantity_precision\",\"jdbcType\":-6,\"typeName\":\"TINYINT\",\"nullable\":false},{\"name\":\"safety_stock_qty\",\"label\":\"safety_stock_qty\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"reference_purchase_price\",\"label\":\"reference_purchase_price\",\"jdbcType\":3,\"typeName\":\"DECIMAL\",\"nullable\":false},{\"name\":\"reference_sale_price\",\"label\":\"reference_sale_price\",\"jdbcType\":3,\"typeName\":\"DECIMAL\",\"nullable\":false},{\"name\":\"status\",\"label\":\"status\",\"jdbcType\":-6,\"typeName\":\"TINYINT\",\"nullable\":false}]',1560,1,'ds_8964279acc574a78a384afdf26287248.jsonl','READY','2026-12-06 00:00:00.000000','2026-11-21 19:21:02.451260','{\"grain\": \"每个产品一行\", \"fields\": [{\"name\": \"product_id\", \"index\": 0, \"meaning\": \"产品ID\"}, {\"name\": \"product_code\", \"index\": 1, \"meaning\": \"产品编码\"}, {\"name\": \"product_name\", \"index\": 2, \"meaning\": \"产品名称\"}, {\"name\": \"category_id\", \"index\": 3, \"meaning\": \"产品分类ID\"}, {\"name\": \"unit_name\", \"index\": 4, \"meaning\": \"单位名称\"}, {\"name\": \"quantity_precision\", \"index\": 5, \"meaning\": \"数量小数位精度（0-2）\"}, {\"name\": \"safety_stock_qty\", \"index\": 6, \"meaning\": \"安全库存数量，按100倍整数存储的原值\"}, {\"name\": \"reference_purchase_price\", \"index\": 7, \"meaning\": \"参考采购价，单位元\"}, {\"name\": \"reference_sale_price\", \"index\": 8, \"meaning\": \"参考销售价，单位元\"}, {\"name\": \"status\", \"index\": 9, \"meaning\": \"产品状态：1启用\"}], \"content\": \"全部启用且未删除的产品主档记录，包含产品ID、编码、名称、分类ID、单位、数量精度、安全库存（100倍整数原值）、参考采购价（元）、参考销售价（元）及状态。\", \"limitations\": \"\"}',NULL);
INSERT INTO `ai_dataset` (`dataset_id`, `sql_run_id`, `attempt`, `ready_run_id`, `user_id`, `conversation_id`, `description`, `source_sql`, `columns_json`, `row_count`, `completed`, `storage_file`, `status`, `expires_at`, `created_at`, `data_description_json`, `truncation_reason`) VALUES ('ds_8aaf771483a54da49ecd400706c7db18','sqlrun_880b00825da14e7f8a8f379d65b9eab9',1,'sqlrun_880b00825da14e7f8a8f379d65b9eab9',1900000000000000001,2124420137200144385,'查询产品 P001143（product_id=8400000000005001143）的全部采购订单明细行，不限时间、不限供应商（覆盖所有供应商），包含已取消、部分入库、在途订单，字段包括供应商、采购单号、状态、审核时间、完全入库时间、预计到货日、采购数量、已入库数量、单价、明细金额；用于核实该产品历史是否只有一家供应商实际供货及是否存在在途订单','SELECT \n    po.supplier_id,\n    po.supplier_code,\n    po.supplier_name,\n    po.purchase_no,\n    po.status,\n    po.approved_at,\n    po.fully_received_at,\n    po.expected_arrival_date,\n    poi.quantity / 100.0 AS quantity,\n    poi.inbound_qty / 100.0 AS inbound_qty,\n    poi.unit_price / 100.0 AS unit_price,\n    poi.total_amount / 100.0 AS total_amount\nFROM purchase_order po\nJOIN purchase_order_item poi ON po.id = poi.purchase_order_id\nWHERE po.deleted = 0\n  AND poi.product_id = 8400000000005001143','[{\"name\":\"supplier_id\",\"label\":\"supplier_id\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"supplier_code\",\"label\":\"supplier_code\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"supplier_name\",\"label\":\"supplier_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"purchase_no\",\"label\":\"purchase_no\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"status\",\"label\":\"status\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"approved_at\",\"label\":\"approved_at\",\"jdbcType\":93,\"typeName\":\"DATETIME\",\"nullable\":true},{\"name\":\"fully_received_at\",\"label\":\"fully_received_at\",\"jdbcType\":93,\"typeName\":\"DATETIME\",\"nullable\":true},{\"name\":\"expected_arrival_date\",\"label\":\"expected_arrival_date\",\"jdbcType\":91,\"typeName\":\"DATE\",\"nullable\":true},{\"name\":\"quantity\",\"label\":\"quantity\",\"jdbcType\":3,\"typeName\":\"DECIMAL\",\"nullable\":true},{\"name\":\"inbound_qty\",\"label\":\"inbound_qty\",\"jdbcType\":3,\"typeName\":\"DECIMAL\",\"nullable\":true},{\"name\":\"unit_price\",\"label\":\"unit_price\",\"jdbcType\":3,\"typeName\":\"DECIMAL\",\"nullable\":true},{\"name\":\"total_amount\",\"label\":\"total_amount\",\"jdbcType\":3,\"typeName\":\"DECIMAL\",\"nullable\":true}]',4,1,'ds_8aaf771483a54da49ecd400706c7db18.jsonl','READY','2026-12-07 00:00:00.000000','2026-11-22 08:31:35.628972','{\"grain\": \"每个采购订单明细行一行\", \"fields\": [{\"name\": \"supplier_id\", \"index\": 0, \"meaning\": \"供应商ID\"}, {\"name\": \"supplier_code\", \"index\": 1, \"meaning\": \"供应商编码\"}, {\"name\": \"supplier_name\", \"index\": 2, \"meaning\": \"供应商名称\"}, {\"name\": \"purchase_no\", \"index\": 3, \"meaning\": \"采购单号\"}, {\"name\": \"status\", \"index\": 4, \"meaning\": \"采购订单状态 (如 INBOUND_DONE)\"}, {\"name\": \"approved_at\", \"index\": 5, \"meaning\": \"审核时间\"}, {\"name\": \"fully_received_at\", \"index\": 6, \"meaning\": \"完全入库时间\"}, {\"name\": \"expected_arrival_date\", \"index\": 7, \"meaning\": \"预计到货日期\"}, {\"name\": \"quantity\", \"index\": 8, \"meaning\": \"采购数量 (业务单位，已还原)\"}, {\"name\": \"inbound_qty\", \"index\": 9, \"meaning\": \"已入库数量 (业务单位，已还原)\"}, {\"name\": \"unit_price\", \"index\": 10, \"meaning\": \"单价 (元，已还原)\"}, {\"name\": \"total_amount\", \"index\": 11, \"meaning\": \"明细总金额 (元，已还原)\"}], \"content\": \"产品 P001143 的所有采购订单明细行，涵盖不同时间段的采购记录，用于分析供应商覆盖及供货状态。\", \"limitations\": \"\"}',NULL);
INSERT INTO `ai_dataset` (`dataset_id`, `sql_run_id`, `attempt`, `ready_run_id`, `user_id`, `conversation_id`, `description`, `source_sql`, `columns_json`, `row_count`, `completed`, `storage_file`, `status`, `expires_at`, `created_at`, `data_description_json`, `truncation_reason`) VALUES ('ds_92ea43a53e304696a82cf1d5a0115433','sqlrun_09bc0395d2d7465083fcdbc6b78d24e1',1,'sqlrun_09bc0395d2d7465083fcdbc6b78d24e1',1900000000000000001,2124418644136972290,'查询 warehouse_id = 8400000000004000001（上海浦东中心仓）的全部 warehouse_stock 库存余额记录，关联 product 取产品编码、产品名称、单位、quantity_precision、safety_stock_qty，仅保留 product.status=1 且 product.deleted=0 的产品。每行一个仓库×产品，含 stock_qty、locked_qty（100倍整数）','SELECT ws.warehouse_id AS warehouse_id, ws.warehouse_name AS warehouse_name, ws.product_id AS product_id, p.product_code AS product_code, p.product_name AS product_name, p.unit_name AS unit_name, p.quantity_precision AS quantity_precision, ws.stock_qty AS stock_qty, ws.locked_qty AS locked_qty, p.safety_stock_qty AS safety_stock_qty FROM warehouse_stock ws JOIN product p ON ws.product_id = p.id WHERE ws.warehouse_id = 8400000000004000001 AND p.status = 1 AND p.deleted = 0','[{\"name\":\"warehouse_id\",\"label\":\"warehouse_id\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"warehouse_name\",\"label\":\"warehouse_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"product_id\",\"label\":\"product_id\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"product_code\",\"label\":\"product_code\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"product_name\",\"label\":\"product_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"unit_name\",\"label\":\"unit_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"quantity_precision\",\"label\":\"quantity_precision\",\"jdbcType\":-6,\"typeName\":\"TINYINT\",\"nullable\":false},{\"name\":\"stock_qty\",\"label\":\"stock_qty\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"locked_qty\",\"label\":\"locked_qty\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"safety_stock_qty\",\"label\":\"safety_stock_qty\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false}]',563,1,'ds_92ea43a53e304696a82cf1d5a0115433.jsonl','READY','2026-12-07 00:00:00.000000','2026-11-22 08:25:23.885903','{\"grain\": \"每个仓库×产品一行\", \"fields\": [{\"name\": \"warehouse_id\", \"index\": 0, \"meaning\": \"仓库ID\"}, {\"name\": \"warehouse_name\", \"index\": 1, \"meaning\": \"仓库名称\"}, {\"name\": \"product_id\", \"index\": 2, \"meaning\": \"产品ID\"}, {\"name\": \"product_code\", \"index\": 3, \"meaning\": \"产品编码\"}, {\"name\": \"product_name\", \"index\": 4, \"meaning\": \"产品名称\"}, {\"name\": \"unit_name\", \"index\": 5, \"meaning\": \"单位名称\"}, {\"name\": \"quantity_precision\", \"index\": 6, \"meaning\": \"数量小数位精度（0-2）\"}, {\"name\": \"stock_qty\", \"index\": 7, \"meaning\": \"当前库存数量（100倍整数存储，即实际数量*100）\"}, {\"name\": \"locked_qty\", \"index\": 8, \"meaning\": \"锁定库存数量（100倍整数存储，即实际数量*100）\"}, {\"name\": \"safety_stock_qty\", \"index\": 9, \"meaning\": \"安全库存数量（100倍整数存储，即实际数量*100）\"}], \"content\": \"上海浦东中心仓的库存余额明细，仅包含状态为启用且未逻辑删除的产品。每行代表一个仓库-产品组合的当前库存快照。\", \"limitations\": \"\"}',NULL);
INSERT INTO `ai_dataset` (`dataset_id`, `sql_run_id`, `attempt`, `ready_run_id`, `user_id`, `conversation_id`, `description`, `source_sql`, `columns_json`, `row_count`, `completed`, `storage_file`, `status`, `expires_at`, `created_at`, `data_description_json`, `truncation_reason`) VALUES ('ds_93d4aad8ec01475c83bcd0da6ad3aae5','sqlrun_49ca29b6095d4a38bf1d9f82dc1d04fa',1,'sqlrun_49ca29b6095d4a38bf1d9f82dc1d04fa',1900000000000000001,2124421893103570946,'查询产品ID 8400000000005000173（P000173）在统一退货单明细表中的全部退货明细行，只限该产品，不限退货类型和状态，逐行返回：退货单ID、产品编码、单位、数量精度、申请退货数量requested_qty（100倍）、审核通过数量approved_qty（100倍）、已处理数量processed_qty（100倍）、单价unit_price（分）。','SELECT roi.return_order_id AS return_order_id, roi.product_code AS product_code, roi.unit_name AS unit_name, roi.quantity_precision AS quantity_precision, roi.requested_qty AS requested_qty, roi.approved_qty AS approved_qty, roi.processed_qty AS processed_qty, roi.unit_price AS unit_price FROM return_order_item roi WHERE roi.product_id = 8400000000005000173','[{\"name\":\"return_order_id\",\"label\":\"return_order_id\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"product_code\",\"label\":\"product_code\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"unit_name\",\"label\":\"unit_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"quantity_precision\",\"label\":\"quantity_precision\",\"jdbcType\":-6,\"typeName\":\"TINYINT\",\"nullable\":false},{\"name\":\"requested_qty\",\"label\":\"requested_qty\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"approved_qty\",\"label\":\"approved_qty\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"processed_qty\",\"label\":\"processed_qty\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"unit_price\",\"label\":\"unit_price\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false}]',0,1,'ds_93d4aad8ec01475c83bcd0da6ad3aae5.jsonl','READY','2026-12-07 00:00:00.000000','2026-11-22 08:39:49.383042','{\"grain\": \"每行代表一条针对该特定产品的退货单明细记录。\", \"fields\": [{\"name\": \"return_order_id\", \"index\": 0, \"meaning\": \"关联的退货单主表ID\"}, {\"name\": \"product_code\", \"index\": 1, \"meaning\": \"产品编码快照\"}, {\"name\": \"unit_name\", \"index\": 2, \"meaning\": \"单位名称快照\"}, {\"name\": \"quantity_precision\", \"index\": 3, \"meaning\": \"数量小数位精度快照（0-2）\"}, {\"name\": \"requested_qty\", \"index\": 4, \"meaning\": \"申请退货数量（存储值为实际数量的100倍）\"}, {\"name\": \"approved_qty\", \"index\": 5, \"meaning\": \"审核通过数量（存储值为实际数量的100倍）\"}, {\"name\": \"processed_qty\", \"index\": 6, \"meaning\": \"仓库累计确认的实际处理总量（存储值为实际数量的100倍）\"}, {\"name\": \"unit_price\", \"index\": 7, \"meaning\": \"原订单明细单价快照（单位：分）\"}], \"content\": \"产品P000173（ID: 8400000000005000173）在统一退货单明细表中的所有退货明细记录，包含申请、审核通过及已处理的数量和单价信息。\", \"limitations\": \"无数据返回，表明该产品目前没有相关的退货明细记录。\"}',NULL);
INSERT INTO `ai_dataset` (`dataset_id`, `sql_run_id`, `attempt`, `ready_run_id`, `user_id`, `conversation_id`, `description`, `source_sql`, `columns_json`, `row_count`, `completed`, `storage_file`, `status`, `expires_at`, `created_at`, `data_description_json`, `truncation_reason`) VALUES ('ds_98a610232bd842c6acb4363d3a4c6860','sqlrun_e9661f4a53464dbe89fdb09be9a88bff',1,'sqlrun_e9661f4a53464dbe89fdb09be9a88bff',1900000000000000001,2124424075508994050,'查询产品 P000005（果沁 碳酸饮料礼盒装）在成都双流西仓（warehouse_id=8400000000004000004）的所有未完成销售订单明细：订单状态不为 CANCELLED、订单未删除、且明细尚未完全出库（outbound_qty < quantity，包含 DRAFT/SUBMITTED/APPROVED/PARTIAL_OUTBOUND 各状态），返回销售单号、订单状态、仓库、客户、销售数量、已锁定数量、已出库数量、未出库数量、单价、预计发货日期、审核时间','SELECT so.sales_no AS sales_no, so.status AS status, so.warehouse_name AS warehouse_name, so.customer_name AS customer_name, soi.quantity / 100.0 AS quantity, soi.locked_qty / 100.0 AS locked_qty, soi.outbound_qty / 100.0 AS outbound_qty, (soi.quantity - soi.outbound_qty) / 100.0 AS unshipped_qty, soi.unit_price / 100.0 AS unit_price, so.expected_delivery_date AS expected_delivery_date, so.approved_at AS approved_at FROM sales_order so JOIN sales_order_item soi ON so.id = soi.sales_order_id WHERE so.deleted = 0 AND so.warehouse_id = 8400000000004000004 AND so.status != \'CANCELLED\' AND soi.product_code = \'P000005\' AND soi.outbound_qty < soi.quantity','[{\"name\":\"sales_no\",\"label\":\"sales_no\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"status\",\"label\":\"status\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"warehouse_name\",\"label\":\"warehouse_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"customer_name\",\"label\":\"customer_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"quantity\",\"label\":\"quantity\",\"jdbcType\":3,\"typeName\":\"DECIMAL\",\"nullable\":true},{\"name\":\"locked_qty\",\"label\":\"locked_qty\",\"jdbcType\":3,\"typeName\":\"DECIMAL\",\"nullable\":true},{\"name\":\"outbound_qty\",\"label\":\"outbound_qty\",\"jdbcType\":3,\"typeName\":\"DECIMAL\",\"nullable\":true},{\"name\":\"unshipped_qty\",\"label\":\"unshipped_qty\",\"jdbcType\":3,\"typeName\":\"DECIMAL\",\"nullable\":true},{\"name\":\"unit_price\",\"label\":\"unit_price\",\"jdbcType\":3,\"typeName\":\"DECIMAL\",\"nullable\":true},{\"name\":\"expected_delivery_date\",\"label\":\"expected_delivery_date\",\"jdbcType\":91,\"typeName\":\"DATE\",\"nullable\":true},{\"name\":\"approved_at\",\"label\":\"approved_at\",\"jdbcType\":93,\"typeName\":\"DATETIME\",\"nullable\":true}]',0,1,'ds_98a610232bd842c6acb4363d3a4c6860.jsonl','READY','2026-12-07 00:00:00.000000','2026-11-22 08:47:15.428026','{\"grain\": \"每笔符合条件的销售订单明细一行\", \"fields\": [{\"name\": \"sales_no\", \"index\": 0, \"meaning\": \"销售单号\"}, {\"name\": \"status\", \"index\": 1, \"meaning\": \"订单状态\"}, {\"name\": \"warehouse_name\", \"index\": 2, \"meaning\": \"仓库名称\"}, {\"name\": \"customer_name\", \"index\": 3, \"meaning\": \"客户名称\"}, {\"name\": \"quantity\", \"index\": 4, \"meaning\": \"销售数量（已还原为业务单位）\"}, {\"name\": \"locked_qty\", \"index\": 5, \"meaning\": \"已锁定库存数量（已还原为业务单位）\"}, {\"name\": \"outbound_qty\", \"index\": 6, \"meaning\": \"已出库数量（已还原为业务单位）\"}, {\"name\": \"unshipped_qty\", \"index\": 7, \"meaning\": \"未出库数量（计算字段：销售数量-已出库数量，已还原为业务单位）\"}, {\"name\": \"unit_price\", \"index\": 8, \"meaning\": \"销售单价（元）\"}, {\"name\": \"expected_delivery_date\", \"index\": 9, \"meaning\": \"预计发货日期\"}, {\"name\": \"approved_at\", \"index\": 10, \"meaning\": \"审核时间\"}], \"content\": \"成都双流西仓产品P000005的未完成销售订单明细查询结果（当前无数据）\", \"limitations\": \"\"}',NULL);
INSERT INTO `ai_dataset` (`dataset_id`, `sql_run_id`, `attempt`, `ready_run_id`, `user_id`, `conversation_id`, `description`, `source_sql`, `columns_json`, `row_count`, `completed`, `storage_file`, `status`, `expires_at`, `created_at`, `data_description_json`, `truncation_reason`) VALUES ('ds_9e30225207004b52977d68cad1396a85','sqlrun_84c9db4ba4bd4c99860713132aace122',1,'sqlrun_84c9db4ba4bd4c99860713132aace122',1900000000000000001,2124465547335741442,'统计 inbound_bill 中 inbound_type=\'PURCHASE_IN\'、status=\'CONFIRMED\'、deleted=0，confirmed_at 落在两个等长窗口内的采购入库规模，分两行输出：period=\'CUR\' 对应 2026-05-25 至 2026-11-22（含端点），period=\'PRE\' 对应 2025-11-23 至 2026-05-24（含端点）。每行给出单据数（count distinct inbound_bill.id）、数量合计（inbound_bill_item.current_qty 的 sum 除以 100 得业务数量）、金额合计（sum(current_qty*unit_price)/10000 得元）。全部仓库。','SELECT CASE WHEN ib.confirmed_at >= \'2026-05-25 00:00:00\' AND ib.confirmed_at <= \'2026-11-22 23:59:59\' THEN \'CUR\' ELSE \'PRE\' END AS period, COUNT(DISTINCT ib.id) AS bill_count, SUM(ibi.current_qty) / 100.0 AS qty, SUM(ibi.current_qty * ibi.unit_price) / 10000.0 AS amount_yuan FROM inbound_bill ib INNER JOIN inbound_bill_item ibi ON ib.id = ibi.inbound_bill_id WHERE ib.inbound_type = \'PURCHASE_IN\' AND ib.status = \'CONFIRMED\' AND ib.deleted = 0 AND ((ib.confirmed_at >= \'2026-05-25 00:00:00\' AND ib.confirmed_at <= \'2026-11-22 23:59:59\') OR (ib.confirmed_at >= \'2025-11-23 00:00:00\' AND ib.confirmed_at <= \'2026-05-24 23:59:59\')) GROUP BY CASE WHEN ib.confirmed_at >= \'2026-05-25 00:00:00\' AND ib.confirmed_at <= \'2026-11-22 23:59:59\' THEN \'CUR\' ELSE \'PRE\' END','[{\"name\":\"period\",\"label\":\"period\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"bill_count\",\"label\":\"bill_count\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"qty\",\"label\":\"qty\",\"jdbcType\":3,\"typeName\":\"DECIMAL\",\"nullable\":true},{\"name\":\"amount_yuan\",\"label\":\"amount_yuan\",\"jdbcType\":3,\"typeName\":\"DECIMAL\",\"nullable\":true}]',2,1,'ds_9e30225207004b52977d68cad1396a85.jsonl','READY','2026-12-07 00:00:00.000000','2026-11-22 11:32:17.309445','{\"grain\": \"每个时间窗口一行，共两行（CUR和PRE）。\", \"fields\": [{\"name\": \"period\", \"index\": 0, \"meaning\": \"时间窗口标识：\'CUR\'代表当前周期(2026-05-25至2026-11-22)，\'PRE\'代表上一周期(2025-11-23至2026-05-24)\"}, {\"name\": \"bill_count\", \"index\": 1, \"meaning\": \"该窗口内已确认的采购入库单据总数\"}, {\"name\": \"qty\", \"index\": 2, \"meaning\": \"该窗口内入库明细的数量合计（业务单位，由存储值除以100得到）\"}, {\"name\": \"amount_yuan\", \"index\": 3, \"meaning\": \"该窗口内入库明细的金额合计（元，由存储的分值乘以数量后除以10000得到）\"}], \"content\": \"采购入库单在两个半年窗口内的规模统计，包括单据数、业务数量和金额（元）。\", \"limitations\": \"\"}',NULL);
INSERT INTO `ai_dataset` (`dataset_id`, `sql_run_id`, `attempt`, `ready_run_id`, `user_id`, `conversation_id`, `description`, `source_sql`, `columns_json`, `row_count`, `completed`, `storage_file`, `status`, `expires_at`, `created_at`, `data_description_json`, `truncation_reason`) VALUES ('ds_9eb72120866741ff9850d53de2c96f00','sqlrun_c0167558c10d4a57a83de7a030d8e941',1,'sqlrun_c0167558c10d4a57a83de7a030d8e941',1900000000000000001,2124465547335741442,'统计库存流水凭证 stock_bill 与 stock_bill_item 中 bill_type 为 \'PURCHASE_RETURN\' 和 \'SALES_RETURN\' 的变动情况，按 bill_type 与两个半年窗口（period=\'CUR\' 为 stock_bill.confirmed_at 在 2026-05-25 至 2026-11-22 含端点，period=\'PRE\' 为 2025-11-23 至 2026-05-24 含端点）分组。每行输出凭证数（count distinct stock_bill.id）、明细行数、变动数量合计（sum(change_qty)/100，带正负）、正变动量合计（sum(CASE WHEN change_qty>0 THEN change_qty ELSE 0 END)/100）、负变动量合计（sum(CASE WHEN change_qty<0 THEN change_qty ELSE 0 END)/100）。全部仓库。','SELECT sb.bill_type AS bill_type, CASE WHEN sb.confirmed_at >= \'2026-05-25\' AND sb.confirmed_at < \'2026-11-23\' THEN \'CUR\' WHEN sb.confirmed_at >= \'2025-11-23\' AND sb.confirmed_at < \'2026-05-25\' THEN \'PRE\' END AS period, COUNT(DISTINCT sb.id) AS bill_count, COUNT(sbi.id) AS item_count, SUM(sbi.change_qty) / 100.0 AS change_qty, SUM(CASE WHEN sbi.change_qty > 0 THEN sbi.change_qty ELSE 0 END) / 100.0 AS positive_qty, SUM(CASE WHEN sbi.change_qty < 0 THEN sbi.change_qty ELSE 0 END) / 100.0 AS negative_qty FROM stock_bill sb JOIN stock_bill_item sbi ON sb.id = sbi.bill_id WHERE sb.bill_type IN (\'PURCHASE_RETURN\', \'SALES_RETURN\') AND sb.confirmed_at >= \'2025-11-23\' AND sb.confirmed_at < \'2026-11-23\' GROUP BY sb.bill_type, CASE WHEN sb.confirmed_at >= \'2026-05-25\' AND sb.confirmed_at < \'2026-11-23\' THEN \'CUR\' WHEN sb.confirmed_at >= \'2025-11-23\' AND sb.confirmed_at < \'2026-05-25\' THEN \'PRE\' END','[{\"name\":\"bill_type\",\"label\":\"bill_type\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"period\",\"label\":\"period\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":true},{\"name\":\"bill_count\",\"label\":\"bill_count\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"item_count\",\"label\":\"item_count\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"change_qty\",\"label\":\"change_qty\",\"jdbcType\":3,\"typeName\":\"DECIMAL\",\"nullable\":true},{\"name\":\"positive_qty\",\"label\":\"positive_qty\",\"jdbcType\":3,\"typeName\":\"DECIMAL\",\"nullable\":true},{\"name\":\"negative_qty\",\"label\":\"negative_qty\",\"jdbcType\":3,\"typeName\":\"DECIMAL\",\"nullable\":true}]',3,1,'ds_9eb72120866741ff9850d53de2c96f00.jsonl','READY','2026-12-07 00:00:00.000000','2026-11-22 11:33:07.668191','{\"grain\": \"每个 bill_type × period 一行\", \"fields\": [{\"name\": \"bill_type\", \"index\": 0, \"meaning\": \"单据类型：PURCHASE_RETURN(采购退货) 或 SALES_RETURN(销售退货)\"}, {\"name\": \"period\", \"index\": 1, \"meaning\": \"时间窗口标识：CUR(当前周期 2026-05-25至2026-11-22) 或 PRE(上一周期 2025-11-23至2026-05-24)\"}, {\"name\": \"bill_count\", \"index\": 2, \"meaning\": \"去重后的库存流水凭证数量\"}, {\"name\": \"item_count\", \"index\": 3, \"meaning\": \"库存流水凭证明细行数\"}, {\"name\": \"change_qty\", \"index\": 4, \"meaning\": \"库存变动数量合计（已除以100还原业务单位，带正负号）\"}, {\"name\": \"positive_qty\", \"index\": 5, \"meaning\": \"正向变动数量合计（仅统计 change_qty > 0 的部分，已除以100）\"}, {\"name\": \"negative_qty\", \"index\": 6, \"meaning\": \"负向变动数量合计（仅统计 change_qty < 0 的部分，已除以100，结果为负值）\"}], \"content\": \"采购退货出库与销售退货入库在指定两个时间段内的库存变动统计，包含凭证数、明细行数、净变动量、正向变动量和负向变动量。\", \"limitations\": \"\"}',NULL);
INSERT INTO `ai_dataset` (`dataset_id`, `sql_run_id`, `attempt`, `ready_run_id`, `user_id`, `conversation_id`, `description`, `source_sql`, `columns_json`, `row_count`, `completed`, `storage_file`, `status`, `expires_at`, `created_at`, `data_description_json`, `truncation_reason`) VALUES ('ds_a17dd113d3534d0ab997ed93a37f108d','sqlrun_25a96a976bfc410e87b3543fde923eab',3,'sqlrun_25a96a976bfc410e87b3543fde923eab',1900000000000000001,2124420137200144385,'查询产品 P001143（product_id=8400000000005001143）由采购入库产生的入库单明细（inbound_bill.source_type=PURCHASE_ORDER），不限时间不限供应商，包含入库单号、来源采购单号、确认时间、供应商（通过 source_party 或采购单关联）、本次入库数量、合格数量、不合格数量、单价；用于计算近180天（2026-05-26至2026-11-22）合格与不合格数量及不合格率，并定位不合格批次与时间','SELECT ib.source_party_id AS supplier_id, s.supplier_code AS supplier_code, ib.inbound_no AS inbound_no, ib.source_no AS purchase_no, ib.confirmed_at AS confirmed_at, ibi.product_id AS product_id, ibi.quantity_precision AS quantity_precision, ibi.current_qty / POWER(10, ibi.quantity_precision) AS current_qty, ibi.qualified_qty / POWER(10, ibi.quantity_precision) AS qualified_qty, ibi.defective_qty / POWER(10, ibi.quantity_precision) AS defective_qty, ibi.unit_price / 100.0 AS unit_price FROM inbound_bill ib JOIN inbound_bill_item ibi ON ib.id = ibi.inbound_bill_id JOIN supplier s ON ib.source_party_id = s.id WHERE ib.deleted = 0 AND ib.source_type = \'PURCHASE_ORDER\' AND ib.status = \'CONFIRMED\' AND ibi.product_id = 8400000000005001143 AND s.deleted = 0','[{\"name\":\"source_party_id\",\"label\":\"supplier_id\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":true},{\"name\":\"supplier_code\",\"label\":\"supplier_code\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"inbound_no\",\"label\":\"inbound_no\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"source_no\",\"label\":\"purchase_no\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"confirmed_at\",\"label\":\"confirmed_at\",\"jdbcType\":93,\"typeName\":\"DATETIME\",\"nullable\":true},{\"name\":\"product_id\",\"label\":\"product_id\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"quantity_precision\",\"label\":\"quantity_precision\",\"jdbcType\":-6,\"typeName\":\"TINYINT\",\"nullable\":false},{\"name\":\"current_qty\",\"label\":\"current_qty\",\"jdbcType\":8,\"typeName\":\"DOUBLE\",\"nullable\":true},{\"name\":\"qualified_qty\",\"label\":\"qualified_qty\",\"jdbcType\":8,\"typeName\":\"DOUBLE\",\"nullable\":true},{\"name\":\"defective_qty\",\"label\":\"defective_qty\",\"jdbcType\":8,\"typeName\":\"DOUBLE\",\"nullable\":true},{\"name\":\"unit_price\",\"label\":\"unit_price\",\"jdbcType\":3,\"typeName\":\"DECIMAL\",\"nullable\":true}]',4,1,'ds_a17dd113d3534d0ab997ed93a37f108d.jsonl','READY','2026-12-07 00:00:00.000000','2026-11-22 08:31:56.371619','{\"grain\": \"每个入库单明细行一行\", \"fields\": [{\"name\": \"supplier_id\", \"index\": 0, \"meaning\": \"供应商ID\"}, {\"name\": \"supplier_code\", \"index\": 1, \"meaning\": \"供应商编码\"}, {\"name\": \"inbound_no\", \"index\": 2, \"meaning\": \"入库单号\"}, {\"name\": \"purchase_no\", \"index\": 3, \"meaning\": \"来源采购单号\"}, {\"name\": \"confirmed_at\", \"index\": 4, \"meaning\": \"入库单确认时间\"}, {\"name\": \"product_id\", \"index\": 5, \"meaning\": \"产品ID\"}, {\"name\": \"quantity_precision\", \"index\": 6, \"meaning\": \"数量小数位精度快照\"}, {\"name\": \"current_qty\", \"index\": 7, \"meaning\": \"本次入库业务数量（已根据精度还原）\"}, {\"name\": \"qualified_qty\", \"index\": 8, \"meaning\": \"合格业务数量（已根据精度还原）\"}, {\"name\": \"defective_qty\", \"index\": 9, \"meaning\": \"不合格业务数量（已根据精度还原）\"}, {\"name\": \"unit_price\", \"index\": 10, \"meaning\": \"入库单价（元，已除以100换算）\"}], \"content\": \"产品P001143的采购入库单明细列表，涵盖供应商、单据编号、时间及数量金额信息\", \"limitations\": \"\"}',NULL);
INSERT INTO `ai_dataset` (`dataset_id`, `sql_run_id`, `attempt`, `ready_run_id`, `user_id`, `conversation_id`, `description`, `source_sql`, `columns_json`, `row_count`, `completed`, `storage_file`, `status`, `expires_at`, `created_at`, `data_description_json`, `truncation_reason`) VALUES ('ds_a46d2d99bb21459399c634be1730930e','sqlrun_8cff9804f275498f99accff46a30e4b9',1,'sqlrun_8cff9804f275498f99accff46a30e4b9',1900000000000000001,2124364502374834178,'查询供应商供货产品表 supplier_product 中 product_id = 8400000000005000227（产品编码 P000227，最佳选择 全麦饼干）的全部供货记录，返回供应商ID、最近成交价、人工报价及有效期、最小起订量、各项评分、评分状态、启用状态','SELECT id, supplier_id, product_id, latest_purchase_price, quoted_purchase_price, quoted_price_reason, quoted_price_updated_at, quote_valid_until, min_order_qty, quality_score, price_score, recommend_score, last_purchase_at, avg_delivery_days, score_basis_amount, score_status, status FROM supplier_product WHERE product_id = 8400000000005000227 AND deleted = 0','[{\"name\":\"id\",\"label\":\"id\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"supplier_id\",\"label\":\"supplier_id\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"product_id\",\"label\":\"product_id\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"latest_purchase_price\",\"label\":\"latest_purchase_price\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":true},{\"name\":\"quoted_purchase_price\",\"label\":\"quoted_purchase_price\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":true},{\"name\":\"quoted_price_reason\",\"label\":\"quoted_price_reason\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"quoted_price_updated_at\",\"label\":\"quoted_price_updated_at\",\"jdbcType\":93,\"typeName\":\"DATETIME\",\"nullable\":true},{\"name\":\"quote_valid_until\",\"label\":\"quote_valid_until\",\"jdbcType\":91,\"typeName\":\"DATE\",\"nullable\":true},{\"name\":\"min_order_qty\",\"label\":\"min_order_qty\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"quality_score\",\"label\":\"quality_score\",\"jdbcType\":4,\"typeName\":\"INT\",\"nullable\":true},{\"name\":\"price_score\",\"label\":\"price_score\",\"jdbcType\":4,\"typeName\":\"INT\",\"nullable\":true},{\"name\":\"recommend_score\",\"label\":\"recommend_score\",\"jdbcType\":4,\"typeName\":\"INT\",\"nullable\":true},{\"name\":\"last_purchase_at\",\"label\":\"last_purchase_at\",\"jdbcType\":93,\"typeName\":\"DATETIME\",\"nullable\":true},{\"name\":\"avg_delivery_days\",\"label\":\"avg_delivery_days\",\"jdbcType\":3,\"typeName\":\"DECIMAL\",\"nullable\":true},{\"name\":\"score_basis_amount\",\"label\":\"score_basis_amount\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":true},{\"name\":\"score_status\",\"label\":\"score_status\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"status\",\"label\":\"status\",\"jdbcType\":-6,\"typeName\":\"TINYINT\",\"nullable\":false}]',1,1,'ds_a46d2d99bb21459399c634be1730930e.jsonl','READY','2026-12-07 00:00:00.000000','2026-11-22 04:49:24.265467','{\"grain\": \"每个供应商对该产品的供货关系一条记录\", \"fields\": [{\"name\": \"id\", \"index\": 0, \"meaning\": \"供应商供货产品记录ID\"}, {\"name\": \"supplier_id\", \"index\": 1, \"meaning\": \"供应商ID\"}, {\"name\": \"product_id\", \"index\": 2, \"meaning\": \"产品ID\"}, {\"name\": \"latest_purchase_price\", \"index\": 3, \"meaning\": \"最近成交单价，单位分（库内存储值，展示时需除以100换算为元）\"}, {\"name\": \"quoted_purchase_price\", \"index\": 4, \"meaning\": \"人工有效报价，单位分（库内存储值，展示时需除以100换算为元）\"}, {\"name\": \"quoted_price_reason\", \"index\": 5, \"meaning\": \"当前人工有效报价原因；报价为空时为空字符串\"}, {\"name\": \"quoted_price_updated_at\", \"index\": 6, \"meaning\": \"报价最近维护时间\"}, {\"name\": \"quote_valid_until\", \"index\": 7, \"meaning\": \"报价有效截止日\"}, {\"name\": \"min_order_qty\", \"index\": 8, \"meaning\": \"最小起订量，放大100倍保存（库内存储值，展示时需除以100还原业务数量）\"}, {\"name\": \"quality_score\", \"index\": 9, \"meaning\": \"供应产品质量评分，INT×100（库内存储值，展示时需除以100得0-100分；NULL表示样本不足）\"}, {\"name\": \"price_score\", \"index\": 10, \"meaning\": \"供应产品价格评分，INT×100（库内存储值，展示时需除以100得0-100分；NULL表示样本不足）\"}, {\"name\": \"recommend_score\", \"index\": 11, \"meaning\": \"供应产品推荐评分，INT×100（库内存储值，展示时需除以100得0-100分；NULL表示样本不足）\"}, {\"name\": \"last_purchase_at\", \"index\": 12, \"meaning\": \"当前最近成交价对应的最后一次已确认采购入库时间\"}, {\"name\": \"avg_delivery_days\", \"index\": 13, \"meaning\": \"最近180天完全入库采购单的金额加权平均到货周期（天），仅供分析参考\"}, {\"name\": \"score_basis_amount\", \"index\": 14, \"meaning\": \"近180天已确认样本金额，单位分；不足样本时为空\"}, {\"name\": \"score_status\", \"index\": 15, \"meaning\": \"评分状态：NOT_READY表示样本不足，READY表示可参与评分\"}, {\"name\": \"status\", \"index\": 16, \"meaning\": \"启用状态：1启用，0禁用\"}], \"content\": \"产品P000227（全麦饼干）的供应商供货关系记录，包含报价、成交历史、评分及状态信息\", \"limitations\": \"\"}',NULL);
INSERT INTO `ai_dataset` (`dataset_id`, `sql_run_id`, `attempt`, `ready_run_id`, `user_id`, `conversation_id`, `description`, `source_sql`, `columns_json`, `row_count`, `completed`, `storage_file`, `status`, `expires_at`, `created_at`, `data_description_json`, `truncation_reason`) VALUES ('ds_a68f58f2e34a4607b7b8794058fa1ddb','sqlrun_8b48ddb2df21407c91ad4aeb6bb15051',2,'sqlrun_8b48ddb2df21407c91ad4aeb6bb15051',1900000000000000001,2124420137200144385,'查询产品 P001143（product_id=8400000000005001143）的产品主档：产品编码、名称、所属分类ID与分类名称、单位、数量小数位、安全库存数量、启用状态','SELECT p.id, p.product_code, p.product_name, p.category_id, pc.category_name, p.unit_name, p.quantity_precision, p.safety_stock_qty / 100.0 AS safety_stock_qty, p.status FROM product p INNER JOIN product_category pc ON p.category_id = pc.id AND pc.deleted = 0 WHERE p.id = 8400000000005001143 AND p.deleted = 0','[{\"name\":\"id\",\"label\":\"id\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"product_code\",\"label\":\"product_code\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"product_name\",\"label\":\"product_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"category_id\",\"label\":\"category_id\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":true},{\"name\":\"category_name\",\"label\":\"category_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"unit_name\",\"label\":\"unit_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"quantity_precision\",\"label\":\"quantity_precision\",\"jdbcType\":-6,\"typeName\":\"TINYINT\",\"nullable\":false},{\"name\":\"safety_stock_qty\",\"label\":\"safety_stock_qty\",\"jdbcType\":3,\"typeName\":\"DECIMAL\",\"nullable\":true},{\"name\":\"status\",\"label\":\"status\",\"jdbcType\":-6,\"typeName\":\"TINYINT\",\"nullable\":false}]',1,1,'ds_a68f58f2e34a4607b7b8794058fa1ddb.jsonl','READY','2026-12-07 00:00:00.000000','2026-11-22 08:32:19.155518','{\"grain\": \"每个产品一行\", \"fields\": [{\"name\": \"id\", \"index\": 0, \"meaning\": \"产品ID\"}, {\"name\": \"product_code\", \"index\": 1, \"meaning\": \"产品编码\"}, {\"name\": \"product_name\", \"index\": 2, \"meaning\": \"产品名称\"}, {\"name\": \"category_id\", \"index\": 3, \"meaning\": \"所属分类ID\"}, {\"name\": \"category_name\", \"index\": 4, \"meaning\": \"所属分类名称\"}, {\"name\": \"unit_name\", \"index\": 5, \"meaning\": \"单位名称\"}, {\"name\": \"quantity_precision\", \"index\": 6, \"meaning\": \"数量小数位精度\"}, {\"name\": \"safety_stock_qty\", \"index\": 7, \"meaning\": \"安全库存数量（已还原为业务数值）\"}, {\"name\": \"status\", \"index\": 8, \"meaning\": \"启用状态（1启用，0禁用）\"}], \"content\": \"查询产品 P001143 (ID: 8400000000005001143) 的主档信息，包括编码、名称、分类、单位、精度、安全库存及状态。\", \"limitations\": \"\"}',NULL);
INSERT INTO `ai_dataset` (`dataset_id`, `sql_run_id`, `attempt`, `ready_run_id`, `user_id`, `conversation_id`, `description`, `source_sql`, `columns_json`, `row_count`, `completed`, `storage_file`, `status`, `expires_at`, `created_at`, `data_description_json`, `truncation_reason`) VALUES ('ds_a901e8bb0d7d4eb696e58d81421a7e06','sqlrun_11e4c56f63b54c53a9eac7b1bd8e394a',1,'sqlrun_11e4c56f63b54c53a9eac7b1bd8e394a',1900000000000000001,2124475847040573442,'查询成都双流西仓（warehouse_id=8400000000004000004）全部待发销售订单明细：订单状态为 SUBMITTED、APPROVED、PARTIAL_OUTBOUND，排除 DRAFT 和 CANCELLED，且 sales_order 与 sales_order_item 均未逻辑删除。需返回每条订单明细一行，包含订单ID、销售单号、客户名称、订单状态、预计交付日、产品ID/编码/名称/单位、订单数量、已出库数量、待发量(quantity-outbound_qty)、锁定数量、订单创建时间。数量字段为100倍整数原值，不预先换算。','SELECT so.id AS sales_order_id, so.sales_no, so.customer_name, so.status, so.expected_delivery_date, soi.product_id, soi.product_code, soi.product_name, soi.unit_name, soi.quantity, soi.outbound_qty, (soi.quantity - soi.outbound_qty) AS pending_qty, soi.locked_qty, so.create_time FROM sales_order so JOIN sales_order_item soi ON so.id = soi.sales_order_id WHERE so.warehouse_id = 8400000000004000004 AND so.status IN (\'SUBMITTED\', \'APPROVED\', \'PARTIAL_OUTBOUND\') AND so.deleted = 0','[{\"name\":\"id\",\"label\":\"sales_order_id\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"sales_no\",\"label\":\"sales_no\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"customer_name\",\"label\":\"customer_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"status\",\"label\":\"status\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"expected_delivery_date\",\"label\":\"expected_delivery_date\",\"jdbcType\":91,\"typeName\":\"DATE\",\"nullable\":true},{\"name\":\"product_id\",\"label\":\"product_id\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"product_code\",\"label\":\"product_code\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"product_name\",\"label\":\"product_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"unit_name\",\"label\":\"unit_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"quantity\",\"label\":\"quantity\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"outbound_qty\",\"label\":\"outbound_qty\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"pending_qty\",\"label\":\"pending_qty\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"locked_qty\",\"label\":\"locked_qty\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"create_time\",\"label\":\"create_time\",\"jdbcType\":93,\"typeName\":\"DATETIME\",\"nullable\":false}]',79,1,'ds_a901e8bb0d7d4eb696e58d81421a7e06.jsonl','READY','2026-12-07 00:00:00.000000','2026-11-22 12:13:09.318523','{\"grain\": \"每张销售订单的每个产品明细一行\", \"fields\": [{\"name\": \"sales_order_id\", \"index\": 0, \"meaning\": \"销售订单ID\"}, {\"name\": \"sales_no\", \"index\": 1, \"meaning\": \"销售单号\"}, {\"name\": \"customer_name\", \"index\": 2, \"meaning\": \"客户名称快照\"}, {\"name\": \"status\", \"index\": 3, \"meaning\": \"订单状态（SUBMITTED/APPROVED/PARTIAL_OUTBOUND）\"}, {\"name\": \"expected_delivery_date\", \"index\": 4, \"meaning\": \"预计发货日期\"}, {\"name\": \"product_id\", \"index\": 5, \"meaning\": \"产品ID\"}, {\"name\": \"product_code\", \"index\": 6, \"meaning\": \"产品编码快照\"}, {\"name\": \"product_name\", \"index\": 7, \"meaning\": \"产品名称快照\"}, {\"name\": \"unit_name\", \"index\": 8, \"meaning\": \"单位名称快照\"}, {\"name\": \"quantity\", \"index\": 9, \"meaning\": \"销售数量（×100整数存储）\"}, {\"name\": \"outbound_qty\", \"index\": 10, \"meaning\": \"已出库数量（×100整数存储）\"}, {\"name\": \"pending_qty\", \"index\": 11, \"meaning\": \"待发量/未出库数量（×100整数存储，计算值：quantity - outbound_qty）\"}, {\"name\": \"locked_qty\", \"index\": 12, \"meaning\": \"已锁定库存数量（×100整数存储）\"}, {\"name\": \"create_time\", \"index\": 13, \"meaning\": \"订单创建时间\"}], \"content\": \"成都双流西仓待发货销售订单明细列表，包含订单基本信息、客户名称、预计交付日及产品维度的数量与状态信息。\", \"limitations\": \"数量字段均为数据库原始存储值（放大100倍的整数），展示或进一步计算时需除以100还原为业务数量。\"}',NULL);
INSERT INTO `ai_dataset` (`dataset_id`, `sql_run_id`, `attempt`, `ready_run_id`, `user_id`, `conversation_id`, `description`, `source_sql`, `columns_json`, `row_count`, `completed`, `storage_file`, `status`, `expires_at`, `created_at`, `data_description_json`, `truncation_reason`) VALUES ('ds_a9ec41f66a7c42aeb1ee1fdd6bc8d524','sqlrun_c1e93d8cde0d4d53a65849960c955134',1,'sqlrun_c1e93d8cde0d4d53a65849960c955134',1900000000000000001,2124761984778977281,'查询产品 product_id=8400000000005001253（编码P001253）、出库仓库 warehouse_id=8400000000004000001（上海浦东中心仓）的销售订单明细，仅取销售订单主表 status 为 SUBMITTED、APPROVED、PARTIAL_OUTBOUND 且 deleted=0 的记录，返回销售单号、订单状态、明细 quantity（100倍整数）、locked_qty（100倍整数）、outbound_qty（100倍整数）、quantity_precision、单位、预计发货日期、提交/审核时间，用于核实锁定库存 64.00 罐是否对应真实待出库需求','SELECT so.sales_no AS sales_no, so.status AS status, soi.product_code AS product_code, soi.quantity AS quantity, soi.locked_qty AS locked_qty, soi.outbound_qty AS outbound_qty, soi.quantity_precision AS quantity_precision, soi.unit_name AS unit_name, so.expected_delivery_date AS expected_delivery_date, so.submitted_at AS submitted_at, so.approved_at AS approved_at FROM sales_order so INNER JOIN sales_order_item soi ON so.id = soi.sales_order_id WHERE so.deleted = 0 AND so.status IN (\'SUBMITTED\', \'APPROVED\', \'PARTIAL_OUTBOUND\') AND so.warehouse_id = 8400000000004000001 AND soi.product_id = 8400000000005001253','[{\"name\":\"sales_no\",\"label\":\"sales_no\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"status\",\"label\":\"status\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"product_code\",\"label\":\"product_code\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"quantity\",\"label\":\"quantity\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"locked_qty\",\"label\":\"locked_qty\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"outbound_qty\",\"label\":\"outbound_qty\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"quantity_precision\",\"label\":\"quantity_precision\",\"jdbcType\":-6,\"typeName\":\"TINYINT\",\"nullable\":false},{\"name\":\"unit_name\",\"label\":\"unit_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"expected_delivery_date\",\"label\":\"expected_delivery_date\",\"jdbcType\":91,\"typeName\":\"DATE\",\"nullable\":true},{\"name\":\"submitted_at\",\"label\":\"submitted_at\",\"jdbcType\":93,\"typeName\":\"DATETIME\",\"nullable\":true},{\"name\":\"approved_at\",\"label\":\"approved_at\",\"jdbcType\":93,\"typeName\":\"DATETIME\",\"nullable\":true}]',1,1,'ds_a9ec41f66a7c42aeb1ee1fdd6bc8d524.jsonl','READY','2026-12-08 00:00:00.000000','2026-11-23 07:09:55.723449','{\"grain\": \"每条销售订单明细一行\", \"fields\": [{\"name\": \"sales_no\", \"index\": 0, \"meaning\": \"销售单号\"}, {\"name\": \"status\", \"index\": 1, \"meaning\": \"订单状态 (SUBMITTED:待审核, APPROVED:待出库, PARTIAL_OUTBOUND:部分出库)\"}, {\"name\": \"product_code\", \"index\": 2, \"meaning\": \"产品编码\"}, {\"name\": \"quantity\", \"index\": 3, \"meaning\": \"销售数量 (放大100倍整数存储，需除以100得到实际业务数量)\"}, {\"name\": \"locked_qty\", \"index\": 4, \"meaning\": \"已锁定库存数量 (放大100倍整数存储，需除以100得到实际业务数量)\"}, {\"name\": \"outbound_qty\", \"index\": 5, \"meaning\": \"已出库数量 (放大100倍整数存储，需除以100得到实际业务数量)\"}, {\"name\": \"quantity_precision\", \"index\": 6, \"meaning\": \"数量小数位精度快照 (0-2)\"}, {\"name\": \"unit_name\", \"index\": 7, \"meaning\": \"单位名称快照\"}, {\"name\": \"expected_delivery_date\", \"index\": 8, \"meaning\": \"预计发货日期\"}, {\"name\": \"submitted_at\", \"index\": 9, \"meaning\": \"提交时间\"}, {\"name\": \"approved_at\", \"index\": 10, \"meaning\": \"审核时间\"}], \"content\": \"产品 P001253 在上海浦东中心仓的有效销售订单明细（状态：待审核、待出库、部分出库），用于分析库存锁定情况。\", \"limitations\": \"数量字段（quantity, locked_qty, outbound_qty）在数据库中按100倍整数存储，展示或计算时需除以100还原为业务单位数量。\"}',NULL);
INSERT INTO `ai_dataset` (`dataset_id`, `sql_run_id`, `attempt`, `ready_run_id`, `user_id`, `conversation_id`, `description`, `source_sql`, `columns_json`, `row_count`, `completed`, `storage_file`, `status`, `expires_at`, `created_at`, `data_description_json`, `truncation_reason`) VALUES ('ds_aa6b6614503f4fbeba71713e7cab15d9','sqlrun_def01ff77cb54eb1b3d3239c9adf3a39',1,'sqlrun_def01ff77cb54eb1b3d3239c9adf3a39',1900000000000000001,2124221025439735809,'按bill_type汇总全部历史库存流水明细的change_qty（除以100还原为件），用于与当前库存余额124417件对账，验证出入库流水是否完整','SELECT sb.bill_type AS bill_type, SUM(sbi.change_qty) / 100.0 AS total_change_qty FROM stock_bill sb JOIN stock_bill_item sbi ON sb.id = sbi.bill_id GROUP BY sb.bill_type','[{\"name\":\"bill_type\",\"label\":\"bill_type\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"total_change_qty\",\"label\":\"total_change_qty\",\"jdbcType\":3,\"typeName\":\"DECIMAL\",\"nullable\":true}]',2,1,'ds_aa6b6614503f4fbeba71713e7cab15d9.jsonl','READY','2026-12-06 00:00:00.000000','2026-11-21 19:25:13.099905','{\"grain\": \"每个 bill_type 一行\", \"fields\": [{\"name\": \"bill_type\", \"index\": 0, \"meaning\": \"库存流水类型，如 PURCHASE_IN (采购入库), SALES_OUT (销售出库) 等\"}, {\"name\": \"total_change_qty\", \"index\": 1, \"meaning\": \"该类型下的累计库存变动数量（件），入库为正，出库为负\"}], \"content\": \"按库存流水凭证类型（bill_type）汇总的历史库存变动数量，已将数据库中的100倍整数存储还原为业务单位（件）。数据覆盖所有已确认的出入库流水。\", \"limitations\": \"\"}',NULL);
INSERT INTO `ai_dataset` (`dataset_id`, `sql_run_id`, `attempt`, `ready_run_id`, `user_id`, `conversation_id`, `description`, `source_sql`, `columns_json`, `row_count`, `completed`, `storage_file`, `status`, `expires_at`, `created_at`, `data_description_json`, `truncation_reason`) VALUES ('ds_abab696fbb634a3080c06d8d64918b42','sqlrun_d1e0eeb7c669462b9198e0e3847439c0',1,'sqlrun_d1e0eeb7c669462b9198e0e3847439c0',1900000000000000001,2123852411582849025,'查询产品主档 product 的全部产品记录，含产品ID、编码、名称、分类ID、单位、数量精度、参考采购价、安全库存、启用状态，用于库存金额折算、单位清单与分类归属','SELECT id AS product_id, product_code, product_name, category_id, unit_name, quantity_precision, reference_purchase_price, safety_stock_qty, status FROM product WHERE deleted = 0','[{\"name\":\"id\",\"label\":\"product_id\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"product_code\",\"label\":\"product_code\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"product_name\",\"label\":\"product_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"category_id\",\"label\":\"category_id\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":true},{\"name\":\"unit_name\",\"label\":\"unit_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"quantity_precision\",\"label\":\"quantity_precision\",\"jdbcType\":-6,\"typeName\":\"TINYINT\",\"nullable\":false},{\"name\":\"reference_purchase_price\",\"label\":\"reference_purchase_price\",\"jdbcType\":3,\"typeName\":\"DECIMAL\",\"nullable\":false},{\"name\":\"safety_stock_qty\",\"label\":\"safety_stock_qty\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"status\",\"label\":\"status\",\"jdbcType\":-6,\"typeName\":\"TINYINT\",\"nullable\":false}]',1560,1,'ds_abab696fbb634a3080c06d8d64918b42.jsonl','READY','2026-12-05 00:00:00.000000','2026-11-20 18:55:44.526974','{\"grain\": \"每个产品一行\", \"fields\": [{\"name\": \"product_id\", \"index\": 0, \"meaning\": \"产品唯一标识ID\"}, {\"name\": \"product_code\", \"index\": 1, \"meaning\": \"产品编码，后端生成且不可修改\"}, {\"name\": \"product_name\", \"index\": 2, \"meaning\": \"产品名称\"}, {\"name\": \"category_id\", \"index\": 3, \"meaning\": \"所属产品分类ID，可空表示未分类\"}, {\"name\": \"unit_name\", \"index\": 4, \"meaning\": \"计量单位名称，自由文本标签\"}, {\"name\": \"quantity_precision\", \"index\": 5, \"meaning\": \"数量小数位精度，取值0-2，决定业务数量的显示位数\"}, {\"name\": \"reference_purchase_price\", \"index\": 6, \"meaning\": \"参考采购单价，单位为元，DECIMAL类型不放大\"}, {\"name\": \"safety_stock_qty\", \"index\": 7, \"meaning\": \"安全库存阈值，按100倍整数存储（例如1000代表10.00），需除以100还原为业务数量\"}, {\"name\": \"status\", \"index\": 8, \"meaning\": \"启用状态，1表示启用，0表示禁用\"}], \"content\": \"ERP系统中所有有效（未删除）的产品主档信息，用于业务分析的基础维度表。\", \"limitations\": \"safety_stock_qty字段在数据库中存储为放大100倍的整数，使用时需注意换算；reference_purchase_price单位为元，与其他单据中的分口径金额不同。\"}',NULL);
INSERT INTO `ai_dataset` (`dataset_id`, `sql_run_id`, `attempt`, `ready_run_id`, `user_id`, `conversation_id`, `description`, `source_sql`, `columns_json`, `row_count`, `completed`, `storage_file`, `status`, `expires_at`, `created_at`, `data_description_json`, `truncation_reason`) VALUES ('ds_acdb3fa1c4384b6d9037d65198606f6e','sqlrun_5b575b8107c44df191aabb1be1f4f0e9',1,'sqlrun_5b575b8107c44df191aabb1be1f4f0e9',1900000000000000001,2124221025439735809,'查询全部5个仓库（DEMOW01~DEMOW05）的库存余额全量记录，用于库存健康诊断：返回仓库ID、仓库编码、仓库名称、产品ID、产品编码、产品名称、单位、库存数量stock_qty、锁定数量locked_qty（均为100倍整数原值）','SELECT ws.warehouse_id AS warehouse_id, ws.warehouse_code AS warehouse_code, ws.warehouse_name AS warehouse_name, ws.product_id AS product_id, ws.product_code AS product_code, ws.product_name AS product_name, ws.unit_name AS unit_name, ws.stock_qty AS stock_qty, ws.locked_qty AS locked_qty FROM warehouse_stock ws INNER JOIN warehouse w ON ws.warehouse_id = w.id WHERE w.deleted = 0 AND w.warehouse_code IN (\'DEMOW01\', \'DEMOW02\', \'DEMOW03\', \'DEMOW04\', \'DEMOW05\')','[{\"name\":\"warehouse_id\",\"label\":\"warehouse_id\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"warehouse_code\",\"label\":\"warehouse_code\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"warehouse_name\",\"label\":\"warehouse_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"product_id\",\"label\":\"product_id\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"product_code\",\"label\":\"product_code\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"product_name\",\"label\":\"product_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"unit_name\",\"label\":\"unit_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"stock_qty\",\"label\":\"stock_qty\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"locked_qty\",\"label\":\"locked_qty\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false}]',1560,1,'ds_acdb3fa1c4384b6d9037d65198606f6e.jsonl','READY','2026-12-06 00:00:00.000000','2026-11-21 19:20:49.932037','{\"grain\": \"每个仓库与产品的组合一行\", \"fields\": [{\"name\": \"warehouse_id\", \"index\": 0, \"meaning\": \"仓库ID\"}, {\"name\": \"warehouse_code\", \"index\": 1, \"meaning\": \"仓库编码\"}, {\"name\": \"warehouse_name\", \"index\": 2, \"meaning\": \"仓库名称\"}, {\"name\": \"product_id\", \"index\": 3, \"meaning\": \"产品ID\"}, {\"name\": \"product_code\", \"index\": 4, \"meaning\": \"产品编码\"}, {\"name\": \"product_name\", \"index\": 5, \"meaning\": \"产品名称\"}, {\"name\": \"unit_name\", \"index\": 6, \"meaning\": \"单位名称\"}, {\"name\": \"stock_qty\", \"index\": 7, \"meaning\": \"当前库存数量（按100倍整数存储）\"}, {\"name\": \"locked_qty\", \"index\": 8, \"meaning\": \"锁定库存数量（按100倍整数存储）\"}], \"content\": \"DEMOW01至DEMOW05五个指定仓库的库存余额明细，包含仓库信息、产品信息及账面/锁定库存数量（原始100倍整数存储）。\", \"limitations\": \"\"}',NULL);
INSERT INTO `ai_dataset` (`dataset_id`, `sql_run_id`, `attempt`, `ready_run_id`, `user_id`, `conversation_id`, `description`, `source_sql`, `columns_json`, `row_count`, `completed`, `storage_file`, `status`, `expires_at`, `created_at`, `data_description_json`, `truncation_reason`) VALUES ('ds_b04635e87fd1423285a42992b19f169b','sqlrun_86ebac5de47b475eb7cf6f3b9726622b',1,'sqlrun_86ebac5de47b475eb7cf6f3b9726622b',1900000000000000001,2124364502374834178,'在供应商表 supplier 中查询 id = 8400000000002000027 的供应商主档，返回名称、付款条件、综合分及价格/质量/交付/服务分、交期、样本金额、评分状态、启用状态','SELECT id, supplier_code, supplier_name, payment_terms, overall_score, delivery_score, quality_score, price_score, service_score, service_score_reason, avg_delivery_days, score_basis_amount, score_status, status FROM supplier WHERE id = 8400000000002000027 AND deleted = 0','[{\"name\":\"id\",\"label\":\"id\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"supplier_code\",\"label\":\"supplier_code\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"supplier_name\",\"label\":\"supplier_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"payment_terms\",\"label\":\"payment_terms\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"overall_score\",\"label\":\"overall_score\",\"jdbcType\":4,\"typeName\":\"INT\",\"nullable\":true},{\"name\":\"delivery_score\",\"label\":\"delivery_score\",\"jdbcType\":4,\"typeName\":\"INT\",\"nullable\":true},{\"name\":\"quality_score\",\"label\":\"quality_score\",\"jdbcType\":4,\"typeName\":\"INT\",\"nullable\":true},{\"name\":\"price_score\",\"label\":\"price_score\",\"jdbcType\":4,\"typeName\":\"INT\",\"nullable\":true},{\"name\":\"service_score\",\"label\":\"service_score\",\"jdbcType\":4,\"typeName\":\"INT\",\"nullable\":true},{\"name\":\"service_score_reason\",\"label\":\"service_score_reason\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"avg_delivery_days\",\"label\":\"avg_delivery_days\",\"jdbcType\":3,\"typeName\":\"DECIMAL\",\"nullable\":true},{\"name\":\"score_basis_amount\",\"label\":\"score_basis_amount\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":true},{\"name\":\"score_status\",\"label\":\"score_status\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"status\",\"label\":\"status\",\"jdbcType\":-6,\"typeName\":\"TINYINT\",\"nullable\":false}]',1,1,'ds_b04635e87fd1423285a42992b19f169b.jsonl','READY','2026-12-07 00:00:00.000000','2026-11-22 04:49:43.379888','{\"grain\": \"每行代表一个供应商主档记录。\", \"fields\": [{\"name\": \"id\", \"index\": 0, \"meaning\": \"供应商ID\"}, {\"name\": \"supplier_code\", \"index\": 1, \"meaning\": \"供应商编码\"}, {\"name\": \"supplier_name\", \"index\": 2, \"meaning\": \"供应商名称\"}, {\"name\": \"payment_terms\", \"index\": 3, \"meaning\": \"付款条件\"}, {\"name\": \"overall_score\", \"index\": 4, \"meaning\": \"综合评分（库内值×100，需除以100得实际分数，NULL表示样本不足）\"}, {\"name\": \"delivery_score\", \"index\": 5, \"meaning\": \"交付评分（库内值×100，需除以100得实际分数，NULL表示样本不足）\"}, {\"name\": \"quality_score\", \"index\": 6, \"meaning\": \"质量评分（库内值×100，需除以100得实际分数，NULL表示样本不足）\"}, {\"name\": \"price_score\", \"index\": 7, \"meaning\": \"价格评分（库内值×100，需除以100得实际分数，NULL表示样本不足）\"}, {\"name\": \"service_score\", \"index\": 8, \"meaning\": \"服务评分（库内值×100，需除以100得实际分数，NULL表示尚未人工设定）\"}, {\"name\": \"service_score_reason\", \"index\": 9, \"meaning\": \"人工服务评分原因\"}, {\"name\": \"avg_delivery_days\", \"index\": 10, \"meaning\": \"最近180天完全入库订单的金额加权平均到货周期（天）\"}, {\"name\": \"score_basis_amount\", \"index\": 11, \"meaning\": \"近180天已确认样本金额（单位：分）\"}, {\"name\": \"score_status\", \"index\": 12, \"meaning\": \"评分状态（READY:可参与评分, NOT_READY:样本不足）\"}, {\"name\": \"status\", \"index\": 13, \"meaning\": \"启用状态（1:启用, 0:禁用）\"}], \"content\": \"指定供应商（ID: 8400000000002000027）的主档详情，包括基础信息、绩效评分及相关状态。\", \"limitations\": \"评分字段（overall_score, delivery_score, quality_score, price_score, service_score）在数据库中存储为放大100倍的整数，使用时需除以100转换为0-100的业务分值。score_basis_amount单位为分。\"}',NULL);
INSERT INTO `ai_dataset` (`dataset_id`, `sql_run_id`, `attempt`, `ready_run_id`, `user_id`, `conversation_id`, `description`, `source_sql`, `columns_json`, `row_count`, `completed`, `storage_file`, `status`, `expires_at`, `created_at`, `data_description_json`, `truncation_reason`) VALUES ('ds_b132809bf3114a80ae22a7deb192ec09','sqlrun_90f50015fd484fd5a9e2ddf70588ce34',1,'sqlrun_90f50015fd484fd5a9e2ddf70588ce34',1900000000000000001,2124418644136972290,'查询 warehouse_id = 8400000000004000004（成都双流西仓）的全部 warehouse_stock 库存余额记录，关联 product 取产品编码、产品名称、单位、quantity_precision、safety_stock_qty，仅保留 product.status=1 且 product.deleted=0 的产品。每行一个仓库×产品，含 stock_qty、locked_qty（100倍整数）','SELECT ws.warehouse_id AS warehouse_id, ws.warehouse_name AS warehouse_name, ws.product_id AS product_id, p.product_code AS product_code, p.product_name AS product_name, p.unit_name AS unit_name, p.quantity_precision AS quantity_precision, ws.stock_qty AS stock_qty, ws.locked_qty AS locked_qty, p.safety_stock_qty AS safety_stock_qty FROM warehouse_stock ws INNER JOIN product p ON ws.product_id = p.id WHERE ws.warehouse_id = 8400000000004000004 AND p.status = 1 AND p.deleted = 0','[{\"name\":\"warehouse_id\",\"label\":\"warehouse_id\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"warehouse_name\",\"label\":\"warehouse_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"product_id\",\"label\":\"product_id\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"product_code\",\"label\":\"product_code\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"product_name\",\"label\":\"product_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"unit_name\",\"label\":\"unit_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"quantity_precision\",\"label\":\"quantity_precision\",\"jdbcType\":-6,\"typeName\":\"TINYINT\",\"nullable\":false},{\"name\":\"stock_qty\",\"label\":\"stock_qty\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"locked_qty\",\"label\":\"locked_qty\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"safety_stock_qty\",\"label\":\"safety_stock_qty\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false}]',323,1,'ds_b132809bf3114a80ae22a7deb192ec09.jsonl','READY','2026-12-07 00:00:00.000000','2026-11-22 08:26:03.659288','{\"grain\": \"每个仓库×产品组合一行\", \"fields\": [{\"name\": \"warehouse_id\", \"index\": 0, \"meaning\": \"仓库ID\"}, {\"name\": \"warehouse_name\", \"index\": 1, \"meaning\": \"仓库名称快照\"}, {\"name\": \"product_id\", \"index\": 2, \"meaning\": \"产品ID\"}, {\"name\": \"product_code\", \"index\": 3, \"meaning\": \"产品编码\"}, {\"name\": \"product_name\", \"index\": 4, \"meaning\": \"产品名称\"}, {\"name\": \"unit_name\", \"index\": 5, \"meaning\": \"单位名称\"}, {\"name\": \"quantity_precision\", \"index\": 6, \"meaning\": \"数量小数位精度（0-2）\"}, {\"name\": \"stock_qty\", \"index\": 7, \"meaning\": \"当前库存数量（放大100倍整数存储）\"}, {\"name\": \"locked_qty\", \"index\": 8, \"meaning\": \"锁定库存数量（放大100倍整数存储）\"}, {\"name\": \"safety_stock_qty\", \"index\": 9, \"meaning\": \"安全库存数量（放大100倍整数存储，产品级阈值）\"}], \"content\": \"指定仓库（成都双流西仓）的库存余额明细，关联产品主档获取编码、名称、单位、精度及安全库存阈值。仅包含状态为启用且未逻辑删除的产品。\", \"limitations\": \"\"}',NULL);
INSERT INTO `ai_dataset` (`dataset_id`, `sql_run_id`, `attempt`, `ready_run_id`, `user_id`, `conversation_id`, `description`, `source_sql`, `columns_json`, `row_count`, `completed`, `storage_file`, `status`, `expires_at`, `created_at`, `data_description_json`, `truncation_reason`) VALUES ('ds_b14e25d19833420f94cf62e2db89b075','sqlrun_863749232d744d038bce489a5494e14f',1,'sqlrun_863749232d744d038bce489a5494e14f',1900000000000000001,2124761984778977281,'查询产品 product_id=8400000000005001253、目标仓库 warehouse_id=8400000000004000001（上海浦东中心仓）的在途采购订单明细：采购订单主表 status 为 SUBMITTED、APPROVED、PARTIAL_INBOUND 且 deleted=0，返回采购单号、订单状态、供应商名称、quantity（100倍整数）、inbound_qty（100倍整数）、unit_price（分）、expected_arrival_date','SELECT po.purchase_no, po.status, po.supplier_id, po.supplier_name, poi.quantity, poi.inbound_qty, poi.unit_price, po.expected_arrival_date FROM purchase_order po JOIN purchase_order_item poi ON po.id = poi.purchase_order_id WHERE po.warehouse_id = 8400000000004000001 AND po.deleted = 0 AND po.status IN (\'SUBMITTED\', \'APPROVED\', \'PARTIAL_INBOUND\') AND poi.product_id = 8400000000005001253','[{\"name\":\"purchase_no\",\"label\":\"purchase_no\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"status\",\"label\":\"status\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"supplier_id\",\"label\":\"supplier_id\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"supplier_name\",\"label\":\"supplier_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"quantity\",\"label\":\"quantity\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"inbound_qty\",\"label\":\"inbound_qty\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"unit_price\",\"label\":\"unit_price\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"expected_arrival_date\",\"label\":\"expected_arrival_date\",\"jdbcType\":91,\"typeName\":\"DATE\",\"nullable\":true}]',0,1,'ds_b14e25d19833420f94cf62e2db89b075.jsonl','READY','2026-12-08 00:00:00.000000','2026-11-23 07:10:23.803048','{\"grain\": \"每条采购订单明细一行\", \"fields\": [{\"name\": \"purchase_no\", \"index\": 0, \"meaning\": \"采购单号\"}, {\"name\": \"status\", \"index\": 1, \"meaning\": \"订单状态 (SUBMITTED:待审核, APPROVED:待入库, PARTIAL_INBOUND:部分入库)\"}, {\"name\": \"supplier_id\", \"index\": 2, \"meaning\": \"供应商ID\"}, {\"name\": \"supplier_name\", \"index\": 3, \"meaning\": \"供应商名称快照\"}, {\"name\": \"quantity\", \"index\": 4, \"meaning\": \"采购数量 (库内存储值，需除以100得到业务数量)\"}, {\"name\": \"inbound_qty\", \"index\": 5, \"meaning\": \"累计已入库数量 (库内存储值，需除以100得到业务数量)\"}, {\"name\": \"unit_price\", \"index\": 6, \"meaning\": \"采购单价 (单位：分，需除以100得到元)\"}, {\"name\": \"expected_arrival_date\", \"index\": 7, \"meaning\": \"预计到货日期\"}], \"content\": \"产品ID为8400000000005001253、目标仓库ID为8400000000004000001（上海浦东中心仓）的在途采购订单明细列表。仅包含状态为待审核(SUBMITTED)、待入库(APPROVED)或部分入库(PARTIAL_INBOUND)且未逻辑删除的采购订单。\", \"limitations\": \"\"}',NULL);
INSERT INTO `ai_dataset` (`dataset_id`, `sql_run_id`, `attempt`, `ready_run_id`, `user_id`, `conversation_id`, `description`, `source_sql`, `columns_json`, `row_count`, `completed`, `storage_file`, `status`, `expires_at`, `created_at`, `data_description_json`, `truncation_reason`) VALUES ('ds_b34c5faa94384341b467b95d5123f6c3','sqlrun_1430a8bb195042e2bccde67add8d1bea',1,'sqlrun_1430a8bb195042e2bccde67add8d1bea',1900000000000000001,2123852411582849025,'查询库存流水凭证明细表 stock_bill_item 中 create_time 在 2026-06-01 至 2026-11-22 之间的全部明细（业务时间口径与凭证确认时间一致），含所属凭证ID、产品ID、产品名称、单位、精度、变动数量','SELECT sbi.bill_id AS bill_id, sbi.product_id AS product_id, sbi.product_code AS product_code, sbi.product_name AS product_name, sbi.unit_name AS unit_name, sbi.quantity_precision AS quantity_precision, sbi.qualified_qty AS qualified_qty, sbi.change_qty AS change_qty, sbi.before_qty AS before_qty, sbi.after_qty AS after_qty, sbi.create_time AS create_time FROM stock_bill_item sbi WHERE sbi.create_time >= \'2026-06-01 00:00:00\' AND sbi.create_time < \'2026-11-23 00:00:00\'','[{\"name\":\"bill_id\",\"label\":\"bill_id\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"product_id\",\"label\":\"product_id\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"product_code\",\"label\":\"product_code\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"product_name\",\"label\":\"product_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"unit_name\",\"label\":\"unit_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"quantity_precision\",\"label\":\"quantity_precision\",\"jdbcType\":-6,\"typeName\":\"TINYINT\",\"nullable\":false},{\"name\":\"qualified_qty\",\"label\":\"qualified_qty\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"change_qty\",\"label\":\"change_qty\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"before_qty\",\"label\":\"before_qty\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"after_qty\",\"label\":\"after_qty\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"create_time\",\"label\":\"create_time\",\"jdbcType\":93,\"typeName\":\"DATETIME\",\"nullable\":false}]',1420,1,'ds_b34c5faa94384341b467b95d5123f6c3.jsonl','READY','2026-12-05 00:00:00.000000','2026-11-20 18:55:05.797976','{\"grain\": \"每条库存流水凭证明细一行\", \"fields\": [{\"name\": \"bill_id\", \"index\": 0, \"meaning\": \"所属库存流水凭证ID\"}, {\"name\": \"product_id\", \"index\": 1, \"meaning\": \"产品ID\"}, {\"name\": \"product_code\", \"index\": 2, \"meaning\": \"产品编码快照\"}, {\"name\": \"product_name\", \"index\": 3, \"meaning\": \"产品名称快照\"}, {\"name\": \"unit_name\", \"index\": 4, \"meaning\": \"单位名称快照\"}, {\"name\": \"quantity_precision\", \"index\": 5, \"meaning\": \"数量小数位精度快照 (0-2)\"}, {\"name\": \"qualified_qty\", \"index\": 6, \"meaning\": \"合格数量 (数据库存储值，实际业务数量需除以100)\"}, {\"name\": \"change_qty\", \"index\": 7, \"meaning\": \"库存变动数量 (数据库存储值，入库为正出库为负，实际业务数量需除以100)\"}, {\"name\": \"before_qty\", \"index\": 8, \"meaning\": \"变动前库存数量 (数据库存储值，实际业务数量需除以100)\"}, {\"name\": \"after_qty\", \"index\": 9, \"meaning\": \"变动后库存数量 (数据库存储值，实际业务数量需除以100)\"}, {\"name\": \"create_time\", \"index\": 10, \"meaning\": \"明细创建时间\"}], \"content\": \"库存流水凭证明细数据，包含指定时间范围内所有库存变动记录的详细信息。\", \"limitations\": \"数量类字段 (qualified_qty, change_qty, before_qty, after_qty) 均为放大100倍的整数值，展示或计算时需除以100还原为真实业务数量。\"}',NULL);
INSERT INTO `ai_dataset` (`dataset_id`, `sql_run_id`, `attempt`, `ready_run_id`, `user_id`, `conversation_id`, `description`, `source_sql`, `columns_json`, `row_count`, `completed`, `storage_file`, `status`, `expires_at`, `created_at`, `data_description_json`, `truncation_reason`) VALUES ('ds_b4145943a6ae4aa2bb7bd3d7bcd98c46','sqlrun_dcb34fcc68fd4efeb27d6c1df38658ef',2,'sqlrun_dcb34fcc68fd4efeb27d6c1df38658ef',1900000000000000001,2124761984778977281,'查询产品 product_id=8400000000005001253 的所有供应商供货关系（不做 status 过滤，deleted=0），返回供应商编码、供应商名称、供货关系状态、供应商主档状态、报价与MOQ，用于确认除已启用候选外是否存在被禁用或停用的备选供应商','SELECT sp.supplier_id AS supplier_id, s.supplier_code AS supplier_code, s.supplier_name AS supplier_name, sp.status AS supplier_product_status, s.status AS supplier_status, sp.quoted_purchase_price AS quoted_purchase_price, sp.latest_purchase_price AS latest_purchase_price, sp.quote_valid_until AS quote_valid_until, sp.min_order_qty AS min_order_qty FROM supplier_product sp JOIN supplier s ON sp.supplier_id = s.id WHERE sp.product_id = 8400000000005001253 AND sp.deleted = 0 AND s.deleted = 0','[{\"name\":\"supplier_id\",\"label\":\"supplier_id\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"supplier_code\",\"label\":\"supplier_code\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"supplier_name\",\"label\":\"supplier_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"status\",\"label\":\"supplier_product_status\",\"jdbcType\":-6,\"typeName\":\"TINYINT\",\"nullable\":false},{\"name\":\"status\",\"label\":\"supplier_status\",\"jdbcType\":-6,\"typeName\":\"TINYINT\",\"nullable\":false},{\"name\":\"quoted_purchase_price\",\"label\":\"quoted_purchase_price\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":true},{\"name\":\"latest_purchase_price\",\"label\":\"latest_purchase_price\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":true},{\"name\":\"quote_valid_until\",\"label\":\"quote_valid_until\",\"jdbcType\":91,\"typeName\":\"DATE\",\"nullable\":true},{\"name\":\"min_order_qty\",\"label\":\"min_order_qty\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false}]',1,1,'ds_b4145943a6ae4aa2bb7bd3d7bcd98c46.jsonl','READY','2026-12-08 00:00:00.000000','2026-11-23 07:11:30.117123','{\"grain\": \"每个供应商对该产品的供货关系一行\", \"fields\": [{\"name\": \"supplier_id\", \"index\": 0, \"meaning\": \"供应商ID\"}, {\"name\": \"supplier_code\", \"index\": 1, \"meaning\": \"供应商编码\"}, {\"name\": \"supplier_name\", \"index\": 2, \"meaning\": \"供应商名称\"}, {\"name\": \"supplier_product_status\", \"index\": 3, \"meaning\": \"供货关系状态（1启用，0禁用）\"}, {\"name\": \"supplier_status\", \"index\": 4, \"meaning\": \"供应商主档状态（1启用，0禁用）\"}, {\"name\": \"quoted_purchase_price\", \"index\": 5, \"meaning\": \"人工有效报价，单位分\"}, {\"name\": \"latest_purchase_price\", \"index\": 6, \"meaning\": \"最近成交单价，单位分\"}, {\"name\": \"quote_valid_until\", \"index\": 7, \"meaning\": \"报价有效截止日\"}, {\"name\": \"min_order_qty\", \"index\": 8, \"meaning\": \"最小起订量，×100整数存储\"}], \"content\": \"产品 8400000000005001253 的所有未删除供应商供货关系，包含供应商编码、名称、供货关系状态、供应商主档状态、报价、最近成交价、报价有效期及最小起订量。\", \"limitations\": \"结果仅包含逻辑删除标记为正常的记录；价格字段单位为分，最小起订量为×100整数口径。\"}',NULL);
INSERT INTO `ai_dataset` (`dataset_id`, `sql_run_id`, `attempt`, `ready_run_id`, `user_id`, `conversation_id`, `description`, `source_sql`, `columns_json`, `row_count`, `completed`, `storage_file`, `status`, `expires_at`, `created_at`, `data_description_json`, `truncation_reason`) VALUES ('ds_b5292ed6099042d0a504f0b5f10fcd78','sqlrun_e21f2cc7c01341c89f62419e6f04c92b',2,'sqlrun_e21f2cc7c01341c89f62419e6f04c92b',1900000000000000001,2124221025439735809,'统计全部未删除（deleted=0）采购订单按状态分布：每个状态下的订单数、明细下单数量合计、已入库数量合计，用于核实是否存在在途（未入库）采购订单；同时给出最早与最晚创建时间','SELECT po.status AS status, COUNT(DISTINCT po.id) AS po_count, SUM(poi.quantity) / 100.0 AS total_qty, SUM(poi.inbound_qty) / 100.0 AS total_inbound_qty, MIN(po.create_time) AS min_create_time, MAX(po.create_time) AS max_create_time FROM purchase_order po INNER JOIN purchase_order_item poi ON po.id = poi.purchase_order_id WHERE po.deleted = 0 GROUP BY po.status','[{\"name\":\"status\",\"label\":\"status\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"po_count\",\"label\":\"po_count\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"total_qty\",\"label\":\"total_qty\",\"jdbcType\":3,\"typeName\":\"DECIMAL\",\"nullable\":true},{\"name\":\"total_inbound_qty\",\"label\":\"total_inbound_qty\",\"jdbcType\":3,\"typeName\":\"DECIMAL\",\"nullable\":true},{\"name\":\"min_create_time\",\"label\":\"min_create_time\",\"jdbcType\":93,\"typeName\":\"DATETIME\",\"nullable\":true},{\"name\":\"max_create_time\",\"label\":\"max_create_time\",\"jdbcType\":93,\"typeName\":\"DATETIME\",\"nullable\":true}]',1,1,'ds_b5292ed6099042d0a504f0b5f10fcd78.jsonl','READY','2026-12-06 00:00:00.000000','2026-11-21 19:22:00.117931','{\"grain\": \"每个采购订单状态一行\", \"fields\": [{\"name\": \"status\", \"index\": 0, \"meaning\": \"采购订单状态枚举值\"}, {\"name\": \"po_count\", \"index\": 1, \"meaning\": \"该状态下的采购订单数量\"}, {\"name\": \"total_qty\", \"index\": 2, \"meaning\": \"该状态下所有明细的下单数量合计（已还原为业务数量，即原始值/100）\"}, {\"name\": \"total_inbound_qty\", \"index\": 3, \"meaning\": \"该状态下所有明细的累计已入库数量合计（已还原为业务数量，即原始值/100）\"}, {\"name\": \"min_create_time\", \"index\": 4, \"meaning\": \"该状态下采购订单的最早创建时间\"}, {\"name\": \"max_create_time\", \"index\": 5, \"meaning\": \"该状态下采购订单的最晚创建时间\"}], \"content\": \"全部未删除(deleted=0)采购订单按状态分组的统计结果，包含订单数、明细下单数量合计、已入库数量合计及创建时间范围。\", \"limitations\": \"\"}',NULL);
INSERT INTO `ai_dataset` (`dataset_id`, `sql_run_id`, `attempt`, `ready_run_id`, `user_id`, `conversation_id`, `description`, `source_sql`, `columns_json`, `row_count`, `completed`, `storage_file`, `status`, `expires_at`, `created_at`, `data_description_json`, `truncation_reason`) VALUES ('ds_b6a79ce97b304dbfbe3b88b7a80d3e08','sqlrun_1c6433b786d948f7a4954081add4fa8a',1,'sqlrun_1c6433b786d948f7a4954081add4fa8a',1900000000000000001,2124465547335741442,'查询 stock_bill 与 stock_bill_item 中 bill_type 为 \'PURCHASE_RETURN\' 或 \'SALES_RETURN\' 的全部记录（confirmed_at 在 2025-11-23 至 2026-11-22 含端点，全部仓库），保留可用软删除与状态字段。每行给：凭证号、类型、原业务单据ID(business_source_id)、原业务单据号(business_source_no)、仓库、确认时间、变动数量(change_qty/100)、产品名称、单位。用于核对哪些退货单真实生成了库存流水，以及 PRE 窗口采购退货是否有库存变动。','SELECT sb.bill_no AS bill_no, sb.bill_type AS bill_type, sb.business_source_id AS business_source_id, sb.business_source_no AS business_source_no, sb.warehouse_name AS warehouse_name, sb.confirmed_at AS confirmed_at, sbi.change_qty / 100.0 AS change_qty, sbi.product_name AS product_name, sbi.unit_name AS unit_name FROM stock_bill sb JOIN stock_bill_item sbi ON sb.id = sbi.bill_id WHERE sb.bill_type IN (\'PURCHASE_RETURN\', \'SALES_RETURN\') AND sb.confirmed_at >= \'2025-11-23 00:00:00\' AND sb.confirmed_at <= \'2026-11-22 23:59:59\'','[{\"name\":\"bill_no\",\"label\":\"bill_no\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"bill_type\",\"label\":\"bill_type\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"business_source_id\",\"label\":\"business_source_id\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":true},{\"name\":\"business_source_no\",\"label\":\"business_source_no\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"warehouse_name\",\"label\":\"warehouse_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"confirmed_at\",\"label\":\"confirmed_at\",\"jdbcType\":93,\"typeName\":\"DATETIME\",\"nullable\":false},{\"name\":\"change_qty\",\"label\":\"change_qty\",\"jdbcType\":3,\"typeName\":\"DECIMAL\",\"nullable\":true},{\"name\":\"product_name\",\"label\":\"product_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"unit_name\",\"label\":\"unit_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false}]',93,1,'ds_b6a79ce97b304dbfbe3b88b7a80d3e08.jsonl','READY','2026-12-07 00:00:00.000000','2026-11-22 11:35:04.479186','{\"grain\": \"每条库存流水凭证明细一行\", \"fields\": [{\"name\": \"bill_no\", \"index\": 0, \"meaning\": \"库存流水凭证号\"}, {\"name\": \"bill_type\", \"index\": 1, \"meaning\": \"库存流水类型 (PURCHASE_RETURN: 采购退货, SALES_RETURN: 销售退货)\"}, {\"name\": \"business_source_id\", \"index\": 2, \"meaning\": \"原业务单据ID (如退货单ID)\"}, {\"name\": \"business_source_no\", \"index\": 3, \"meaning\": \"原业务单据号 (如退货单号)\"}, {\"name\": \"warehouse_name\", \"index\": 4, \"meaning\": \"执行仓库名称\"}, {\"name\": \"confirmed_at\", \"index\": 5, \"meaning\": \"库存流水确认时间\"}, {\"name\": \"change_qty\", \"index\": 6, \"meaning\": \"库存变动数量 (入库为正，出库为负，已除以100还原为实际业务数量)\"}, {\"name\": \"product_name\", \"index\": 7, \"meaning\": \"产品名称\"}, {\"name\": \"unit_name\", \"index\": 8, \"meaning\": \"产品单位\"}], \"content\": \"查询了2025-11-23至2026-11-22期间，所有仓库中类型为采购退货(PURCHASE_RETURN)或销售退货(SALES_RETURN)的库存流水凭证明细。数据包含凭证号、类型、原业务单据信息、仓库、确认时间、变动数量(已还原为实际单位)、产品名称及单位。\", \"limitations\": \"\"}',NULL);
INSERT INTO `ai_dataset` (`dataset_id`, `sql_run_id`, `attempt`, `ready_run_id`, `user_id`, `conversation_id`, `description`, `source_sql`, `columns_json`, `row_count`, `completed`, `storage_file`, `status`, `expires_at`, `created_at`, `data_description_json`, `truncation_reason`) VALUES ('ds_ba8fa152d7544a0aa705d0df3f847ab3','sqlrun_263f7493ab8c4e43b82beef79919127f',1,'sqlrun_263f7493ab8c4e43b82beef79919127f',1900000000000000001,2124364502374834178,'查询库存余额表 warehouse_stock 中产品ID = 8400000000005000227（P000227 最佳选择 全麦饼干）在各仓库的库存记录，返回仓库、当前库存数量、锁定数量（均按100倍整数存储）','SELECT warehouse_id, warehouse_name, product_code, product_name, unit_name, stock_qty, locked_qty FROM warehouse_stock WHERE product_id = 8400000000005000227','[{\"name\":\"warehouse_id\",\"label\":\"warehouse_id\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"warehouse_name\",\"label\":\"warehouse_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"product_code\",\"label\":\"product_code\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"product_name\",\"label\":\"product_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"unit_name\",\"label\":\"unit_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"stock_qty\",\"label\":\"stock_qty\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"locked_qty\",\"label\":\"locked_qty\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false}]',1,1,'ds_ba8fa152d7544a0aa705d0df3f847ab3.jsonl','READY','2026-12-07 00:00:00.000000','2026-11-22 04:51:10.511927','{\"grain\": \"每个仓库一条记录\", \"fields\": [{\"name\": \"warehouse_id\", \"index\": 0, \"meaning\": \"仓库ID\"}, {\"name\": \"warehouse_name\", \"index\": 1, \"meaning\": \"仓库名称\"}, {\"name\": \"product_code\", \"index\": 2, \"meaning\": \"产品编码\"}, {\"name\": \"product_name\", \"index\": 3, \"meaning\": \"产品名称\"}, {\"name\": \"unit_name\", \"index\": 4, \"meaning\": \"计量单位\"}, {\"name\": \"stock_qty\", \"index\": 5, \"meaning\": \"当前账面库存数量（×100整数存储，需除以100得到业务数量）\"}, {\"name\": \"locked_qty\", \"index\": 6, \"meaning\": \"锁定库存数量（×100整数存储，需除以100得到业务数量；可用库存 = stock_qty - locked_qty）\"}], \"content\": \"产品P000227（最佳选择 全麦饼干）在所有仓库的当前库存余额及锁定情况\", \"limitations\": \"stock_qty和locked_qty均为×100整数存储，展示或计算时需除以100还原为业务数量。安全库存比较时需注意口径一致（product.safety_stock_qty也是×100存储）。\"}',NULL);
INSERT INTO `ai_dataset` (`dataset_id`, `sql_run_id`, `attempt`, `ready_run_id`, `user_id`, `conversation_id`, `description`, `source_sql`, `columns_json`, `row_count`, `completed`, `storage_file`, `status`, `expires_at`, `created_at`, `data_description_json`, `truncation_reason`) VALUES ('ds_badb4730305047619592fb58a8a02892','sqlrun_1b1fcb9633494d309337c26f41eefa02',1,'sqlrun_1b1fcb9633494d309337c26f41eefa02',1900000000000000001,2124424075508994050,'查询产品 P000005 在全部仓库的全部销售订单明细（排除已取消、未删除订单），不限时间，返回销售单号、订单状态、仓库、客户、销售数量、锁定数量、已出库数量、单价、预计发货日期、审核时间、创建时间','SELECT so.sales_no AS sales_no, so.status AS status, so.warehouse_name AS warehouse_name, so.customer_name AS customer_name, soi.quantity / 100.0 AS quantity, soi.locked_qty / 100.0 AS locked_qty, soi.outbound_qty / 100.0 AS outbound_qty, soi.unit_price / 100.0 AS unit_price, so.expected_delivery_date AS expected_delivery_date, so.approved_at AS approved_at, so.create_time AS create_time FROM sales_order so JOIN sales_order_item soi ON so.id = soi.sales_order_id WHERE so.deleted = 0 AND so.status != \'CANCELLED\' AND soi.product_code = \'P000005\'','[{\"name\":\"sales_no\",\"label\":\"sales_no\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"status\",\"label\":\"status\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"warehouse_name\",\"label\":\"warehouse_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"customer_name\",\"label\":\"customer_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"quantity\",\"label\":\"quantity\",\"jdbcType\":3,\"typeName\":\"DECIMAL\",\"nullable\":true},{\"name\":\"locked_qty\",\"label\":\"locked_qty\",\"jdbcType\":3,\"typeName\":\"DECIMAL\",\"nullable\":true},{\"name\":\"outbound_qty\",\"label\":\"outbound_qty\",\"jdbcType\":3,\"typeName\":\"DECIMAL\",\"nullable\":true},{\"name\":\"unit_price\",\"label\":\"unit_price\",\"jdbcType\":3,\"typeName\":\"DECIMAL\",\"nullable\":true},{\"name\":\"expected_delivery_date\",\"label\":\"expected_delivery_date\",\"jdbcType\":91,\"typeName\":\"DATE\",\"nullable\":true},{\"name\":\"approved_at\",\"label\":\"approved_at\",\"jdbcType\":93,\"typeName\":\"DATETIME\",\"nullable\":true},{\"name\":\"create_time\",\"label\":\"create_time\",\"jdbcType\":93,\"typeName\":\"DATETIME\",\"nullable\":false}]',14,1,'ds_badb4730305047619592fb58a8a02892.jsonl','READY','2026-12-07 00:00:00.000000','2026-11-22 08:49:23.634710','{\"grain\": \"每笔销售订单中针对产品P000005的一条明细记录\", \"fields\": [{\"name\": \"sales_no\", \"index\": 0, \"meaning\": \"销售单号\"}, {\"name\": \"status\", \"index\": 1, \"meaning\": \"订单状态（如DRAFT/SUBMITTED/APPROVED/PARTIAL_OUTBOUND/OUTBOUND_DONE）\"}, {\"name\": \"warehouse_name\", \"index\": 2, \"meaning\": \"出库仓库名称快照\"}, {\"name\": \"customer_name\", \"index\": 3, \"meaning\": \"客户名称快照\"}, {\"name\": \"quantity\", \"index\": 4, \"meaning\": \"销售数量（已从×100整数还原为业务单位数值）\"}, {\"name\": \"locked_qty\", \"index\": 5, \"meaning\": \"已锁定库存数量（已从×100整数还原为业务单位数值）\"}, {\"name\": \"outbound_qty\", \"index\": 6, \"meaning\": \"已出库数量（已从×100整数还原为业务单位数值）\"}, {\"name\": \"unit_price\", \"index\": 7, \"meaning\": \"销售单价（元，已从分口径除以100）\"}, {\"name\": \"expected_delivery_date\", \"index\": 8, \"meaning\": \"预计发货日期\"}, {\"name\": \"approved_at\", \"index\": 9, \"meaning\": \"订单审核通过时间\"}, {\"name\": \"create_time\", \"index\": 10, \"meaning\": \"订单创建时间\"}], \"content\": \"产品P000005在所有仓库的销售订单明细记录，排除已取消(CANCELLED)和逻辑删除(deleted=1)的订单，包含未完成及已完成状态的订单\", \"limitations\": \"\"}',NULL);
INSERT INTO `ai_dataset` (`dataset_id`, `sql_run_id`, `attempt`, `ready_run_id`, `user_id`, `conversation_id`, `description`, `source_sql`, `columns_json`, `row_count`, `completed`, `storage_file`, `status`, `expires_at`, `created_at`, `data_description_json`, `truncation_reason`) VALUES ('ds_bec3c9e5d9db4d1fab50d916b541bfec','sqlrun_3a7108c21819434798524d578f98920d',1,'sqlrun_3a7108c21819434798524d578f98920d',1900000000000000001,2124364502374834178,'在产品表 product 中查询产品名称包含\"全麦饼干\"的产品记录，返回产品ID、产品编码、名称、单位、数量精度、参考采购价、参考销售价、安全库存、状态、是否删除','SELECT id AS product_id, product_code, product_name, unit_name, quantity_precision, reference_purchase_price, reference_sale_price, safety_stock_qty, status, deleted FROM product WHERE product_name LIKE \'%全麦饼干%\' AND deleted = 0','[{\"name\":\"id\",\"label\":\"product_id\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"product_code\",\"label\":\"product_code\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"product_name\",\"label\":\"product_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"unit_name\",\"label\":\"unit_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"quantity_precision\",\"label\":\"quantity_precision\",\"jdbcType\":-6,\"typeName\":\"TINYINT\",\"nullable\":false},{\"name\":\"reference_purchase_price\",\"label\":\"reference_purchase_price\",\"jdbcType\":3,\"typeName\":\"DECIMAL\",\"nullable\":false},{\"name\":\"reference_sale_price\",\"label\":\"reference_sale_price\",\"jdbcType\":3,\"typeName\":\"DECIMAL\",\"nullable\":false},{\"name\":\"safety_stock_qty\",\"label\":\"safety_stock_qty\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"status\",\"label\":\"status\",\"jdbcType\":-6,\"typeName\":\"TINYINT\",\"nullable\":false},{\"name\":\"deleted\",\"label\":\"deleted\",\"jdbcType\":-6,\"typeName\":\"TINYINT\",\"nullable\":false}]',5,1,'ds_bec3c9e5d9db4d1fab50d916b541bfec.jsonl','READY','2026-12-07 00:00:00.000000','2026-11-22 04:49:08.316279','{\"grain\": \"每行代表一个具体的产品记录。\", \"fields\": [{\"name\": \"product_id\", \"index\": 0, \"meaning\": \"产品ID\"}, {\"name\": \"product_code\", \"index\": 1, \"meaning\": \"产品编码\"}, {\"name\": \"product_name\", \"index\": 2, \"meaning\": \"产品名称\"}, {\"name\": \"unit_name\", \"index\": 3, \"meaning\": \"单位名称\"}, {\"name\": \"quantity_precision\", \"index\": 4, \"meaning\": \"数量小数位精度（0-2）\"}, {\"name\": \"reference_purchase_price\", \"index\": 5, \"meaning\": \"参考采购价（单位：元）\"}, {\"name\": \"reference_sale_price\", \"index\": 6, \"meaning\": \"参考销售价（单位：元）\"}, {\"name\": \"safety_stock_qty\", \"index\": 7, \"meaning\": \"安全库存数量（存储值为实际数量的100倍，例如1000表示10.00）\"}, {\"name\": \"status\", \"index\": 8, \"meaning\": \"状态（1启用，0禁用）\"}, {\"name\": \"deleted\", \"index\": 9, \"meaning\": \"逻辑删除标记（0正常，1删除）\"}], \"content\": \"ERP系统中产品名称包含\\\"全麦饼干\\\"的有效产品主档信息，包括ID、编码、名称、单位、精度、参考价及安全库存等。\", \"limitations\": \"\"}',NULL);
INSERT INTO `ai_dataset` (`dataset_id`, `sql_run_id`, `attempt`, `ready_run_id`, `user_id`, `conversation_id`, `description`, `source_sql`, `columns_json`, `row_count`, `completed`, `storage_file`, `status`, `expires_at`, `created_at`, `data_description_json`, `truncation_reason`) VALUES ('ds_c0ce6bc7d63548c99ea87be1f9b4639f','sqlrun_a35d866fd92c49669050289cfa13e5cd',1,'sqlrun_a35d866fd92c49669050289cfa13e5cd',1900000000000000001,2124421893103570946,'查询产品ID 8400000000005000173（P000173）当前在途/未完成采购的明细，purchase_order.status 属于 DRAFT、SUBMITTED、APPROVED、PARTIAL_INBOUND、deleted=0。逐行返回：采购单号、供应商名称、目标入库仓库名称、订单状态、预计到货日期、采购数量quantity（100倍）、已入库inbound_qty（100倍）、未入库数量quantity-inbound_qty。用于判断是否存在在途或未确认采购会继续增加库存。','SELECT po.purchase_no AS purchase_no, po.supplier_name AS supplier_name, po.warehouse_name AS warehouse_name, po.status AS status, po.expected_arrival_date AS expected_arrival_date, poi.quantity AS quantity, poi.inbound_qty AS inbound_qty, (poi.quantity - poi.inbound_qty) AS remaining_qty, poi.unit_price AS unit_price, po.approved_at AS approved_at FROM purchase_order po JOIN purchase_order_item poi ON po.id = poi.purchase_order_id WHERE po.deleted = 0 AND po.status IN (\'DRAFT\', \'SUBMITTED\', \'APPROVED\', \'PARTIAL_INBOUND\') AND poi.product_id = 8400000000005000173','[{\"name\":\"purchase_no\",\"label\":\"purchase_no\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"supplier_name\",\"label\":\"supplier_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"warehouse_name\",\"label\":\"warehouse_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"status\",\"label\":\"status\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"expected_arrival_date\",\"label\":\"expected_arrival_date\",\"jdbcType\":91,\"typeName\":\"DATE\",\"nullable\":true},{\"name\":\"quantity\",\"label\":\"quantity\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"inbound_qty\",\"label\":\"inbound_qty\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"remaining_qty\",\"label\":\"remaining_qty\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"unit_price\",\"label\":\"unit_price\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"approved_at\",\"label\":\"approved_at\",\"jdbcType\":93,\"typeName\":\"DATETIME\",\"nullable\":true}]',0,1,'ds_c0ce6bc7d63548c99ea87be1f9b4639f.jsonl','READY','2026-12-07 00:00:00.000000','2026-11-22 08:38:28.573409','{\"grain\": \"每张符合条件的采购订单中该产品的每一行明细\", \"fields\": [{\"name\": \"purchase_no\", \"index\": 0, \"meaning\": \"采购单号\"}, {\"name\": \"supplier_name\", \"index\": 1, \"meaning\": \"供应商名称快照\"}, {\"name\": \"warehouse_name\", \"index\": 2, \"meaning\": \"目标入库仓库名称快照\"}, {\"name\": \"status\", \"index\": 3, \"meaning\": \"采购订单状态 (DRAFT/SUBMITTED/APPROVED/PARTIAL_INBOUND)\"}, {\"name\": \"expected_arrival_date\", \"index\": 4, \"meaning\": \"预计到货日期\"}, {\"name\": \"quantity\", \"index\": 5, \"meaning\": \"采购总数量 (放大100倍整数存储)\"}, {\"name\": \"inbound_qty\", \"index\": 6, \"meaning\": \"已入库数量 (放大100倍整数存储)\"}, {\"name\": \"remaining_qty\", \"index\": 7, \"meaning\": \"未入库数量 (quantity - inbound_qty, 放大100倍整数存储)\"}, {\"name\": \"unit_price\", \"index\": 8, \"meaning\": \"采购单价 (单位: 分)\"}, {\"name\": \"approved_at\", \"index\": 9, \"meaning\": \"订单审核通过时间\"}], \"content\": \"产品ID 8400000000005000173 (P000173) 的在途/未完成采购明细列表。包含采购单号、供应商、仓库、状态、预计到货日期、数量（100倍存储）、已入库量（100倍存储）、剩余未入库量（100倍存储）、单价（分）及审核时间。\", \"limitations\": \"无数据返回，表明该产品当前无在途或未完成的采购订单。\"}',NULL);
INSERT INTO `ai_dataset` (`dataset_id`, `sql_run_id`, `attempt`, `ready_run_id`, `user_id`, `conversation_id`, `description`, `source_sql`, `columns_json`, `row_count`, `completed`, `storage_file`, `status`, `expires_at`, `created_at`, `data_description_json`, `truncation_reason`) VALUES ('ds_c7cc4f42fd99473ab8d6a3baddc1e303','sqlrun_e9310f5b71814f8a9847d6ed1f2bd31e',1,'sqlrun_e9310f5b71814f8a9847d6ed1f2bd31e',1900000000000000001,2124418644136972290,'查询 product 表中 status=1 且 deleted=0 的全部启用产品，返回产品ID、产品编码、产品名称、单位、quantity_precision、safety_stock_qty（100倍整数），用于比对哪些产品在 warehouse_stock 中无库存记录','SELECT p.id AS product_id, p.product_code, p.product_name, p.unit_name, p.quantity_precision, p.safety_stock_qty FROM product p WHERE p.status = 1 AND p.deleted = 0','[{\"name\":\"id\",\"label\":\"product_id\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"product_code\",\"label\":\"product_code\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"product_name\",\"label\":\"product_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"unit_name\",\"label\":\"unit_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"quantity_precision\",\"label\":\"quantity_precision\",\"jdbcType\":-6,\"typeName\":\"TINYINT\",\"nullable\":false},{\"name\":\"safety_stock_qty\",\"label\":\"safety_stock_qty\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false}]',1560,1,'ds_c7cc4f42fd99473ab8d6a3baddc1e303.jsonl','READY','2026-12-07 00:00:00.000000','2026-11-22 08:26:58.603611','{\"grain\": \"每个产品一行\", \"fields\": [{\"name\": \"product_id\", \"index\": 0, \"meaning\": \"产品ID\"}, {\"name\": \"product_code\", \"index\": 1, \"meaning\": \"产品编码\"}, {\"name\": \"product_name\", \"index\": 2, \"meaning\": \"产品名称\"}, {\"name\": \"unit_name\", \"index\": 3, \"meaning\": \"单位名称\"}, {\"name\": \"quantity_precision\", \"index\": 4, \"meaning\": \"数量小数位精度(0-2)\"}, {\"name\": \"safety_stock_qty\", \"index\": 5, \"meaning\": \"安全库存数量，按100倍整数存储（例如4400表示44.00）\"}], \"content\": \"所有状态为启用(status=1)且未逻辑删除(deleted=0)的产品主档信息，用于识别在库存表中无对应记录的产品。\", \"limitations\": \"\"}',NULL);
INSERT INTO `ai_dataset` (`dataset_id`, `sql_run_id`, `attempt`, `ready_run_id`, `user_id`, `conversation_id`, `description`, `source_sql`, `columns_json`, `row_count`, `completed`, `storage_file`, `status`, `expires_at`, `created_at`, `data_description_json`, `truncation_reason`) VALUES ('ds_cb78e8a523e04a4a8be9ca6aad3f2c0b','sqlrun_c0cf546c7e5f4747bddc4ddfa9ad781d',1,'sqlrun_c0cf546c7e5f4747bddc4ddfa9ad781d',1900000000000000001,2124475847040573442,'查询全部未逻辑删除（deleted=0）的产品主档记录，每产品一行，返回产品ID、编码、名称、单位、数量小数位、安全库存数量safety_stock_qty、启用状态status。数量保持100倍整数原值，不做筛选。','SELECT id AS product_id, product_code, product_name, unit_name, quantity_precision, safety_stock_qty, status FROM product WHERE deleted = 0','[{\"name\":\"id\",\"label\":\"product_id\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"product_code\",\"label\":\"product_code\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"product_name\",\"label\":\"product_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"unit_name\",\"label\":\"unit_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"quantity_precision\",\"label\":\"quantity_precision\",\"jdbcType\":-6,\"typeName\":\"TINYINT\",\"nullable\":false},{\"name\":\"safety_stock_qty\",\"label\":\"safety_stock_qty\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"status\",\"label\":\"status\",\"jdbcType\":-6,\"typeName\":\"TINYINT\",\"nullable\":false}]',1560,1,'ds_cb78e8a523e04a4a8be9ca6aad3f2c0b.jsonl','READY','2026-12-07 00:00:00.000000','2026-11-22 12:13:52.280666','{\"grain\": \"每个产品一行\", \"fields\": [{\"name\": \"product_id\", \"index\": 0, \"meaning\": \"产品ID\"}, {\"name\": \"product_code\", \"index\": 1, \"meaning\": \"产品编码\"}, {\"name\": \"product_name\", \"index\": 2, \"meaning\": \"产品名称\"}, {\"name\": \"unit_name\", \"index\": 3, \"meaning\": \"单位名称\"}, {\"name\": \"quantity_precision\", \"index\": 4, \"meaning\": \"数量小数位精度（0-2）\"}, {\"name\": \"safety_stock_qty\", \"index\": 5, \"meaning\": \"安全库存数量（按100倍整数存储，例如4400表示44.00）\"}, {\"name\": \"status\", \"index\": 6, \"meaning\": \"启用状态（1启用，0禁用）\"}], \"content\": \"ERP系统中所有未逻辑删除（deleted=0）的产品主档信息，包含用于调拨判断的安全库存阈值及相关基础属性。\", \"limitations\": \"\"}',NULL);
INSERT INTO `ai_dataset` (`dataset_id`, `sql_run_id`, `attempt`, `ready_run_id`, `user_id`, `conversation_id`, `description`, `source_sql`, `columns_json`, `row_count`, `completed`, `storage_file`, `status`, `expires_at`, `created_at`, `data_description_json`, `truncation_reason`) VALUES ('ds_ce18e33304254591838a1537a2794e84','sqlrun_d56c583fc8114f79a7d6ba0d7548eb23',1,'sqlrun_d56c583fc8114f79a7d6ba0d7548eb23',1900000000000000001,2124364502374834178,'查询供应商供货产品表 supplier_product 中 product_id 属于 8400000000005000538、8400000000005000849、8400000000005001165、8400000000005001476（其余四个全麦饼干 SKU）的供货记录，返回供应商ID、产品ID、报价、最近成交价、起订量、推荐分、评分状态、平均交期、启用状态，用于了解同类产品可用的供应商资源池','SELECT supplier_id, product_id, quoted_purchase_price, latest_purchase_price, min_order_qty, recommend_score, score_status, avg_delivery_days, status FROM supplier_product WHERE deleted = 0 AND product_id IN (8400000000005000538, 8400000000005000849, 8400000000005001165, 8400000000005001476)','[{\"name\":\"supplier_id\",\"label\":\"supplier_id\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"product_id\",\"label\":\"product_id\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"quoted_purchase_price\",\"label\":\"quoted_purchase_price\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":true},{\"name\":\"latest_purchase_price\",\"label\":\"latest_purchase_price\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":true},{\"name\":\"min_order_qty\",\"label\":\"min_order_qty\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"recommend_score\",\"label\":\"recommend_score\",\"jdbcType\":4,\"typeName\":\"INT\",\"nullable\":true},{\"name\":\"score_status\",\"label\":\"score_status\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"avg_delivery_days\",\"label\":\"avg_delivery_days\",\"jdbcType\":3,\"typeName\":\"DECIMAL\",\"nullable\":true},{\"name\":\"status\",\"label\":\"status\",\"jdbcType\":-6,\"typeName\":\"TINYINT\",\"nullable\":false}]',4,1,'ds_ce18e33304254591838a1537a2794e84.jsonl','READY','2026-12-07 00:00:00.000000','2026-11-22 04:51:30.393175','{\"grain\": \"每个供应商-产品组合一条记录\", \"fields\": [{\"name\": \"supplier_id\", \"index\": 0, \"meaning\": \"供应商ID\"}, {\"name\": \"product_id\", \"index\": 1, \"meaning\": \"产品ID\"}, {\"name\": \"quoted_purchase_price\", \"index\": 2, \"meaning\": \"人工有效报价，单位分（展示时需除以100转换为元）\"}, {\"name\": \"latest_purchase_price\", \"index\": 3, \"meaning\": \"最近成交单价，单位分（展示时需除以100转换为元）\"}, {\"name\": \"min_order_qty\", \"index\": 4, \"meaning\": \"最小起订量，按100倍整数存储（展示时需除以100转换为业务数量）\"}, {\"name\": \"recommend_score\", \"index\": 5, \"meaning\": \"供应产品推荐评分，INT×100存储（展示时需除以100转换为0-100分值；NULL表示样本不足）\"}, {\"name\": \"score_status\", \"index\": 6, \"meaning\": \"评分状态：READY表示可参与评分，NOT_READY表示样本不足\"}, {\"name\": \"avg_delivery_days\", \"index\": 7, \"meaning\": \"最近180天完全入库采购单的金额加权平均到货周期，单位天（历史统计值）\"}, {\"name\": \"status\", \"index\": 8, \"meaning\": \"供货关系启用状态：1启用，0禁用\"}], \"content\": \"指定四个全麦饼干SKU的供应商供货关系明细，用于分析现有供应商资源池。\", \"limitations\": \"价格字段单位为分，数量字段为×100整数，评分字段为×100整数，直接读取原始数值会导致量级错误，需按业务口径换算后使用。avg_delivery_days仅为历史统计参考，不代表当前承诺交期。\"}',NULL);
INSERT INTO `ai_dataset` (`dataset_id`, `sql_run_id`, `attempt`, `ready_run_id`, `user_id`, `conversation_id`, `description`, `source_sql`, `columns_json`, `row_count`, `completed`, `storage_file`, `status`, `expires_at`, `created_at`, `data_description_json`, `truncation_reason`) VALUES ('ds_cfd3d342254c453a87157bd131c62f06','sqlrun_9343c8eadd514413bbb1c9839b579b45',1,'sqlrun_9343c8eadd514413bbb1c9839b579b45',1900000000000000001,2124221025439735809,'查询采购订单中状态为 SUBMITTED、APPROVED、PARTIAL_INBOUND 且 deleted=0 的未完成订单，按产品汇总：未完成订单数、下单数量合计（purchase_order_item.quantity，100倍整数）、已入库数量合计（purchase_order_item.inbound_qty，100倍整数）、在途未入库量（quantity - inbound_qty，100倍整数）','SELECT poi.product_id AS product_id, MAX(poi.product_code) AS product_code, MAX(poi.product_name) AS product_name, COUNT(DISTINCT po.id) AS open_po_count, SUM(poi.quantity) AS open_po_qty, SUM(poi.inbound_qty) AS inbound_qty, SUM(poi.quantity - poi.inbound_qty) AS pending_qty FROM purchase_order po JOIN purchase_order_item poi ON po.id = poi.purchase_order_id WHERE po.deleted = 0 AND po.status IN (\'SUBMITTED\', \'APPROVED\', \'PARTIAL_INBOUND\') GROUP BY poi.product_id','[{\"name\":\"product_id\",\"label\":\"product_id\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"product_code\",\"label\":\"product_code\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":true},{\"name\":\"product_name\",\"label\":\"product_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":true},{\"name\":\"open_po_count\",\"label\":\"open_po_count\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"open_po_qty\",\"label\":\"open_po_qty\",\"jdbcType\":3,\"typeName\":\"DECIMAL\",\"nullable\":true},{\"name\":\"inbound_qty\",\"label\":\"inbound_qty\",\"jdbcType\":3,\"typeName\":\"DECIMAL\",\"nullable\":true},{\"name\":\"pending_qty\",\"label\":\"pending_qty\",\"jdbcType\":3,\"typeName\":\"DECIMAL\",\"nullable\":true}]',0,1,'ds_cfd3d342254c453a87157bd131c62f06.jsonl','READY','2026-12-06 00:00:00.000000','2026-11-21 19:21:46.073955','{\"grain\": \"每个产品一行\", \"fields\": [{\"name\": \"product_id\", \"index\": 0, \"meaning\": \"产品ID\"}, {\"name\": \"product_code\", \"index\": 1, \"meaning\": \"产品编码\"}, {\"name\": \"product_name\", \"index\": 2, \"meaning\": \"产品名称\"}, {\"name\": \"open_po_count\", \"index\": 3, \"meaning\": \"未完成采购订单数（去重后的订单ID计数）\"}, {\"name\": \"open_po_qty\", \"index\": 4, \"meaning\": \"下单数量合计（原始值×100，即放大100倍的整数存储值）\"}, {\"name\": \"inbound_qty\", \"index\": 5, \"meaning\": \"已入库数量合计（原始值×100，即放大100倍的整数存储值）\"}, {\"name\": \"pending_qty\", \"index\": 6, \"meaning\": \"在途未入库量（原始值×100，即下单数量减去已入库数量的差值）\"}], \"content\": \"统计处于待审核(SUBMITTED)、待入库(APPROVED)或部分入库(PARTIAL_INBOUND)状态的采购订单中，各产品的未完成订单数量及库存相关指标。\", \"limitations\": \"数量字段均为数据库原始存储值（放大100倍），展示时需除以100还原为业务单位；当前查询结果为空集。\"}',NULL);
INSERT INTO `ai_dataset` (`dataset_id`, `sql_run_id`, `attempt`, `ready_run_id`, `user_id`, `conversation_id`, `description`, `source_sql`, `columns_json`, `row_count`, `completed`, `storage_file`, `status`, `expires_at`, `created_at`, `data_description_json`, `truncation_reason`) VALUES ('ds_d01877d3aef643fc9805906e35552652','sqlrun_e3f34d9a0a7b4aad903a8fa419b4c37f',1,'sqlrun_e3f34d9a0a7b4aad903a8fa419b4c37f',1900000000000000001,2124421893103570946,'查询产品ID 8400000000005000173（P000173）当前待执行的销售订单明细，sales_order.status 属于 APPROVED 或 PARTIAL_OUTBOUND、deleted=0。逐行返回：销售单号、客户名称、出库仓库名称、订单状态、预计发货日期、订单数量quantity（100倍）、已锁定locked_qty、已出库outbound_qty、未出库数量（quantity-outbound_qty）。用于判断是否存在已确认但未执行的销售需求。','SELECT so.sales_no AS sales_no, so.customer_name AS customer_name, so.warehouse_name AS warehouse_name, so.status AS status, so.expected_delivery_date AS expected_delivery_date, soi.quantity AS quantity, soi.locked_qty AS locked_qty, soi.outbound_qty AS outbound_qty, (soi.quantity - soi.outbound_qty) AS unshipped_qty, soi.unit_price AS unit_price, so.approved_at AS approved_at FROM sales_order so JOIN sales_order_item soi ON so.id = soi.sales_order_id WHERE so.deleted = 0 AND so.status IN (\'APPROVED\', \'PARTIAL_OUTBOUND\') AND soi.product_id = 8400000000005000173','[{\"name\":\"sales_no\",\"label\":\"sales_no\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"customer_name\",\"label\":\"customer_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"warehouse_name\",\"label\":\"warehouse_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"status\",\"label\":\"status\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"expected_delivery_date\",\"label\":\"expected_delivery_date\",\"jdbcType\":91,\"typeName\":\"DATE\",\"nullable\":true},{\"name\":\"quantity\",\"label\":\"quantity\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"locked_qty\",\"label\":\"locked_qty\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"outbound_qty\",\"label\":\"outbound_qty\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"unshipped_qty\",\"label\":\"unshipped_qty\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"unit_price\",\"label\":\"unit_price\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"approved_at\",\"label\":\"approved_at\",\"jdbcType\":93,\"typeName\":\"DATETIME\",\"nullable\":true}]',0,1,'ds_d01877d3aef643fc9805906e35552652.jsonl','READY','2026-12-07 00:00:00.000000','2026-11-22 08:38:15.407292','{\"grain\": \"每张符合条件的销售订单中该产品的一行明细\", \"fields\": [{\"name\": \"sales_no\", \"index\": 0, \"meaning\": \"销售单号\"}, {\"name\": \"customer_name\", \"index\": 1, \"meaning\": \"客户名称快照\"}, {\"name\": \"warehouse_name\", \"index\": 2, \"meaning\": \"出库仓库名称快照\"}, {\"name\": \"status\", \"index\": 3, \"meaning\": \"订单状态 (APPROVED 或 PARTIAL_OUTBOUND)\"}, {\"name\": \"expected_delivery_date\", \"index\": 4, \"meaning\": \"预计发货日期\"}, {\"name\": \"quantity\", \"index\": 5, \"meaning\": \"订单数量 (存储值为实际数量的100倍)\"}, {\"name\": \"locked_qty\", \"index\": 6, \"meaning\": \"已锁定库存数量 (存储值为实际数量的100倍)\"}, {\"name\": \"outbound_qty\", \"index\": 7, \"meaning\": \"已出库数量 (存储值为实际数量的100倍)\"}, {\"name\": \"unshipped_qty\", \"index\": 8, \"meaning\": \"未出库数量 (计算值: quantity - outbound_qty, 存储值为实际数量的100倍)\"}, {\"name\": \"unit_price\", \"index\": 9, \"meaning\": \"销售单价 (单位分)\"}, {\"name\": \"approved_at\", \"index\": 10, \"meaning\": \"订单审核时间\"}], \"content\": \"产品P000173当前处于已审核(APPROVED)或部分出库(PARTIAL_OUTBOUND)状态的销售订单明细列表\", \"limitations\": \"\"}',NULL);
INSERT INTO `ai_dataset` (`dataset_id`, `sql_run_id`, `attempt`, `ready_run_id`, `user_id`, `conversation_id`, `description`, `source_sql`, `columns_json`, `row_count`, `completed`, `storage_file`, `status`, `expires_at`, `created_at`, `data_description_json`, `truncation_reason`) VALUES ('ds_d1268f13637d4ef8b184bb1ee8b2031b','sqlrun_60c425eae62c483d8aee72b6aa085cc5',1,'sqlrun_60c425eae62c483d8aee72b6aa085cc5',1900000000000000001,2124210189346299906,'查询所有未删除的启用仓库清单，用于确定用户关心“哪批采购晚到”时可选的仓库范围','SELECT warehouse_code AS `仓库编码`, warehouse_name AS `仓库名称`, status AS `状态` FROM warehouse WHERE deleted = 0 AND status = 1','[{\"name\":\"warehouse_code\",\"label\":\"仓库编码\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"warehouse_name\",\"label\":\"仓库名称\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"status\",\"label\":\"状态\",\"jdbcType\":-6,\"typeName\":\"TINYINT\",\"nullable\":false}]',5,1,'ds_d1268f13637d4ef8b184bb1ee8b2031b.jsonl','READY','2026-12-06 00:00:00.000000','2026-11-21 18:37:02.400157','{\"grain\": \"每个仓库一行\", \"fields\": [{\"name\": \"仓库编码\", \"index\": 0, \"meaning\": \"仓库编码\"}, {\"name\": \"仓库名称\", \"index\": 1, \"meaning\": \"仓库名称\"}, {\"name\": \"状态\", \"index\": 2, \"meaning\": \"仓库状态（1表示启用）\"}], \"content\": \"所有未删除且处于启用状态（status=1）的仓库主档信息，用于提供业务操作时的仓库选项列表。\", \"limitations\": \"\"}',NULL);
INSERT INTO `ai_dataset` (`dataset_id`, `sql_run_id`, `attempt`, `ready_run_id`, `user_id`, `conversation_id`, `description`, `source_sql`, `columns_json`, `row_count`, `completed`, `storage_file`, `status`, `expires_at`, `created_at`, `data_description_json`, `truncation_reason`) VALUES ('ds_d6034a913a244931b53a9bf30177bcdc','sqlrun_5b1d27ac4822475ca4f9040effd506cb',1,'sqlrun_5b1d27ac4822475ca4f9040effd506cb',1900000000000000001,2124465547335741442,'按确认月份聚合统计 outbound_bill 中 outbound_type=\'SALES_OUT\'、status=\'CONFIRMED\'、deleted=0 的记录，confirmed_at 在 2025-11-23 至 2026-11-22（含端点），全部仓库。每月输出：出库单数、数量合计（sum(outbound_bill_item.current_qty)/100）、金额合计（sum(outbound_bill_item.current_qty * sales_order_item.unit_price)/10000 元，通过 outbound_bill_item.source_item_id = sales_order_item.id 关联取单价）。用于计算月度销售退货率分母。','SELECT DATE_FORMAT(ob.confirmed_at, \'%Y-%m\') AS month, COUNT(DISTINCT ob.id) AS bill_count, SUM(obi.current_qty) / 100.0 AS qty, SUM(obi.current_qty * soi.unit_price) / 10000.0 AS amount_yuan FROM outbound_bill ob INNER JOIN outbound_bill_item obi ON ob.id = obi.outbound_bill_id INNER JOIN sales_order_item soi ON obi.source_item_id = soi.id WHERE ob.outbound_type = \'SALES_OUT\' AND ob.status = \'CONFIRMED\' AND ob.deleted = 0 AND ob.confirmed_at >= \'2025-11-23 00:00:00\' AND ob.confirmed_at <= \'2026-11-22 23:59:59\' GROUP BY DATE_FORMAT(ob.confirmed_at, \'%Y-%m\')','[{\"name\":\"month\",\"label\":\"month\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":true},{\"name\":\"bill_count\",\"label\":\"bill_count\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"qty\",\"label\":\"qty\",\"jdbcType\":3,\"typeName\":\"DECIMAL\",\"nullable\":true},{\"name\":\"amount_yuan\",\"label\":\"amount_yuan\",\"jdbcType\":3,\"typeName\":\"DECIMAL\",\"nullable\":true}]',13,1,'ds_d6034a913a244931b53a9bf30177bcdc.jsonl','READY','2026-12-07 00:00:00.000000','2026-11-22 11:34:49.334848','{\"grain\": \"每个确认月份一行\", \"fields\": [{\"name\": \"month\", \"index\": 0, \"meaning\": \"确认月份，格式YYYY-MM\"}, {\"name\": \"bill_count\", \"index\": 1, \"meaning\": \"该月已确认的销售出库单数量\"}, {\"name\": \"qty\", \"index\": 2, \"meaning\": \"该月销售出库数量合计（业务单位，已从存储的100倍整数还原）\"}, {\"name\": \"amount_yuan\", \"index\": 3, \"meaning\": \"该月销售出库金额合计（元，由数量*单价/10000计算得出，其中单价来自关联的销售订单明细）\"}], \"content\": \"2025-11至2026-11期间，全部仓库的销售出库单月度汇总数据，包含出库单数、销售数量合计和销售金额合计（元），用于计算月度销售退货率的分母。\", \"limitations\": \"\"}',NULL);
INSERT INTO `ai_dataset` (`dataset_id`, `sql_run_id`, `attempt`, `ready_run_id`, `user_id`, `conversation_id`, `description`, `source_sql`, `columns_json`, `row_count`, `completed`, `storage_file`, `status`, `expires_at`, `created_at`, `data_description_json`, `truncation_reason`) VALUES ('ds_d7b8209ca0874c30bc2cac9586fc5a46','sqlrun_d11741465d2b4ee798c9a917ab4e1b8e',1,'sqlrun_d11741465d2b4ee798c9a917ab4e1b8e',1900000000000000001,2124420137200144385,'查询供应商 S0002（supplier_id=8400000000002000002，佛山宏远商贸）在近180天（2026-05-26至2026-11-22）内的全部采购订单明细行（不限产品），字段包括采购单号、产品编码、状态、审核时间、完全入库时间、预计到货日、数量、单价、金额；用于补充替补供应商在其他产品上的交付表现与订单样本量','SELECT po.supplier_code AS supplier_code, po.supplier_name AS supplier_name, poi.product_code AS product_code, poi.product_name AS product_name, po.purchase_no AS purchase_no, po.status AS status, po.approved_at AS approved_at, po.fully_received_at AS fully_received_at, po.expected_arrival_date AS expected_arrival_date, poi.quantity / 100.0 AS quantity, poi.inbound_qty / 100.0 AS inbound_qty, poi.unit_price / 100.0 AS unit_price, poi.total_amount / 100.0 AS total_amount FROM purchase_order po JOIN purchase_order_item poi ON po.id = poi.purchase_order_id WHERE po.supplier_id = 8400000000002000002 AND po.deleted = 0 AND po.create_time >= \'2026-05-26 00:00:00\' AND po.create_time < \'2026-11-23 00:00:00\'','[{\"name\":\"supplier_code\",\"label\":\"supplier_code\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"supplier_name\",\"label\":\"supplier_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"product_code\",\"label\":\"product_code\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"product_name\",\"label\":\"product_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"purchase_no\",\"label\":\"purchase_no\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"status\",\"label\":\"status\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"approved_at\",\"label\":\"approved_at\",\"jdbcType\":93,\"typeName\":\"DATETIME\",\"nullable\":true},{\"name\":\"fully_received_at\",\"label\":\"fully_received_at\",\"jdbcType\":93,\"typeName\":\"DATETIME\",\"nullable\":true},{\"name\":\"expected_arrival_date\",\"label\":\"expected_arrival_date\",\"jdbcType\":91,\"typeName\":\"DATE\",\"nullable\":true},{\"name\":\"quantity\",\"label\":\"quantity\",\"jdbcType\":3,\"typeName\":\"DECIMAL\",\"nullable\":true},{\"name\":\"inbound_qty\",\"label\":\"inbound_qty\",\"jdbcType\":3,\"typeName\":\"DECIMAL\",\"nullable\":true},{\"name\":\"unit_price\",\"label\":\"unit_price\",\"jdbcType\":3,\"typeName\":\"DECIMAL\",\"nullable\":true},{\"name\":\"total_amount\",\"label\":\"total_amount\",\"jdbcType\":3,\"typeName\":\"DECIMAL\",\"nullable\":true}]',43,1,'ds_d7b8209ca0874c30bc2cac9586fc5a46.jsonl','READY','2026-12-07 00:00:00.000000','2026-11-22 08:33:26.184854','{\"grain\": \"每个采购订单明细行一行\", \"fields\": [{\"name\": \"supplier_code\", \"index\": 0, \"meaning\": \"供应商编码\"}, {\"name\": \"supplier_name\", \"index\": 1, \"meaning\": \"供应商名称\"}, {\"name\": \"product_code\", \"index\": 2, \"meaning\": \"产品编码\"}, {\"name\": \"product_name\", \"index\": 3, \"meaning\": \"产品名称\"}, {\"name\": \"purchase_no\", \"index\": 4, \"meaning\": \"采购单号\"}, {\"name\": \"status\", \"index\": 5, \"meaning\": \"采购订单状态\"}, {\"name\": \"approved_at\", \"index\": 6, \"meaning\": \"审核时间\"}, {\"name\": \"fully_received_at\", \"index\": 7, \"meaning\": \"完全入库时间\"}, {\"name\": \"expected_arrival_date\", \"index\": 8, \"meaning\": \"预计到货日期\"}, {\"name\": \"quantity\", \"index\": 9, \"meaning\": \"采购数量（业务单位，已还原为实际数值）\"}, {\"name\": \"inbound_qty\", \"index\": 10, \"meaning\": \"已入库数量（业务单位，已还原为实际数值）\"}, {\"name\": \"unit_price\", \"index\": 11, \"meaning\": \"采购单价（元，已还原为实际数值）\"}, {\"name\": \"total_amount\", \"index\": 12, \"meaning\": \"明细总金额（元，已还原为实际数值）\"}], \"content\": \"供应商 S0002（佛山宏远商贸）在近180天内的采购订单明细列表，涵盖所有产品，用于分析其交付样本量和具体订单执行情况。\", \"limitations\": \"\"}',NULL);
INSERT INTO `ai_dataset` (`dataset_id`, `sql_run_id`, `attempt`, `ready_run_id`, `user_id`, `conversation_id`, `description`, `source_sql`, `columns_json`, `row_count`, `completed`, `storage_file`, `status`, `expires_at`, `created_at`, `data_description_json`, `truncation_reason`) VALUES ('ds_d7c189555e4e479789658c225adabdba','sqlrun_7efc074d25e944d196c8515cd5d291b2',1,'sqlrun_7efc074d25e944d196c8515cd5d291b2',1900000000000000001,2124221025439735809,'不限时间范围，按仓库+产品统计 bill_type=PURCHASE_IN 的库存流水，返回每个仓库+产品最后一次采购入库确认时间（max(stock_bill.confirmed_at)）及入库单据数，用于计算最近入库距今天数（基准2026-11-22）','SELECT sb.warehouse_id AS warehouse_id, w.warehouse_code AS warehouse_code, sbi.product_id AS product_id, sbi.product_code AS product_code, sbi.product_name AS product_name, MAX(sb.confirmed_at) AS last_purchase_in_confirmed_at, COUNT(DISTINCT sb.id) AS purchase_in_bill_count FROM stock_bill sb JOIN stock_bill_item sbi ON sb.id = sbi.bill_id JOIN warehouse w ON sb.warehouse_id = w.id WHERE sb.bill_type = \'PURCHASE_IN\' AND w.deleted = 0 GROUP BY sb.warehouse_id, w.warehouse_code, sbi.product_id, sbi.product_code, sbi.product_name','[{\"name\":\"warehouse_id\",\"label\":\"warehouse_id\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"warehouse_code\",\"label\":\"warehouse_code\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"product_id\",\"label\":\"product_id\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"product_code\",\"label\":\"product_code\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"product_name\",\"label\":\"product_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"last_purchase_in_confirmed_at\",\"label\":\"last_purchase_in_confirmed_at\",\"jdbcType\":93,\"typeName\":\"DATETIME\",\"nullable\":true},{\"name\":\"purchase_in_bill_count\",\"label\":\"purchase_in_bill_count\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false}]',1560,1,'ds_d7c189555e4e479789658c225adabdba.jsonl','READY','2026-12-06 00:00:00.000000','2026-11-21 19:21:32.836535','{\"grain\": \"每个仓库与产品的组合一行\", \"fields\": [{\"name\": \"warehouse_id\", \"index\": 0, \"meaning\": \"仓库ID\"}, {\"name\": \"warehouse_code\", \"index\": 1, \"meaning\": \"仓库编码\"}, {\"name\": \"product_id\", \"index\": 2, \"meaning\": \"产品ID\"}, {\"name\": \"product_code\", \"index\": 3, \"meaning\": \"产品编码\"}, {\"name\": \"product_name\", \"index\": 4, \"meaning\": \"产品名称\"}, {\"name\": \"last_purchase_in_confirmed_at\", \"index\": 5, \"meaning\": \"该仓库该产品最后一次采购入库流水的确认时间\"}, {\"name\": \"purchase_in_bill_count\", \"index\": 6, \"meaning\": \"该仓库该产品历史累计的采购入库流水单据数（去重后的stock_bill.id计数）\"}], \"content\": \"全量仓库下各产品的采购入库（PURCHASE_IN）库存流水汇总，包含最后一次入库确认时间和累计入库单据数量。\", \"limitations\": \"\"}',NULL);
INSERT INTO `ai_dataset` (`dataset_id`, `sql_run_id`, `attempt`, `ready_run_id`, `user_id`, `conversation_id`, `description`, `source_sql`, `columns_json`, `row_count`, `completed`, `storage_file`, `status`, `expires_at`, `created_at`, `data_description_json`, `truncation_reason`) VALUES ('ds_d8e997d0d4d3479e8f5485da1fb9c12a','sqlrun_a6c9212cf47d452aa63ef4523687eff8',1,'sqlrun_a6c9212cf47d452aa63ef4523687eff8',1900000000000000001,2123852411582849025,'查询库存余额表 warehouse_stock 的全部库存记录（含仓库ID、仓库编码、仓库名称、商品ID、商品编码、商品名称、单位、账面库存、锁定库存），用于计算各仓库可用库存及各仓库按商品分类的库存构成','SELECT ws.warehouse_id AS warehouse_id, ws.warehouse_code AS warehouse_code, ws.warehouse_name AS warehouse_name, ws.product_id AS product_id, ws.product_code AS product_code, ws.product_name AS product_name, ws.unit_name AS unit_name, ws.stock_qty / 100.0 AS stock_qty, ws.locked_qty / 100.0 AS locked_qty FROM warehouse_stock ws','[{\"name\":\"warehouse_id\",\"label\":\"warehouse_id\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"warehouse_code\",\"label\":\"warehouse_code\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"warehouse_name\",\"label\":\"warehouse_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"product_id\",\"label\":\"product_id\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"product_code\",\"label\":\"product_code\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"product_name\",\"label\":\"product_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"unit_name\",\"label\":\"unit_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"stock_qty\",\"label\":\"stock_qty\",\"jdbcType\":3,\"typeName\":\"DECIMAL\",\"nullable\":true},{\"name\":\"locked_qty\",\"label\":\"locked_qty\",\"jdbcType\":3,\"typeName\":\"DECIMAL\",\"nullable\":true}]',1560,1,'ds_d8e997d0d4d3479e8f5485da1fb9c12a.jsonl','READY','2026-12-05 00:00:00.000000','2026-11-20 18:55:20.785918','{\"grain\": \"每行代表一个特定仓库中一种特定商品的库存余额记录（唯一键：warehouse_id + product_id）。\", \"fields\": [{\"name\": \"warehouse_id\", \"index\": 0, \"meaning\": \"仓库ID\"}, {\"name\": \"warehouse_code\", \"index\": 1, \"meaning\": \"仓库编码\"}, {\"name\": \"warehouse_name\", \"index\": 2, \"meaning\": \"仓库名称\"}, {\"name\": \"product_id\", \"index\": 3, \"meaning\": \"商品ID\"}, {\"name\": \"product_code\", \"index\": 4, \"meaning\": \"商品编码\"}, {\"name\": \"product_name\", \"index\": 5, \"meaning\": \"商品名称\"}, {\"name\": \"unit_name\", \"index\": 6, \"meaning\": \"计量单位名称\"}, {\"name\": \"stock_qty\", \"index\": 7, \"meaning\": \"账面库存数量（已还原为业务数值，即原始值/100）\"}, {\"name\": \"locked_qty\", \"index\": 8, \"meaning\": \"锁定库存数量（已还原为业务数值，即原始值/100）\"}], \"content\": \"ERP 系统库存余额表全量快照，包含各仓库下各商品的当前账面库存与锁定库存，数量已换算为业务单位数值。\", \"limitations\": \"\"}',NULL);
INSERT INTO `ai_dataset` (`dataset_id`, `sql_run_id`, `attempt`, `ready_run_id`, `user_id`, `conversation_id`, `description`, `source_sql`, `columns_json`, `row_count`, `completed`, `storage_file`, `status`, `expires_at`, `created_at`, `data_description_json`, `truncation_reason`) VALUES ('ds_d94d72f0bbaf4829bfa23dbaa84b1f99','sqlrun_f7ee89ef20fc4b759ae23da6fb0e5ba3',2,'sqlrun_f7ee89ef20fc4b759ae23da6fb0e5ba3',1900000000000000001,2124210189346299906,'统计演示区域仓 01（DEMOW01）未删除销售订单按状态分组的订单数和预计发货日期区间，用于判断 2026-11-22 至 2026-11-30 期间是否存在尚未出库的确定性需求','SELECT so.status AS status, COUNT(so.id) AS order_count, MIN(so.expected_delivery_date) AS earliest_expected_delivery_date, MAX(so.expected_delivery_date) AS latest_expected_delivery_date FROM sales_order so JOIN warehouse w ON so.warehouse_id = w.id WHERE so.deleted = 0 AND w.deleted = 0 AND w.warehouse_code = \'DEMOW01\' GROUP BY so.status','[{\"name\":\"status\",\"label\":\"status\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"order_count\",\"label\":\"order_count\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"earliest_expected_delivery_date\",\"label\":\"earliest_expected_delivery_date\",\"jdbcType\":91,\"typeName\":\"DATE\",\"nullable\":true},{\"name\":\"latest_expected_delivery_date\",\"label\":\"latest_expected_delivery_date\",\"jdbcType\":91,\"typeName\":\"DATE\",\"nullable\":true}]',1,1,'ds_d94d72f0bbaf4829bfa23dbaa84b1f99.jsonl','READY','2026-12-06 00:00:00.000000','2026-11-21 18:37:35.543652','{\"grain\": \"每个销售订单状态一行\", \"fields\": [{\"name\": \"status\", \"index\": 0, \"meaning\": \"销售订单状态（英文枚举值，如 OUTBOUND_DONE 表示已出库）\"}, {\"name\": \"order_count\", \"index\": 1, \"meaning\": \"该状态下的订单数量\"}, {\"name\": \"earliest_expected_delivery_date\", \"index\": 2, \"meaning\": \"该状态下订单的最早预计发货日期\"}, {\"name\": \"latest_expected_delivery_date\", \"index\": 3, \"meaning\": \"该状态下订单的最晚预计发货日期\"}], \"content\": \"演示区域仓01（DEMOW01）中所有未逻辑删除的销售订单，按订单状态分组统计的数量及预计发货日期的最小值和最大值。\", \"limitations\": \"数据包含该仓库所有历史未删除订单，未按特定时间窗口（如2026-11-22至2026-11-30）过滤订单创建或审核时间，仅通过状态判断是否有未出库订单。当前结果仅显示已出库状态，暗示无其他状态订单存在。\"}',NULL);
INSERT INTO `ai_dataset` (`dataset_id`, `sql_run_id`, `attempt`, `ready_run_id`, `user_id`, `conversation_id`, `description`, `source_sql`, `columns_json`, `row_count`, `completed`, `storage_file`, `status`, `expires_at`, `created_at`, `data_description_json`, `truncation_reason`) VALUES ('ds_d9abcb6506754fbda458ce8c294149e4','sqlrun_f6b4daf6ef8947e788e61b9df403f80f',1,'sqlrun_f6b4daf6ef8947e788e61b9df403f80f',1900000000000000001,2124210189346299906,'查询仓库编码 DEMOW01 的全部已确认销售出库流水明细（stock_bill.bill_type=SALES_OUT 对应的 stock_bill_item 行），返回流水号、confirm 时间、产品ID、产品编码、产品名称、单位、变动数量 change_qty（100倍整数，出库为负值）','SELECT sb.bill_no AS bill_no, sb.confirmed_at AS confirmed_at, sbi.product_id AS product_id, sbi.product_code AS product_code, sbi.product_name AS product_name, sbi.unit_name AS unit_name, sbi.change_qty AS change_qty FROM stock_bill sb JOIN stock_bill_item sbi ON sb.id = sbi.bill_id JOIN warehouse w ON sb.warehouse_id = w.id WHERE sb.bill_type = \'SALES_OUT\' AND w.warehouse_code = \'DEMOW01\' AND w.deleted = 0','[{\"name\":\"bill_no\",\"label\":\"bill_no\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"confirmed_at\",\"label\":\"confirmed_at\",\"jdbcType\":93,\"typeName\":\"DATETIME\",\"nullable\":false},{\"name\":\"product_id\",\"label\":\"product_id\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"product_code\",\"label\":\"product_code\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"product_name\",\"label\":\"product_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"unit_name\",\"label\":\"unit_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"change_qty\",\"label\":\"change_qty\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false}]',312,1,'ds_d9abcb6506754fbda458ce8c294149e4.jsonl','READY','2026-12-06 00:00:00.000000','2026-11-21 18:39:07.021761','{\"grain\": \"每条库存流水凭证明细一行\", \"fields\": [{\"name\": \"bill_no\", \"index\": 0, \"meaning\": \"库存流水号\"}, {\"name\": \"confirmed_at\", \"index\": 1, \"meaning\": \"流水确认时间\"}, {\"name\": \"product_id\", \"index\": 2, \"meaning\": \"产品ID\"}, {\"name\": \"product_code\", \"index\": 3, \"meaning\": \"产品编码快照\"}, {\"name\": \"product_name\", \"index\": 4, \"meaning\": \"产品名称快照\"}, {\"name\": \"unit_name\", \"index\": 5, \"meaning\": \"单位名称快照\"}, {\"name\": \"change_qty\", \"index\": 6, \"meaning\": \"库存变动数量（×100整数存储，出库为负值）\"}], \"content\": \"仓库 DEMOW01 的已确认销售出库库存流水明细\", \"limitations\": \"\"}',NULL);
INSERT INTO `ai_dataset` (`dataset_id`, `sql_run_id`, `attempt`, `ready_run_id`, `user_id`, `conversation_id`, `description`, `source_sql`, `columns_json`, `row_count`, `completed`, `storage_file`, `status`, `expires_at`, `created_at`, `data_description_json`, `truncation_reason`) VALUES ('ds_db95013c65d141d3967257786cbe92b7','sqlrun_2faebe8f22944b708a90a82e7f1f8f9b',1,'sqlrun_2faebe8f22944b708a90a82e7f1f8f9b',1900000000000000001,2124420137200144385,'查询供应商 S0001（上海万隆食品贸易有限责任公司）和 S0002（佛山宏远商贸有限责任公司）的供应商主档信息，包括综合/交付/质量/价格/服务评分、评分状态、平均到货周期、样本金额、启用状态、付款条件','SELECT id, supplier_code, supplier_name, overall_score, delivery_score, quality_score, price_score, service_score, score_status, avg_delivery_days, score_basis_amount, status, payment_terms FROM supplier WHERE deleted = 0 AND supplier_code IN (\'S0001\', \'S0002\')','[{\"name\":\"id\",\"label\":\"id\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"supplier_code\",\"label\":\"supplier_code\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"supplier_name\",\"label\":\"supplier_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"overall_score\",\"label\":\"overall_score\",\"jdbcType\":4,\"typeName\":\"INT\",\"nullable\":true},{\"name\":\"delivery_score\",\"label\":\"delivery_score\",\"jdbcType\":4,\"typeName\":\"INT\",\"nullable\":true},{\"name\":\"quality_score\",\"label\":\"quality_score\",\"jdbcType\":4,\"typeName\":\"INT\",\"nullable\":true},{\"name\":\"price_score\",\"label\":\"price_score\",\"jdbcType\":4,\"typeName\":\"INT\",\"nullable\":true},{\"name\":\"service_score\",\"label\":\"service_score\",\"jdbcType\":4,\"typeName\":\"INT\",\"nullable\":true},{\"name\":\"score_status\",\"label\":\"score_status\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"avg_delivery_days\",\"label\":\"avg_delivery_days\",\"jdbcType\":3,\"typeName\":\"DECIMAL\",\"nullable\":true},{\"name\":\"score_basis_amount\",\"label\":\"score_basis_amount\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":true},{\"name\":\"status\",\"label\":\"status\",\"jdbcType\":-6,\"typeName\":\"TINYINT\",\"nullable\":false},{\"name\":\"payment_terms\",\"label\":\"payment_terms\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false}]',2,1,'ds_db95013c65d141d3967257786cbe92b7.jsonl','READY','2026-12-07 00:00:00.000000','2026-11-22 08:30:29.894329','{\"grain\": \"每个供应商一行\", \"fields\": [{\"name\": \"id\", \"index\": 0, \"meaning\": \"供应商ID\"}, {\"name\": \"supplier_code\", \"index\": 1, \"meaning\": \"供应商编码\"}, {\"name\": \"supplier_name\", \"index\": 2, \"meaning\": \"供应商名称\"}, {\"name\": \"overall_score\", \"index\": 3, \"meaning\": \"综合评分（存储值为实际分数×100，例如9917代表99.17分）\"}, {\"name\": \"delivery_score\", \"index\": 4, \"meaning\": \"交付评分（存储值为实际分数×100）\"}, {\"name\": \"quality_score\", \"index\": 5, \"meaning\": \"质量评分（存储值为实际分数×100）\"}, {\"name\": \"price_score\", \"index\": 6, \"meaning\": \"价格评分（存储值为实际分数×100）\"}, {\"name\": \"service_score\", \"index\": 7, \"meaning\": \"服务评分（存储值为实际分数×100）\"}, {\"name\": \"score_status\", \"index\": 8, \"meaning\": \"评分状态（READY表示可参与评分，NOT_READY表示样本不足）\"}, {\"name\": \"avg_delivery_days\", \"index\": 9, \"meaning\": \"平均到货周期（天）\"}, {\"name\": \"score_basis_amount\", \"index\": 10, \"meaning\": \"评分依据金额（单位：分，即近180天已确认样本金额）\"}, {\"name\": \"status\", \"index\": 11, \"meaning\": \"启用状态（1启用，0禁用）\"}, {\"name\": \"payment_terms\", \"index\": 12, \"meaning\": \"付款条件\"}], \"content\": \"供应商 S0001（上海万隆食品贸易有限责任公司）和 S0002（佛山宏远商贸有限责任公司）的主档信息及供应商级评分详情。\", \"limitations\": \"评分字段为放大100倍存储的整数，展示时需除以100；score_basis_amount单位为分，展示时需除以100转换为元。\"}',NULL);
INSERT INTO `ai_dataset` (`dataset_id`, `sql_run_id`, `attempt`, `ready_run_id`, `user_id`, `conversation_id`, `description`, `source_sql`, `columns_json`, `row_count`, `completed`, `storage_file`, `status`, `expires_at`, `created_at`, `data_description_json`, `truncation_reason`) VALUES ('ds_e03344093da04b4a8b78545a2afe89c3','sqlrun_77f3be5d2e5940b4b3b0b5405054288c',1,'sqlrun_77f3be5d2e5940b4b3b0b5405054288c',1900000000000000001,2124475847040573442,'查询所有仓库主档信息（仓库ID、编码、名称、状态），用于确认名称中包含“成都”“双流”的仓库，明确用户所说的“成都双流西仓”对应哪个仓库ID','SELECT id AS warehouse_id, warehouse_code, warehouse_name, status FROM warehouse WHERE deleted = 0','[{\"name\":\"id\",\"label\":\"warehouse_id\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"warehouse_code\",\"label\":\"warehouse_code\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"warehouse_name\",\"label\":\"warehouse_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"status\",\"label\":\"status\",\"jdbcType\":-6,\"typeName\":\"TINYINT\",\"nullable\":false}]',5,1,'ds_e03344093da04b4a8b78545a2afe89c3.jsonl','READY','2026-12-07 00:00:00.000000','2026-11-22 12:11:34.315696','{\"grain\": \"每个仓库一行\", \"fields\": [{\"name\": \"warehouse_id\", \"index\": 0, \"meaning\": \"仓库ID\"}, {\"name\": \"warehouse_code\", \"index\": 1, \"meaning\": \"仓库编码\"}, {\"name\": \"warehouse_name\", \"index\": 2, \"meaning\": \"仓库名称\"}, {\"name\": \"status\", \"index\": 3, \"meaning\": \"仓库状态：1表示启用，0表示禁用\"}], \"content\": \"所有未逻辑删除的仓库主档列表，用于识别特定名称（如含“成都”、“双流”）的仓库及其唯一标识。\", \"limitations\": \"\"}',NULL);
INSERT INTO `ai_dataset` (`dataset_id`, `sql_run_id`, `attempt`, `ready_run_id`, `user_id`, `conversation_id`, `description`, `source_sql`, `columns_json`, `row_count`, `completed`, `storage_file`, `status`, `expires_at`, `created_at`, `data_description_json`, `truncation_reason`) VALUES ('ds_e0ce38f9f450403394e6860c89c7e44e','sqlrun_517fd52995c2450fb513569997b96d40',1,'sqlrun_517fd52995c2450fb513569997b96d40',1900000000000000001,2124475847040573442,'查询成都双流西仓（warehouse_id=8400000000004000004）全部产品的库存余额记录，返回每个产品一行，包含产品ID、编码、名称、单位、库存数量stock_qty、锁定数量locked_qty，数量保持100倍整数原值。不做产品筛选，取该仓全部记录。','SELECT warehouse_id, product_id, product_code, product_name, unit_name, stock_qty, locked_qty FROM warehouse_stock WHERE warehouse_id = 8400000000004000004','[{\"name\":\"warehouse_id\",\"label\":\"warehouse_id\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"product_id\",\"label\":\"product_id\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"product_code\",\"label\":\"product_code\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"product_name\",\"label\":\"product_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"unit_name\",\"label\":\"unit_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"stock_qty\",\"label\":\"stock_qty\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"locked_qty\",\"label\":\"locked_qty\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false}]',323,1,'ds_e0ce38f9f450403394e6860c89c7e44e.jsonl','READY','2026-12-07 00:00:00.000000','2026-11-22 12:13:27.735245','{\"grain\": \"每仓每产品一行\", \"fields\": [{\"name\": \"warehouse_id\", \"index\": 0, \"meaning\": \"仓库ID\"}, {\"name\": \"product_id\", \"index\": 1, \"meaning\": \"产品ID\"}, {\"name\": \"product_code\", \"index\": 2, \"meaning\": \"产品编码\"}, {\"name\": \"product_name\", \"index\": 3, \"meaning\": \"产品名称\"}, {\"name\": \"unit_name\", \"index\": 4, \"meaning\": \"单位名称\"}, {\"name\": \"stock_qty\", \"index\": 5, \"meaning\": \"当前库存数量（按100倍整数存储，例如129000表示1290.00）\"}, {\"name\": \"locked_qty\", \"index\": 6, \"meaning\": \"锁定库存数量（按100倍整数存储，例如0表示0.00）\"}], \"content\": \"指定仓库（成都双流西仓）下所有存在库存记录的产品明细，包含产品基础信息及库存数量、锁定数量。\", \"limitations\": \"\"}',NULL);
INSERT INTO `ai_dataset` (`dataset_id`, `sql_run_id`, `attempt`, `ready_run_id`, `user_id`, `conversation_id`, `description`, `source_sql`, `columns_json`, `row_count`, `completed`, `storage_file`, `status`, `expires_at`, `created_at`, `data_description_json`, `truncation_reason`) VALUES ('ds_ea284255848d4ea0b2d76fda1523af32','sqlrun_2ba34c742005423287d01546ecfaea98',1,'sqlrun_2ba34c742005423287d01546ecfaea98',1900000000000000001,2124418644136972290,'查询所有启用状态（status=1、deleted=0）的仓库清单，用于确认库存与安全库存比对的范围','SELECT id AS warehouse_id, warehouse_code, warehouse_name, status FROM warehouse WHERE deleted = 0 AND status = 1','[{\"name\":\"id\",\"label\":\"warehouse_id\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"warehouse_code\",\"label\":\"warehouse_code\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"warehouse_name\",\"label\":\"warehouse_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"status\",\"label\":\"status\",\"jdbcType\":-6,\"typeName\":\"TINYINT\",\"nullable\":false}]',5,1,'ds_ea284255848d4ea0b2d76fda1523af32.jsonl','READY','2026-12-07 00:00:00.000000','2026-11-22 08:24:24.293699','{\"grain\": \"每个仓库一行\", \"fields\": [{\"name\": \"warehouse_id\", \"index\": 0, \"meaning\": \"仓库ID\"}, {\"name\": \"warehouse_code\", \"index\": 1, \"meaning\": \"仓库编码\"}, {\"name\": \"warehouse_name\", \"index\": 2, \"meaning\": \"仓库名称\"}, {\"name\": \"status\", \"index\": 3, \"meaning\": \"状态（1表示启用）\"}], \"content\": \"所有启用状态（status=1）且未删除（deleted=0）的仓库清单\", \"limitations\": \"\"}',NULL);
INSERT INTO `ai_dataset` (`dataset_id`, `sql_run_id`, `attempt`, `ready_run_id`, `user_id`, `conversation_id`, `description`, `source_sql`, `columns_json`, `row_count`, `completed`, `storage_file`, `status`, `expires_at`, `created_at`, `data_description_json`, `truncation_reason`) VALUES ('ds_ea39c63c4c074d9e929d6fd2c1689f21','sqlrun_20dc938ca27945f4af16e457d510e695',1,'sqlrun_20dc938ca27945f4af16e457d510e695',1900000000000000001,2124424075508994050,'查询产品 P000005（果沁 碳酸饮料礼盒装）在2026-05-22至2026-11-22期间，各仓库的销售出库明细汇总：销售确认出库（outbound_bill.status=\'CONFIRMED\' 且 outbound_type=\'SALES_OUT\'，排除已删除）的数量合计、出库单数、首次和最近一次确认出库时间；同时给出不限时间的各仓最近一次销售出库时间，用于判断窗口内无出库的仓何时最后一次出库','SELECT ob.warehouse_id AS warehouse_id, MAX(ob.warehouse_name) AS warehouse_name, SUM(CASE WHEN ob.confirmed_at >= \'2026-05-22 00:00:00\' AND ob.confirmed_at < \'2026-11-23 00:00:00\' THEN obi.current_qty ELSE 0 END) / 100.0 AS outbound_qty, COUNT(DISTINCT CASE WHEN ob.confirmed_at >= \'2026-05-22 00:00:00\' AND ob.confirmed_at < \'2026-11-23 00:00:00\' THEN ob.id ELSE NULL END) AS bill_count, MIN(CASE WHEN ob.confirmed_at >= \'2026-05-22 00:00:00\' AND ob.confirmed_at < \'2026-11-23 00:00:00\' THEN ob.confirmed_at ELSE NULL END) AS first_outbound_at, MAX(CASE WHEN ob.confirmed_at >= \'2026-05-22 00:00:00\' AND ob.confirmed_at < \'2026-11-23 00:00:00\' THEN ob.confirmed_at ELSE NULL END) AS last_outbound_at_window, MAX(ob.confirmed_at) AS last_outbound_at_all FROM outbound_bill ob JOIN outbound_bill_item obi ON ob.id = obi.outbound_bill_id WHERE ob.deleted = 0 AND ob.status = \'CONFIRMED\' AND ob.outbound_type = \'SALES_OUT\' AND obi.product_code = \'P000005\' GROUP BY ob.warehouse_id','[{\"name\":\"warehouse_id\",\"label\":\"warehouse_id\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"warehouse_name\",\"label\":\"warehouse_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":true},{\"name\":\"outbound_qty\",\"label\":\"outbound_qty\",\"jdbcType\":3,\"typeName\":\"DECIMAL\",\"nullable\":true},{\"name\":\"bill_count\",\"label\":\"bill_count\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"first_outbound_at\",\"label\":\"first_outbound_at\",\"jdbcType\":93,\"typeName\":\"DATETIME\",\"nullable\":true},{\"name\":\"last_outbound_at_window\",\"label\":\"last_outbound_at_window\",\"jdbcType\":93,\"typeName\":\"DATETIME\",\"nullable\":true},{\"name\":\"last_outbound_at_all\",\"label\":\"last_outbound_at_all\",\"jdbcType\":93,\"typeName\":\"DATETIME\",\"nullable\":true}]',1,1,'ds_ea39c63c4c074d9e929d6fd2c1689f21.jsonl','READY','2026-12-07 00:00:00.000000','2026-11-22 08:47:00.243665','{\"grain\": \"每个仓库一行\", \"fields\": [{\"name\": \"warehouse_id\", \"index\": 0, \"meaning\": \"仓库ID\"}, {\"name\": \"warehouse_name\", \"index\": 1, \"meaning\": \"仓库名称\"}, {\"name\": \"outbound_qty\", \"index\": 2, \"meaning\": \"指定时间窗口内(2026-05-22至2026-11-22)的销售出库数量合计(业务单位)\"}, {\"name\": \"bill_count\", \"index\": 3, \"meaning\": \"指定时间窗口内的销售出库单数\"}, {\"name\": \"first_outbound_at\", \"index\": 4, \"meaning\": \"指定时间窗口内的首次确认出库时间\"}, {\"name\": \"last_outbound_at_window\", \"index\": 5, \"meaning\": \"指定时间窗口内的最近一次确认出库时间\"}, {\"name\": \"last_outbound_at_all\", \"index\": 6, \"meaning\": \"不限时间的该仓库针对该产品最近一次销售出库确认时间\"}], \"content\": \"产品 P000005 (果沁 碳酸饮料礼盒装) 在各仓库的销售出库明细汇总。包含指定时间窗口内的出库数量合计、出库单数、首次和最近一次确认出库时间，以及不限时间的各仓最近一次销售出库时间。\", \"limitations\": \"\"}',NULL);
INSERT INTO `ai_dataset` (`dataset_id`, `sql_run_id`, `attempt`, `ready_run_id`, `user_id`, `conversation_id`, `description`, `source_sql`, `columns_json`, `row_count`, `completed`, `storage_file`, `status`, `expires_at`, `created_at`, `data_description_json`, `truncation_reason`) VALUES ('ds_eb70b3ecfa2e4759bca230ffa05d3c7c','sqlrun_610afa07167b43d5bf1ad95a9ca9b61d',1,'sqlrun_610afa07167b43d5bf1ad95a9ca9b61d',1900000000000000001,2123852411582849025,'在库存余额表 warehouse_stock 中按仓库编码、仓库名称、单位名称（unit_name）分组汇总 stock_qty 与 locked_qty（按100倍整数存储，需除以100还原），并计算可用库存=账面-锁定。按单位分组以避免跨单位相加。仅使用该单表。','SELECT warehouse_code AS `仓库编码`, warehouse_name AS `仓库名称`, unit_name AS `单位`, SUM(stock_qty) / 100.0 AS `账面库存合计`, SUM(locked_qty) / 100.0 AS `锁定库存合计`, (SUM(stock_qty) - SUM(locked_qty)) / 100.0 AS `可用库存合计` FROM warehouse_stock GROUP BY warehouse_code, warehouse_name, unit_name','[{\"name\":\"warehouse_code\",\"label\":\"仓库编码\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"warehouse_name\",\"label\":\"仓库名称\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"unit_name\",\"label\":\"单位\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"账面库存合计\",\"label\":\"账面库存合计\",\"jdbcType\":3,\"typeName\":\"DECIMAL\",\"nullable\":true},{\"name\":\"锁定库存合计\",\"label\":\"锁定库存合计\",\"jdbcType\":3,\"typeName\":\"DECIMAL\",\"nullable\":true},{\"name\":\"可用库存合计\",\"label\":\"可用库存合计\",\"jdbcType\":3,\"typeName\":\"DECIMAL\",\"nullable\":true}]',5,1,'ds_eb70b3ecfa2e4759bca230ffa05d3c7c.jsonl','READY','2026-12-05 00:00:00.000000','2026-11-20 18:59:28.120844','{\"grain\": \"每个仓库×单位一行\", \"fields\": [{\"name\": \"仓库编码\", \"index\": 0, \"meaning\": \"仓库编码\"}, {\"name\": \"仓库名称\", \"index\": 1, \"meaning\": \"仓库名称\"}, {\"name\": \"单位\", \"index\": 2, \"meaning\": \"单位名称（用于区分不同计量单位，避免跨单位求和）\"}, {\"name\": \"账面库存合计\", \"index\": 3, \"meaning\": \"账面库存合计（原始stock_qty之和除以100后的业务数量）\"}, {\"name\": \"锁定库存合计\", \"index\": 4, \"meaning\": \"锁定库存合计（原始locked_qty之和除以100后的业务数量）\"}, {\"name\": \"可用库存合计\", \"index\": 5, \"meaning\": \"可用库存合计（账面库存合计减去锁定库存合计）\"}], \"content\": \"库存余额表中各仓库按单位分组的账面库存、锁定库存及可用库存汇总数据。\", \"limitations\": \"\"}',NULL);
INSERT INTO `ai_dataset` (`dataset_id`, `sql_run_id`, `attempt`, `ready_run_id`, `user_id`, `conversation_id`, `description`, `source_sql`, `columns_json`, `row_count`, `completed`, `storage_file`, `status`, `expires_at`, `created_at`, `data_description_json`, `truncation_reason`) VALUES ('ds_eba7e817ea47485c939c3e456972e2eb','sqlrun_2a9f5c98607a4c6dade71ae24d8f05eb',1,'sqlrun_2a9f5c98607a4c6dade71ae24d8f05eb',1900000000000000001,2124418644136972290,'查询 warehouse_id = 8400000000004000003（北京顺义北仓）的全部 warehouse_stock 库存余额记录，关联 product 取产品编码、产品名称、单位、quantity_precision、safety_stock_qty，仅保留 product.status=1 且 product.deleted=0 的产品。每行一个仓库×产品，含 stock_qty、locked_qty（100倍整数）','SELECT ws.warehouse_id AS warehouse_id, ws.warehouse_name AS warehouse_name, ws.product_id AS product_id, p.product_code AS product_code, p.product_name AS product_name, p.unit_name AS unit_name, p.quantity_precision AS quantity_precision, ws.stock_qty AS stock_qty, ws.locked_qty AS locked_qty, p.safety_stock_qty AS safety_stock_qty FROM warehouse_stock ws INNER JOIN product p ON ws.product_id = p.id WHERE ws.warehouse_id = 8400000000004000003 AND p.status = 1 AND p.deleted = 0','[{\"name\":\"warehouse_id\",\"label\":\"warehouse_id\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"warehouse_name\",\"label\":\"warehouse_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"product_id\",\"label\":\"product_id\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"product_code\",\"label\":\"product_code\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"product_name\",\"label\":\"product_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"unit_name\",\"label\":\"unit_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"quantity_precision\",\"label\":\"quantity_precision\",\"jdbcType\":-6,\"typeName\":\"TINYINT\",\"nullable\":false},{\"name\":\"stock_qty\",\"label\":\"stock_qty\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"locked_qty\",\"label\":\"locked_qty\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"safety_stock_qty\",\"label\":\"safety_stock_qty\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false}]',363,1,'ds_eba7e817ea47485c939c3e456972e2eb.jsonl','READY','2026-12-07 00:00:00.000000','2026-11-22 08:25:51.676254','{\"grain\": \"每行代表一个特定仓库与一个特定产品的组合（Warehouse-Product Pair）。\", \"fields\": [{\"name\": \"warehouse_id\", \"index\": 0, \"meaning\": \"仓库ID\"}, {\"name\": \"warehouse_name\", \"index\": 1, \"meaning\": \"仓库名称快照\"}, {\"name\": \"product_id\", \"index\": 2, \"meaning\": \"产品ID\"}, {\"name\": \"product_code\", \"index\": 3, \"meaning\": \"产品编码\"}, {\"name\": \"product_name\", \"index\": 4, \"meaning\": \"产品名称\"}, {\"name\": \"unit_name\", \"index\": 5, \"meaning\": \"计量单位名称\"}, {\"name\": \"quantity_precision\", \"index\": 6, \"meaning\": \"数量小数位精度（0-2），用于还原业务数量时参考\"}, {\"name\": \"stock_qty\", \"index\": 7, \"meaning\": \"当前库存数量（100倍整数存储，即实际值*100）\"}, {\"name\": \"locked_qty\", \"index\": 8, \"meaning\": \"锁定库存数量（100倍整数存储，即实际值*100）\"}, {\"name\": \"safety_stock_qty\", \"index\": 9, \"meaning\": \"安全库存数量（100倍整数存储，即实际值*100，产品级阈值）\"}], \"content\": \"指定仓库（北京顺义北仓）下所有有效产品的当前库存余额明细，包含账面库存、锁定库存及安全库存阈值。\", \"limitations\": \"\"}',NULL);
INSERT INTO `ai_dataset` (`dataset_id`, `sql_run_id`, `attempt`, `ready_run_id`, `user_id`, `conversation_id`, `description`, `source_sql`, `columns_json`, `row_count`, `completed`, `storage_file`, `status`, `expires_at`, `created_at`, `data_description_json`, `truncation_reason`) VALUES ('ds_f53106e7e5fe4d95bead57288fae11c6','sqlrun_057708059f724310a87e09f07e23c3df',2,'sqlrun_057708059f724310a87e09f07e23c3df',1900000000000000001,2123852411582849025,'查询仓库主档 warehouse 的全部仓库记录，含仓库ID、编码、名称、启用状态与逻辑删除标记，用于确定启用仓库范围（status=1 且 deleted=0）','SELECT id, warehouse_code, warehouse_name, status, deleted FROM warehouse WHERE deleted = 0','[{\"name\":\"id\",\"label\":\"id\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"warehouse_code\",\"label\":\"warehouse_code\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"warehouse_name\",\"label\":\"warehouse_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"status\",\"label\":\"status\",\"jdbcType\":-6,\"typeName\":\"TINYINT\",\"nullable\":false},{\"name\":\"deleted\",\"label\":\"deleted\",\"jdbcType\":-6,\"typeName\":\"TINYINT\",\"nullable\":false}]',5,1,'ds_f53106e7e5fe4d95bead57288fae11c6.jsonl','READY','2026-12-05 00:00:00.000000','2026-11-20 18:55:34.464663','{\"grain\": \"每个仓库一行\", \"fields\": [{\"name\": \"id\", \"index\": 0, \"meaning\": \"仓库唯一标识ID\"}, {\"name\": \"warehouse_code\", \"index\": 1, \"meaning\": \"仓库业务编码\"}, {\"name\": \"warehouse_name\", \"index\": 2, \"meaning\": \"仓库名称\"}, {\"name\": \"status\", \"index\": 3, \"meaning\": \"启用状态：1表示启用，0表示禁用\"}, {\"name\": \"deleted\", \"index\": 4, \"meaning\": \"逻辑删除标记：0表示正常，1表示已删除\"}], \"content\": \"ERP系统中所有未逻辑删除的仓库主档记录，用于识别当前有效的仓库列表。样本显示返回的记录均为启用状态（status=1）。\", \"limitations\": \"\"}',NULL);
INSERT INTO `ai_dataset` (`dataset_id`, `sql_run_id`, `attempt`, `ready_run_id`, `user_id`, `conversation_id`, `description`, `source_sql`, `columns_json`, `row_count`, `completed`, `storage_file`, `status`, `expires_at`, `created_at`, `data_description_json`, `truncation_reason`) VALUES ('ds_f79d3bd7f0f14e95a0e85c6bc28ad6c8','sqlrun_2f316fdaf8c8450abc4976cb6157f7ee',1,'sqlrun_2f316fdaf8c8450abc4976cb6157f7ee',1900000000000000001,2124761984778977281,'查询仓库主档中所有仓库的ID、仓库编码、仓库名称和状态，用于确认“上海浦东中心仓”在系统中的准确ID与编码','SELECT id AS warehouse_id, warehouse_code, warehouse_name, status FROM warehouse WHERE deleted = 0','[{\"name\":\"id\",\"label\":\"warehouse_id\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"warehouse_code\",\"label\":\"warehouse_code\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"warehouse_name\",\"label\":\"warehouse_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"status\",\"label\":\"status\",\"jdbcType\":-6,\"typeName\":\"TINYINT\",\"nullable\":false}]',5,1,'ds_f79d3bd7f0f14e95a0e85c6bc28ad6c8.jsonl','READY','2026-12-08 00:00:00.000000','2026-11-23 07:08:58.644532','{\"grain\": \"每个仓库一行\", \"fields\": [{\"name\": \"warehouse_id\", \"index\": 0, \"meaning\": \"仓库ID（主键）\"}, {\"name\": \"warehouse_code\", \"index\": 1, \"meaning\": \"仓库编码（唯一标识）\"}, {\"name\": \"warehouse_name\", \"index\": 2, \"meaning\": \"仓库名称（唯一标识）\"}, {\"name\": \"status\", \"index\": 3, \"meaning\": \"仓库状态：1启用，0禁用\"}], \"content\": \"仓库主档中所有未删除的仓库记录，包含ID、编码、名称和状态\", \"limitations\": \"\"}',NULL);
INSERT INTO `ai_dataset` (`dataset_id`, `sql_run_id`, `attempt`, `ready_run_id`, `user_id`, `conversation_id`, `description`, `source_sql`, `columns_json`, `row_count`, `completed`, `storage_file`, `status`, `expires_at`, `created_at`, `data_description_json`, `truncation_reason`) VALUES ('ds_fb421c6a2f204b1e900c2c57e74ad49d','sqlrun_a4c780636df24c64acdbbef81feef649',1,'sqlrun_a4c780636df24c64acdbbef81feef649',1900000000000000001,2124424075508994050,'查询产品编码 P000005（果沁 碳酸饮料礼盒装）的产品主档信息，包括产品编码、名称、单位、数量小数位精度、安全库存、参考采购价、参考销售价、状态','SELECT product_code AS `product_code`, product_name AS `product_name`, unit_name AS `unit_name`, quantity_precision AS `quantity_precision`, safety_stock_qty / 100.0 AS `safety_stock_qty`, reference_purchase_price / 100.0 AS `reference_purchase_price`, reference_sale_price / 100.0 AS `reference_sale_price`, status AS `status` FROM product WHERE deleted = 0 AND product_code = \'P000005\'','[{\"name\":\"product_code\",\"label\":\"product_code\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"product_name\",\"label\":\"product_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"unit_name\",\"label\":\"unit_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"quantity_precision\",\"label\":\"quantity_precision\",\"jdbcType\":-6,\"typeName\":\"TINYINT\",\"nullable\":false},{\"name\":\"safety_stock_qty\",\"label\":\"safety_stock_qty\",\"jdbcType\":3,\"typeName\":\"DECIMAL\",\"nullable\":true},{\"name\":\"reference_purchase_price\",\"label\":\"reference_purchase_price\",\"jdbcType\":3,\"typeName\":\"DECIMAL\",\"nullable\":true},{\"name\":\"reference_sale_price\",\"label\":\"reference_sale_price\",\"jdbcType\":3,\"typeName\":\"DECIMAL\",\"nullable\":true},{\"name\":\"status\",\"label\":\"status\",\"jdbcType\":-6,\"typeName\":\"TINYINT\",\"nullable\":false}]',1,1,'ds_fb421c6a2f204b1e900c2c57e74ad49d.jsonl','READY','2026-12-07 00:00:00.000000','2026-11-22 08:46:11.008214','{\"grain\": \"每个产品一行\", \"fields\": [{\"name\": \"product_code\", \"index\": 0, \"meaning\": \"产品编码\"}, {\"name\": \"product_name\", \"index\": 1, \"meaning\": \"产品名称\"}, {\"name\": \"unit_name\", \"index\": 2, \"meaning\": \"单位名称\"}, {\"name\": \"quantity_precision\", \"index\": 3, \"meaning\": \"数量小数位精度（0-2）\"}, {\"name\": \"safety_stock_qty\", \"index\": 4, \"meaning\": \"安全库存数量（业务单位，已从存储值除以100还原）\"}, {\"name\": \"reference_purchase_price\", \"index\": 5, \"meaning\": \"参考采购价（元，已从分转换为元）\"}, {\"name\": \"reference_sale_price\", \"index\": 6, \"meaning\": \"参考销售价（元，已从分转换为元）\"}, {\"name\": \"status\", \"index\": 7, \"meaning\": \"产品状态（1启用，0禁用）\"}], \"content\": \"产品编码 P000005（果沁 碳酸饮料礼盒装）的产品主档详细信息，包括基础属性、库存阈值和参考价格。\", \"limitations\": \"\"}',NULL);
INSERT INTO `ai_dataset` (`dataset_id`, `sql_run_id`, `attempt`, `ready_run_id`, `user_id`, `conversation_id`, `description`, `source_sql`, `columns_json`, `row_count`, `completed`, `storage_file`, `status`, `expires_at`, `created_at`, `data_description_json`, `truncation_reason`) VALUES ('ds_fd1d7af2e5f14fc687f57a9602e84258','sqlrun_b1d2c416c2004004855b926c3bb1cd5c',1,'sqlrun_b1d2c416c2004004855b926c3bb1cd5c',1900000000000000001,2124465547335741442,'查询统一退货单明细表 return_order_item 的全部记录，范围与对应主表一致：退货单创建时间在 2025-11-23 至 2026-11-22（含端点）的非删除退货单明细（全部退货类型、全部状态，含 CANCELLED/DRAFT）。用于按产品汇总退货金额与数量。','SELECT roi.id AS id, roi.return_order_id AS return_order_id, roi.source_order_item_id AS source_order_item_id, roi.product_id AS product_id, roi.product_code AS product_code, roi.product_name AS product_name, roi.unit_name AS unit_name, roi.quantity_precision AS quantity_precision, roi.source_fulfilled_qty AS source_fulfilled_qty, roi.requested_qty AS requested_qty, roi.approved_qty AS approved_qty, roi.processed_qty AS processed_qty, roi.unit_price AS unit_price, roi.total_amount AS total_amount, roi.create_time AS create_time FROM return_order_item roi INNER JOIN return_order ro ON roi.return_order_id = ro.id WHERE ro.deleted = 0 AND ro.create_time >= \'2025-11-23 00:00:00\' AND ro.create_time < \'2026-11-23 00:00:00\'','[{\"name\":\"id\",\"label\":\"id\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"return_order_id\",\"label\":\"return_order_id\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"source_order_item_id\",\"label\":\"source_order_item_id\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"product_id\",\"label\":\"product_id\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"product_code\",\"label\":\"product_code\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"product_name\",\"label\":\"product_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"unit_name\",\"label\":\"unit_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"quantity_precision\",\"label\":\"quantity_precision\",\"jdbcType\":-6,\"typeName\":\"TINYINT\",\"nullable\":false},{\"name\":\"source_fulfilled_qty\",\"label\":\"source_fulfilled_qty\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"requested_qty\",\"label\":\"requested_qty\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"approved_qty\",\"label\":\"approved_qty\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"processed_qty\",\"label\":\"processed_qty\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"unit_price\",\"label\":\"unit_price\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"total_amount\",\"label\":\"total_amount\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"create_time\",\"label\":\"create_time\",\"jdbcType\":93,\"typeName\":\"DATETIME\",\"nullable\":false}]',366,1,'ds_fd1d7af2e5f14fc687f57a9602e84258.jsonl','READY','2026-12-07 00:00:00.000000','2026-11-22 11:31:22.408912','{\"grain\": \"每条退货明细一行\", \"fields\": [{\"name\": \"id\", \"index\": 0, \"meaning\": \"退货明细ID\"}, {\"name\": \"return_order_id\", \"index\": 1, \"meaning\": \"退货单主表ID\"}, {\"name\": \"source_order_item_id\", \"index\": 2, \"meaning\": \"原销售订单明细ID或采购订单明细ID\"}, {\"name\": \"product_id\", \"index\": 3, \"meaning\": \"产品ID\"}, {\"name\": \"product_code\", \"index\": 4, \"meaning\": \"产品编码快照\"}, {\"name\": \"product_name\", \"index\": 5, \"meaning\": \"产品名称快照\"}, {\"name\": \"unit_name\", \"index\": 6, \"meaning\": \"单位名称快照\"}, {\"name\": \"quantity_precision\", \"index\": 7, \"meaning\": \"数量小数位快照：0-2\"}, {\"name\": \"source_fulfilled_qty\", \"index\": 8, \"meaning\": \"创建退货明细时原订单累计已出库或已入库数量快照，放大100倍保存\"}, {\"name\": \"requested_qty\", \"index\": 9, \"meaning\": \"申请退货数量，放大100倍保存\"}, {\"name\": \"approved_qty\", \"index\": 10, \"meaning\": \"审核通过数量，放大100倍保存\"}, {\"name\": \"processed_qty\", \"index\": 11, \"meaning\": \"仓库累计确认的实际处理总量，放大100倍保存\"}, {\"name\": \"unit_price\", \"index\": 12, \"meaning\": \"原采购或销售订单明细单价快照，放大100倍保存\"}, {\"name\": \"total_amount\", \"index\": 13, \"meaning\": \"当前有效明细金额，放大100倍保存\"}, {\"name\": \"create_time\", \"index\": 14, \"meaning\": \"创建时间\"}], \"content\": \"统一退货单明细表记录，范围限定为关联主表在指定时间段内创建且未逻辑删除的退货单明细。涵盖所有退货类型和状态。\", \"limitations\": \"数量和金额字段均为数据库存储值（放大100倍），使用时需根据业务口径进行单位换算（如金额除以100得元，数量除以100得实际数量）。\"}',NULL);
INSERT INTO `ai_dataset` (`dataset_id`, `sql_run_id`, `attempt`, `ready_run_id`, `user_id`, `conversation_id`, `description`, `source_sql`, `columns_json`, `row_count`, `completed`, `storage_file`, `status`, `expires_at`, `created_at`, `data_description_json`, `truncation_reason`) VALUES ('ds_fd967aa0eea346bf8912f0779cfccbfe','sqlrun_34748eaa2e8a4db6a9bbee9d8fed403c',1,'sqlrun_34748eaa2e8a4db6a9bbee9d8fed403c',1900000000000000001,2124475847040573442,'查询目标入库仓库为成都双流西仓（warehouse_id=8400000000004000004）的全部未完成采购订单明细（purchase_order 与 purchase_order_item 均未逻辑删除，采购单状态排除 INBOUND_DONE 和 CANCELLED，包含 DRAFT/SUBMITTED/APPROVED/PARTIAL_INBOUND），每条采购明细一行，返回采购单号、供应商名称、采购单状态、预计到货日、产品ID/编码/名称/单位、采购数量、已入库数量、未入库数量(quantity-inbound_qty)。数量保持100倍整数原值。','SELECT po.purchase_no AS purchase_no, po.supplier_name AS supplier_name, po.status AS status, po.expected_arrival_date AS expected_arrival_date, poi.product_id AS product_id, poi.product_code AS product_code, poi.product_name AS product_name, poi.unit_name AS unit_name, poi.quantity AS quantity, poi.inbound_qty AS inbound_qty, (poi.quantity - poi.inbound_qty) AS pending_qty FROM purchase_order po JOIN purchase_order_item poi ON po.id = poi.purchase_order_id WHERE po.warehouse_id = 8400000000004000004 AND po.deleted = 0 AND po.status IN (\'DRAFT\', \'SUBMITTED\', \'APPROVED\', \'PARTIAL_INBOUND\')','[{\"name\":\"purchase_no\",\"label\":\"purchase_no\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"supplier_name\",\"label\":\"supplier_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"status\",\"label\":\"status\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"expected_arrival_date\",\"label\":\"expected_arrival_date\",\"jdbcType\":91,\"typeName\":\"DATE\",\"nullable\":true},{\"name\":\"product_id\",\"label\":\"product_id\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"product_code\",\"label\":\"product_code\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"product_name\",\"label\":\"product_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"unit_name\",\"label\":\"unit_name\",\"jdbcType\":12,\"typeName\":\"VARCHAR\",\"nullable\":false},{\"name\":\"quantity\",\"label\":\"quantity\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"inbound_qty\",\"label\":\"inbound_qty\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false},{\"name\":\"pending_qty\",\"label\":\"pending_qty\",\"jdbcType\":-5,\"typeName\":\"BIGINT\",\"nullable\":false}]',38,1,'ds_fd967aa0eea346bf8912f0779cfccbfe.jsonl','READY','2026-12-07 00:00:00.000000','2026-11-22 12:13:38.693000','{\"grain\": \"每张采购订单的每个产品明细一行\", \"fields\": [{\"name\": \"purchase_no\", \"index\": 0, \"meaning\": \"采购单号\"}, {\"name\": \"supplier_name\", \"index\": 1, \"meaning\": \"供应商名称快照\"}, {\"name\": \"status\", \"index\": 2, \"meaning\": \"采购订单状态（DRAFT/SUBMITTED/APPROVED/PARTIAL_INBOUND）\"}, {\"name\": \"expected_arrival_date\", \"index\": 3, \"meaning\": \"预计到货日期\"}, {\"name\": \"product_id\", \"index\": 4, \"meaning\": \"产品ID\"}, {\"name\": \"product_code\", \"index\": 5, \"meaning\": \"产品编码快照\"}, {\"name\": \"product_name\", \"index\": 6, \"meaning\": \"产品名称快照\"}, {\"name\": \"unit_name\", \"index\": 7, \"meaning\": \"单位名称快照\"}, {\"name\": \"quantity\", \"index\": 8, \"meaning\": \"采购数量（×100整数存储）\"}, {\"name\": \"inbound_qty\", \"index\": 9, \"meaning\": \"累计已入库数量（×100整数存储）\"}, {\"name\": \"pending_qty\", \"index\": 10, \"meaning\": \"未入库数量（quantity - inbound_qty，×100整数存储）\"}], \"content\": \"成都双流西仓的未完成采购订单明细列表，用于分析在途供给情况。\", \"limitations\": \"\"}',NULL);
